#[test]
fn layer_move_reorders_in_one_undo_step() {
    let mut s = world();
    let names = |s: &Session| s.map().layers.iter().map(|l| l.name.clone()).collect::<Vec<_>>();
    let depth = s.undo_depth();
    // Down three places: one command, one undo step.
    s.run("layer.move", &json!({"layer": "Cities", "to": 3})).unwrap();
    assert_eq!(names(&s), ["Rivers", "Lakes", "Countries", "Cities"]);
    assert_eq!(s.undo_depth(), depth + 1);
    // Up, to the middle.
    s.run("layer.move", &json!({"layer": "Cities", "to": 1})).unwrap();
    assert_eq!(names(&s), ["Rivers", "Cities", "Lakes", "Countries"]);
    // Past the end is the bottom.
    s.run("layer.move", &json!({"layer": "Rivers", "to": 1e9})).unwrap();
    assert_eq!(names(&s), ["Cities", "Lakes", "Countries", "Rivers"]);
    // Staying put, a missing or junk position and an unknown layer fail and leave no undo step.
    let depth = s.undo_depth();
    for p in [
        json!({"layer": "Rivers", "to": 3}),
        json!({"layer": "Rivers", "to": 99}),
        json!({"layer": "Rivers"}),
        json!({"layer": "Rivers", "to": -1}),
        json!({"layer": "Rivers", "to": 1.5}),
        json!({"layer": "Nope", "to": 0}),
    ] {
        assert!(s.run("layer.move", &p).is_err(), "{p}");
    }
    assert_eq!(names(&s), ["Cities", "Lakes", "Countries", "Rivers"]);
    assert_eq!(s.undo_depth(), depth);
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(names(&s), ["Rivers", "Cities", "Lakes", "Countries"]);
}

#[test]
fn table_remove_takes_a_standalone_table_out_of_the_project() {
    let mut s = world();
    let names = |s: &Session| s.project.tables.iter().map(|t| t.name.clone()).collect::<Vec<_>>();
    for name in ["sites", "notes"] {
        s.run("layer.addDataText", &json!({"fileName": format!("{name}.csv"), "text": "id,street\n1,Champ de Mars\n"})).unwrap();
    }
    assert_eq!(names(&s), ["sites", "notes"]);
    let (depth, layers) = (s.undo_depth(), s.map().layers.len());
    s.run("table.remove", &json!({"table": "sites"})).unwrap();
    assert_eq!(names(&s), ["notes"]);
    assert_eq!((s.undo_depth(), s.map().layers.len()), (depth + 1, layers), "one undo step, and the map's layers stay");
    // A table that isn't there, a layer's name and a missing or junk name fail and leave no undo step.
    for p in [json!({"table": "sites"}), json!({"table": "Cities"}), json!({}), json!({"table": 3}), Value::Null] {
        assert!(s.run("table.remove", &p).is_err(), "{p}");
    }
    assert_eq!((names(&s), s.undo_depth()), (vec!["notes".to_string()], depth + 1));
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(names(&s), ["sites", "notes"]);
    // Two tables of one name have ids of their own: the id says which, the name is the first.
    s.run("layer.addDataText", &json!({"fileName": "notes.csv", "text": "id,city\n1,Paris\n"})).unwrap();
    assert_eq!(names(&s), ["sites", "notes", "notes"]);
    let ids: Vec<u32> = s.project.tables.iter().map(|t| t.id).collect();
    assert!(ids.iter().all(|&id| id != 0) && ids[0] != ids[1] && ids[1] != ids[2] && ids[0] != ids[2], "{ids:?}");
    for table in [json!(0), json!(9999), json!(-1), json!(1.5), json!("9999")] {
        assert!(s.run("table.remove", &json!({"table": table})).is_err(), "{table}");
    }
    // The position the command took before ids is refused, not ignored.
    assert!(s.run("table.remove", &json!({"table": "notes", "at": 2})).is_err());
    assert_eq!(names(&s), ["sites", "notes", "notes"]);
    s.run("table.remove", &json!({"table": ids[2]})).unwrap();
    assert_eq!(s.project.tables.iter().map(|t| t.id).collect::<Vec<_>>(), [ids[0], ids[1]]);
    assert!(s.project.table(ids[1]).is_some_and(|t| t.field_index("street").is_some()), "the first of the two stays");
    // An id in text works as well, and an id isn't given again: undo brings the table back under its own.
    s.run("table.remove", &json!({"table": ids[1].to_string()})).unwrap();
    let again = s.run("layer.addDataText", &json!({"fileName": "more.csv", "text": "id,city\n1,Paris\n"})).unwrap();
    assert!(again["id"].as_u64().is_some_and(|id| ids.iter().all(|&old| u64::from(old) != id)), "{again}");
    s.run("edit.undo", &Value::Null).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.project.tables.iter().map(|t| t.id).collect::<Vec<_>>(), [ids[0], ids[1]]);
    s.run("edit.redo", &Value::Null).unwrap();
    assert_eq!(s.project.tables.iter().map(|t| t.id).collect::<Vec<_>>(), [ids[0]]);
    // A table added and undone leaves its id unused: the next table gets another.
    let undone = s.run("layer.addDataText", &json!({"fileName": "a.csv", "text": "id,city\n1,Paris\n"})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    let next = s.run("layer.addDataText", &json!({"fileName": "b.csv", "text": "id,city\n1,Paris\n"})).unwrap();
    assert!(undone["id"].as_u64() < next["id"].as_u64(), "{undone} then {next}");
}

#[test]
fn a_saved_selection_is_read_in_range_in_order_and_once() {
    // A selection edited by hand: a row repeated, out of order, and one past the layer's end.
    let s = world();
    let mut v: Value = serde_json::to_value(&s.project).unwrap();
    let layers = v["maps"][0]["layers"].as_array_mut().unwrap();
    let i = layers.iter().position(|l| l["name"] == "Countries").unwrap();
    layers[i]["selection"] = json!([3, 1, 3, 1_000_000]);
    let p = Project::from_json(&v.to_string()).unwrap();
    let countries = p.map().layers.iter().find(|l| l.name == "Countries").unwrap();
    assert_eq!(countries.selection, [1, 3]);
    // An offline area's snapshot, edited the same way, opens with the selection put right too.
    let mut s = world();
    s.run("offline.download", &json!({"name": "Paris", "extent": [1.0, 48.0, 4.0, 50.0]})).unwrap();
    let cities = s.project.offline_areas[0].data.layers.iter_mut().find(|l| l.name == "Cities").unwrap();
    let last = cities.dataset.features.len() - 1;
    cities.selection = vec![last, 0, last, last + 1];
    s.run("offline.open", &json!({"name": "Paris"})).unwrap();
    let mut want = vec![0, last];
    // Row 0 and the last row, once each: one row when the layer has a single feature.
    want.dedup();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().selection, want);
}

#[test]
fn standalone_tables_keep_their_ids_in_the_project_file() {
    let mut s = world();
    for name in ["sites", "sites", "notes"] {
        s.run("layer.addDataText", &json!({"fileName": format!("{name}.csv"), "text": "id,street\n1,Champ de Mars\n"})).unwrap();
    }
    s.run("table.remove", &json!({"table": "sites"})).unwrap();
    let ids: Vec<u32> = s.project.tables.iter().map(|t| t.id).collect();
    // Saved and read again: the same ids, and the next table gets one that was never used.
    let text = serde_json::to_string(&s.project).unwrap();
    let mut p = Project::from_json(&text).unwrap();
    assert_eq!(
        p.tables.iter().map(|t| (t.id, t.name.clone(), t.features.len())).collect::<Vec<_>>(),
        [(ids[0], "sites".to_string(), 1), (ids[1], "notes".to_string(), 1)]
    );
    let next = p.add_table(rustgis_data::Dataset::new("more", rustgis_data::GeometryType::None, Vec::new()));
    assert!(next > ids[1], "{next} after {ids:?}");
    // A file from before tables had ids, and one with an id repeated by hand: every table gets
    // an id of its own, and those that had a good one keep it.
    let mut v: Value = serde_json::from_str(&text).unwrap();
    for t in v["tables"].as_array_mut().unwrap() {
        t.as_object_mut().unwrap().remove("id");
    }
    v.as_object_mut().unwrap().remove("next_table_id");
    let old = Project::from_json(&v.to_string()).unwrap();
    assert_eq!(old.tables.iter().map(|t| t.id).collect::<Vec<_>>(), [1, 2]);
    v["tables"][0]["id"] = json!(7);
    v["tables"][1]["id"] = json!(7);
    let edited = Project::from_json(&v.to_string()).unwrap();
    assert_eq!(edited.tables.iter().map(|t| t.id).collect::<Vec<_>>(), [7, 8]);
    // A tool's table put again under its name keeps the id.
    let stats = json!({"tool": "summaryStatistics", "params": {"input": "Countries", "field": "pop_est", "case": "continent"}});
    s.run("gp.run", &stats).unwrap();
    let id = s.project.tables.last().map(|t| t.id).unwrap();
    s.run("gp.run", &stats).unwrap();
    assert_eq!((s.project.tables.len(), s.project.tables.last().map(|t| t.id)), (3, Some(id)));
    // Commands and tools reach a table by its id as well as by its name, which is the first of
    // two tables sharing it.
    for v in [10, 99] {
        s.run("layer.addDataText", &json!({"fileName": "counts.csv", "text": format!("k,v\na,{v}\n")})).unwrap();
    }
    let info = s.run("info.project", &Value::Null).unwrap();
    let counts: Vec<u64> =
        info["tables"].as_array().unwrap().iter().filter(|t| t["name"] == "counts").filter_map(|t| t["id"].as_u64()).collect();
    assert_eq!((counts.len(), info["tables"][0]["rows"].as_u64()), (2, Some(1)), "{info}");
    // A name exactly as written comes before one that differs in case, for tools as for commands.
    s.run("layer.addDataText", &json!({"fileName": "Counts.csv", "text": "k,v\na,5\n"})).unwrap();
    let upper = s.project.tables.last().map(|t| t.id).unwrap();
    assert_eq!(s.table_index(&json!({"table": "Counts"})).ok().and_then(|i| s.project.tables.get(i)).map(|t| t.id), Some(upper));
    for (input, sum) in [(json!("counts"), 10.0), (json!("COUNTS"), 10.0), (json!("Counts"), 5.0), (json!(counts[1].to_string()), 99.0)] {
        s.run("gp.run", &json!({"tool": "summaryStatistics", "params": {"input": input, "field": "v"}})).unwrap();
        // The run's table is the last: put again under its name, or added.
        let out = s.project.tables.last().unwrap();
        assert_eq!(out.value(0, out.field_index("SUM_v").unwrap()), &rustgis_data::Value::Float(sum), "{input}");
    }
    // A table named as another's id: the text finds it by its name, and a number is the id.
    s.run("layer.addDataText", &json!({"fileName": format!("{}.csv", counts[1]), "text": "k,v\na,1\n"})).unwrap();
    assert_eq!(s.project.tables.last().map(|t| t.name.clone()), Some(counts[1].to_string()));
    for (input, sum) in [(json!(counts[1].to_string()), 1.0), (json!(counts[1]), 99.0)] {
        s.run("gp.run", &json!({"tool": "summaryStatistics", "params": {"input": input, "field": "v"}})).unwrap();
        let out = s.project.tables.last().unwrap();
        assert_eq!(out.value(0, out.field_index("SUM_v").unwrap()), &rustgis_data::Value::Float(sum), "{input}");
    }
    for input in [json!(9999), json!(-1), json!(1.5)] {
        assert!(s.run("gp.run", &json!({"tool": "summaryStatistics", "params": {"input": input, "field": "v"}})).is_err());
    }
    let dir = std::env::temp_dir().join(format!("rustgis-table-ids-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("counts.csv");
    s.run("share.exportTable", &json!({"table": counts[1], "path": path})).unwrap();
    assert!(std::fs::read_to_string(&path).unwrap().contains("99"));
    std::fs::remove_dir_all(&dir).ok();
    assert!(s.run("share.exportTable", &json!({"table": 9999, "path": path})).is_err());
    // The table the attribute table shows is forgotten with the table, and with the project.
    s.table_standalone = Some(id);
    s.run("table.remove", &json!({"table": ids[0]})).unwrap();
    assert_eq!(s.table_standalone, Some(id), "another table's removal leaves it");
    s.run("table.remove", &json!({"table": id})).unwrap();
    assert_eq!(s.table_standalone, None);
    s.table_standalone = Some(ids[1]);
    s.run("project.new", &Value::Null).unwrap();
    assert_eq!(s.table_standalone, None);
}

#[test]
fn select_symbolize_undo_redo() {
    let mut s = world();
    let r = s.run("select.byAttributes", &json!({"layer": "Countries", "where": "continent = 'Africa'"})).unwrap();
    assert!(r["selected"].as_u64().unwrap() > 40);
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "unique", "field": "continent"})).unwrap();
    assert_eq!(s.map().layer_by_name("Countries").unwrap().renderer.kind_label(), "Unique Values");
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().layer_by_name("Countries").unwrap().renderer.kind_label(), "Graduated Colors");
    s.run("edit.redo", &Value::Null).unwrap();
    assert_eq!(s.map().layer_by_name("Countries").unwrap().renderer.kind_label(), "Unique Values");
}

#[test]
fn undo_steps_share_the_layers_they_leave_alone() {
    // #214: each undo step held a full copy of every layer, so a large layer grew by its whole
    // size with every command (a rename, a style change).
    let mut s = world();
    s.map_mut().layers.iter_mut().for_each(|l| {
        l.projected();
    });
    s.run("layer.rename", &json!({"layer": "Countries", "name": "Nations"})).unwrap();
    s.run("layer.rename", &json!({"layer": "Nations", "name": "States"})).unwrap();
    let live = s.map().layer_by_name("States").unwrap();
    let id = live.id;
    for (snap, ..) in &s.undo {
        let old = snap.maps.iter().flat_map(|m| &m.layers).find(|l| l.id == id).unwrap();
        assert!(old.dataset.features.shares(&live.dataset.features), "the snapshot copied the features");
        assert_eq!(old.projected_cache().as_ptr(), live.projected_cache().as_ptr(), "the snapshot copied the projected geometry");
    }
    // An edit copies the layer it changes, once, and leaves the snapshot as it was.
    let before = s.map().layer_by_name("Cities").unwrap().dataset.features.len();
    s.run("edit.addFeature", &json!({"layer": "Cities", "geometry": {"type": "Point", "coordinates": [1.0, 2.0]}})).unwrap();
    let cities = s.map().layer_by_name("Cities").unwrap();
    let (snap, ..) = s.undo.last().unwrap();
    let old = snap.maps.iter().flat_map(|m| &m.layers).find(|l| l.id == cities.id).unwrap();
    assert!(!old.dataset.features.shares(&cities.dataset.features));
    assert_eq!((old.dataset.features.len(), cities.dataset.features.len()), (before, before + 1));
    let states = s.map().layer_by_name("States").unwrap();
    let old = snap.maps.iter().flat_map(|m| &m.layers).find(|l| l.id == id).unwrap();
    assert!(old.dataset.features.shares(&states.dataset.features));
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().dataset.features.len(), before);
}

#[test]
fn geoprocessing_adds_layers_and_history() {
    let mut s = world();
    s.run("gp.run", &json!({"tool": "buffer", "params": {"input": "Cities", "distance": 200}})).unwrap();
    assert!(s.map().layer_by_name("Cities_Buffer").is_some());
    s.run("gp.run", &json!({"tool": "summaryStatistics", "params": {"input": "Countries", "field": "pop_est", "case": "continent"}}))
        .unwrap();
    assert_eq!(s.project.tables.len(), 1);
    assert!(s.run("gp.run", &json!({"tool": "buffer", "params": {"input": "Nope"}})).is_err());
    assert_eq!(s.project.gp_history.len(), 2, "a failed run restores the project");
}

/// Pivot Table adds a standalone table in one undo step: a row for each continent and a field for
/// each income group, holding the population summed over that continent's countries in the group.
#[test]
fn pivot_table_adds_a_table_in_one_undo_step() {
    let mut s = world();
    let countries = s.map().layer_by_name("Countries").map(|l| l.dataset.clone()).unwrap();
    let total: f64 =
        (0..countries.features.len()).filter_map(|r| countries.value(r, countries.field_index("pop_est").unwrap()).as_f64()).sum();
    let params = json!({"input": "Countries", "fields": "continent", "pivot": "income_grp", "value": "pop_est", "statistic": "SUM"});
    s.run("gp.run", &json!({"tool": "pivotTable", "params": params})).unwrap();
    let t = s.project.tables.last().unwrap();
    assert_eq!(t.name, "Countries_Pivot");
    assert_eq!(t.fields.first().map(|f| f.name.as_str()), Some("continent"));
    assert!(t.fields.len() > 2 && t.fields.iter().skip(1).all(|f| f.name.starts_with("income_grp")), "{:?}", t.fields);
    let cells: f64 = (0..t.features.len()).flat_map(|r| (1..t.fields.len()).filter_map(move |c| t.value(r, c).as_f64())).sum();
    assert!((cells - total).abs() < 1.0, "{cells} != {total}");
    assert_eq!(s.project.gp_history.len(), 1);
    s.run("edit.undo", &Value::Null).unwrap();
    assert!(s.project.tables.is_empty());
}

#[test]
fn spatial_join_command_joins_layers_and_records_history() {
    let mut s = world();
    s.run(
        "gp.spatialJoin",
        &json!({
            "target": "Cities",
            "join": "Countries",
            "match": "Intersects",
            "operation": "Join one to one",
            "output": "Joined_Cities"
        }),
    )
    .unwrap();
    let l = s.map().layer_by_name("Joined_Cities").unwrap();
    assert_eq!(l.dataset.features.len(), s.map().layer_by_name("Cities").unwrap().dataset.features.len());
    assert!(l.dataset.field_index("join_count").is_some());
    assert_eq!(s.project.gp_history.len(), 1);

    s.run(
        "gp.run",
        &json!({
            "tool": "spatialJoin",
            "params": {
                "target": "Countries",
                "join": "Cities",
                "match": "Contains",
                "output": "Countries_With_Cities"
            }
        }),
    )
    .unwrap();
    assert!(s.map().layer_by_name("Countries_With_Cities").is_some());
}

#[test]
fn editing_features_and_fields() {
    let mut s = world();
    s.run(
        "edit.addFeature",
        &json!({"layer": "Cities", "geometry": {"type": "Point", "coordinates": [1.0, 2.0]}, "attributes": {"name": "Null Island"}}),
    )
    .unwrap();
    let n = s.map().layer_by_name("Cities").unwrap().dataset.features.len();
    assert!(
        s.run("edit.addFeature", &json!({"layer": "Cities", "geometry": {"type": "LineString", "coordinates": [[0,0],[1,1]]}})).is_err()
    );
    s.run("edit.addField", &json!({"layer": "Cities", "name": "score", "type": "double"})).unwrap();
    s.run("edit.calculateField", &json!({"layer": "Cities", "field": "score", "expression": "pop_max / 1000"})).unwrap();
    s.run("edit.delete", &Value::Null).unwrap();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().dataset.features.len(), n - 1);
}

/// A polygon layer stacks fills (a colour, hatch lines, markers on a grid), for the layer or a
/// class of its own; junk is refused and numbers held within range; each change undoes, and the
/// project keeps them (a layer without them saves as before).
#[test]
fn fill_layers_stack_and_survive_save_and_undo() {
    use rustgis_map::Rgba;
    use rustgis_map::fills::{FillLayer, FillPattern, MAX_FILLS};
    let mut s = world();
    let before = serde_json::to_string(&s.project).unwrap();
    assert!(!before.contains("fill_layers") && !before.contains("class_fills"), "nothing written for layers without them");
    let depth = s.undo_depth();
    let fills = json!([
        {"color": "#E8F0D0", "pattern": "solid"},
        {"color": "#336633", "pattern": "hatch", "angle": 45, "spacing": 6, "width": 0.75},
        {"pattern": "dots", "marker": "square", "size": 2, "spacing": [8, 6], "displacement": [4, 0], "outline": "#000000", "outlineWidth": 0.5}
    ]);
    assert_eq!(s.run("layer.fillLayers", &json!({"layer": "Countries", "fills": fills})).unwrap(), json!({"fills": 3}));
    assert_eq!(s.undo_depth(), depth + 1, "one undo step");
    let got = |s: &Session| s.map().layer_by_name("Countries").unwrap().fill_layers.clone();
    let f = got(&s);
    assert_eq!(f[0], FillLayer { color: Some(Rgba::rgb(0xE8, 0xF0, 0xD0)), pattern: FillPattern::Solid });
    assert_eq!(f[1].pattern, FillPattern::Hatch { angle: 45.0, spacing: 6.0, width: 0.75, offset: 0.0 });
    let FillPattern::Dots { marker, spacing, outline, .. } = f[2].pattern else { panic!("{f:?}") };
    assert_eq!((marker, spacing, outline, f[2].color), (rustgis_map::Marker::Square, [8.0, 6.0], Some(Rgba::rgb(0, 0, 0)), None));
    // Kept with the project, and undone.
    let text = serde_json::to_string(&s.project).unwrap();
    let reopened = Session::new(serde_json::from_str(&text).unwrap());
    assert_eq!(got(&reopened), f);
    s.run("edit.undo", &json!({})).unwrap();
    assert!(got(&s).is_empty());
    // Held within range; a number given for both ways.
    s.run("layer.fillLayers", &json!({"layer": "Countries", "fills": [{"pattern": "hatch", "spacing": 1e300, "width": -4, "angle": -45}, {"pattern": "dots", "spacing": 1e9}]}))
        .unwrap();
    let f = got(&s);
    assert_eq!(f[0].pattern, FillPattern::Hatch { angle: 315.0, spacing: 500.0, width: 0.0, offset: 0.0 });
    assert!(matches!(f[1].pattern, FillPattern::Dots { spacing: [500.0, 500.0], .. }), "{f:?}");
    // A character of a font as the dots (a QGIS font marker's), kept with its family; not with a
    // shape too.
    s.run("layer.fillLayers", &json!({"layer": "Countries", "fills": [{"pattern": "dots", "char": "★", "font": "Noto Sans"}]})).unwrap();
    let FillPattern::Dots { marker: rustgis_map::Marker::Char(g), .. } = got(&s)[0].pattern else { panic!("{:?}", got(&s)) };
    assert_eq!((g.ch, g.font.as_str()), ('★', "Noto Sans"));
    assert!(
        s.run("layer.fillLayers", &json!({"layer": "Countries", "fills": [{"pattern": "dots", "marker": "square", "char": "x"}]})).is_err()
    );
    // A class's own (Unique Values), then back to the layer's.
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "unique", "field": "continent"})).unwrap();
    let value = match &s.map().layer_by_name("Countries").unwrap().renderer {
        rustgis_map::Renderer::Unique { classes, .. } => classes[0].0.clone(),
        r => panic!("{r:?}"),
    };
    s.run("layer.fillLayers", &json!({"layer": "Countries", "value": value, "fills": [{"pattern": "hatch"}]})).unwrap();
    let class_fills = |s: &Session| match &s.map().layer_by_name("Countries").unwrap().renderer {
        rustgis_map::Renderer::Unique { class_fills, .. } => class_fills.clone(),
        _ => Default::default(),
    };
    assert_eq!(class_fills(&s).get(&value).map(Vec::len), Some(1));
    s.run("layer.fillLayers", &json!({"layer": "Countries", "value": value, "fills": []})).unwrap();
    assert!(class_fills(&s).is_empty());
    assert!(s.run("layer.fillLayers", &json!({"layer": "Countries", "value": "no such class", "fills": []})).is_err());
    // Junk, and a layer that isn't polygons.
    let many: Vec<Value> = (0..=MAX_FILLS).map(|_| json!({})).collect();
    for bad in [
        json!({"layer": "Countries"}),
        json!({"layer": "Countries", "fills": "hatch"}),
        json!({"layer": "Countries", "fills": many}),
        json!({"layer": "Countries", "fills": [7]}),
        json!({"layer": "Countries", "fills": [{"pattern": "stripes"}]}),
        json!({"layer": "Countries", "fills": [{"color": "red"}]}),
        json!({"layer": "Countries", "fills": [{"pattern": "hatch", "spacing": "wide"}]}),
        json!({"layer": "Countries", "fills": [{"pattern": "dots", "spacing": [1]}]}),
        json!({"layer": "Countries", "fills": [{"pattern": "dots", "marker": "blob"}]}),
        json!({"layer": "Rivers", "fills": []}),
    ] {
        assert!(s.run("layer.fillLayers", &bad).is_err(), "{bad}");
    }
}

/// Gradient and shapeburst fills: their colours, stops and how they run, kept with the project;
/// junk refused, numbers held within range.
#[test]
fn gradient_and_shapeburst_fills_are_set_and_kept() {
    use rustgis_map::Rgba;
    use rustgis_map::fills::{FillPattern, GradientPoint, GradientShape, MAX_GRADIENT_POINT, Spread, Stop};
    let mut s = world();
    let fills = json!([
        {"color": "#FF0000", "pattern": "gradient", "color2": "#0000FF", "shape": "radial", "from": "centroid", "to": [1, 0.5], "spread": "reflect", "angle": 30, "stops": [[0.5, "#00FF00"]]},
        {"color": "#2B6ADB", "pattern": "shapeburst", "color2": "#6A94DB", "distance": 14, "blur": 10, "ignoreRings": true, "discrete": true}
    ]);
    assert_eq!(s.run("layer.fillLayers", &json!({"layer": "Countries", "fills": fills})).unwrap(), json!({"fills": 2}));
    let got = |s: &Session| s.map().layer_by_name("Countries").unwrap().fill_layers.clone();
    let f = got(&s);
    let FillPattern::Gradient { shape, color2, stops, from, to, spread, angle, in_view, discrete } = f[0].pattern else { panic!("{f:?}") };
    assert_eq!(
        (shape, color2, from, to, spread, angle, in_view, discrete),
        (
            GradientShape::Radial,
            Rgba::rgb(0, 0, 255),
            GradientPoint::CENTROID,
            GradientPoint::At([1.0, 0.5]),
            Spread::Reflect,
            30.0,
            false,
            false
        )
    );
    assert_eq!(stops.as_slice(), &[Stop { at: 0.5, color: Rgba::rgb(0, 255, 0) }]);
    assert_eq!(
        f[1].pattern,
        FillPattern::Shapeburst {
            color2: Rgba::rgb(0x6A, 0x94, 0xDB),
            stops: Default::default(),
            discrete: true,
            distance: Some(14.0),
            blur: 10,
            ignore_rings: true
        }
    );
    // Kept with the project.
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(text.contains(r#""from":"centroid""#), "{text}");
    assert_eq!(got(&Session::new(serde_json::from_str(&text).unwrap())), f);
    // Defaults: QGIS's, top middle to bottom middle, to white; a shapeburst over the whole shape.
    s.run("layer.fillLayers", &json!({"layer": "Countries", "fills": [{"pattern": "gradient"}, {"pattern": "shapeburst"}]})).unwrap();
    let f = got(&s);
    assert!(
        matches!(f[0].pattern, FillPattern::Gradient { shape: GradientShape::Linear, from: GradientPoint::At([0.5, 0.0]), to: GradientPoint::At([0.5, 1.0]), color2, .. } if color2 == Rgba::rgb(255, 255, 255)),
        "{f:?}"
    );
    assert!(matches!(f[1].pattern, FillPattern::Shapeburst { distance: None, blur: 0, .. }), "{f:?}");
    // Held within range.
    s.run("layer.fillLayers", &json!({"layer": "Countries", "fills": [{"pattern": "gradient", "from": [1e300, -1e300], "angle": -90, "stops": [[7, "#000000"], [-1, "#FFFFFF"]]}]})).unwrap();
    let FillPattern::Gradient { from, angle, stops, .. } = got(&s)[0].pattern else { panic!() };
    assert_eq!((from, angle), (GradientPoint::At([MAX_GRADIENT_POINT, -MAX_GRADIENT_POINT]), 270.0));
    assert_eq!(stops.as_slice().iter().map(|s| s.at).collect::<Vec<_>>(), vec![0.0, 1.0], "in order, within 0 to 1");
    for bad in [
        json!({"pattern": "gradient", "shape": "spiral"}),
        json!({"pattern": "gradient", "spread": 2}),
        json!({"pattern": "gradient", "from": "middle"}),
        json!({"pattern": "gradient", "from": [0.5]}),
        json!({"pattern": "gradient", "stops": [[0.5]]}),
        json!({"pattern": "gradient", "stops": [[0.5, "green"]]}),
        json!({"pattern": "gradient", "stops": (0..20).map(|i| json!([i as f64 / 20.0, "#000000"])).collect::<Vec<_>>()}),
        json!({"pattern": "gradient", "inView": "yes"}),
        json!({"pattern": "shapeburst", "blur": 99}),
        json!({"pattern": "shapeburst", "distance": -1}),
        json!({"pattern": "shapeburst", "color2": "blue"}),
    ] {
        assert!(s.run("layer.fillLayers", &json!({"layer": "Countries", "fills": [bad]})).is_err(), "{bad}");
    }
}

#[test]
fn line_strokes_stack_and_survive_save_and_undo() {
    use rustgis_map::{LineCap, LineJoin, LineStroke, Rgba};
    let mut s = world();
    let depth = s.undo_depth();
    // A black casing under an orange core, both shifted 8.5 pt right (#478).
    let strokes = json!([
        {"color": "#000000", "width": 11.5, "offset": 8.5, "cap": "round", "join": "round"},
        {"color": "#FF8C00", "width": 7, "offset": 8.5, "cap": "flat", "join": "miter"},
        {"offset": -2}
    ]);
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": strokes})).unwrap();
    let want = vec![
        LineStroke {
            color: Some(Rgba::rgb(0, 0, 0)),
            width: Some(11.5),
            offset: 8.5,
            cap: LineCap::Round,
            join: LineJoin::Round,
            level: None,
            dash: None,
            markers: None,
        },
        LineStroke {
            color: Some(Rgba::rgb(0xFF, 0x8C, 0)),
            width: Some(7.0),
            offset: 8.5,
            cap: LineCap::Butt,
            join: LineJoin::Miter,
            level: None,
            dash: None,
            markers: None,
        },
        LineStroke { offset: -2.0, ..LineStroke::default() },
    ];
    assert_eq!(s.map().layer_by_name("Rivers").unwrap().line_strokes, want);
    assert_eq!(s.undo_depth(), depth + 1);
    // Kept in the project file, and drawn in an export.
    let dir = std::env::temp_dir().join(format!("rustgis-strokes-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("strokes.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    assert_eq!(t.map().layer_by_name("Rivers").unwrap().line_strokes, want);
    let png = dir.join("map.png");
    t.run("share.exportMap", &json!({"path": png.display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    // Out-of-range numbers are brought into range; junk is refused and changes nothing.
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [{"width": 1e9, "offset": -1e9}]})).unwrap();
    let st = s.map().layer_by_name("Rivers").unwrap().line_strokes.clone();
    assert_eq!((st[0].width, st[0].offset), (Some(50.0), -100.0));
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [{"width": 1e300, "offset": 1e300}]})).unwrap();
    let st = s.map().layer_by_name("Rivers").unwrap().line_strokes.clone();
    assert_eq!((st[0].width, st[0].offset), (Some(50.0), 100.0));
    let depth = s.undo_depth();
    for bad in [
        json!({"layer": "Rivers"}),
        json!({"layer": "Rivers", "strokes": [{"cap": "pointy"}]}),
        json!({"layer": "Rivers", "strokes": [{"join": "zigzag"}]}),
        json!({"layer": "Rivers", "strokes": [{"cap": 5}]}),
        json!({"layer": "Rivers", "strokes": [{"join": true}]}),
        json!({"layer": "Rivers", "strokes": [{"color": "orange"}]}),
        json!({"layer": "Rivers", "strokes": [{"width": "wide"}]}),
        json!({"layer": "Rivers", "strokes": [7]}),
        json!({"layer": "Rivers", "strokes": vec![json!({}); 17]}),
        // Polygons have no strokes of their own (points have marks).
        json!({"layer": "Countries", "strokes": []}),
    ] {
        assert!(s.run("layer.lineStrokes", &bad).is_err(), "{bad}");
    }
    assert_eq!(s.undo_depth(), depth);
    s.run("layer.lineStrokes", &json!({"layer": "Cities", "strokes": []})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    // [] goes back to the single stroke; undo brings the stack back.
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": []})).unwrap();
    assert!(s.map().layer_by_name("Rivers").unwrap().line_strokes.is_empty());
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().layer_by_name("Rivers").unwrap().line_strokes.len(), 1);
}

#[test]
fn line_strokes_take_markers_and_hash_marks_along_the_line() {
    use rustgis_map::{LineMark, LineMarkers, Marker, Placements, Rgba};
    let mut s = world();
    // A river: its line, triangles at both ends turned with it, and ticks across it.
    let strokes = json!([
        {"color": "#1E5AA8", "width": 2},
        {"color": "#1E5AA8", "markers": {"mark": "Triangle", "size": 8, "at": ["first", "last"], "outline": "#FFFFFF"}, "width": 1},
        {"color": "#1E5AA8", "width": 1, "markers": {"mark": "hash", "size": 6, "interval": 10, "angle": 30, "rotate": false}}
    ]);
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": strokes})).unwrap();
    let st = s.map().layer_by_name("Rivers").unwrap().line_strokes.clone();
    assert_eq!(st[0].markers, None);
    let ends = LineMarkers {
        mark: LineMark::Marker(Marker::Triangle),
        size: 8.0,
        at: Placements::FIRST.with(Placements::LAST),
        outline: Some(Rgba::rgb(255, 255, 255)),
        ..LineMarkers::default()
    };
    assert_eq!(st[1].markers, Some(ends));
    let ticks = LineMarkers { mark: LineMark::Hash, size: 6.0, interval: 10.0, angle: 30.0, rotate: false, ..LineMarkers::default() };
    assert_eq!(st[2].markers, Some(ticks));
    // A single place is a list of one; out-of-range numbers are brought into range.
    let one = json!([{"markers": {"at": "middle", "size": 1e9, "interval": 0, "angle": 450}}]);
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": one})).unwrap();
    let m = s.map().layer_by_name("Rivers").unwrap().line_strokes[0].markers.unwrap();
    assert_eq!((m.at, m.size, m.interval, m.angle), (Placements::MIDDLE, 100.0, 0.5, 90.0));
    // Drawn in an export.
    let dir = std::env::temp_dir().join(format!("rustgis-markers-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": strokes})).unwrap();
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    // Junk is refused, saying where, and changes nothing.
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"markers": 5}), "stroke 1: markers: an object"),
        (json!({"markers": {"mark": "hexagon"}}), "unknown mark 'hexagon'"),
        (json!({"markers": {"mark": 3}}), "mark is"),
        (json!({"markers": {"at": "sideways"}}), "at is a placement"),
        (json!({"markers": {"at": []}}), "at is a placement"),
        (json!({"markers": {"at": ["first", 2]}}), "at is a placement"),
        (json!({"markers": {"rotate": "yes"}}), "rotate is true or false"),
        (json!({"markers": {"size": "big"}}), "size is a number"),
        (json!({"markers": {"outline": "white"}}), "outline must be"),
    ] {
        let err = s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [bad]})).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    assert_eq!(s.undo_depth(), depth);
}

#[test]
fn a_character_of_a_font_is_a_marker_on_points_and_along_lines() {
    use rustgis_map::{Glyph, LineMark, Marker};
    let mut s = world();
    let marker = |s: &Session| s.map().layer_by_name("Cities").unwrap().symbol(0).marker;
    s.run("layer.marker", &json!({"layer": "Cities", "char": "★x", "font": "DejaVu Sans", "size": 14})).unwrap();
    assert_eq!(marker(&s), Marker::Char(Glyph::new('★', "DejaVu Sans")));
    // Another character keeps the family; a family alone changes the character's.
    s.run("layer.marker", &json!({"layer": "Cities", "char": "A"})).unwrap();
    assert_eq!(marker(&s), Marker::Char(Glyph::new('A', "DejaVu Sans")));
    s.run("layer.marker", &json!({"layer": "Cities", "font": ""})).unwrap();
    assert_eq!(marker(&s), Marker::Char(Glyph::new('A', "")));
    // Drawn in an export, a family this machine lacks in the label font.
    let dir = std::env::temp_dir().join(format!("rustgis-chars-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("layer.marker", &json!({"layer": "Cities", "font": "No Such Family"})).unwrap();
    let strokes =
        json!([{"color": "#1E5AA8", "markers": {"mark": "character", "char": "»", "font": "DejaVu Sans", "size": 8, "interval": 20}}]);
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": strokes})).unwrap();
    let m = s.map().layer_by_name("Rivers").unwrap().line_strokes[0].markers.unwrap();
    assert_eq!(m.mark, LineMark::Marker(Marker::Char(Glyph::new('»', "DejaVu Sans"))));
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    // A shape goes back to the shape.
    s.run("layer.marker", &json!({"layer": "Cities", "shape": "square"})).unwrap();
    assert_eq!(marker(&s), Marker::Square);
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "char": ""}), "char is a character"),
        (json!({"layer": "Cities", "char": 7}), "char is a character"),
        (json!({"layer": "Cities", "char": "a", "shape": "star"}), "not both"),
    ] {
        let err = s.run("layer.marker", &bad).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    let err = s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [{"markers": {"mark": "hash", "char": "x"}}]})).unwrap_err();
    assert!(err.contains("hash marks take no char"), "{err}");
    let err = s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [{"markers": {"mark": "character"}}]})).unwrap_err();
    assert!(err.contains("needs its char"), "{err}");
    // A shape with a char is refused, as by `layer.marker`.
    let err =
        s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [{"markers": {"mark": "circle", "char": "x"}}]})).unwrap_err();
    assert!(err.contains("not both"), "{err}");
    assert_eq!(s.undo_depth(), depth);
}

#[test]
fn a_point_takes_stacked_marks_and_turns_by_a_field() {
    use rustgis_map::{Glyph, LineMark, Marker};
    let mut s = world();
    // A white disc under a black character, and a red square 6 pt right of the point.
    let marks = json!([
        {"color": "#FFFFFF", "markers": {"mark": "circle", "size": 14}},
        {"color": "#000000", "markers": {"mark": "character", "char": "A", "size": 12}},
        {"color": "#FF0000", "markers": {"mark": "square", "size": 4, "offsetAlong": 6}}
    ]);
    let mark = s.notice_mark();
    s.run("layer.lineStrokes", &json!({"layer": "Cities", "strokes": marks})).unwrap();
    assert!(s.notices_since(mark).iter().all(|n| !n.text.contains("ignores")), "every key is read");
    let st = s.map().layer_by_name("Cities").unwrap().line_strokes.clone();
    assert_eq!(st.len(), 3);
    assert_eq!(st[1].markers.unwrap().mark, LineMark::Marker(Marker::Char(Glyph::new('A', ""))));
    assert_eq!(st[2].markers.unwrap().offset_along, 6.0);
    // A line stroke would draw nothing at a point.
    let err = s.run("layer.lineStrokes", &json!({"layer": "Cities", "strokes": [{"width": 2}]})).unwrap_err();
    assert!(err.contains("stroke 1: a point layer's strokes are markers"), "{err}");
    let err = s.run("layer.lineStrokes", &json!({"layer": "Countries", "strokes": marks})).unwrap_err();
    assert!(err.contains("line and point layers"), "{err}");
    // Turned by a numeric field, counterclockwise.
    s.run("layer.markerRotation", &json!({"layer": "Cities", "field": "pop_max", "counterclockwise": true})).unwrap();
    let l = s.map().layer_by_name("Cities").unwrap();
    let r = l.marker_rotation.clone().unwrap();
    assert_eq!((r.field.as_str(), r.counterclockwise), ("pop_max", true));
    let fi = l.dataset.field_index("pop_max").unwrap();
    let v = l.dataset.value(0, fi).as_f64().unwrap();
    assert_eq!(l.marker_turn(0), -(v.rem_euclid(360.0) as f32));
    // Drawn in an export.
    let dir = std::env::temp_dir().join(format!("rustgis-marks-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "field": "name"}), "not a numeric field"),
        (json!({"layer": "Cities", "field": "nowhere"}), "no field named"),
        (json!({"layer": "Cities", "field": 3}), "field is a field's name"),
        (json!({"layer": "Rivers", "field": "pop_max"}), "point layers"),
    ] {
        let err = s.run("layer.markerRotation", &bad).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    assert_eq!(s.undo_depth(), depth);
    // None turns them back.
    s.run("layer.markerRotation", &json!({"layer": "Cities", "field": null})).unwrap();
    assert!(s.map().layer_by_name("Cities").unwrap().marker_rotation.is_none());
}

#[test]
fn a_symbol_is_set_by_expressions() {
    let mut s = world();
    let r = s
        .run("layer.symbolBy", &json!({"layer": "Cities", "size": "scale_linear(pop_max, 0, 2e7, 4, 20)", "fill": "if(pop_max > 1e7, '#ff0000', NULL)", "angle": "45"}))
        .unwrap();
    assert_eq!(r["angle"], "45");
    let l = s.map().layer_by_name("Cities").unwrap();
    let fi = l.dataset.field_index("pop_max").unwrap();
    let big = (0..l.dataset.features.len()).find(|r| l.dataset.value(*r, fi).as_f64().is_some_and(|v| v > 1e7)).unwrap();
    let st = l.styler(None);
    assert_eq!(st.symbol(big).fill, rustgis_map::Rgba::new(255, 0, 0, 255));
    assert!(st.symbol(big).size > 4.0);
    assert_eq!(st.marker_turn(big), 45.0);
    // Drawn in an export.
    let dir = std::env::temp_dir().join(format!("rustgis-symbol-by-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "size": "nosuch + 1"}), "size: "),
        (json!({"layer": "Cities", "fill": "'red' ||"}), "fill: "),
        (json!({"layer": "Cities", "stroke": 3}), "stroke is an expression"),
        (json!({"layer": "Rivers", "angle": "10"}), "angle works on point layers"),
        (json!({"layer": "Rivers", "size": "4"}), "size works on point layers"),
    ] {
        let err = s.run("layer.symbolBy", &bad).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    assert_eq!(s.undo_depth(), depth);
    // A line's width by expression; the Cities keep theirs.
    s.run("layer.symbolBy", &json!({"layer": "Rivers", "strokeWidth": "2.5"})).unwrap();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().symbol_by.angle.as_deref(), Some("45"));
    // A key left out is kept; null removes one, and undo brings it back.
    s.run("layer.symbolBy", &json!({"layer": "Cities", "angle": null, "fill": ""})).unwrap();
    let by = &s.map().layer_by_name("Cities").unwrap().symbol_by;
    assert!(by.size.is_some() && by.fill.is_none() && by.angle.is_none());
    s.undo();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().symbol_by.angle.as_deref(), Some("45"));
}

/// Applied again by its own expression, an imported rule style keeps as many classes as it has
/// (past the first 64 values, up to the 200 an import makes); classes by an expression reading the map's scale are said to be
/// the values given without one.
#[test]
fn unique_values_by_expression_keep_their_classes_and_say_scales() {
    let mut s = world();
    let mut ds = rustgis_data::Dataset::new(
        "many",
        rustgis_data::GeometryType::Point,
        vec![rustgis_data::Field::new("v", rustgis_data::FieldType::Integer)],
    );
    let n = rustgis_map::symbology::MAX_EXPRESSION_CLASSES as i64;
    for i in 0..n {
        ds.push(Some(rustgis_data::Geometry::Point(rustgis_geom::Coord::new(i as f64 / 10.0, 1.0))), vec![rustgis_data::Value::Int(i)]);
    }
    let many = s.map_mut().add_dataset(ds);
    let rules: String =
        (0..n).map(|i| format!(r#"<rule filter="&quot;v&quot; = {i} AND &quot;v&quot; &gt;= 0" symbol="0" label="R{i:03}"/>"#)).collect();
    let qml = format!(
        r#"<qgis version="3.40.0"><renderer-v2 type="RuleRenderer"><rules key="r">{rules}</rules><symbols><symbol type="marker" name="0"><layer class="SimpleMarker" enabled="1"/></symbol></symbols></renderer-v2></qgis>"#
    );
    s.run("style.importQgis", &json!({"layer": many, "text": qml})).unwrap();
    let classes = |s: &Session| match &s.map().layer(many).unwrap().renderer {
        rustgis_map::Renderer::Unique { classes, expression: Some(_), .. } => classes.len(),
        r => panic!("{r:?}"),
    };
    assert_eq!(classes(&s), n as usize);
    let mark = s.notice_mark();
    s.run("layer.symbology", &json!({"layer": many, "type": "unique", "ramp": "Ember"})).unwrap();
    assert_eq!(classes(&s), n as usize, "every rule keeps its class, up to the limit");
    let said = |s: &Session, what: &str| s.notices_since(mark).iter().any(|n| n.text.contains(what));
    assert!(!said(&s, "past the first"), "{:?}", s.notices_since(mark));
    assert!(!said(&s, "without a map scale"));
    // An expression of its own keeps the first 64, and says so.
    s.run("layer.symbology", &json!({"layer": many, "type": "unique", "expression": "'k' || (1000 + v)"})).unwrap();
    assert_eq!(classes(&s), rustgis_map::symbology::MAX_UNIQUE);
    assert!(said(&s, "past the first 64"));
    // One reading the map's scale is classed without one, and says so.
    let mark = s.notice_mark();
    s.run(
        "layer.symbology",
        &json!({"layer": many, "type": "unique", "expression": "CASE WHEN @map_scale < 50000 THEN 'detail' ELSE 'overview' END"}),
    )
    .unwrap();
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("without a map scale")), "{:?}", s.notices_since(mark));
    // Its classes are what it gives with no scale: 'detail' only at some scales isn't one.
    let rustgis_map::Renderer::Unique { classes: kept, .. } = &s.map().layer(many).unwrap().renderer else { panic!() };
    assert_eq!(kept.iter().map(|c| c.0.as_str()).collect::<Vec<_>>(), ["overview"]);
    // So too with the scale written right after a word, which the expression still reads.
    let mark = s.notice_mark();
    s.run(
        "layer.symbology",
        &json!({"layer": many, "type": "unique", "expression": "CASE WHEN@map_scale < 50000 THEN 'detail' ELSE 'overview' END"}),
    )
    .unwrap();
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("without a map scale")), "{:?}", s.notices_since(mark));
    let rustgis_map::Renderer::Unique { classes: kept, .. } = &s.map().layer(many).unwrap().renderer else { panic!() };
    assert_eq!(kept.iter().map(|c| c.0.as_str()).collect::<Vec<_>>(), ["overview"]);
}

/// A layer of points read from GeoJSON, one for each value given, in that order: the integer
/// field `n` holds it, the text field `code` its digits, the text field `name` "h" and them.
fn numbered_points(values: &[i64]) -> Session {
    let feats: Vec<Value> = values
        .iter()
        .enumerate()
        .map(|(i, n)| {
            json!({"type": "Feature", "geometry": {"type": "Point", "coordinates": [i as f64 * 0.1, 0.0]},
                "properties": {"n": n, "code": n.to_string(), "name": format!("h{n}")}})
        })
        .collect();
    let text = json!({"type": "FeatureCollection", "features": feats}).to_string();
    let (ds, _) = rustgis_data::io::read_geojson(&text, "Herds").unwrap();
    let ty = |f: &str| ds.fields[ds.field_index(f).unwrap()].ty;
    assert_eq!(
        (ty("n"), ty("code"), ty("name")),
        (rustgis_data::FieldType::Integer, rustgis_data::FieldType::Text, rustgis_data::FieldType::Text)
    );
    let mut s = Session::new(Project::default());
    let id = s.map_mut().add_dataset(ds);
    s.active_layer = Some(id);
    s
}

fn herd_legend(s: &Session) -> Vec<String> {
    s.map().layer_by_name("Herds").unwrap().renderer.legend().into_iter().map(|e| e.label).collect()
}

fn herd_classes(s: &Session) -> Vec<String> {
    match &s.map().layer_by_name("Herds").unwrap().renderer {
        rustgis_map::Renderer::Unique { classes, .. } => classes.iter().map(|c| c.0.clone()).collect(),
        r => panic!("{r:?}"),
    }
}

/// #1340: Unique Values on an integer field lists its classes and legend by number, as on a text
/// field holding only numbers; a text field of other text keeps text order.
#[test]
fn unique_values_on_a_number_field_are_in_numeric_order() {
    let herds = [10153, 12490, 14443, 1741, 1910, 19947, 2723, 3076, 3672, 4060, 5985, 7636, 9081, 9627];
    let mut s = numbered_points(&herds);
    let mut sorted = herds.to_vec();
    sorted.sort_unstable();
    let numbers: Vec<String> = sorted.iter().map(i64::to_string).collect();
    let mut legend = numbers.clone();
    legend.push("<all other values>".into());
    for field in ["n", "code"] {
        let mark = s.notice_mark();
        s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": field})).unwrap();
        assert_eq!(herd_classes(&s), numbers, "{field}");
        assert_eq!(herd_legend(&s), legend, "{field}");
        // Every value has a class: nothing to say.
        assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("past the first")), "{:?}", s.notices_since(mark));
    }
    // A renamed class keeps its value's row.
    s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": "n"})).unwrap();
    s.run("layer.classStyle", &json!({"layer": "Herds", "value": "9627", "label": "Most"})).unwrap();
    let mut renamed = legend.clone();
    renamed[sorted.iter().position(|v| *v == 9627).unwrap()] = "Most".into();
    assert_eq!(herd_legend(&s), renamed);
    // Text: text order.
    s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": "name"})).unwrap();
    let mut names: Vec<String> = herds.iter().map(|n| format!("h{n}")).collect();
    names.sort();
    assert_eq!(herd_classes(&s), names);
    names.push("<all other values>".into());
    assert_eq!(herd_legend(&s), names);
}

/// More values than Unique Values keeps: the first by number (or by text, for text) are classes,
/// and the features past them are said, with how many, whether classed by a field or an
/// expression.
#[test]
fn unique_values_on_a_field_say_what_is_past_their_classes() {
    let max = rustgis_map::symbology::MAX_UNIQUE;
    // 100 values, each on two features, in no order.
    let values: Vec<i64> = (0..100).rev().chain(0..100).map(|i| i * 7).collect();
    let mut s = numbered_points(&values);
    let past = 2 * (100 - max);
    let first: Vec<String> = (0..max as i64).map(|i| (i * 7).to_string()).collect();
    for field in ["n", "code"] {
        let mark = s.notice_mark();
        s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": field})).unwrap();
        assert_eq!(herd_classes(&s), first, "{field}");
        let said = format!(
            "Herds: {past} features whose value is past the first {max} values of {field} (by number) are drawn as <all other values>"
        );
        assert!(s.notices_since(mark).iter().any(|n| n.text == said), "{said}\n{:?}", s.notices_since(mark));
    }
    let mark = s.notice_mark();
    s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "expression": "n"})).unwrap();
    assert_eq!(herd_classes(&s), first);
    let said = format!("Herds: {past} features whose value is past the first {max} values the expression gives (by number)");
    assert!(s.notices_since(mark).iter().any(|n| n.text.starts_with(&said)), "{:?}", s.notices_since(mark));
    // Text: the first in text order.
    let mark = s.notice_mark();
    s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": "name"})).unwrap();
    let mut names: Vec<String> = (0..100).map(|i| format!("h{}", i * 7)).collect();
    names.sort();
    assert_eq!(herd_classes(&s), names[..max]);
    let said = format!("Herds: {past} features whose value is past the first {max} values of name (in text order)");
    assert!(s.notices_since(mark).iter().any(|n| n.text.starts_with(&said)), "{:?}", s.notices_since(mark));
    // A selection of fewer values says nothing.
    let mark = s.notice_mark();
    s.run("layer.definitionQuery", &json!({"layer": "Herds", "where": "n < 300"})).unwrap();
    s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": "n"})).unwrap();
    assert_eq!(herd_classes(&s).len(), 43);
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("past the first")), "{:?}", s.notices_since(mark));
}

/// Subtypes draw the layer by Unique Values of the subtype field: past 64 values, the features
/// drawn as <all other values> are said too.
#[test]
fn subtypes_say_what_is_past_their_classes() {
    let max = rustgis_map::symbology::MAX_UNIQUE;
    let subtypes = json!([{"code": 0, "name": "None"}, {"code": 7, "name": "Seven"}]);
    let past = |s: &Session, mark| {
        s.notices_since(mark).iter().filter(|n| n.text.contains("past the first")).map(|n| n.text.clone()).collect::<Vec<_>>()
    };
    // 100 values, each on two features.
    let values: Vec<i64> = (0..100).rev().chain(0..100).map(|i| i * 7).collect();
    let mut s = numbered_points(&values);
    let mark = s.notice_mark();
    s.run("data.subtypes", &json!({"layer": "Herds", "field": "n", "subtypes": subtypes})).unwrap();
    let first: Vec<String> = (0..max as i64).map(|i| (i * 7).to_string()).collect();
    assert_eq!(herd_classes(&s), first);
    let said = format!(
        "Herds: {} features whose value is past the first {max} values of n (by number) are drawn as <all other values>",
        2 * (100 - max)
    );
    assert_eq!(past(&s, mark), [said]);
    // Only the features a definition query lets through are drawn, so only they are counted;
    // the classes still come from every feature.
    s.run("layer.definitionQuery", &json!({"layer": "Herds", "where": "n >= 600"})).unwrap();
    let mark = s.notice_mark();
    s.run("data.subtypes", &json!({"layer": "Herds", "field": "n", "subtypes": subtypes})).unwrap();
    assert_eq!(herd_classes(&s), first, "classes from every feature");
    let said = format!(
        "Herds: {} features whose value is past the first {max} values of n (by number) are drawn as <all other values>",
        2 * (100 - 600 / 7 - 1)
    );
    assert_eq!(past(&s, mark), [said]);
    s.run("layer.definitionQuery", &json!({"layer": "Herds", "where": "n < 300"})).unwrap();
    let mark = s.notice_mark();
    s.run("data.subtypes", &json!({"layer": "Herds", "field": "n", "subtypes": subtypes})).unwrap();
    assert!(past(&s, mark).is_empty(), "every drawn feature has a class");
    s.run("layer.definitionQuery", &json!({"layer": "Herds", "where": ""})).unwrap();
    // Not drawn by them, or with fewer values: nothing to say.
    let mark = s.notice_mark();
    s.run("data.subtypes", &json!({"layer": "Herds", "field": "n", "subtypes": subtypes, "symbolize": false})).unwrap();
    assert!(past(&s, mark).is_empty());
    let mut s = numbered_points(&[0, 7, 14, 7]);
    let mark = s.notice_mark();
    s.run("data.subtypes", &json!({"layer": "Herds", "field": "n", "subtypes": subtypes})).unwrap();
    assert_eq!(herd_classes(&s), ["0", "7", "14"]);
    assert!(past(&s, mark).is_empty());
}

#[test]
fn unique_values_class_by_an_expression() {
    let mut s = world();
    let e = "CASE WHEN pop_max >= 10000000 THEN 'mega' ELSE 'city' END";
    // Classed by a field that isn't the first, which clearing the expression comes back to.
    let by = s.map().layer_by_name("Cities").unwrap().dataset.fields.last().unwrap().name.clone();
    assert_ne!(Some(&by), s.map().layer_by_name("Cities").unwrap().dataset.fields.first().map(|f| &f.name));
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "field": by})).unwrap();
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "expression": e})).unwrap();
    let keys = |s: &Session| match &s.map().layer_by_name("Cities").unwrap().renderer {
        rustgis_map::Renderer::Unique { classes, .. } => classes.iter().map(|c| c.0.clone()).collect::<Vec<_>>(),
        r => panic!("{r:?}"),
    };
    let expression = |s: &Session| s.map().layer_by_name("Cities").unwrap().renderer.expression().map(str::to_string);
    assert_eq!((keys(&s), expression(&s).as_deref()), (vec!["city".to_string(), "mega".to_string()], Some(e)));
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "type": "unique", "expression": "nosuch + 1"}), "nosuch"),
        (json!({"layer": "Cities", "type": "unique", "expression": e, "field": "name"}), "not both"),
        (json!({"layer": "Cities", "type": "graduated", "expression": e}), "only Unique Values"),
        (json!({"layer": "Cities", "type": "unique", "expression": 5}), "expression is text"),
    ] {
        let err = s.run("layer.symbology", &bad).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    assert_eq!(s.undo_depth(), depth);
    // Applied again with neither a field nor an expression (another colour scheme): the same
    // expression. Null or blank goes back to a field; undo brings the expression back.
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "ramp": "Ember"})).unwrap();
    assert_eq!(expression(&s).as_deref(), Some(e));
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "expression": null})).unwrap();
    assert!(expression(&s).is_none());
    assert_eq!(s.map().layer_by_name("Cities").unwrap().renderer.field(), Some(by.as_str()), "back to the field it had");
    s.undo();
    assert_eq!(expression(&s).as_deref(), Some(e));
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "expression": "  "})).unwrap();
    assert!(expression(&s).is_none(), "blank text goes back to the field too");
    assert_eq!(s.map().layer_by_name("Cities").unwrap().renderer.field(), Some(by.as_str()));
    s.undo();
    assert_eq!(expression(&s).as_deref(), Some(e));
    // A style shared to the web says it draws one symbol; a map draws the classes.
    let dir = std::env::temp_dir().join(format!("rustgis-unique-by-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("share.webStyle", &json!({"layer": "Cities", "path": dir.join("cities.json").display().to_string()})).unwrap();
    assert!(s.notices.iter().any(|n| n.text.contains("classes by expression aren't in it")), "{:?}", s.notices.last());
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    // More values than classes: the features past them are said, with how many; a few values
    // say nothing.
    let past = |s: &Session| s.notices.iter().filter(|n| n.text.contains("past the first")).count();
    assert_eq!(past(&s), 0);
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "expression": "name"})).unwrap();
    let l = s.map().layer_by_name("Cities").unwrap();
    let (_, rest) =
        rustgis_map::Renderer::unique_by_counted(&l.dataset, &[], "name", rustgis_map::Ramp::Harbour, l.renderer.base_symbol()).unwrap();
    assert!(rest.features > 0 && !rest.by_number);
    let rest = rest.features;
    let said =
        format!("Cities: {rest} features whose value is past the first {} values the expression gives", rustgis_map::symbology::MAX_UNIQUE);
    assert!(s.notices.iter().any(|n| n.text.starts_with(&said)), "{:?}", s.notices.last());
    s.undo();
    // Shared to the web, the one symbol is one that draws: not a rest without a fill or an outline
    // width.
    let cities = s.map().layer_by_name("Cities").unwrap().id;
    let l = s.map_mut().layer_mut(cities).unwrap();
    let rustgis_map::Renderer::Unique { other, classes, .. } = &mut l.renderer else { panic!() };
    (other.fill, other.stroke, other.stroke_width) = (rustgis_map::Rgba::new(0, 0, 0, 0), rustgis_map::Rgba::rgb(9, 9, 9), 0.0);
    let first = classes[0].1.fill.hex();
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("one.json");
    s.run("share.webStyle", &json!({"layer": "Cities", "path": path.display().to_string()})).unwrap();
    let style: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    let circle = style["layers"].as_array().unwrap().iter().find(|l| l["type"] == "circle").unwrap();
    assert_eq!(circle["paint"]["circle-color"], json!(first));
    assert!(s.notices.iter().any(|n| n.text.contains("one symbol (its first class's)")), "{:?}", s.notices.last());
    // A point's rest of no size draws nothing either, however it is filled.
    let l = s.map_mut().layer_mut(cities).unwrap();
    let rustgis_map::Renderer::Unique { other, .. } = &mut l.renderer else { panic!() };
    (other.fill, other.size) = (rustgis_map::Rgba::rgb(9, 9, 9), 0.0);
    s.run("share.webStyle", &json!({"layer": "Cities", "path": path.display().to_string()})).unwrap();
    let style: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    let circle = style["layers"].as_array().unwrap().iter().find(|l| l["type"] == "circle").unwrap();
    assert_eq!(circle["paint"]["circle-color"], json!(first));
    // A line's colour is its stroke's, as the map draws it.
    let mut ds = rustgis_data::Dataset::new("ways", rustgis_data::GeometryType::Polyline, vec![]);
    ds.push(Some(rustgis_data::Geometry::Line(vec![vec![rustgis_data::Coord::new(0.0, 0.0), rustgis_data::Coord::new(1.0, 1.0)]])), vec![]);
    let ways = s.map_mut().add_dataset(ds);
    let l = s.map_mut().layer_mut(ways).unwrap();
    let mut sym = l.renderer.base_symbol();
    (sym.fill, sym.stroke) = (rustgis_map::Rgba::rgb(1, 2, 3), rustgis_map::Rgba::rgb(200, 100, 50));
    l.renderer = rustgis_map::Renderer::Single(sym);
    s.run("share.webStyle", &json!({"layer": ways, "path": path.display().to_string()})).unwrap();
    let style: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    let line = style["layers"].as_array().unwrap().iter().find(|l| l["type"] == "line").unwrap();
    assert_eq!(line["paint"]["line-color"], json!(sym.stroke.hex()));
    // By expression, a line's rest with a fill but no stroke draws nothing: the first class's.
    let mut ds = rustgis_data::Dataset::new(
        "kinds",
        rustgis_data::GeometryType::Polyline,
        vec![rustgis_data::Field::new("k", rustgis_data::FieldType::Text)],
    );
    ds.push(
        Some(rustgis_data::Geometry::Line(vec![vec![rustgis_data::Coord::new(0.0, 0.0), rustgis_data::Coord::new(1.0, 1.0)]])),
        vec![rustgis_data::Value::Text("a".into())],
    );
    let kinds = s.map_mut().add_dataset(ds);
    s.run("layer.symbology", &json!({"layer": kinds, "type": "unique", "expression": "k || 'x'"})).unwrap();
    let l = s.map_mut().layer_mut(kinds).unwrap();
    let rustgis_map::Renderer::Unique { other, classes, .. } = &mut l.renderer else { panic!() };
    (other.fill, other.stroke) = (rustgis_map::Rgba::rgb(1, 2, 3), rustgis_map::Rgba::new(0, 0, 0, 0));
    let first = classes[0].1.stroke.hex();
    s.run("share.webStyle", &json!({"layer": kinds, "path": path.display().to_string()})).unwrap();
    let style: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    let line = style["layers"].as_array().unwrap().iter().find(|l| l["type"] == "line").unwrap();
    assert_eq!(line["paint"]["line-color"], json!(first));
    std::fs::remove_dir_all(&dir).ok();
    // Deleting a field it reads: a single symbol, as for a renderer on that field, and said.
    let mark = s.notice_mark();
    let rustgis_map::Renderer::Unique { classes, .. } = &s.map().layer_by_name("Cities").unwrap().renderer else { panic!() };
    let first_fill = classes[0].1.fill;
    s.run("edit.deleteField", &json!({"layer": "Cities", "field": "pop_max"})).unwrap();
    let rustgis_map::Renderer::Single(drawn) = &s.map().layer_by_name("Cities").unwrap().renderer else { panic!() };
    assert_eq!(drawn.fill, first_fill, "drawn with the first class's symbol");
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("drawn with a single symbol")), "{:?}", s.notices_since(mark));
    // A field nothing draws by goes without a word about the symbols.
    let mark = s.notice_mark();
    s.run("edit.deleteField", &json!({"layer": "Cities", "field": "name"})).unwrap();
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("single symbol")), "{:?}", s.notices_since(mark));
}

#[test]
fn qgis_measures_in_project_units_are_left_out() {
    // QGIS's $area is in the project's units, which aren't read: left out, noted, not read as m².
    let mut s = world();
    let qml = |filter: &str| {
        format!(
            r#"<qgis version="3.40.0"><renderer-v2 type="RuleRenderer"><rules key="r">
            <rule filter="{filter}" symbol="0" label="Big"/><rule filter="&quot;pop_est&quot; &gt; 5" symbol="0" label="Kept"/></rules>
            <symbols><symbol type="fill" name="0"><layer class="SimpleFill" enabled="1"/></symbol></symbols></renderer-v2></qgis>"#
        )
    };
    let r = s.run("style.importQgis", &json!({"layer": "Countries", "text": qml("$area &gt; 2")})).unwrap();
    let said: Vec<&str> = r["notes"].as_array().unwrap().iter().filter_map(|n| n["text"].as_str()).collect();
    assert!(said.iter().any(|n| n.contains("the rule \"Big\"") && n.contains("project's units")), "{said:?}");
    // Named only in quotes, it is text: the rule reads.
    let r = s.run("style.importQgis", &json!({"layer": "Countries", "text": qml("name &lt;&gt; '$area'")})).unwrap();
    assert!(!r["notes"].to_string().contains("project's units"), "{r}");
}

/// A QGIS categorized renderer by an expression classes by it where the expression reads on the
/// layer; where it doesn't, every feature draws with the first category's symbol, noted, as before.
#[test]
fn qgis_categories_by_an_expression_class_by_it_where_it_reads() {
    let mut s = world();
    let qml = |attr: &str, cats: &str| {
        format!(
            r#"<qgis version="3.40.0"><renderer-v2 type="categorizedSymbol" attr="{attr}"><categories>{cats}</categories><symbols>
            <symbol type="marker" name="0"><layer class="SimpleMarker" enabled="1"><prop k="color" v="255,0,0,255"/></layer></symbol>
            <symbol type="marker" name="1"><layer class="SimpleMarker" enabled="1"><prop k="color" v="0,0,255,255"/></layer></symbol>
            </symbols></renderer-v2></qgis>"#
        )
    };
    let notes =
        |r: &serde_json::Value| r["notes"].as_array().unwrap().iter().map(|n| n["text"].as_str().unwrap().to_string()).collect::<Vec<_>>();
    let cats = r#"<category value="Big" symbol="0" label="Over 5 M"/><category value="" symbol="1" label="Others"/>"#;
    let big = "CASE WHEN &quot;pop_max&quot; &gt; 5000000 THEN 'Big' END";
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(big, cats)})).unwrap();
    let said = notes(&r);
    assert!(!said.iter().any(|n| n.contains("expression")), "{said:?}");
    let l = s.map().layer_by_name("Cities").unwrap();
    assert_eq!(l.renderer.expression(), Some("CASE WHEN \"pop_max\" > 5000000 THEN 'Big' END"));
    let c = l.renderer.classer(&l.dataset, None);
    let pop = l.dataset.field_index("pop_max").unwrap();
    for row in 0..l.dataset.features.len() {
        let over = l.dataset.value(row, pop).as_f64().is_some_and(|v| v > 5_000_000.0);
        assert_eq!(l.renderer.unique_class(&l.dataset, row, &c).is_some(), over, "row {row}");
    }
    // Naming a field the layer hasn't: the first category's symbol for every feature, noted
    // with the expression as QGIS wrote it.
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("upper(&quot;nosuch&quot;)", cats)})).unwrap();
    let said = notes(&r);
    assert!(
        said.iter()
            .any(|n| n.contains("upper(\"nosuch\")") && n.contains("doesn't fit the layer") && n.contains("first category's symbol")),
        "{said:?}"
    );
    let fill = |s: &Session| match &s.map().layer_by_name("Cities").unwrap().renderer {
        rustgis_map::Renderer::Single(sym) => sym.fill.0,
        other => panic!("{other:?}"),
    };
    assert_eq!(fill(&s), [255, 0, 0, 255]);
    // The first category is the first listed, "all other values" too.
    let rest_first = r#"<category value="" symbol="1"/><category value="Big" symbol="0"/>"#;
    s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("upper(&quot;nosuch&quot;)", rest_first)})).unwrap();
    assert_eq!(fill(&s), [0, 0, 255, 255]);
    // Undone, the style before.
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(fill(&s), [255, 0, 0, 255]);
    // A switched-off first category is passed over; with no category to draw, said so.
    let off_first = r#"<category value="X" symbol="1" render="false"/><category value="Big" symbol="0"/>"#;
    s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("upper(&quot;nosuch&quot;)", off_first)})).unwrap();
    assert_eq!(fill(&s), [255, 0, 0, 255]);
    let none = r#"<category value="Big" symbol="9"/>"#;
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("upper(&quot;nosuch&quot;)", none)})).unwrap();
    assert!(notes(&r).iter().any(|n| n.contains("every feature drawn as the rest, which draws nothing")), "{:?}", notes(&r));
    s.run("edit.undo", &Value::Null).unwrap();

    // A field's name with a space, as QGIS writes it (unquoted): classed by that field.
    // (Add Field takes no space; a file's field can have one.)
    s.run("edit.addField", &json!({"layer": "Cities", "name": "size_class", "type": "text"})).unwrap();
    s.run(
        "edit.calculateField",
        &json!({"layer": "Cities", "field": "size_class", "expression": "CASE WHEN pop_max > 5000000 THEN 'Big' END"}),
    )
    .unwrap();
    let id = s.map().layer_by_name("Cities").unwrap().id;
    if let Some(f) = s.map_mut().layer_mut(id).and_then(|l| l.dataset.fields.iter_mut().find(|f| f.name == "size_class")) {
        f.name = "Size Class".into();
    }
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("size class", cats)})).unwrap();
    assert!(notes(&r).is_empty(), "{:?}", notes(&r));
    let l = s.map().layer_by_name("Cities").unwrap();
    assert!(
        matches!(&l.renderer, rustgis_map::Renderer::Unique { field, expression: None, .. } if field == "Size Class"),
        "{:?}",
        l.renderer
    );
    // Each feature over five million is "Big", every other the rest.
    let picks = |l: &rustgis_map::Layer| {
        let c = l.renderer.classer(&l.dataset, None);
        let Some(pop) = l.dataset.field_index("pop_max") else { panic!("pop_max") };
        let Some(classes) = (match &l.renderer {
            rustgis_map::Renderer::Unique { classes, .. } => Some(classes.clone()),
            _ => None,
        }) else {
            panic!("{:?}", l.renderer)
        };
        (0..l.dataset.features.len())
            .map(|row| {
                let over = l.dataset.value(row, pop).as_f64().is_some_and(|v| v > 5_000_000.0);
                (over, l.renderer.unique_class(&l.dataset, row, &c).and_then(|i| classes.get(i)).map(|k| k.0.clone()))
            })
            .collect::<Vec<_>>()
    };
    let rows = picks(l);
    assert!(rows.iter().any(|r| r.0));
    for (row, (over, class)) in rows.iter().enumerate() {
        assert_eq!(class.as_deref(), over.then_some("Big"), "row {row}");
    }
    // Boolean categories (as QGIS writes them) by such a field: matching its text "true" and
    // "false" as they are, a boolean field's values as RustGIS prints them.
    let bools = r#"<category value="true" type="bool" symbol="0"/><category value="false" type="bool" symbol="1"/>"#;
    // (A bare name is a field to the importer itself; one with a space is matched here.)
    for (ty, name) in [("text", "Is Big"), ("boolean", "Big Flag"), ("boolean", "big_bool")] {
        let tmp = name.replace(' ', "_");
        s.run("edit.addField", &json!({"layer": "Cities", "name": tmp, "type": ty})).unwrap();
        let e = if ty == "text" { "CASE WHEN pop_max > 5000000 THEN 'true' ELSE 'false' END" } else { "pop_max > 5000000" };
        s.run("edit.calculateField", &json!({"layer": "Cities", "field": tmp, "expression": e})).unwrap();
        if let Some(f) = s.map_mut().layer_mut(id).and_then(|l| l.dataset.fields.iter_mut().find(|f| f.name == tmp)) {
            f.name = name.into();
        }
        let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(name, bools)})).unwrap();
        assert!(notes(&r).is_empty(), "{:?}", notes(&r));
        let rows = picks(s.map().layer_by_name("Cities").unwrap());
        let (yes, no) = if ty == "text" { ("true", "false") } else { ("True", "False") };
        for (row, (over, class)) in rows.iter().enumerate() {
            assert_eq!(class.as_deref(), Some(if *over { yes } else { no }), "{ty} {name} row {row}");
        }
    }
    // A text category "True" beside boolean ones by a text field: each keeps its own value, the
    // boolean ones matching the field's "true" and "false", the text one only "True".
    let mixed = format!(r#"<category value="True" type="string" symbol="1" label="Text"/>{bools}"#);
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("Is Big", &mixed)})).unwrap();
    assert!(notes(&r).is_empty(), "{:?}", notes(&r));
    let l = s.map().layer_by_name("Cities").unwrap();
    let rustgis_map::Renderer::Unique { classes, class_labels, .. } = &l.renderer else { panic!("{:?}", l.renderer) };
    assert_eq!(classes.iter().map(|c| c.0.as_str()).collect::<Vec<_>>(), ["True", "true", "false"], "{:?}", notes(&r));
    assert_eq!(class_labels.get("True").map(String::as_str), Some("Text"));
    for (row, (over, class)) in picks(l).iter().enumerate() {
        assert_eq!(class.as_deref(), Some(if *over { "true" } else { "false" }), "mixed row {row}");
    }
    // By an expression, boolean categories match its value as RustGIS prints it.
    let by_expr = "&quot;pop_max&quot; &gt; 5000000";
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(by_expr, bools)})).unwrap();
    assert!(notes(&r).is_empty(), "{:?}", notes(&r));
    for (row, (over, class)) in picks(s.map().layer_by_name("Cities").unwrap()).iter().enumerate() {
        assert_eq!(class.as_deref(), Some(if *over { "True" } else { "False" }), "expression row {row}");
    }
    // ... unless another category has that value: kept as written, said once with a count.
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(by_expr, &mixed)})).unwrap();
    let said = notes(&r);
    assert!(said.iter().any(|n| n.contains("1 boolean category kept as written (the first: true), as another category")), "{said:?}");
    let l = s.map().layer_by_name("Cities").unwrap();
    let rustgis_map::Renderer::Unique { classes, .. } = &l.renderer else { panic!("{:?}", l.renderer) };
    assert_eq!(classes.iter().map(|c| c.0.as_str()).collect::<Vec<_>>(), ["True", "true", "False"]);
    // ... or when two categories list the value: drawn as the rest, said.
    let twice = r#"<category value="true" type="bool" symbol="0"/><category value="true" type="bool" symbol="1"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(by_expr, twice)})).unwrap());
    assert!(said.iter().any(|n| n.contains("its value listed by more than one category: its features drawn as the rest")), "{said:?}");

    // The layer's own classes by an expression are left alone by a style that sets no renderer,
    // even one an import couldn't take (it measures: QGIS's measures are in the project's units).
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "unique", "expression": "CASE WHEN $area >= 0 THEN 'Big' END"}))
        .unwrap();
    assert!(s.map().layer_by_name("Countries").unwrap().renderer.expression().is_some_and(|e| e.contains("$area")));
    let before = s.map().layer_by_name("Countries").unwrap().renderer.clone();
    let labels_only = r#"<qgis version="3.40.0"><renderer-v2 type="heatmapRenderer"/></qgis>"#;
    s.run("style.importQgis", &json!({"layer": "Countries", "text": labels_only})).unwrap();
    assert_eq!(s.map().layer_by_name("Countries").unwrap().renderer, before);
}

#[test]
fn qgis_rules_class_features_and_say_which_several_rules_pick() {
    let mut s = world();
    let qml = |rules: &str| {
        format!(
            r#"<qgis version="3.40.0"><renderer-v2 type="RuleRenderer"><rules key="r">{rules}</rules><symbols>
            <symbol type="marker" name="0"><layer class="SimpleMarker" enabled="1"><prop k="color" v="255,0,0,255"/></layer></symbol>
            <symbol type="marker" name="1"><layer class="SimpleMarker" enabled="1"><prop k="color" v="0,0,255,255"/></layer></symbol>
            </symbols></renderer-v2></qgis>"#
        )
    };
    let notes =
        |r: &serde_json::Value| r["notes"].as_array().unwrap().iter().map(|n| n["text"].as_str().unwrap().to_string()).collect::<Vec<_>>();
    // Every city of more than a million picks both rules, at the same scales.
    let big = s.map().layer_by_name("Cities").unwrap();
    let both = (0..big.dataset.features.len())
        .filter(|r| big.dataset.field_index("pop_max").and_then(|f| big.dataset.value(*r, f).as_f64()).is_some_and(|v| v > 5_000_000.0))
        .count();
    assert!(both > 0);
    let rules = r#"<rule filter="&quot;pop_max&quot; &gt; 1000000 AND length(name) &gt; 0" symbol="0" label="Million"/>
        <rule filter="&quot;pop_max&quot; &gt; 5000000" symbol="1" label="Five"/>"#;
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(rules)})).unwrap();
    let said = notes(&r);
    assert!(said.iter().any(|n| n.contains(&format!("{both} features that more than one of its rules picks"))), "{said:?}");
    let l = s.map().layer_by_name("Cities").unwrap();
    assert!(l.renderer.expression().is_some_and(|e| e.contains("THEN 'Million'")), "{:?}", l.renderer);
    // At scales that never meet, nothing is said.
    let apart = r#"<rule filter="&quot;pop_max&quot; &gt; 1000000 AND length(name) &gt; 0" symbol="0" scalemaxdenom="10000"/>
        <rule filter="&quot;pop_max&quot; &gt; 5000000" symbol="1" scalemindenom="20000"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(apart)})).unwrap());
    assert!(!said.iter().any(|n| n.contains("more than one")), "{said:?}");
    // Rules reading the map's scale can't be counted at no scale: said without a count.
    let scaled = r#"<rule filter="$scale &gt; 0 AND &quot;pop_max&quot; &gt; 1000000" symbol="0"/>
        <rule filter="&quot;pop_max&quot; &gt; 5000000" symbol="1"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(scaled)})).unwrap());
    assert!(said.iter().any(|n| n.contains("features that more than one of its rules picks (if any)")), "{said:?}");
    // The scale named only in quotes is text: counted.
    let quoted = r#"<rule filter="&quot;pop_max&quot; &gt; 1000000 AND name &lt;&gt; '@map_scale'" symbol="0"/>
        <rule filter="&quot;pop_max&quot; &gt; 5000000" symbol="1"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(quoted)})).unwrap());
    assert!(said.iter().any(|n| n.contains(&format!("{both} features that more than one of its rules picks"))), "{said:?}");
    // Only the features its definition query keeps are counted.
    let cities = s.map().layer_by_name("Cities").unwrap();
    let shown = (0..cities.dataset.features.len())
        .filter(|r| {
            cities.dataset.field_index("pop_max").and_then(|f| cities.dataset.value(*r, f).as_f64()).is_some_and(|v| v > 10_000_000.0)
        })
        .count();
    assert!(shown > 0 && shown < both);
    s.run("layer.definitionQuery", &json!({"layer": "Cities", "where": "pop_max > 10000000"})).unwrap();
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(rules)})).unwrap());
    assert!(said.iter().any(|n| n.contains(&format!("{shown} features that more than one of its rules picks"))), "{said:?}");
    s.run("layer.definitionQuery", &json!({"layer": "Cities", "where": ""})).unwrap();
    // An else rule picks what its siblings don't: nothing two rules pick.
    let rest = r#"<rule filter="&quot;pop_max&quot; &gt; 0"><rule filter="&quot;pop_max&quot; &lt; 1000000" symbol="0"/><rule filter="ELSE" symbol="1"/></rule>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(rest)})).unwrap());
    assert!(!said.iter().any(|n| n.contains("more than one")), "{said:?}");
    // A rule whose filter names a field the layer hasn't: left out by its label, the others kept.
    let gone = r#"<rule filter="&quot;nosuch&quot; + 1 &gt; 2" symbol="0" label="Gone"/><rule filter="&quot;pop_max&quot; &gt; 5" symbol="1" label="Kept"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(gone)})).unwrap());
    assert!(said.iter().any(|n| n.contains("the rule \"Gone\"") && n.contains("nosuch")), "{said:?}");
    // Several that don't fit: one note, with how many and the first.
    let two = format!("{gone}<rule filter=\"&quot;nosuch2&quot; = 1\" symbol=\"0\" label=\"Gone too\"/>");
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(&two)})).unwrap());
    assert_eq!(said.iter().filter(|n| n.contains("fit the layer")).count(), 1, "{said:?}");
    assert!(said.iter().any(|n| n.contains("2 rules whose filters don't fit the layer, the first \"Gone\"")), "{said:?}");
    s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(gone)})).unwrap();
    let l = s.map().layer_by_name("Cities").unwrap();
    let rustgis_map::Renderer::Unique { classes, expression: Some(e), .. } = &l.renderer else { panic!("{:?}", l.renderer) };
    assert_eq!((classes.len(), classes[0].0.as_str()), (1, "Kept"));
    assert!(!e.contains("nosuch"), "{e}");
    let styler = l.styler(Some(1e6));
    let drawn = (0..l.dataset.features.len()).filter(|r| styler.symbol(*r).fill == rustgis_map::Rgba::rgb(0, 0, 255)).count();
    assert!(drawn > 0, "the kept rule draws");
    // None that reads: the first rule's symbol for every feature, as before rules were classed.
    let none = r#"<rule filter="&quot;nosuch&quot; = 1" symbol="1"/><rule filter="$area &gt; 2" symbol="0"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(none)})).unwrap());
    assert!(said.iter().any(|n| n.contains("none of whose filters fit the layer")), "{said:?}");
    let l = s.map().layer_by_name("Cities").unwrap();
    assert!(matches!(l.renderer, rustgis_map::Renderer::Single(sym) if sym.fill == rustgis_map::Rgba::rgb(0, 0, 255)), "{:?}", l.renderer);
    // A layer's filter that is an expression now carries over.
    let filtered = r#"<qgis version="3.40.0"><labeling type="rule-based"><rules key="r">
        <rule filter="length(&quot;name&quot;) &lt;= 5"><settings><text-style fieldName="name"/></settings></rule></rules></labeling></qgis>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": filtered})).unwrap());
    assert!(said.is_empty(), "{said:?}");
    let l = s.map().layer_by_name("Cities").unwrap();
    assert_eq!(l.labels.classes.first().and_then(|c| c.where_.as_deref()), Some("length(\"name\") <= 5"));
}

#[test]
fn labels_are_set_by_expressions() {
    let mut s = world();
    let r = s
        .run(
            "labels.by",
            &json!({"layer": "Cities", "text": "upper(name)", "size": "scale_linear(pop_max, 0, 2e7, 8, 20)", "color": "if(pop_max > 1e7, '#ff0000', NULL)", "angle": "30"}),
        )
        .unwrap();
    assert_eq!((r["text"].as_str(), r["angle"].as_str()), (Some("upper(name)"), Some("30")));
    let l = s.map().layer_by_name("Cities").unwrap();
    assert!(l.labels.enabled, "a text expression turns the labels on");
    assert_eq!(l.labels.default.by.color.as_deref(), Some("if(pop_max > 1e7, '#ff0000', NULL)"));
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "text": "nosuch || 'x'"}), "text: "),
        (json!({"layer": "Cities", "size": "("}), "size: "),
        (json!({"layer": "Cities", "color": 3}), "color is an expression"),
        (json!({"layer": "Cities", "class": "Nope", "angle": "4"}), "no label class named"),
        (json!({"layer": "Cities"}), "give text, size, color or angle"),
    ] {
        let err = s.run("labels.by", &bad).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    assert_eq!(s.undo_depth(), depth);
    // A class's own; a key left out is kept, null removes one, and undo brings it back.
    s.run("labels.class.add", &json!({"layer": "Cities", "name": "Big", "where": "pop_max > 5000000"})).unwrap();
    s.run("labels.by", &json!({"layer": "Cities", "class": "Big", "text": "name || '!'"})).unwrap();
    s.run("labels.by", &json!({"layer": "Cities", "angle": null, "text": ""})).unwrap();
    let l = s.map().layer_by_name("Cities").unwrap();
    assert_eq!(l.labels.classes[0].by.text.as_deref(), Some("name || '!'"));
    assert!(l.labels.default.by.text.is_none() && l.labels.default.by.angle.is_none() && l.labels.default.by.size.is_some());
    s.undo();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().labels.default.by.angle.as_deref(), Some("30"));
    // A style shared to the web says its label expressions are left out.
    let dir = std::env::temp_dir().join(format!("rustgis-labels-by-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("share.webStyle", &json!({"layer": "Cities", "path": dir.join("cities.json").display().to_string()})).unwrap();
    assert!(s.notices.iter().any(|n| n.text.contains("label expressions aren't in it")), "{:?}", s.notices.last());
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    // Converted, each label keeps its text, size and colour: the annotation draws by its fields.
    s.run("labels.class.clear", &json!({"layer": "Cities"})).unwrap();
    s.run("labels.by", &json!({"layer": "Cities", "text": "upper(name)", "angle": null})).unwrap();
    s.run("labels.convert", &json!({"layer": "Cities"})).unwrap();
    let a = s.map().layer_by_name("Cities Annotation").unwrap();
    let names: Vec<&str> = a.dataset.fields.iter().map(|f| f.name.as_str()).collect();
    assert_eq!(names, ["TEXT", "SIZE", "COLOR"]);
    let by = &a.labels.default.by;
    assert_eq!(
        (by.text.as_deref(), by.size.as_deref(), by.color.as_deref(), by.angle.as_deref()),
        (None, Some("\"SIZE\""), Some("\"COLOR\""), None)
    );
    let fi = |n: &str| a.dataset.field_index(n).unwrap();
    let paris = (0..a.dataset.features.len()).find(|r| a.dataset.value(*r, fi("TEXT")).to_string() == "PARIS").expect("upper-case text");
    assert!(a.dataset.value(paris, fi("SIZE")).as_f64().is_some_and(|v| v > 8.0));
    let red = (0..a.dataset.features.len()).filter(|r| a.dataset.value(*r, fi("COLOR")).to_string() == "255,0,0,255").count();
    assert!(red > 0 && red < a.dataset.features.len(), "only the big cities' red, the rest the class's");
    assert!(!s.notices.iter().any(|n| n.text.contains("cut to")), "short texts aren't cut");
}

/// What label expressions lose is said, and what's reported or kept follows what the map draws:
/// a text cut by Convert To Annotation, the Web Style's notices, Project Info's labels, and the
/// angle a converted label keeps, decided for each feature.
#[test]
fn label_expressions_say_what_they_lose() {
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value as Attr};
    let mut s = world();
    let cities = s.map().layer_by_name("Cities").unwrap().id;
    // A text past its most characters is cut, said once with a count.
    let long = format!("name || '{}'", "x".repeat(rustgis_map::label_by::MAX_LABEL_TEXT));
    s.run("labels.by", &json!({"layer": "Cities", "text": long})).unwrap();
    let n = s.run("labels.convert", &json!({"layer": "Cities"})).unwrap()["annotations"].as_u64().unwrap();
    let said = format!("Cities Annotation: {n} label texts cut to {} characters", rustgis_map::label_by::MAX_LABEL_TEXT);
    assert!(s.notices.iter().any(|x| x.text == said), "{:?}", s.notices.last());
    s.undo();
    // Project Info names the text expression the labels draw by, and the field once it doesn't read.
    s.map_mut().layer_mut(cities).unwrap().labels.default.field = "name".into();
    s.run("labels.by", &json!({"layer": "Cities", "text": "upper(name)"})).unwrap();
    let labels = |s: &mut Session| {
        let info = s.run("info.project", &Value::Null).unwrap();
        info["layers"].as_array().unwrap().iter().find(|l| l["name"] == "Cities").unwrap()["labels"].clone()
    };
    assert_eq!(labels(&mut s), json!("upper(name)"));
    s.map_mut().layer_mut(cities).unwrap().labels.default.by.text = Some("upper(gone)".into());
    assert_eq!(labels(&mut s), json!("name"));
    // Deleting the field Default labels by keeps the labels while its text expression reads, and
    // starts Default again (labels off) once it doesn't.
    s.run("edit.addField", &json!({"layer": "Cities", "name": "spare", "type": "text"})).unwrap();
    for (text, on) in [("'#' || pop_max", true), ("upper(spare)", false)] {
        let l = s.map_mut().layer_mut(cities).unwrap();
        (l.labels.enabled, l.labels.default.field, l.labels.default.by.text) = (true, "spare".into(), Some(text.into()));
        s.run("edit.deleteField", &json!({"layer": "Cities", "field": "spare"})).unwrap();
        let l = s.map().layer(cities).unwrap();
        assert_eq!(l.labels.enabled, on, "{text}");
        assert_eq!(l.labels.default.by.text.is_some(), on, "{text}");
        assert!(l.labels.default.field != "spare");
        s.undo();
    }
    s.map_mut().layer_mut(cities).unwrap().labels.default.by.text = Some("upper(name)".into());
    // Web Style: a Default class labelling by a text expression alone says only that its style has
    // none, even with other classes; one with a size but no text or field says nothing of it.
    let dir = std::env::temp_dir().join(format!("rustgis-labels-lose-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let share = |s: &mut Session| {
        let before = s.notices.len();
        s.run("share.webStyle", &json!({"layer": "Cities", "path": dir.join("c.json").display().to_string()})).unwrap();
        s.notices[before..].iter().map(|n| n.text.clone()).collect::<Vec<_>>()
    };
    let l = s.map_mut().layer_mut(cities).unwrap();
    l.labels.default.field.clear();
    l.labels.default.by.text = Some("upper(name)".into());
    s.run("labels.class.add", &json!({"layer": "Cities", "name": "Big", "where": "pop_max > 5000000"})).unwrap();
    // Project Info lists each class's text expression with its field.
    s.run("labels.by", &json!({"layer": "Cities", "class": "Big", "text": "name || '!'"})).unwrap();
    let info = s.run("info.project", &Value::Null).unwrap();
    let classes = &info["layers"].as_array().unwrap().iter().find(|l| l["name"] == "Cities").unwrap()["labelClasses"];
    assert_eq!(classes[0]["text"], json!("name || '!'"), "{classes}");
    let said = share(&mut s);
    assert!(said.iter().any(|t| t.contains("has no labels: its Default class's text is an expression")), "{said:?}");
    assert!(!said.iter().any(|t| t.contains("labels every feature")), "{said:?}");
    let l = s.map_mut().layer_mut(cities).unwrap();
    (l.labels.default.by.text, l.labels.default.by.size) = (None, Some("8".into()));
    let said = share(&mut s);
    assert!(said.iter().any(|t| t.contains("has no labels: its Default class has no label field")), "{said:?}");
    assert!(!said.iter().any(|t| t.contains("expression") || t.contains("labels every feature")), "{said:?}");
    std::fs::remove_dir_all(&dir).ok();
    // A converted label keeps its angle on a point, and none on a line it is placed along, in a
    // layer of both; a layer of lines alone gets no ANGLE field.
    let line = Geometry::Line(vec![vec![Coord::new(0.0, 0.0), Coord::new(5.0, 0.0)]]);
    let point = Geometry::Point(Coord::new(1.0, 1.0));
    for (geoms, angles) in [(vec![line.clone(), point], Some(vec![Attr::Null, Attr::Float(30.0)])), (vec![line], None)] {
        let mut ds = Dataset::new("ways", GeometryType::Polyline, vec![Field::new("name", FieldType::Text)]);
        for g in geoms {
            ds.push(Some(g), vec![Attr::Text("w".into())]);
        }
        let id = s.map_mut().add_dataset(ds);
        let l = s.map_mut().layer_mut(id).unwrap();
        (l.labels.enabled, l.labels.default.field, l.labels.default.placement) =
            (true, "name".into(), rustgis_map::LabelPlacement::Parallel);
        l.labels.default.by.angle = Some("30".into());
        let a = s.run("labels.convert", &json!({"layer": id})).unwrap()["layer"].as_u64().unwrap() as u32;
        let a = &s.map().layer(a).unwrap().dataset;
        let got = a.field_index("ANGLE").map(|fi| (0..a.features.len()).map(|r| a.value(r, fi).clone()).collect::<Vec<_>>());
        assert_eq!(got, angles);
    }
}

#[test]
fn a_qgis_styles_data_defined_settings_are_kept_where_they_read() {
    let mut s = world();
    // Size by a field Cities has; fill by a QGIS function RustGIS lacks; outline by a field it hasn't.
    let dd = |name: &str, expr: &str| {
        format!(
            r#"<Option type="Map" name="{name}"><Option value="true" type="bool" name="active"/><Option value="{expr}" type="QString" name="expression"/><Option value="3" type="int" name="type"/></Option>"#
        )
    };
    let qml = format!(
        r#"<qgis version="3.40.0"><renderer-v2 type="singleSymbol"><symbols><symbol type="marker" name="0" alpha="1">
        <layer class="SimpleMarker" enabled="1"><Option type="Map"><Option name="name" value="circle"/><Option name="size_unit" value="Pixel"/></Option>
        <data_defined_properties><Option type="Map"><Option type="Map" name="properties">{}{}{}</Option></Option></data_defined_properties></layer>
        </symbol></symbols></renderer-v2></qgis>"#,
        dd("size", "&quot;pop_max&quot; / 1e6"),
        dd("fillColor", "set_color_part(@symbol_color, 'value', 40)"),
        dd("outlineColor", "&quot;nosuch&quot;"),
    );
    let out = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml})).unwrap();
    let by = &s.map().layer_by_name("Cities").unwrap().symbol_by;
    assert_eq!((by.size.as_deref(), &by.fill, &by.stroke), (Some(r#""pop_max" / 1e6"#), &None, &None), "{by:?}");
    let notes = serde_json::to_string(&out["notes"]).unwrap();
    assert!(
        notes.contains("data-defined symbol fill colour `set_color_part") && notes.contains("outline colour `\\\"nosuch\\\"`"),
        "{notes}"
    );
}

#[test]
fn a_stroke_is_dashed_by_command() {
    let mut s = world();
    let stroke = |dash: Value| json!({"layer": "Rivers", "strokes": [{"color": "#000000", "width": 2, "dash": dash}]});
    s.run("layer.lineStrokes", &stroke(json!([4, 2.5]))).unwrap();
    let dash = |s: &Session| s.map().layer_by_name("Rivers").unwrap().line_strokes[0].dash.map(|d| d.steps().to_vec());
    assert_eq!(dash(&s), Some(vec![4.0, 2.5]));
    let depth = s.undo_depth();
    for bad in [json!([]), json!([0, 0]), json!([-1, 2]), json!([1, "2"]), json!("4 2"), json!([1, 1, 1, 1, 1, 1, 1, 1, 1]), json!([1e9])] {
        assert!(s.run("layer.lineStrokes", &stroke(bad.clone())).is_err(), "{bad}");
    }
    assert_eq!((s.undo_depth(), dash(&s)), (depth, Some(vec![4.0, 2.5])), "a refused pattern changes nothing");
    s.run("layer.lineStrokes", &stroke(Value::Null)).unwrap();
    assert_eq!(dash(&s), None, "null: solid");
}

#[test]
fn a_class_stacks_strokes_of_its_own() {
    use rustgis_map::symbology::ClassRef;
    use rustgis_map::{LineStroke, Rgba};
    let mut s = world();
    s.run("layer.symbology", &json!({"layer": "Rivers", "type": "unique", "field": "scalerank"})).unwrap();
    // The layer's one stroke, a casing and core for rivers of rank 1, a thin line for
    // <all other values>; rank 2 keeps the layer's.
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [{"offset": 3}]})).unwrap();
    let depth = s.undo_depth();
    let pair = json!([{"color": "#000000", "width": 6}, {"color": "#FF8C00", "width": 3}]);
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "value": "1", "strokes": pair})).unwrap();
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "other": true, "strokes": [{"width": 0.5}]})).unwrap();
    assert_eq!(s.undo_depth(), depth + 2);
    let casing = vec![
        LineStroke { color: Some(Rgba::rgb(0, 0, 0)), width: Some(6.0), ..Default::default() },
        LineStroke { color: Some(Rgba::rgb(0xFF, 0x8C, 0)), width: Some(3.0), ..Default::default() },
    ];
    let layer_own = vec![LineStroke { offset: 3.0, ..Default::default() }];
    let check = |s: &Session| {
        let l = s.map().layer_by_name("Rivers").unwrap();
        let fi = l.dataset.field_index("scalerank").unwrap();
        assert!(l.has_strokes());
        for row in 0..l.dataset.features.len() {
            let want = if l.dataset.value(row, fi).to_string() == "1" { &casing } else { &layer_own };
            assert_eq!(l.strokes(row), want.as_slice(), "row {row}");
            // Classed once, the same as asked apart.
            assert_eq!(l.style(row), (l.symbol(row), want.as_slice()), "row {row}");
        }
        assert_eq!(l.renderer.class_strokes(&ClassRef::Other).unwrap().len(), 1);
    };
    check(&s);
    // A number names the class as the data prints it.
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "value": 1, "strokes": pair})).unwrap();
    check(&s);
    // Kept in the project file, and through applying the same symbology again.
    let dir = std::env::temp_dir().join(format!("rustgis-class-strokes-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("strokes.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    check(&t);
    let png = dir.join("map.png");
    t.run("share.exportMap", &json!({"path": png.display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    s.run("layer.symbology", &json!({"layer": "Rivers", "type": "unique", "field": "scalerank", "ramp": "Ember"})).unwrap();
    check(&s);
    // Junk, a class that isn't there, or a class on the wrong renderer: refused, nothing changes.
    let depth = s.undo_depth();
    for bad in [
        json!({"layer": "Rivers", "value": "7", "strokes": pair}),
        json!({"layer": "Rivers", "index": 0, "strokes": pair}),
        json!({"layer": "Rivers", "value": "1", "index": 0, "strokes": pair}),
        json!({"layer": "Rivers", "value": [1], "strokes": pair}),
        json!({"layer": "Rivers", "value": "1", "strokes": vec![json!({}); 17]}),
        json!({"layer": "Rivers", "value": "1", "strokes": [{"cap": "pointy"}]}),
        json!({"layer": "Cities", "value": "1", "strokes": []}),
    ] {
        assert!(s.run("layer.lineStrokes", &bad).is_err(), "{bad}");
    }
    assert_eq!(s.undo_depth(), depth);
    // [] gives the class back to the layer's strokes; undo brings its own back.
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "value": "1", "strokes": []})).unwrap();
    assert!(s.map().layer_by_name("Rivers").unwrap().strokes(0).iter().all(|st| st.offset == 3.0));
    s.run("edit.undo", &Value::Null).unwrap();
    check(&s);
    // Another field starts fresh.
    s.run("layer.symbology", &json!({"layer": "Rivers", "type": "unique", "field": "name"})).unwrap();
    assert!(!s.map().layer_by_name("Rivers").unwrap().renderer.has_class_strokes());
    // Graduated Colors classes go by index; a single symbol has no classes.
    s.run("layer.symbology", &json!({"layer": "Rivers", "type": "graduated", "field": "scalerank", "classes": 2})).unwrap();
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "index": 0, "strokes": pair})).unwrap();
    assert_eq!(s.map().layer_by_name("Rivers").unwrap().renderer.class_strokes(&ClassRef::Index(0)).unwrap(), casing.as_slice());
    assert!(s.run("layer.lineStrokes", &json!({"layer": "Rivers", "index": 9, "strokes": pair})).is_err());
    assert!(s.run("layer.lineStrokes", &json!({"layer": "Rivers", "value": "1", "strokes": pair})).is_err());
    s.run("layer.symbology", &json!({"layer": "Rivers", "type": "single"})).unwrap();
    assert!(s.run("layer.lineStrokes", &json!({"layer": "Rivers", "index": 0, "strokes": pair})).is_err());
}

#[test]
fn strokes_draw_in_levels() {
    let mut s = world();
    let depth = s.undo_depth();
    let strokes = json!([{"color": "#000000", "width": 6, "level": 2}, {"color": "#FFFFFF", "width": 2}]);
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": strokes})).unwrap();
    s.run("layer.strokeLevels", &json!({"layer": "Rivers", "on": true})).unwrap();
    assert_eq!(s.undo_depth(), depth + 2);
    let check = |s: &Session| {
        let l = s.map().layer_by_name("Rivers").unwrap();
        assert!(l.stroke_levels);
        assert_eq!(l.line_strokes[0].level, Some(2));
        // Without a level of its own, a stroke draws at its place in the stack.
        assert_eq!((l.line_strokes[0].level_at(0), l.line_strokes[1].level_at(1)), (2, 1));
    };
    check(&s);
    let dir = std::env::temp_dir().join(format!("rustgis-stroke-levels-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("levels.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    check(&t);
    t.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    let depth = s.undo_depth();
    for (id, bad) in [
        ("layer.lineStrokes", json!({"layer": "Rivers", "strokes": [{"level": 256}]})),
        ("layer.lineStrokes", json!({"layer": "Rivers", "strokes": [{"level": -1}]})),
        ("layer.lineStrokes", json!({"layer": "Rivers", "strokes": [{"level": 1.5}]})),
        ("layer.lineStrokes", json!({"layer": "Rivers", "strokes": [{"level": "top"}]})),
        ("layer.strokeLevels", json!({"layer": "Rivers"})),
        ("layer.strokeLevels", json!({"layer": "Cities", "on": true})),
    ] {
        assert!(s.run(id, &bad).is_err(), "{id} {bad}");
    }
    assert_eq!(s.undo_depth(), depth);
    s.run("layer.strokeLevels", &json!({"layer": "Rivers", "on": false})).unwrap();
    assert!(!s.map().layer_by_name("Rivers").unwrap().stroke_levels);
    s.run("edit.undo", &Value::Null).unwrap();
    check(&s);
}

#[test]
fn a_reference_scale_is_set_kept_and_undone() {
    let mut s = world();
    let depth = s.undo_depth();
    s.run("layer.referenceScale", &json!({"layer": "Rivers", "scale": 25000})).unwrap();
    // "current" takes the map's scale, rounded.
    let now = s.map().scale().round();
    s.run("layer.referenceScale", &json!({"layer": "Cities", "scale": "current"})).unwrap();
    assert_eq!(s.undo_depth(), depth + 2);
    let check = |s: &Session| {
        let at = |n: &str| s.map().layer_by_name(n).unwrap().reference_scale;
        assert_eq!((at("Rivers"), at("Cities"), at("Lakes")), (Some(25000.0), Some(now), None));
    };
    check(&s);
    let dir = std::env::temp_dir().join(format!("rustgis-reference-scale-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("reference.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    check(&t);
    t.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    let depth = s.undo_depth();
    for bad in [
        json!({"layer": "Rivers", "scale": 0}),
        json!({"layer": "Rivers", "scale": -25000}),
        json!({"layer": "Rivers", "scale": 1e12}),
        json!({"layer": "Rivers", "scale": "big"}),
        json!({"layer": "Rivers", "scale": [25000]}),
        json!({"layer": "Nowhere", "scale": 25000}),
    ] {
        assert!(s.run("layer.referenceScale", &bad).is_err(), "{bad}");
    }
    assert_eq!(s.undo_depth(), depth);
    s.run("layer.referenceScale", &json!({"layer": "Rivers", "scale": null})).unwrap();
    assert_eq!(s.map().layer_by_name("Rivers").unwrap().reference_scale, None);
    s.run("edit.undo", &Value::Null).unwrap();
    check(&s);
}

#[test]
fn rivers_are_labelled_along_their_lines_in_italics() {
    let mut s = world();
    s.run("labels.field", &json!({"layer": "Rivers", "field": "name"})).unwrap();
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "curved"})).unwrap();
    s.run("labels.style", &json!({"layer": "Rivers", "italic": true})).unwrap();
    let check = |s: &Session| {
        let c = &s.map().layer_by_name("Rivers").unwrap().labels.default;
        assert_eq!((c.placement, c.italic), (rustgis_map::LabelPlacement::Curved, true));
    };
    check(&s);
    let dir = std::env::temp_dir().join(format!("rustgis-line-labels-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("labels.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    check(&t);
    t.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "parallel"})).unwrap();
    assert_eq!(s.map().layer_by_name("Rivers").unwrap().labels.default.placement, rustgis_map::LabelPlacement::Parallel);
    // Not slanted unless asked: a project from before reads as upright.
    s.run("labels.style", &json!({"layer": "Rivers", "italic": false})).unwrap();
    let text = serde_json::to_string(&s.map().layer_by_name("Rivers").unwrap().labels).unwrap();
    assert!(!text.contains("italic"), "{text}");
}

#[test]
fn a_qgis_project_in_degrees_opens_in_equirectangular() {
    // QGIS draws a project in degrees as plate carrée, longitude and latitude as x and y.
    // A PROJ string goes where QGIS keeps it for a system without an authority code.
    let qgs = |crs: &str| {
        let tag = if crs.starts_with('+') { "proj4" } else { "authid" };
        format!(
            r#"<qgis version="3.10.0"><title>World</title><projectCrs><spatialrefsys><{tag}>{crs}</{tag}></spatialrefsys></projectCrs>
  <mapcanvas name="theMapCanvas"><extent><xmin>5</xmin><ymin>45</ymin><xmax>15</xmax><ymax>50</ymax></extent></mapcanvas><projectlayers/></qgis>"#
        )
    };
    let mut s = world();
    for (crs, datum_note) in [
        ("EPSG:4326", false),
        ("EPSG:4258", false),
        ("OGC:CRS84", false),
        ("EPSG:4314", true),
        // Saved without an authority code: its PROJ string.
        ("+proj=longlat +datum=WGS84 +no_defs", false),
        ("+proj=longlat +datum=WGS84 +pm=0.0 +no_defs", false),
        ("+proj=longlat +ellps=bessel +towgs84=598.1,73.7,418.2,0.202,0.045,-2.455,6.7 +no_defs", true),
    ] {
        let out = s.run("project.importQgis", &json!({"text": qgs(crs)})).unwrap();
        assert_eq!(s.map().projection.code(), "equirectangular", "{crs}");
        let text = serde_json::to_string(&out["notes"]).unwrap();
        assert!(!text.contains("Web Mercator"), "{crs}: {text}");
        assert_eq!(text.contains("drawn in Equirectangular on WGS 84"), datum_note, "{crs}: {text}");
        // The saved view, read in degrees.
        let c = s.map().to_lonlat(s.map().camera.center).unwrap();
        assert!((c.x - 10.0).abs() < 0.5 && (c.y - 47.5).abs() < 0.5, "{crs}: {c:?}");
    }
    // Longitudes from Paris (in grads): drawn the same way, the view left to the data.
    let out = s.run("project.importQgis", &json!({"text": qgs("EPSG:4807")})).unwrap();
    assert_eq!(s.map().projection.code(), "equirectangular");
    let text = serde_json::to_string(&out["notes"]).unwrap();
    assert!(text.contains("on WGS 84") && text.contains("from Greenwich"), "{text}");
    // A projected one keeps its own projection.
    s.run("project.importQgis", &json!({"text": qgs("EPSG:2056").replace("<xmin>5</xmin>", "<xmin>2600000</xmin>")})).unwrap();
    assert_eq!(s.map().projection.code(), "EPSG:2056");
}

#[test]
fn a_qgis_project_with_a_geographic_proj_string_keeps_its_saved_view() {
    for (crs, datum_note, saved_view) in [
        ("+proj=longlat +datum=WGS84", false, true),
        ("+proj=latlong +datum=WGS84", false, true),
        ("+proj=lonlat +datum=WGS84", false, true),
        ("+proj=latlon +datum=WGS84", false, true),
        ("  +datum=WGS84 +proj=longlat +no_defs", false, true),
        ("+proj=longlat +datum=potsdam", true, true),
        ("+proj=longlat +datum=WGS84 +pm=paris", true, false),
    ] {
        let text = format!(
            r#"<qgis><projectCrs><spatialrefsys><authid></authid><proj4>{crs}</proj4></spatialrefsys></projectCrs>
<mapcanvas><extent><xmin>5</xmin><ymin>45</ymin><xmax>15</xmax><ymax>50</ymax></extent></mapcanvas><projectlayers/></qgis>"#
        );
        let mut s = world();
        let out = s.run("project.importQgis", &json!({"text": text})).unwrap();
        assert_eq!(s.map().projection.code(), "equirectangular", "{crs}");
        let notes = serde_json::to_string(&out["notes"]).unwrap();
        assert!(!notes.contains("Web Mercator"), "{crs}: {notes}");
        assert_eq!(notes.contains("drawn in Equirectangular on WGS 84"), datum_note, "{crs}: {notes}");
        let c = s.map().to_lonlat(s.map().camera.center).unwrap();
        assert_eq!((c.x - 10.0).abs() < 0.5 && (c.y - 47.5).abs() < 0.5, saved_view, "{crs}: {c:?}");
    }
}

#[test]
fn a_qgis_project_opens_as_a_map_and_a_qgis_style_styles_a_layer() {
    let dir = std::env::temp_dir().join(format!("rustgis-qgis-{}", std::process::id()));
    std::fs::create_dir_all(dir.join("data")).unwrap();
    let roads = r#"{"type":"FeatureCollection","features":[
        {"type":"Feature","properties":{"class":"motorway","name":"A1","lanes":3},"geometry":{"type":"LineString","coordinates":[[8.70,47.49],[8.75,47.51]]}},
        {"type":"Feature","properties":{"class":"track","name":"Feldweg","lanes":1},"geometry":{"type":"LineString","coordinates":[[8.71,47.50],[8.74,47.48]]}}]}"#;
    std::fs::write(dir.join("data/roads.geojson"), roads).unwrap();
    std::fs::write(dir.join("data/towns.csv"), "name,lon,lat\nWinterthur,8.72,47.50\n").unwrap();
    let qgs = r#"<!DOCTYPE qgis PUBLIC 'http://mrcc.com/qgis.dtd' 'SYSTEM'>
<qgis version="3.42.0"><title>Winterthur</title>
  <projectCrs><spatialrefsys><authid>EPSG:2056</authid></spatialrefsys></projectCrs>
  <layer-tree-group><layer-tree-layer id="t" checked="Qt::Checked"/><layer-tree-layer id="r" checked="Qt::Unchecked"/><layer-tree-layer id="db" checked="Qt::Checked"/></layer-tree-group>
  <mapcanvas name="theMapCanvas"><extent><xmin>0</xmin><ymin>0</ymin><xmax>10</xmax><ymax>10</ymax></extent></mapcanvas>
  <projectlayers>
    <maplayer type="vector" labelsEnabled="1"><id>r</id><datasource>./data/roads.geojson|subset="lanes" &gt; 0</datasource><layername>Roads</layername><provider>ogr</provider>
      <renderer-v2 type="categorizedSymbol" attr="class" referencescale="25000"><categories><category value="motorway" symbol="0" render="true"/><category value="" symbol="1" render="true"/></categories>
        <symbols><symbol type="line" name="0" alpha="1"><layer class="SimpleLine" enabled="1"><prop k="line_color" v="0,0,0,255"/><prop k="line_width" v="1"/></layer><layer class="SimpleLine" enabled="1"><prop k="line_color" v="250,150,50,255"/><prop k="line_width" v="0.6"/></layer></symbol>
        <symbol type="line" name="1" alpha="1"><layer class="SimpleLine" enabled="1"><prop k="line_color" v="120,120,120,255"/></layer></symbol></symbols></renderer-v2>
      <labeling type="rule-based"><rules key="x"><rule filter="&quot;class&quot; = 'motorway'" description="Big"><settings><text-style fieldName="name" fontSize="9" namedStyle="Italic"/><placement placement="2"/></settings></rule>
        <rule filter="&quot;nofield&quot; = 1" description="Broken"><settings><text-style fieldName="name"/></settings></rule></rules></labeling></maplayer>
    <maplayer type="vector"><id>t</id><datasource>file:./data/towns.csv?type=csv&amp;xField=lon&amp;yField=lat&amp;crs=EPSG:4326</datasource><layername>Towns</layername><provider>delimitedtext</provider>
      <renderer-v2 type="singleSymbol"><symbols><symbol type="marker" name="0" alpha="1"><layer class="SimpleMarker" enabled="1"><prop k="name" v="square"/><prop k="color" v="200,0,0,255"/></layer></symbol></symbols></renderer-v2></maplayer>
    <maplayer type="vector"><id>db</id><datasource>dbname='gis' host=db password='secret' table="public"."parcels" (geom)</datasource><layername>Parcels</layername><provider>postgres</provider></maplayer>
  </projectlayers></qgis>"#;
    let path = dir.join("winterthur.qgs");
    std::fs::write(&path, qgs).unwrap();
    let mut s = world();
    let maps = s.project.maps.len();
    let depth = s.undo_depth();
    let out = s.run("project.importQgis", &json!({"path": path.display().to_string()})).unwrap();
    assert_eq!((s.project.maps.len(), s.map().name.as_str()), (maps + 1, "Winterthur"), "a map of its own");
    assert_eq!(s.undo_depth(), depth + 1, "one step");
    assert_eq!(s.map().projection.code(), "EPSG:2056");
    assert_eq!(s.map().basemap, rustgis_map::Basemap::Blank);
    let names: Vec<&str> = s.map().layers.iter().map(|l| l.name.as_str()).collect();
    assert_eq!(names, ["Towns", "Roads"], "top first; the database table isn't added");
    let roads = s.map().layer_by_name("Roads").unwrap();
    assert!(!roads.visible, "unchecked in the layer tree");
    assert_eq!(roads.definition_query.as_deref(), Some("\"lanes\" > 0"));
    assert!(roads.reference_scale.is_some());
    let rustgis_map::Renderer::Unique { field, class_strokes, .. } = &roads.renderer else { panic!("{:?}", roads.renderer) };
    assert_eq!((field.as_str(), class_strokes.get("motorway").map(Vec::len)), ("class", Some(2)));
    let classes: Vec<(&str, bool)> = roads.labels.classes.iter().map(|c| (c.name.as_str(), c.visible)).collect();
    assert_eq!(classes, [("Big", true), ("Broken", false)], "a clause the layer can't read is switched off");
    assert_eq!(roads.labels.classes[0].placement, rustgis_map::LabelPlacement::Parallel);
    let towns = s.map().layer_by_name("Towns").unwrap();
    assert_eq!((towns.dataset.features.len(), towns.renderer.base_symbol().marker), (1, rustgis_map::Marker::Square));
    // What wasn't carried over: the database table, with no password in the note.
    let notes = out["notes"].as_array().unwrap();
    let text = serde_json::to_string(notes).unwrap();
    assert!(text.contains("parcels") && !text.contains("secret"), "{text}");
    assert!(text.contains("Broken"), "{text}");
    // Drawn, and gone again with one undo.
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.project.maps.len(), maps);

    // A style file on a sample layer: Rivers drawn as a cased line.
    let qml = r#"<!DOCTYPE qgis PUBLIC 'http://mrcc.com/qgis.dtd' 'SYSTEM'><qgis version="3.22"><renderer-v2 type="singleSymbol"><symbols><symbol type="line" name="0" alpha="1">
        <layer class="SimpleLine" enabled="1"><Option type="Map"><Option name="line_color" value="20,60,120,255"/><Option name="line_width" value="1.2"/></Option></layer>
        <layer class="SimpleLine" enabled="1"><Option type="Map"><Option name="line_color" value="150,200,255,255"/><Option name="line_width" value="0.5"/></Option></layer>
        </symbol></symbols></renderer-v2><layerOpacity>0.5</layerOpacity></qgis>"#;
    s.run("style.importQgis", &json!({"layer": "Rivers", "text": qml})).unwrap();
    let rivers = s.map().layer_by_name("Rivers").unwrap();
    assert_eq!((rivers.line_strokes.len(), rivers.transparency), (2, 50.0));
    // A raster's style on a feature layer says its colouring is left out.
    let qml = r#"<qgis version="4.2.3" layerType="Raster"><pipe><rasterrenderer type="singlebandgray" grayBand="1"/></pipe></qgis>"#;
    let out = s.run("style.importQgis", &json!({"layer": "Rivers", "text": qml})).unwrap();
    assert!(serde_json::to_string(&out["notes"]).unwrap().contains("a raster's colouring"), "{out}");
    assert!(s.run("style.importQgis", &json!({"layer": "Rivers", "text": "<nonsense"})).is_err());
    // A style saved from another layer: classes and labels by fields Rivers hasn't are noted, and
    // the label class that has nothing to label from is switched off.
    let qml = r#"<qgis version="3.22" labelsEnabled="1"><renderer-v2 type="categorizedSymbol" attr="nofield"><categories><category value="a" symbol="0" render="true"/></categories>
        <symbols><symbol type="line" name="0" alpha="1"><layer class="SimpleLine" enabled="1"><prop k="line_color" v="0,0,0,255"/></layer></symbol></symbols></renderer-v2>
        <labeling type="simple"><settings><text-style fieldName="nolabelfield"/></settings></labeling></qgis>"#;
    let out = s.run("style.importQgis", &json!({"layer": "Rivers", "text": qml})).unwrap();
    let text = serde_json::to_string(&out["notes"]).unwrap();
    assert!(text.contains("nofield") && text.contains("nolabelfield"), "{text}");
    let rivers = s.map().layer_by_name("Rivers").unwrap();
    assert!(rivers.labels.classes.iter().chain(std::iter::once(&rivers.labels.default)).all(|c| c.field != "nolabelfield" || !c.visible));
    // A project's web layer keeps its visibility and opacity; its scale range is noted.
    let qgs = r#"<qgis version="3.42.0"><title>Web</title>
  <layer-tree-group><layer-tree-layer id="x" checked="Qt::Unchecked"/></layer-tree-group>
  <projectlayers><maplayer type="raster" hasScaleBasedVisibilityFlag="1" minScale="100000" maxScale="1000"><id>x</id><datasource>type=xyz&amp;url=https://tiles.example/%7Bz%7D/%7Bx%7D/%7By%7D.png&amp;zmax=19&amp;zmin=0</datasource><layername>Tiles</layername><provider>wms</provider>
    <pipe><rasterrenderer opacity="0.25" type="singlebandcolordata"/></pipe><blendMode>13</blendMode></maplayer></projectlayers></qgis>"#;
    let out = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let t = s.map().tiles.iter().find(|t| t.name == "Tiles").expect("the web layer is added");
    assert!(!t.visible, "unchecked in the layer tree");
    assert!((t.opacity - 0.25).abs() < 1e-6, "{}", t.opacity);
    let text = serde_json::to_string(&out["notes"]).unwrap();
    assert!(text.contains("scale range"), "{text}");
    // Web layers are overlays, so they stay in the tree's order, and take the layer's blending.
    let t = s.map().tiles.iter().find(|t| t.name == "Tiles").unwrap();
    assert!(t.overlay);
    assert_eq!(t.blend, rustgis_map::effects::Blend::Multiply);
    // A layer of no provider (QGIS's annotation layer) is noted by its kind.
    let qgs = r#"<qgis version="3.42.0"><title>Notes</title><projectlayers><maplayer type="annotation"><id>a</id><layername>Notes</layername></maplayer></projectlayers></qgis>"#;
    let out = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let text = serde_json::to_string(&out["notes"]).unwrap();
    assert!(text.contains("doesn't read QGIS's annotation layers"), "{text}");
    // A project given as text with no folder: a relative path is noted, not looked for in the
    // working directory.
    let rel = r#"<qgis version="3.42.0"><projectlayers><maplayer type="vector"><id>a</id><datasource>./data/roads.geojson</datasource><layername>Rel</layername><provider>ogr</provider></maplayer></projectlayers></qgis>"#;
    for p in [json!({"text": rel}), json!({"text": rel, "dir": "  "})] {
        let out = s.run("project.importQgis", &p).unwrap();
        assert!(out["layers"].as_array().unwrap().is_empty(), "{p}");
        let text = serde_json::to_string(&out["notes"]).unwrap();
        assert!(text.contains("pass dir"), "{text}");
    }
    // XML past what's parsed (64 MiB) is refused before parsing.
    assert!(s.run("project.importQgis", &json!({"text": " ".repeat((64 << 20) + 1)})).is_err());
    // A path relative to a drive's working directory is noted, with or without a folder.
    let drive = rel.replace("./data/roads.geojson", "C:roads.geojson");
    let out = s.run("project.importQgis", &json!({"text": drive, "dir": dir.display().to_string()})).unwrap();
    assert!(serde_json::to_string(&out["notes"]).unwrap().contains("drive"), "{out}");
    // A web layer a service offers as features or a coverage comes in as a map layer, which takes
    // the QGIS layer's visibility, opacity, blending and scale range.
    let web = r#"<qgis version="3.42.0"><layer-tree-group><layer-tree-layer id="w" checked="Qt::Unchecked"/></layer-tree-group><projectlayers>
        <maplayer type="raster" hasScaleBasedVisibilityFlag="1" minScale="100000" maxScale="1000"><id>w</id><datasource>url=https://wms.example/wms&amp;layers=a</datasource><layername>Web</layername><provider>wms</provider>
        <pipe><rasterrenderer opacity="0.5" type="singlebandcolordata"/></pipe><blendMode>13</blendMode></maplayer></projectlayers></qgis>"#;
    let mut report = rustgis_map::qgis::Report::default();
    let project = rustgis_map::qgis::read_project(web, "", &mut report).unwrap();
    let mut w = world();
    let before = w.active_layer;
    w.active_layer = w.map().layers.iter().map(|l| l.id).find(|id| Some(*id) != before);
    crate::cmd::qgis::web_settings(&mut w, &json!({"name": "Web"}), before, &project.layers[0], &mut report);
    let l = w.map().layers.iter().find(|l| Some(l.id) == w.active_layer).unwrap();
    assert!(!l.visible);
    assert_eq!((l.transparency, l.blend), (50.0, rustgis_map::effects::Blend::Multiply));
    assert!(l.min_scale.is_some() && l.max_scale.is_some());
    // Plugins can't run the import: a project names files and web addresses its layers come from.
    assert!(crate::cmd::plugins::user_only("project.importQgis"));
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn project_save_and_open_roundtrip() {
    let mut s = world();
    let dir = std::env::temp_dir().join(format!("rustgis-test-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("atlas.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    assert_eq!(t.map().layers.len(), 4);
    let png = dir.join("map.png");
    t.run("share.exportMap", &json!({"path": png.display().to_string(), "width": 320, "height": 200})).unwrap();
    assert!(std::fs::metadata(&png).unwrap().len() > 1000);
    std::fs::remove_dir_all(&dir).ok();
}

/// RustGIS files are read only from regular files: a device that reports no size and never ends
/// (`/dev/zero`) would exhaust memory, and a named pipe without a writer would hang the reader.
#[cfg(unix)]
#[test]
fn item_files_refuse_devices_and_pipes() {
    let dir = std::env::temp_dir().join(format!("rustgis-item-pipe-{}", std::process::id()));
    std::fs::remove_dir_all(&dir).ok();
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = world();
    for (id, name) in [
        ("style.add", "styles.rgisstyle"),
        ("report.open", "report.rgisreport"),
        ("project.open", "p.rgis"),
        ("project.open", "p.rgispkg"),
        ("project.importQgis", "q.qgz"),
        ("layout.import", "l.rgislayout"),
        ("dl.import", "m.rgisdlpk"),
        ("layer.addData", "l.rgislyr"),
    ] {
        let fifo = dir.join(name);
        assert!(std::process::Command::new("mkfifo").arg(&fifo).status().unwrap().success());
        for path in [std::path::Path::new("/dev/zero"), fifo.as_path()] {
            if id == "layer.addData" && path == std::path::Path::new("/dev/zero") {
                continue; // Without its extension it isn't read as a layer file.
            }
            let error = s.run(id, &json!({"path": path})).unwrap_err();
            assert!(error.contains("isn't a file"), "{id} {}: {error}", path.display());
        }
    }
    std::fs::remove_dir_all(&dir).ok();
}

/// Save As and packaging must not replace readable files with a project above the opening limit.
#[test]
fn oversized_project_save_preserves_file_and_live_state() {
    let dir = std::env::temp_dir().join(format!("rustgis-save-limit-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("existing.rgis");
    let mut s = world();
    s.run("project.saveAs", &json!({"path": path})).unwrap();
    let original = std::fs::read(&path).unwrap();
    let package = dir.join("existing.rgispkg");
    s.run("project.package", &json!({"path": package})).unwrap();
    let original_package = std::fs::read(&package).unwrap();
    s.run("project.rename", &json!({"name": "Unsaved work"})).unwrap();
    let source = dir.join("roads.geojson").display().to_string();
    s.project.maps[0].layers[0].dataset.source = Some(source.clone());
    // A single large value reaches the real limit without a large data fixture on disk.
    s.project.thumbnail = Some("x".repeat(crate::project::MAX_BYTES as usize));
    let error = s.run("project.saveAs", &json!({"path": path})).unwrap_err();
    assert!(error.contains("too large"), "{error}");
    let error = s.run("project.package", &json!({"path": package})).unwrap_err();
    assert!(error.contains("too large"), "{error}");
    assert_eq!(std::fs::read(&path).unwrap(), original);
    assert_eq!(std::fs::read(&package).unwrap(), original_package);
    assert_eq!(s.project.name, "Unsaved work");
    assert_eq!(s.project.maps[0].layers[0].dataset.source.as_deref(), Some(source.as_str()));
    assert_eq!(s.path.as_deref(), Some(path.as_path()));
    assert!(s.dirty(), "a failed save must not mark the project saved");
    s.project.thumbnail = None;
    s.run("project.saveAs", &json!({"path": path})).unwrap();
    assert!(!s.dirty());
    assert!(Project::load(&path).is_ok());
    std::fs::remove_dir_all(&dir).unwrap();
}

#[test]
fn project_extension_is_rgis_and_legacy_rgisx_opens() {
    let mut s = world();
    let dir = std::env::temp_dir().join(format!("rustgis-ext-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("project.saveAs", &json!({"path": dir.join("atlas").display().to_string()})).unwrap();
    let saved = dir.join("atlas.rgis");
    assert!(saved.exists(), "a path without an extension gets .rgis");
    let legacy = dir.join("old.rgisx");
    std::fs::copy(&saved, &legacy).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": legacy.display().to_string()})).unwrap();
    assert_eq!(t.map().layers.len(), 4);
    for (name, is) in [("a.rgis", true), ("A.RGISX", true), ("a.rgismap", false), ("a.rgispkg", false), ("rgis", false)] {
        assert_eq!(crate::project::is_project_file(name), is, "{name}");
    }
    for (name, opens) in [("a.rgis", true), ("A.RGISPKG", true), ("rgispkg", false), ("a.geojson", false), ("a.rgismap", false)] {
        assert_eq!(crate::project::opens_as_project(name), opens, "{name}");
    }
    assert_eq!(crate::project::open_command("dir/a.geojson"), "layer.addData");
    std::fs::remove_dir_all(&dir).ok();
}

/// A table file picked inside a File Geodatabase stands for the geodatabase, in `layer.addData`
/// and `info.fileLayers` alike; through GDAL when it is installed.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_file_inside_a_geodatabase_adds_the_geodatabase() {
    let dir = std::env::temp_dir().join(format!("rustgis-gdb-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let gdb = dir.join("roads.gdb");
    let table = gdb.join("a00000001.gdbtable").display().to_string();
    let mut s = Session::new(Project::default());
    if rustgis_data::source::gdal::available() {
        let geojson = dir.join("cities.geojson");
        std::fs::write(
            &geojson,
            r#"{"type":"FeatureCollection","features":[
{"type":"Feature","properties":{"name":"a"},"geometry":{"type":"Point","coordinates":[8.5,47.4]}},
{"type":"Feature","properties":{"name":"b"},"geometry":{"type":"Point","coordinates":[7.4,46.9]}}]}"#,
        )
        .unwrap();
        let made = std::process::Command::new("ogr2ogr")
            .args(["-f", "OpenFileGDB", "-nln", "cities"])
            .arg(&gdb)
            .arg(&geojson)
            .status()
            .is_ok_and(|st| st.success());
        if made {
            let listed = s.run("info.fileLayers", &json!({"path": table})).unwrap();
            assert_eq!(listed["layers"], json!(["cities"]), "{listed}");
            let added = s.run("layer.addData", &json!({"path": table})).unwrap();
            assert_eq!(added["features"], json!(2), "{added}");
            std::fs::remove_dir_all(&dir).ok();
            return;
        }
    }
    // Without GDAL the geodatabase can't be read, but the error names it, not the table.
    std::fs::create_dir_all(&gdb).unwrap();
    std::fs::write(&table, b"").unwrap();
    for cmd in ["layer.addData", "info.fileLayers"] {
        let e = s.run(cmd, &json!({"path": table})).unwrap_err();
        assert!(e.contains("roads.gdb") && !e.contains("gdbtable"), "{cmd}: {e}");
    }
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn save_clears_dirty_and_open_clears_history() {
    let mut s = world();
    assert!(!s.dirty() && !s.can_undo(), "a fresh sample is clean");
    s.run("layer.color", &json!({"layer": "Countries", "color": "#336699"})).unwrap();
    assert!(s.dirty() && s.can_undo());
    let dir = std::env::temp_dir().join(format!("rustgis-dirty-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("a.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    assert!(!s.dirty(), "saving clears the dirty marker");
    assert!(s.can_undo(), "saving keeps the edit history");
    s.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    assert!(!s.dirty() && !s.can_undo() && !s.can_redo(), "opening starts a fresh history");
    assert!(s.run("edit.undo", &Value::Null).is_err());
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn degenerate_geometry_and_deleted_fields() {
    let mut s = world();
    for g in [
        json!({"type": "LineString", "coordinates": [[0, 0]]}),
        json!({"type": "MultiPoint", "coordinates": []}),
        json!({"type": "MultiPolygon", "coordinates": []}),
    ] {
        let layer = if g["type"] == "LineString" {
            "Rivers"
        } else if g["type"] == "MultiPoint" {
            "Cities"
        } else {
            "Countries"
        };
        assert!(s.run("edit.addFeature", &json!({"layer": layer, "geometry": g})).is_err(), "{g}");
    }
    s.run("layer.definitionQuery", &json!({"layer": "Countries", "where": "pop_est > 1000"})).unwrap();
    s.run("edit.deleteField", &json!({"layer": "Countries", "field": "pop_est"})).unwrap();
    let l = s.map().layer_by_name("Countries").unwrap();
    assert_eq!(l.renderer.kind_label(), "Single Symbol");
    assert!(l.definition_query.is_none());
    s.run("edit.deleteField", &json!({"layer": "Countries", "field": "name"})).unwrap();
    assert!(!s.map().layer_by_name("Countries").unwrap().labels.enabled);
}

#[test]
fn open_from_text() {
    let mut s = world();
    let text = serde_json::to_string(&s.project).unwrap();
    s.run("layer.addDataText", &json!({"fileName": "pts.csv", "text": "name,lon,lat\nA,1,2\n"})).unwrap();
    assert!(s.map().layer_by_name("pts").is_some());
    assert!(s.run("layer.addDataText", &json!({"fileName": "x.shp", "text": ""})).is_err());
    assert!(s.run("layer.addDataText", &json!({"fileName": "x.geojson", "text": "{"})).is_err());
    assert!(s.run("project.openText", &json!({"text": "not json"})).is_err());
    s.run("project.openText", &json!({"text": text})).unwrap();
    assert!(s.map().layer_by_name("pts").is_none() && !s.dirty() && !s.can_undo());
}

#[test]
fn opened_project_is_named_after_its_file() {
    // Issue #197: a project saved from the sample and renamed kept the sample's name.
    let mut s = world();
    let text = serde_json::to_string(&s.project).unwrap();
    s.run("project.openText", &json!({"text": text, "fileName": "test.rgis"})).unwrap();
    assert_eq!(s.project.name, "test");
    s.run("project.openText", &json!({"text": text})).unwrap();
    assert_eq!(s.project.name, "World Atlas", "without a file name the project keeps its own");
    s.run("project.openText", &json!({"text": text, "fileName": " .rgis"})).unwrap();
    assert_eq!(s.project.name, "World Atlas", "an empty file name doesn't rename it");
    let dir = std::env::temp_dir().join(format!("rustgis-named-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("Trip plan.rgis");
    std::fs::write(&path, &text).unwrap();
    s.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    assert_eq!(s.project.name, "Trip plan");
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
