/// A 3-band 8×6 UTM 17N GeoTIFF near 81°W, 42°N, as base64.
fn utm_tiff_b64() -> String {
    use base64::Engine;
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let gt = GeoTransform { origin_x: 497_000.0, origin_y: 4_651_000.0, pixel_width: 500.0, pixel_height: -500.0 };
    let bands = (0..3).map(|b| (0..48).map(|i| ((i * 5 + b * 40) % 256) as f32).collect()).collect();
    let r = Raster::new("utm", 8, 6, bands, gt, Crs::from_epsg(32617).unwrap(), None, ColorHint::Rgb { alpha: false }, "UInt8").unwrap();
    base64::engine::general_purpose::STANDARD.encode(geotiff::write(&r, 0).unwrap())
}

/// The sample world with a streamed layer active.
fn with_streamed(path: &std::path::Path) -> Session {
    let mut s = world();
    s.run("layer.addData", &json!({"path": path.display().to_string(), "stream": true, "name": "Streamed"})).unwrap();
    s
}

fn with_raster() -> Session {
    let mut s = world();
    s.run("layer.addDataBytes", &json!({"fileName": "scene.tif", "data": utm_tiff_b64()})).unwrap();
    s
}

/// A QGIS raster style colours a raster layer; one reading a band the raster hasn't is noted and
/// leaves it as it was.
#[test]
fn a_qgis_raster_style_colours_a_raster() {
    let mut s = with_raster();
    let qml = r#"<qgis version="4.2.3" layerType="Raster"><pipe><rasterrenderer type="multibandcolor" redBand="3" greenBand="2" blueBand="1" opacity="0.5"/>
        <brightnesscontrast brightness="0" contrast="25" gamma="1"/></pipe></qgis>"#;
    let out = s.run("style.importQgis", &json!({"layer": "scene", "text": qml})).unwrap();
    assert_eq!(out["notes"], json!([]));
    let l = s.map().layer_by_name("scene").unwrap();
    let st = &l.raster.as_ref().unwrap().style;
    assert_eq!(
        (&st.renderer, st.contrast, l.transparency),
        (&rustgis_map::raster::RasterRenderer::Rgb { red: 2, green: 1, blue: 0 }, 25.0, 50.0)
    );
    let before = st.clone();
    // A style that reads a band the raster hasn't leaves it as it was, its opacity too.
    let qml = r#"<qgis version="4.2.3" layerType="Raster"><pipe><rasterrenderer type="singlebandgray" grayBand="5"/></pipe><layerOpacity>0.2</layerOpacity></qgis>"#;
    let out = s.run("style.importQgis", &json!({"layer": "scene", "text": qml})).unwrap();
    assert!(serde_json::to_string(&out["notes"]).unwrap().contains("band 5 of a raster with 3"), "{out}");
    let l = s.map().layer_by_name("scene").unwrap();
    assert_eq!((&l.raster.as_ref().unwrap().style, l.transparency), (&before, 50.0));
    // Pixels not there yet (a remote raster still loading): applied, and noted as unchecked.
    let id = s.map().layer_by_name("scene").unwrap().id;
    s.map_mut().layer_mut(id).unwrap().raster.as_mut().unwrap().data = None;
    let out = s.run("style.importQgis", &json!({"layer": "scene", "text": qml})).unwrap();
    assert!(serde_json::to_string(&out["notes"]).unwrap().contains("before the raster's bands could be checked"), "{out}");
}

/// The parts of a large GeoTIFF the web app reads (#140), opened and kept in a project: a
/// cloud-optimised file read a part at a time, as `parts.rs` reads a picked file.
#[test]
fn geotiff_parts_open_and_survive_a_saved_project() {
    use base64::Engine;
    use rustgis_data::raster::cog::{self, Sparse};
    use rustgis_data::raster::geotiff::{self, Partial};
    let file = cog::example(1024, 256);
    let len = file.len() as u64;
    let mut parts = Sparse::default().with_len(len).with(0, file[..4096].to_vec());
    let mut done = false;
    for _ in 0..100 {
        match geotiff::read_sparse(&parts, "scene").unwrap() {
            Partial::Done(_) => {
                done = true;
                break;
            }
            Partial::Need(a, b) => {
                let end = b.max(a + (64 << 10)).min(len).min(parts.next_start(a).unwrap_or(len));
                parts = parts.with(a, file[a as usize..end as usize].to_vec());
            }
        }
    }
    assert!(done);
    let container = parts.container();
    let mut s = world();
    let data = base64::engine::general_purpose::STANDARD.encode(&container);
    s.run("layer.addDataBytes", &json!({"fileName": "scene.tif", "data": data})).unwrap();
    let value = |s: &Session| s.map().layer_by_name("scene").and_then(|l| l.raster.as_ref()?.data.as_ref()?.value(0, 300, 200));
    // Pixel (x, y) of the example is (x + y) % 256.
    assert_eq!(value(&s), Some(244.0));
    // Saved, the project keeps the parts, not the whole file, and opens the raster again.
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(text.len() < file.len() * 2, "{} for a {}-byte file", text.len(), file.len());
    s.run("project.openText", &json!({"text": text})).unwrap();
    assert_eq!(value(&s), Some(244.0));
}

/// File-supplied items reject implicit network and reserved actions before their handlers run,
/// while ordinary in-project cells still run. This uses the existing Wasm plugin fixture.
#[test]
fn imported_tasks_and_notebooks_reject_network_and_reserved_actions() {
    let mut s = world();
    plugin("eng-item-containment", &[]);
    for (command, params) in [
        ("layer.geocode", json!({"layer": "Cities", "address": "name"})),
        ("connection.test", json!({"id": "saved-connection"})),
        ("plugin.uninstall", json!({"id": "eng-item-containment"})),
    ] {
        let steps = json!([{"title": "Outside", "command": command, "params": params}]);
        let task = json!({"name": "From a file", "steps": steps});
        let why = s.run("task.import", &json!({"text": task.to_string()})).unwrap_err();
        assert!(why.contains("network") && why.contains("imported"), "{why}");
        // Opened projects and later edits reach the execution check without task.import.
        s.run("task.new", &json!({"name": command, "steps": steps, "imported": true})).unwrap();
        let why = s.run("task.run", &json!({"task": command})).unwrap_err();
        assert!(why.contains("from a file"), "{why}");
    }
    let text = json!({"name": "Shared", "cells": [
        {"kind": "code", "source": "select.all {\"layer\":\"Cities\"}"},
        {"kind": "code", "source": "plugin.uninstall {\"id\":\"eng-item-containment\"}"},
        {"kind": "code", "source": "layer.geocode {\"layer\":\"Cities\",\"address\":\"name\"}"}
    ]})
    .to_string();
    s.run("notebook.open", &json!({"text": text})).unwrap();
    let result = s.run("notebook.run", &json!({"notebook": "Shared"})).unwrap();
    assert_eq!(result["error"], 1);
    let notebook = s.project.notebooks.iter().find(|n| n.name == "Shared").unwrap();
    assert!(!notebook.cells[0].error);
    assert!(notebook.cells[1].error && notebook.cells[1].output.as_deref().unwrap().contains("from a file"));
    assert!(!s.map().layer_by_name("Cities").unwrap().selection.is_empty());
    let result = s.run("notebook.run", &json!({"notebook": "Shared", "cell": 2})).unwrap();
    assert_eq!(result["error"], 2);
    assert!(rustgis_plugins::get("eng-item-containment").is_some(), "no uninstall handler ran");
    rustgis_plugins::unload("eng-item-containment");
}

/// Plugin tools are rejected through all imported item runners, including models' direct tool
/// paths. A locally authored model still runs the same real plugin tool.
#[test]
fn imported_items_reject_resolved_plugin_tools() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::imported_items_reject_resolved_plugin_tools") {
        return;
    }
    let mut s = world();
    plugin("eng-tool-containment", &[]);
    let tool = "plugin:eng-tool-containment/m";
    let params = json!({"input": "Cities"});
    let gp = json!({"tool": tool, "params": params});
    let before = s.map().layers.len();
    let task = json!({"name": "Plugin task", "steps": [{"title": "Run", "command": "gp.run", "params": gp}]});
    assert!(s.run("task.import", &json!({"text": task.to_string()})).unwrap_err().contains("imported"));
    let notebook = json!({"name": "Plugin notebook", "cells": [{"kind": "code", "source": format!("gp.run {gp}")}]});
    s.run("notebook.open", &json!({"text": notebook.to_string()})).unwrap();
    assert_eq!(s.run("notebook.run", &json!({"notebook": "Plugin notebook"})).unwrap()["error"], 0);
    let graph = json!({"nodes": [{"id": "x", "kind": "tool", "tool": tool, "params": params}], "edges": []});
    for (name, body) in [("Plugin steps", json!({"steps": [{"tool": tool, "params": params}]})), ("Plugin graph", json!({"graph": graph}))]
    {
        let mut model = body;
        model["name"] = json!(name);
        s.run("model.import", &json!({"text": model.to_string()})).unwrap();
        let why = s.run("model.run", &json!({"name": name})).unwrap_err();
        assert!(why.contains("from a file"), "{why}");
    }
    assert_eq!(s.map().layers.len(), before, "no untrusted tool ran");
    // The same graph made here is authorized; no plugin interface or manifest policy changes.
    s.run("model.new", &json!({"name": "Made here", "graph": graph})).unwrap();
    s.run("model.run", &json!({"name": "Made here"})).unwrap();
    assert_eq!(s.map().layers.len(), before + 1);
    assert!(s.map().layer_by_name("Made").is_some());
    rustgis_plugins::unload("eng-tool-containment");
}

#[test]
fn imported_tasks_name_outputs_and_steps_are_edited() {
    let mut s = Session::new(sample::world_project());
    // A task from a file may name a tool's output layer, but not write to a path through it.
    let lesson = json!({"name": "Lesson", "steps": [
        {"title": "Buffer the cities", "instructions": "Analyze › Tools › Buffer", "command": "gp.run", "params": {"tool": "buffer", "params": {"input": "Cities", "distance": 100, "output": "Near cities"}}},
        {"title": "Zoom", "command": "layer.zoomTo", "params": {"layer": "Near cities"}},
        {"title": "Clear", "command": "select.clear"}
    ]});
    s.run("task.import", &json!({"text": lesson.to_string()})).unwrap();
    s.run("task.run", &json!({"task": "Lesson", "step": 0})).unwrap();
    assert!(s.map().layer_by_name("Near cities").is_some());
    let to_a_file = json!({"name": "To a file", "steps": [{"title": "Buffer", "command": "gp.run", "params": {"tool": "buffer", "params": {"input": "Cities", "distance": 100, "output": "C:/temp/x.shp"}}}]});
    assert!(s.run("task.import", &json!({"text": to_a_file.to_string()})).is_err());
    assert!(crate::cmd::items::touches_files(&s, "gp.run", &json!({"tool": "buffer", "params": {"output": "../x.shp"}})));
    assert!(!crate::cmd::items::touches_files(&s, "gp.run", &json!({"tool": "buffer", "params": {"output": "Near cities"}})));
    // Spatial Join and Zonal Statistics run their built-in tool with the parameters flat: a
    // plain output name stays in the session there too.
    assert!(!crate::cmd::items::touches_files(&s, "gp.spatialJoin", &json!({"target": "Cities", "join": "Countries", "output": "Joined"})));
    assert!(!crate::cmd::items::touches_files(&s, "gp.zonalStats", &json!({"raster": "dem", "polygons": "Countries", "output": "Zones"})));
    // Only a plain layer name, only gp.run's (and those two's), only for RustGIS's own tools.
    for (command, params) in [
        ("gp.run", json!({"tool": "buffer", "params": {"output": "x.shp"}})),
        ("gp.run", json!({"tool": "buffer", "params": {"output": "sub/x"}})),
        ("gp.run", json!({"tool": "buffer", "params": {"output": "sub\\x"}})),
        ("gp.run", json!({"tool": "buffer", "params": {"output": ".bashrc"}})),
        ("gp.run", json!({"tool": "geolibre:slope", "params": {"output": "slope"}})),
        ("gp.run", json!({"tool": "plugin:kit/hex", "params": {"output": "hex"}})),
        // Not one of RustGIS's own tools, even without a prefix.
        ("gp.run", json!({"tool": "someOtherTool", "params": {"output": "x"}})),
        ("gp.run", json!({"tool": "buffer", "params": {"input": "Cities", "nested": {"output": "x"}}})),
        ("layer.rename", json!({"layer": "Cities", "output": "x"})),
        ("gp.spatialJoin", json!({"target": "Cities", "join": "Countries", "output": "C:/temp/x.shp"})),
        ("gp.zonalStats", json!({"raster": "dem", "polygons": "Countries", "output": "../zones"})),
    ] {
        assert!(crate::cmd::items::touches_files(&s, command, &params), "{command} {params}");
    }

    // `"step": null` runs the whole task, as before; a step that isn't an index is refused.
    s.run("select.all", &json!({"layer": "Cities"})).unwrap();
    let r = s.run("task.run", &json!({"task": "Lesson", "step": null})).unwrap();
    assert_eq!(r["ran"].as_array().unwrap().len(), 3);
    assert!(s.run("task.run", &json!({"task": "Lesson", "step": "two"})).is_err());

    // Steps are edited, moved and deleted, each one undoable.
    s.run(
        "task.editStep",
        &json!({"task": "Lesson", "step": 1, "title": "  Look at it  ", "instructions": "Line one.
Line two."}),
    )
    .unwrap();
    let step = |s: &Session, i: usize| s.project.tasks.iter().find(|t| t.name == "Lesson").unwrap().steps[i].clone();
    assert_eq!(
        (step(&s, 1).title.as_str(), step(&s, 1).instructions.as_str()),
        (
            "Look at it",
            "Line one.
Line two."
        )
    );
    assert_eq!(step(&s, 1).command, "layer.zoomTo", "editing keeps the command");
    assert!(s.run("task.editStep", &json!({"task": "Lesson", "step": 1, "title": " "})).is_err());
    assert!(s.run("task.editStep", &json!({"task": "Lesson", "step": 9, "title": "x"})).is_err());
    s.run("task.moveStep", &json!({"task": "Lesson", "step": 2, "to": 0})).unwrap();
    assert_eq!(step(&s, 0).title, "Clear");
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(step(&s, 0).title, "Buffer the cities");
    s.run("task.removeStep", &json!({"task": "Lesson", "step": 2})).unwrap();
    assert_eq!(s.project.tasks.iter().find(|t| t.name == "Lesson").unwrap().steps.len(), 2);
    assert!(s.run("task.moveStep", &json!({"task": "Lesson", "step": 0, "to": 5})).is_err());
    // Neither changes nothing (which would leave an undo step).
    let depth = s.undo_depth();
    assert!(s.run("task.moveStep", &json!({"task": "Lesson", "step": 1, "to": 1})).is_err());
    let bad = s.run("task.removeStep", &json!({"task": "Lesson", "step": -1})).unwrap_err();
    assert!(bad.contains("whole number"), "{bad}");
    assert!(s.run("task.editStep", &json!({"task": "Lesson", "step": 1})).is_err());
    let same = s.project.tasks.iter().find(|t| t.name == "Lesson").unwrap().steps[1].title.clone();
    assert!(s.run("task.editStep", &json!({"task": "Lesson", "step": 1, "title": format!(" {same} ")})).is_err());
    assert_eq!(s.undo_depth(), depth);
    // Still a task from a file: a step that writes a file stays refused after editing.
    assert!(!s.item_trusted("task", "lesson"));
}

#[test]
fn tissot_indicatrix_reports_the_maps_own_distortion() {
    let mut s = Session::new(sample::world_project());
    let field = |s: &Session, layer: &str, lat: f64, name: &str| -> Value {
        let ds = &s.map().layer_by_name(layer).unwrap().dataset;
        let col = |n: &str| ds.fields.iter().position(|f| f.name == n).unwrap();
        let row = (0..ds.features.len())
            .find(|&r| {
                ds.value(r, col("lat")) == &rustgis_data::Value::Float(lat) && ds.value(r, col("lon")) == &rustgis_data::Value::Float(0.0)
            })
            .unwrap();
        match ds.value(row, col(name)) {
            rustgis_data::Value::Float(v) => json!(v),
            rustgis_data::Value::Text(t) => json!(t),
            v => panic!("{name}: {v:?}"),
        }
    };
    // Web Mercator, the default: area grows to about sec² 60° = 4, shapes are kept.
    s.run("gp.run", &json!({"tool": "tissot", "params": {"output": "merc"}})).unwrap();
    assert_eq!(field(&s, "merc", 60.0, "projection"), json!("Web Mercator"));
    let area = field(&s, "merc", 60.0, "area_scale").as_f64().unwrap();
    assert!((area - 4.0).abs() < 0.05, "{area}");
    assert!(field(&s, "merc", 60.0, "max_angle").as_f64().unwrap() < 0.5);
    // Mollweide is equal-area: about 1 everywhere, while angles bend away from its centre.
    s.run("map.projection", &json!({"type": "mollweide"})).unwrap();
    s.run("gp.run", &json!({"tool": "tissot", "params": {"output": "moll"}})).unwrap();
    for lat in [-60.0, 0.0, 30.0, 60.0] {
        let area = field(&s, "moll", lat, "area_scale").as_f64().unwrap();
        assert!((area - 1.0).abs() < 0.01, "{lat}: {area}");
    }
    assert!(field(&s, "moll", 60.0, "max_angle").as_f64().unwrap() > 10.0);
    // On the globe there's no flat projection to measure: circles only.
    s.run("map.projection", &json!({"type": "globe"})).unwrap();
    s.run("gp.run", &json!({"tool": "tissot", "params": {"output": "globe"}})).unwrap();
    let fields: Vec<String> = s.map().layer_by_name("globe").unwrap().dataset.fields.iter().map(|f| f.name.clone()).collect();
    assert_eq!(fields, ["lat", "lon"]);
    // Map Extent on the globe fills the whole Earth.
    s.run("gp.run", &json!({"tool": "tissot", "params": {"area": "Map Extent", "spacing": 60, "output": "globeView"}})).unwrap();
    // Six columns of 60° and three rows (−60°, 0°, 60°; the poles' rows are left out).
    assert_eq!(s.map().layer_by_name("globeView").unwrap().dataset.features.len(), 18);
}

/// A5 grids (#551) through gp.run: a world grid of equal-area cells, and the sample's cities
/// counted by cell, every city in one.
#[test]
fn a5_grids_and_points_by_cell() {
    let mut s = world();
    let r = s.run("gp.run", &json!({"tool": "a5Grid", "params": {"resolution": 1, "area": "World", "output": "cells"}})).unwrap();
    let cells = s.map().layer_by_name("cells").unwrap_or_else(|| panic!("{r}"));
    let names: Vec<&str> = cells.dataset.fields.iter().map(|f| f.name.as_str()).collect();
    assert_eq!(names, ["a5", "resolution", "area_km2"]);
    assert!(cells.dataset.features.len() > 12);
    let cities = s.map().layer_by_name("Cities").unwrap().dataset.features.len();
    s.run("gp.run", &json!({"tool": "a5Aggregate", "params": {"input": "Cities", "resolution": 2, "output": "by cell"}})).unwrap();
    let by = &s.map().layer_by_name("by cell").unwrap().dataset;
    let i = by.field_index("count").unwrap();
    let total: f64 = (0..by.features.len()).map(|r| by.value(r, i).as_f64().unwrap()).sum();
    assert_eq!(total as usize, cities);
    assert!(s.run("gp.run", &json!({"tool": "a5Grid", "params": {"resolution": 13, "area": "World"}})).is_err());
}

#[test]
fn globe_projection_toggles_renders_and_saves() {
    let mut s = with_raster();
    assert_eq!(s.run("map.projection", &Value::Null).unwrap()["projection"], "globe");
    assert_eq!(s.map().projection, rustgis_map::Projection::Globe);
    // The globe draws vectors, rasters and labels, from any side.
    for (lon, lat, res) in [(-81.0, 42.0, 30_000.0), (100.0, -60.0, 60_000.0), (-81.0, 42.0, 50.0), (0.0, 89.0, 160_000.0)] {
        s.map_mut().camera =
            rustgis_map::Camera { center: rustgis_geom::lonlat_to_merc(rustgis_geom::Coord::new(lon, lat)), res, bearing: 0.0, pitch: 0.0 };
        let png = crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap();
        assert!(png.len() > 1000);
    }
    assert!(s.run("map.projection", &json!({"type": "nope"})).is_err());
    s.run("map.projection", &json!({"type": "mercator"})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().projection, rustgis_map::Projection::Globe, "undo restores the globe");
    let json = serde_json::to_string(&s.project).unwrap();
    assert!(Project::from_json(&json).unwrap().map().projection == rustgis_map::Projection::Globe);
}

/// `map.projection` takes ESRI codes (#213): South America Albers, the issue's regional map.
#[test]
fn esri_projection_codes() {
    let mut s = world();
    s.run("map.goToXY", &json!({"lon": -60.0, "lat": -15.0, "scale": 20_000_000})).unwrap();
    let r = s.run("map.projection", &json!({"type": "esri:102033"})).unwrap();
    assert_eq!(r["projection"], "ESRI:102033");
    assert_eq!(r["label"], "ESRI:102033");
    let c = s.map().center_lonlat();
    assert!((c.x + 60.0).abs() < 1e-6 && (c.y + 15.0).abs() < 1e-6, "{c:?}");
    assert!(crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap().len() > 1000);
    let json = serde_json::to_string(&s.project).unwrap();
    assert_eq!(Project::from_json(&json).unwrap().map().projection.code(), "ESRI:102033");
    // A code the table leaves out is refused, and the map keeps its projection.
    let e = s.run("map.projection", &json!({"type": "ESRI:54003"})).unwrap_err();
    assert!(e.contains("ESRI:54003"), "{e}");
    assert_eq!(s.map().projection.code(), "ESRI:102033");
    // ESRI's Web Mercator is the default map.
    assert_eq!(s.run("map.projection", &json!({"type": "ESRI:102100"})).unwrap()["projection"], "mercator");
}

/// Presets take a central meridian, and the conics their standard parallels too (#517). The map
/// keeps them, and a bad value changes nothing.
#[test]
fn projection_presets_take_parameters() {
    let mut s = world();
    let r = s.run("map.projection", &json!({"type": "robinson", "lon_0": 150})).unwrap();
    assert_eq!(r["projection"], "robinson +lon_0=150");
    assert_eq!(r["label"], "Robinson (lon_0=150)");
    // Without a type, the values go to the map's own preset. A code with them, as typed, is the same.
    s.run("map.projection", &json!({"lon_0": -20})).unwrap();
    assert_eq!(s.map().projection.code(), "robinson +lon_0=-20");
    s.run("map.projection", &json!({"type": "Albers Equal Area Conic +lat_2=-35 +lon_0=-55 +lat_1=-5"})).unwrap();
    assert_eq!(s.map().projection.code(), "albers +lon_0=-55 +lat_1=-5 +lat_2=-35");
    s.run("map.projection", &json!({"lat_1": 0})).unwrap();
    assert_eq!(s.map().projection.code(), "albers +lon_0=-55 +lat_1=0 +lat_2=-35");
    // The preset's own value drops out.
    s.run("map.projection", &json!({"type": "robinson", "lon_0": 0})).unwrap();
    assert_eq!(s.map().projection.code(), "robinson");
    // Out of range, a parameter the preset doesn't take, not a number, parameters on a code or on
    // Web Mercator, and parallels that make no cone: refused, and the map keeps its projection.
    s.run("map.projection", &json!({"type": "robinson", "lon_0": 150})).unwrap();
    for bad in [
        json!({"lon_0": 200}),
        json!({"lat_1": 10}),
        json!({"lon_0": "east"}),
        json!({"type": "EPSG:3035", "lon_0": 10}),
        json!({"type": "mercator", "lon_0": 10}),
        json!({"type": "robinson +lon_0=999"}),
        json!({"type": "albers", "lat_1": -30, "lat_2": 30}),
    ] {
        assert!(s.run("map.projection", &bad).is_err(), "{bad}");
        assert_eq!(s.map().projection.code(), "robinson +lon_0=150", "{bad}");
    }
    // Saved with the map, and drawn.
    let json = serde_json::to_string(&s.project).unwrap();
    assert_eq!(Project::from_json(&json).unwrap().map().projection.code(), "robinson +lon_0=150");
    let png = crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap();
    assert!(png.len() > 1000);
}

#[test]
fn vn2000_projection_command_and_project_persistence() {
    let mut s = world();
    // Explicit prefixed province syntax works and canonicalizes to the preset
    s.run("map.projection", &json!({"type": "vn2000:danang"})).unwrap();
    assert_eq!(s.map().projection.code(), "vn2000tm3 +lon_0=107.75");
    assert_eq!(s.map().projection.label(), "VN-2000 / TM-3 (Vietnam) (lon_0=107.75)");

    // Capital Hanoi on central meridian 105.0 drops redundant parameter
    s.run("map.projection", &json!({"type": "vn2000:hanoi"})).unwrap();
    assert_eq!(s.map().projection.code(), "vn2000tm3");
    assert_eq!(s.map().projection.label(), "VN-2000 / TM-3 (Vietnam)");

    // UTM zones work
    s.run("map.projection", &json!({"type": "vn2000Utm48"})).unwrap();
    assert_eq!(s.map().projection.code(), "vn2000Utm48");
    assert_eq!(s.map().projection.label(), "VN-2000 / UTM zone 48N");

    s.run("map.projection", &json!({"type": "vn2000Utm49"})).unwrap();
    assert_eq!(s.map().projection.code(), "vn2000Utm49");
    assert_eq!(s.map().projection.label(), "VN-2000 / UTM zone 49N");

    // Bare province names and "vietnam" are rejected in strict command context
    for bare in ["danang", "vinh", "hanoi", "hue", "hcm", "vietnam"] {
        assert!(s.run("map.projection", &json!({"type": bare})).is_err(), "{bare}");
    }
    // Ambiguous bare VN-2000 is rejected
    for bare in ["vn2000", "VN-2000", "VN2000"] {
        let err = s.run("map.projection", &json!({"type": bare})).unwrap_err();
        assert!(err.contains("ambiguous"), "{bare}: {err}");
    }

    // Set a provincial TM-3 projection and verify project save and reload
    s.run("map.projection", &json!({"type": "VN-2000 / Đà Nẵng"})).unwrap();
    assert_eq!(s.map().projection.code(), "vn2000tm3 +lon_0=107.75");
    let text = serde_json::to_string(&s.project).unwrap();

    // Reload project from serialized JSON text
    let mut s2 = world();
    s2.run("project.openText", &json!({"text": text})).unwrap();
    assert_eq!(s2.map().projection.code(), "vn2000tm3 +lon_0=107.75");
    assert_eq!(s2.map().projection.label(), "VN-2000 / TM-3 (Vietnam) (lon_0=107.75)");
}

#[test]
fn custom_projections_switch_keep_scale_query_and_render() {
    let mut s = with_raster();
    s.run("map.goToXY", &json!({"lon": 10.0, "lat": 50.0, "scale": 5_000_000})).unwrap();
    let before = s.scale();
    let r = s.run("map.projection", &json!({"type": "europeEqualArea"})).unwrap();
    assert_eq!(r["projection"], "europeEqualArea");
    assert!((s.scale() / before - 1.0).abs() < 0.02, "scale kept: {before} vs {}", s.scale());
    let c = s.map().center_lonlat();
    assert!((c.x - 10.0).abs() < 1e-6 && (c.y - 50.0).abs() < 1e-6, "{c:?}");
    // Identify and box select work in the projection's coordinates.
    let v = s.run("identify", &json!({"lon": 2.35, "lat": 48.85, "tolerancePx": 5})).unwrap();
    assert!(!v.is_null(), "something is under Paris");
    let sel = s.run("select.byRect", &json!({"minLon": 5.0, "minLat": 45.0, "maxLon": 15.0, "maxLat": 55.0})).unwrap();
    assert!(sel["selected"].as_u64().unwrap() > 0);
    assert!(crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap().len() > 1000);
    // An EPSG code; the raster (UTM 17N) in the map's own system draws without reprojection.
    s.run("map.projection", &json!({"type": "EPSG:32617"})).unwrap();
    s.run("layer.zoomTo", &json!({"layer": "scene"})).unwrap();
    assert!(crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap().len() > 1000);
    assert!(s.run("map.projection", &json!({"type": "EPSG:4326"})).is_err(), "degrees are refused");
    assert!(s.run("map.projection", &json!({"type": "nope"})).is_err());
    // A known code whose method isn't implemented (EPSG:8441, Laborde) is refused, not drawn in
    // Web Mercator under its own name; the map keeps its projection (#208). proj4rs 0.3 grew
    // Brazil Polyconic, so EPSG:5880 switches now.
    let e = s.run("map.projection", &json!({"type": "EPSG:8441"})).unwrap_err();
    assert!(e.contains("labrd"), "{e}");
    assert_eq!(s.map().projection.code(), "EPSG:32617");
    assert!(s.run("map.goToXY", &json!({"lon": 100.0, "lat": 0.0})).is_err(), "folded far side of the UTM zone");
    // Undo and save/reload keep the projection.
    s.run("map.projection", &json!({"type": "mollweide"})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().projection.code(), "EPSG:32617");
    let json = serde_json::to_string(&s.project).unwrap();
    assert_eq!(Project::from_json(&json).unwrap().map().projection.code(), "EPSG:32617");
    assert!(s.run("map.projections", &Value::Null).unwrap().as_array().unwrap().len() >= 10);
    // A project naming a projection this version can't use opens in Web Mercator.
    let broken = json.replace("EPSG:32617", "EPSG:9");
    let reopened = Project::from_json(&broken).unwrap();
    assert_eq!(reopened.map().projection, rustgis_map::Projection::WebMercator);
    assert_eq!(reopened.map().camera, rustgis_map::Camera::world(), "UTM metres aren't read as Mercator ones");
    // Bookmarks follow a projection switch, and the extent history doesn't replay old cameras.
    s.run("map.projection", &json!({"type": "mercator"})).unwrap();
    s.run("map.goToXY", &json!({"lon": 10.0, "lat": 50.0, "scale": 5_000_000})).unwrap();
    // The sample has a "Europe" already: the new one is numbered (#351), and found by its name.
    let europe = s.run("bookmark.add", &json!({"name": "Europe"})).unwrap()["name"].clone();
    assert_eq!(europe, "Europe 2");
    s.run("map.goToXY", &json!({"lon": -100.0, "lat": 40.0})).unwrap();
    assert!(s.can_extent_back());
    s.run("map.projection", &json!({"type": "europeEqualArea"})).unwrap();
    assert!(!s.can_extent_back(), "history from Web Mercator is dropped");
    s.run("bookmark.go", &json!({"name": europe})).unwrap();
    let c = s.map().center_lonlat();
    assert!((c.x - 10.0).abs() < 1e-6 && (c.y - 50.0).abs() < 1e-6, "{c:?}");
    assert!((s.scale() / 5_000_000.0 - 1.0).abs() < 0.02, "{}", s.scale());
    // An export at another size measures its scale bar with its own camera.
    let wide = s.map().ground_res_at(&rustgis_map::Camera { res: s.map().camera.res * 3.0, ..s.map().camera });
    assert!((wide / s.map().ground_res() - 3.0).abs() < 1e-9);
    // The built-in world projections (and Equal Earth by its EPSG code) draw the whole world.
    for p in ["robinson", "equalEarth", "naturalEarth", "winkelTripel", "eckertIV", "EPSG:8857"] {
        s.run("map.projection", &json!({"type": p})).unwrap_or_else(|e| panic!("{p}: {e}"));
        s.run("map.zoomFull", &Value::Null).unwrap();
        let c = s.map().center_lonlat();
        assert!(c.x.abs() < 1.0 && c.y.abs() < 30.0, "{p}: {c:?}");
        let v = s.run("identify", &json!({"lon": 2.35, "lat": 48.85, "tolerancePx": 5})).unwrap();
        assert!(!v.is_null(), "{p}: something is under Paris");
        assert!(crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap().len() > 1000, "{p}");
    }
}

#[test]
fn raster_layers_open_style_identify_and_round_trip() {
    let mut s = with_raster();
    let l = s.map().layers.first().unwrap();
    assert!(l.is_raster(), "a new raster goes on top, as every new layer does (#808)");
    assert_eq!(l.name, "scene");
    assert_eq!(s.active_layer, Some(l.id));
    let e = l.extent();
    assert!((e.center().x + 81.0).abs() < 0.1 && (e.center().y - 42.0).abs() < 0.1, "{e:?}");
    // Rendering, stretches and enhancement.
    for p in [
        json!({"type": "stretch", "band": 2, "ramp": "Terrain"}),
        json!({"type": "classify", "classes": 4, "method": "quantile"}),
        json!({"type": "unique"}),
        json!({"type": "shadedRelief", "azimuth": 270}),
        json!({"type": "rgb"}),
    ] {
        s.run("raster.symbology", &p).unwrap_or_else(|e| panic!("{p}: {e}"));
    }
    // Bounds typed by hand are for Graduated Colors: a raster's classes are worked out.
    assert!(s.run("raster.symbology", &json!({"type": "classify", "method": "manual"})).is_err());
    assert!(s.run("raster.symbology", &json!({"type": "colormap"})).is_err());
    assert!(s.run("raster.symbology", &json!({"band": 9})).is_err());
    s.run("raster.bands", &json!({"red": 3, "green": 2, "blue": 1})).unwrap();
    s.run("raster.symbology", &json!({"type": "rgb"})).unwrap(); // keeps the combination
    assert!(s.run("raster.bands", &json!({"preset": "colorInfrared"})).is_err(), "no band 4");
    s.run("raster.stretch", &json!({"type": "standardDeviation", "n": 2.5})).unwrap();
    s.run("raster.dra", &json!({"on": true})).unwrap();
    s.run("raster.resampling", &json!({"type": "bilinear"})).unwrap();
    s.run("raster.enhance", &json!({"brightness": 20, "contrast": -10, "gamma": 1.4})).unwrap();
    s.run("layer.ramp", &json!({"ramp": "Aurora"})).unwrap();
    let st = s.map().layers.first().unwrap().raster.as_ref().unwrap().style.clone();
    assert_eq!(st.renderer, rustgis_map::RasterRenderer::Rgb { red: 2, green: 1, blue: 0 });
    assert!(st.dra && st.gamma == 1.4);
    // Feature-only commands are off for rasters, and layer conditions follow a named layer.
    assert!(s.run("table.open", &Value::Null).is_err());
    assert!(s.run("labels.enable", &json!({"layer": "scene"})).is_err());
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "single"})).unwrap();
    s.active_layer = s.map().layer_by_name("Countries").map(|l| l.id);
    s.run("raster.info", &json!({"layer": "scene"})).unwrap();
    s.active_layer = s.map().layer_by_name("scene").map(|l| l.id);
    // Identify reports features first (Lake Erie is here), then pixel values.
    let v = s.run("identify", &json!({"lon": -81.0, "lat": 42.0})).unwrap();
    assert_eq!(v["layer"], "Lakes", "{v}");
    for l in ["Cities", "Rivers", "Lakes", "Countries"] {
        s.run("layer.visibility", &json!({"layer": l, "visible": false})).unwrap();
    }
    let v = s.run("identify", &json!({"lon": -81.0, "lat": 42.0})).unwrap();
    assert_eq!(v["raster"], true, "{v}");
    assert!(v["attributes"]["Band 1"].is_string());
    let info = s.run("raster.info", &Value::Null).unwrap();
    assert_eq!(info["crs"], "EPSG:32617");
    assert_eq!(info["bands"].as_array().map(Vec::len), Some(3));
    // Export, then reopen from the file.
    let dir = std::env::temp_dir().join(format!("rustgis-raster-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let tif = dir.join("out.tif");
    s.run("share.exportRaster", &json!({"path": tif.display().to_string()})).unwrap();
    s.run("layer.addData", &json!({"path": tif.display().to_string()})).unwrap();
    assert!(s.map().layer_by_name("out").is_some_and(|l| l.raster.as_ref().is_some_and(|r| r.path.is_some())));
    // Save and reload the project: the upload is embedded, the file is reopened by path.
    let proj = dir.join("p.rgis");
    s.run("project.saveAs", &json!({"path": proj.display().to_string()})).unwrap();
    s.run("project.open", &json!({"path": proj.display().to_string()})).unwrap();
    for name in ["scene", "out"] {
        let l = s.map().layer_by_name(name).unwrap();
        assert!(l.raster.as_ref().unwrap().data.is_some(), "{name} reloaded");
    }
    assert!(s.map().layer_by_name("scene").unwrap().raster.as_ref().unwrap().style.dra, "style kept");
    // Undo after a style change restores the previous style.
    s.active_layer = s.map().layer_by_name("scene").map(|l| l.id);
    s.run("raster.dra", &json!({"on": false})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert!(s.map().layer_by_name("scene").unwrap().raster.as_ref().unwrap().style.dra);
    let _ = std::fs::remove_dir_all(&dir);
    // The map renders with rasters.
    assert!(crate::cmd::share::map_png(&mut s, Some(320.0), Some(200.0), None).is_ok());
}

/// #348: `raster.mask` hides pixel values on the fly: values drawn as no data and a range,
/// kept in the project and undone like any style change.
#[test]
fn raster_masks_hide_values() {
    let mut s = with_raster();
    let style = |s: &Session| s.map().layer_by_name("scene").unwrap().raster.as_ref().unwrap().style.clone();
    let info = s.run("raster.info", &Value::Null).unwrap();
    let (lo, hi) = (info["bands"][0]["min"].as_f64().unwrap(), info["bands"][0]["max"].as_f64().unwrap());
    assert!(info["mask"].is_null());
    s.run("raster.mask", &json!({"values": format!("{lo}, {lo} ; {hi}")})).unwrap();
    assert_eq!(style(&s).mask.values, vec![lo, hi], "text, sorted and without repeats");
    let rl = s.map().layer_by_name("scene").unwrap().raster.clone().unwrap();
    let st = rl.masked_stats().unwrap();
    assert!(st[0].min > lo && st[0].max < hi, "{:?}", st[0]);
    // A range on top, then the other way round; a bound given as null is removed.
    s.run("raster.mask", &json!({"min": lo + 1.0, "max": hi - 1.0})).unwrap();
    s.run("raster.mask", &json!({"inside": true, "max": null})).unwrap();
    let m = style(&s).mask;
    assert_eq!((m.min, m.max, m.inside, m.values.len()), (Some(lo + 1.0), None, true, 2));
    assert!(s.run("raster.info", &Value::Null).unwrap()["mask"].as_str().is_some_and(|t| t.contains('≥')));
    // Refused: a reversed range, values that aren't numbers, too many values.
    assert!(s.run("raster.mask", &json!({"min": 5, "max": 1})).is_err());
    assert!(s.run("raster.mask", &json!({"values": "1, x"})).is_err());
    assert!(s.run("raster.mask", &json!({"values": [1, "nan"]})).is_err());
    assert!(s.run("raster.mask", &json!({"min": "x"})).is_err());
    assert!(s.run("raster.mask", &json!({"values": (0..300).collect::<Vec<_>>()})).is_err());
    assert_eq!(style(&s).mask, m, "nothing changed by a refused mask");
    // Class breaks follow the pixels shown.
    s.run("raster.mask", &json!({"clear": true, "min": lo, "max": (lo + hi) / 2.0})).unwrap();
    s.run("raster.symbology", &json!({"type": "classify", "classes": 4})).unwrap();
    let top = |s: &Session| match style(s).renderer {
        rustgis_map::RasterRenderer::Classify { breaks, .. } => breaks.last().copied().unwrap_or_default(),
        _ => f64::NAN,
    };
    assert!(top(&s) <= (lo + hi) / 2.0, "{}", top(&s));
    s.run("raster.mask", &json!({"max": null})).unwrap();
    assert!(top(&s) > (lo + hi) / 2.0, "worked out again without the bound");
    // Masking down to one value collapses the classes; clearing the mask brings back the 4 asked for.
    let classes = |s: &Session| match style(s).renderer {
        rustgis_map::RasterRenderer::Classify { breaks, .. } => breaks.len(),
        _ => 0,
    };
    s.run("raster.mask", &json!({"min": lo, "max": lo})).unwrap();
    assert_eq!(classes(&s), 1);
    s.run("raster.mask", &json!({"clear": true})).unwrap();
    assert_eq!(classes(&s), 4);
    // Undo the clear and the one-value range.
    s.run("edit.undo", &Value::Null).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    // Breaks edited by hand are kept.
    let mut edited = style(&s);
    if let rustgis_map::RasterRenderer::Classify { breaks, .. } = &mut edited.renderer {
        breaks[0] += 0.5;
    }
    let id = s.map().layer_by_name("scene").unwrap().id;
    s.map_mut().layer_mut(id).unwrap().raster.as_mut().unwrap().style = edited.clone();
    s.run("raster.mask", &json!({"values": [lo]})).unwrap();
    assert_eq!(style(&s).renderer, edited.renderer);
    // Undo that mask.
    s.run("edit.undo", &Value::Null).unwrap();
    // Undo removing the max bound; then saved and drawn.
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(style(&s).mask.max, Some((lo + hi) / 2.0));
    let dir = std::env::temp_dir().join(format!("rustgis-mask-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let proj = dir.join("p.rgis");
    s.run("project.saveAs", &json!({"path": proj.display().to_string()})).unwrap();
    s.run("project.open", &json!({"path": proj.display().to_string()})).unwrap();
    assert_eq!(style(&s).mask.max, Some((lo + hi) / 2.0), "kept in the project");
    let _ = std::fs::remove_dir_all(&dir);
    assert!(crate::cmd::share::map_png(&mut s, Some(320.0), Some(200.0), None).is_ok());
    s.active_layer = s.map().layer_by_name("scene").map(|l| l.id);
    s.run("raster.mask", &json!({"clear": true})).unwrap();
    assert!(style(&s).mask.is_empty());
}

/// Shards of `hostile_params_never_panic`: each takes every eighth command, so the parts run side by
/// side (opengeos/RustGIS#1201).
const HOSTILE_SHARDS: usize = 8;
const _: () = assert!(HOSTILE_SHARDS == 8, "add a hostile_params_never_panic_N test for each shard");

#[test]
fn hostile_params_never_panic_0() {
    hostile_params_never_panic(0);
}

#[test]
fn hostile_params_never_panic_1() {
    hostile_params_never_panic(1);
}

#[test]
fn hostile_params_never_panic_2() {
    hostile_params_never_panic(2);
}

#[test]
fn hostile_params_never_panic_3() {
    hostile_params_never_panic(3);
}

#[test]
fn hostile_params_never_panic_4() {
    hostile_params_never_panic(4);
}

#[test]
fn hostile_params_never_panic_5() {
    hostile_params_never_panic(5);
}

#[test]
fn hostile_params_never_panic_6() {
    hostile_params_never_panic(6);
}

#[test]
fn hostile_params_never_panic_7() {
    hostile_params_never_panic(7);
}

/// Every command with junk parameters returns Ok or Err, never panics, and leaves a usable session.
/// Runs the commands of one shard: those whose place in the registry is `shard` modulo
/// [`HOSTILE_SHARDS`].
fn hostile_params_never_panic(shard: usize) {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test(&format!("tests::hostile_params_never_panic_{shard}")) {
        return;
    }
    let junk = [
        Value::Null,
        json!({}),
        // Shared vertex moves: valid row/destination, hostile node addresses and coordinate types.
        json!({"layer":"Countries","row":0,"part":u64::MAX,"ring":-1,"index":[],"lon":12,"lat":45}),
        json!({"layer":"Countries","row":0,"part":0,"ring":0,"index":0,"lon":{},"lat":1e300}),
        json!({"layer": 99999, "path": "/nonexistent/x.geojson", "name": "", "where": "((", "tool": "buffer", "params": 7}),
        json!({"layer": "Countries", "row": 1e30, "field": "nope", "value": [1], "scale": -1, "lon": 1e300, "lat": "x", "classes": 1e9, "type": "graduated"}),
        // Label halos and spacing: out of range, of the wrong type.
        json!({"layer": "Cities", "haloWidth": 1e308, "haloColor": 7, "spacing": "NaN"}),
        json!({"layer": "Cities", "haloWidth": -1, "haloColor": "#zzz", "spacing": -1e9}),
        json!({"layer": "Cities", "rows": [1, 99999999], "geometry": {"type": "Polygon", "coordinates": [[]]}, "width": 1e9, "height": -3, "expression": "'"}),
        json!({"band": -1, "red": 1e12, "green": "x", "blue": f64::MAX, "preset": "", "ramp": "nope", "classes": -5, "n": 1e308, "low": -50, "high": 900, "gamma": 0, "zFactor": -1, "fileName": "a.tif", "data": "!!!"}),
        json!({"fileName": "a.tif", "data": "AAAA", "type": "unique", "on": "maybe"}),
        json!({"type": "custom", "min": 1e308, "max": -1e308}),
        json!({"type": "custom", "min": [1e308, "x", null, 4], "max": [null, -1e308, 5]}),
        json!({"type": "custom", "min": [1e308, null, 0], "max": [-1e308, f64::NAN, null], "red": 3}),
        json!({"kind": "colorbar", "ticks": -1e308, "tickSide": 7, "orientation": "x", "layer": "", "reverse": "maybe"}),
        json!({"type": "albers", "lon_0": f64::MAX, "lat_1": "x", "lat_2": -1e308}),
        json!({"kind": "legend", "element": 1, "exclude": [null, 7, "", {"x": 1}]}),
        json!({"kind": "text", "element": 1, "font": {"family": "serif"}, "italic": [], "align": 7}),
        // A QGIS project and style whose web layer and scale range are junk.
        json!({"text": "<qgis><projectlayers><maplayer type=\"raster\" hasScaleBasedVisibilityFlag=\"1\" minScale=\"NaN\" maxScale=\"-1e308\"><datasource>type=xyz&amp;url=&amp;zmax=999</datasource><layername></layername><provider>wms</provider><pipe><rasterrenderer opacity=\"inf\"/></pipe></maplayer></projectlayers></qgis>"}),
        // A label class placed along lines, with junk the placement and style read after it.
        json!({"layer": "Countries", "position": "curved", "italic": "maybe", "size": -1e308}),
        // A publication sheet's style, accent and orientation, and a shape's rounded corners.
        // (The profile left out or valid, so the style and accent are reached.)
        json!({"style": 7, "accent": "#XYZ", "kind": "ellipse", "element": 1, "radius": "x"}),
        json!({"style": "", "accent": [], "kind": "rectangle", "element": 1, "radius": -1e308}),
        json!({"profile": "a3", "style": "poster", "accent": "#ZZZZZZ", "kind": "rectangle", "radius": 1e308}),
        // A STAC trend's source: a valid band and period so the junk after them is reached, and an
        // API on a closed local port, so nothing is read.
        json!({"collection": "c", "asset": "NDVI", "url": "http://127.0.0.1:9/v1", "bbox": "nowhere", "cellSize": -1e308, "resampling": 3, "start": "2020", "end": "2021"}),
        json!({"collection": "c", "asset": "NDVI", "url": "http://127.0.0.1:9/v1", "bbox": [1e308, -91, 7, "x"], "start": "2020", "end": "2021"}),
        // A summary over time: a statistic given, so its threshold, groups and share are reached.
        json!({"stat": "countAbove", "above": "x", "by": 7, "minValid": -1e308, "months": [13, "x", null], "name": {"a": 1}}),
        json!({"stat": "std", "by": "month", "minValid": f64::NAN, "dates": ["x", 7, null]}),
        // A categorical summary: countIn's classes, and a mode by groups with a share out of range.
        json!({"stat": "countIn", "classes": [1e308, -1, "x", null, 3.5, {"a": 1}]}),
        json!({"stat": "countIn", "classes": "all", "by": "year"}),
        // A web-service connection's login method and secret, and the connection an add records.
        json!({"id": "c1", "kind": "wms", "auth": "query", "keyName": "\u{0}", "user": ":", "apiKey": "\n", "password": [], "allowInsecure": "yes", "connection": 7}),
        json!({"id": "c1", "auth": "basic", "user": 7, "keyName": {"a": 1}, "apiKey": "k".repeat(9000), "remember": "yes", "connection": "c999999"}),
        json!({"stat": "mode", "by": "month", "minValid": 2, "months": []}),
        json!({"stat": "frequency", "by": "year", "minValid": -1, "name": []}),
        // MySQL addresses that can't be read, so nothing connects.
        json!({"database": "mysql://u:p#@[::1/x?ssl-mode=nope", "password": 7, "layer": ":", "crs": "EPSG:-1"}),
        json!({"database": "MARIADB://u@h:99999999/%zz?ssl-mode=VERIFY_CA&ssl-ca=/nonexistent", "sql": "SELECT 1"}),
        json!({"database": "mssql://u:p#@[::1/x?encrypt=nope", "password": 7, "layer": ":", "crs": "EPSG:-1"}),
        json!({"database": "MSSQL://u@h:99999999/%zz?ca=/nonexistent", "sql": "SELECT 1"}),
        // Control points that don't parse, then ones that reach a fit.
        json!({"points": [[], 7, [1, 2, 3, 4, "x"]], "transform": "spline"}),
        json!({"points": [[0, 0, 1e308, -1e308], [1, 0, -1e308, 1e308], [0, 1, 1e308, 1e308], [1, 1, 0, 0, 0]], "transform": "spline"}),
        json!({"points": vec![json!([5, 5, 1, 1]); 1000], "compare": true}),
        // A warp: junk systems, sizes and paths with points that reach the fit.
        json!({"transform": "spline", "crs": "EPSG:999999999", "pointsCrs": [7], "resampling": 1, "cellSize": -1e308, "path": 5, "points": [[0, 0, 1, 1]]}),
        json!({"transform": "affine", "crs": 32613, "pointsCrs": 4326, "cellSize": 1e-300, "path": "/nonexistent/x.tif", "points": [[0, 0, 1, 1], [1, 0, 2, 1], [0, 1, 1, 2]]}),
        json!({"points": [[0, 0, f64::MAX, f64::MAX], [1, 0, -f64::MAX, f64::MAX], [0, 1, f64::MAX, -f64::MAX]], "compare": true}),
        // Polygons burned: a layer, a value and a no-data that pass, then a grid that can't be made.
        json!({"layer": "Countries", "value": 3, "nodata": -1e30, "cellSize": [1e-300, 1e300], "origin": [1e308, -1e308]}),
        json!({"layer": "Countries", "field": "name", "nodata": f64::MAX, "grid": [], "extent": "view", "path": 7}),
        // Connections: junk kinds, options and secrets; no connection exists in a fresh session.
        json!({"id": "c1", "kind": "s3", "address": "http://127.0.0.1:9", "name": "\u{7}", "group": 5, "options": {"credentials": "nope", "buckets": "NO_", "region": [1]}, "password": 7, "remember": [true], "accessKeyId": "A", "secretAccessKey": 9}),
        json!({"id": "", "kind": "postgres", "address": "postgres:host=127.0.0.1 port=9 password=x", "options": "x"}),
        json!({"kind": "wms", "address": "http://127.0.0.1:9/wms", "probe": "x", "answer": 7}),
        json!({"id": {"unexpected":"object"}, "remember": "true", "password": []}),
        json!({"kind": "stac", "address": "http://127.0.0.1:9/stac", "answer": "\u{0}{"}),
        json!({"id": "c1", "node": "s3:/\u{7}", "probe": true, "answer": 7, "documents": "x"}),
        // Saved S3 keys: junk remember flags, partial pairs, tokens, and a choice of nothing.
        json!({"id": "c1", "accessKeyId": "A", "secretAccessKey": "S", "sessionToken": "T", "remember": "yes"}),
        json!({"id": "c1", "accessKeyId": 7, "secretAccessKey": [], "remember": null}),
        json!({"id": "c1", "remember": true, "source": "rustgis-s3:junk", "node": 5}),
        json!({"source": "rustgis-s3::0::s3://bucket/key", "id": "c1", "remember": {"a": 1}}),
        json!({"source": 7, "id": ["c1"]}),
    ];
    let ids: Vec<&str> = Session::new(Project::default())
        .registry
        .commands
        .iter()
        .enumerate()
        .filter(|(i, _)| i % HOSTILE_SHARDS == shard)
        .map(|(_, c)| c.id)
        .collect();
    // Shards share the process under `cargo test`: each streams its own file.
    let streamed = grid_fgb(&format!("hostile-{shard}"), 20);
    for id in ids {
        if matches!(
            id,
            "project.save"
                | "project.saveAs"
                | "project.exportLog"
                | "share.exportMap"
                | "time.export"
                | "share.exportLayer"
                | "share.exportTable"
                | "share.exportRaster"
                // Download from the network.
                | "gp.installGeolibre"
                // Deletes the installed GeoLibre runner.
                | "gp.uninstallGeolibre"
                | "plugin.registry"
                | "plugin.installFromRegistry"
                // Ask Earth Search when no API is given.
                | "stac.collections"
                | "stac.search"
                // Asks geoBoundaries for its list.
                | "boundaries.countries"
                // Asks Source Cooperative for its featured products.
                | "sourcecoop.products"
                // Starts a sign-in's callback server (RustGIS's own app on ArcGIS Online).
                | "arcgis.signIn"
                // Signs every session out, which the process's other tests use (its junk is
                // covered by an_arcgis_token_in_a_service_address_reaches_its_layers).
                | "arcgis.signOut"
        ) {
            continue;
        }
        for p in &junk {
            // Places given by name go to the public geocoder: with an answer given, the junk
            // goes through reading it and the options, and nothing is fetched.
            let routed;
            let p = match p {
                Value::Object(o) if id == "map.route" => {
                    let mut o = o.clone();
                    o.insert("answer".into(), json!(r#"{"code":"Ok","routes":[{"legs":[{"steps":[{"geometry":"_ibE_ibE_ibE_ibE","maneuver":{"type":"depart"}}]}]}]}"#));
                    routed = Value::Object(o);
                    &routed
                }
                _ if id == "map.route" => continue,
                p => p,
            };
            let mut s = world();
            let _ = s.run(id, p);
            let _ = s.run("info.project", &Value::Null);
            // Again with a raster layer active.
            let mut s = with_raster();
            let _ = s.run(id, p);
            let _ = s.run("info.project", &Value::Null);
            // And with a streamed layer active.
            let mut s = with_streamed(&streamed);
            let _ = s.run(id, p);
            let _ = s.run("info.project", &Value::Null);
        }
    }
}

#[test]
fn every_tool_survives_an_environment_extent() {
    // An extent holding some features, and one holding none, with every tool and junk params.
    for extent in [json!([0, 40, 20, 55]), json!([-179.9, -89, -179.8, -88.9])] {
        for t in rustgis_analysis::tools().filter(|t| !rustgis_analysis::is_external(t)) {
            let mut s = world();
            s.run("gp.env", &json!({"extent": extent})).unwrap();
            for params in [json!({"input": "Countries"}), json!({"input": "Cities", "distance": 1e9, "clip": "Countries"})] {
                let _ = s.run("gp.run", &json!({"tool": t.id, "params": params}));
            }
            let _ = s.run("info.project", &Value::Null);
        }
    }
    let mut s = world();
    s.run("gp.env", &json!({"extent": [-179.9, -89, -179.8, -88.9]})).unwrap();
    let e = s.run("gp.run", &json!({"tool": "buffer", "params": {"input": "Cities", "distance": 10}})).unwrap_err();
    assert!(e.contains("inside the environment"), "{e}");
}

#[cfg(feature = "geolibre")]
#[test]
fn geolibre_tools_run_on_layers_and_add_their_outputs() {
    let mut s = with_raster();
    let st = s.run("gp.geolibre", &Value::Null).unwrap();
    assert_eq!(st["supported"], true);
    assert!(s.run("gp.setGeolibre", &json!({"path": "/no/such/geolibre"})).is_err(), "not a runner");
    let undo = s.undo_label();
    s.run("gp.setGeolibre", &json!({"path": ""})).unwrap();
    assert_eq!(s.undo_label(), undo, "choosing a runner isn't an edit");
    if st["available"] != true {
        eprintln!("skipped: no GeoLibre runner (set RUSTGIS_GEOLIBRE)");
        return;
    }
    let tools = s.run("gp.tools", &Value::Null).unwrap();
    assert!(tools.as_array().unwrap().iter().any(|t| t["id"] == "geolibre:slope"));
    let before = s.map().layers.len();
    let r = s.run("gp.run", &json!({"tool": "geolibre:slope", "params": {"input": "scene"}})).unwrap();
    assert_eq!(r["layers"].as_array().map(Vec::len), Some(1), "{r}");
    assert_eq!(s.map().layers.len(), before + 1);
    let slope = s.map().layer_by_name("Slope").unwrap();
    assert!(slope.is_raster() && slope.raster.as_ref().is_some_and(|r| r.embedded.is_some()), "kept in the project");
    // It saves with the project, and undo takes it away.
    let json = serde_json::to_string(&s.project).unwrap();
    assert!(
        Project::from_json(&json)
            .unwrap()
            .map()
            .layer_by_name("Slope")
            .is_some_and(|l| l.raster.as_ref().is_some_and(|r| r.data.is_some()))
    );
    s.run("edit.undo", &Value::Null).unwrap();
    assert!(s.map().layer_by_name("Slope").is_none());
    // A vector where a raster belongs is an error, not a crash.
    let err = s.run("gp.run", &json!({"tool": "geolibre:slope", "params": {"input": "Cities"}})).unwrap_err();
    assert!(err.starts_with("Slope:"), "{err}");
}

/// The browser's way: prepare a run, let a runner (here, pretend) produce the files, then
/// apply it with `gp.finish`, which keeps undo and history.
#[cfg(feature = "geolibre")]
#[test]
fn geolibre_runs_can_finish_asynchronously() {
    use crate::cmd::gp::{external_complete, external_start};
    let mut s = with_raster();
    assert!(s.run("gp.finish", &json!({"id": 99})).is_err(), "nothing pending");
    assert!(external_complete(&mut s, 99, Ok((vec![], vec![]))).is_err(), "nothing started");
    if s.run("gp.geolibre", &Value::Null).unwrap()["available"] != true {
        eprintln!("skipped: no GeoLibre runner (set RUSTGIS_GEOLIBRE)");
        return;
    }
    assert!(external_start(&mut s, "geolibre:slope", &json!({})).err().unwrap().contains("required"));
    assert!(external_start(&mut s, "buffer", &json!({})).is_err(), "only GeoLibre tools");
    let run = external_start(&mut s, "geolibre:slope", &json!({"input": "scene"})).unwrap();
    assert_eq!((run.tool.as_str(), run.files.len()), ("slope", 1), "the embedded raster is staged");
    assert!(run.argv.iter().any(|a| a.starts_with("--output=/work/")));
    // The "runner" writes the input back as the output.
    let out = run.files[0].1.clone();
    external_complete(&mut s, run.id, Ok((vec![("output.tif".into(), out)], vec![]))).unwrap();
    let before = s.map().layers.len();
    let r = s.run("gp.finish", &json!({"id": run.id})).unwrap();
    assert_eq!(r["layers"].as_array().map(Vec::len), Some(1), "{r}");
    assert_eq!(s.map().layers.len(), before + 1);
    assert!(s.project.gp_history.last().is_some_and(|h| h.ok && h.tool == "Slope"));
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().layers.len(), before, "undo removes it");
    assert!(s.run("gp.finish", &json!({"id": run.id})).is_err(), "applied once");
    // A runner error is reported like a failed gp.run.
    let run = external_start(&mut s, "geolibre:slope", &json!({"input": "scene"})).unwrap();
    external_complete(&mut s, run.id, Err("trap".into())).unwrap();
    assert_eq!(s.run("gp.finish", &json!({"id": run.id})).unwrap_err(), "Slope: trap");
    // A run of a project that was closed meanwhile doesn't land in the new one.
    let run = external_start(&mut s, "geolibre:slope", &json!({"input": "scene"})).unwrap();
    s.run("project.new", &Value::Null).unwrap();
    assert!(external_complete(&mut s, run.id, Ok((vec![], vec![]))).unwrap_err().contains("project was closed"));
}

#[test]
fn clipboard_copies_cuts_and_pastes_features() {
    let mut s = world();
    assert!(s.run("edit.copy", &Value::Null).is_err(), "nothing selected");
    s.run("select.byAttributes", &json!({"layer": "Cities", "where": "name = 'Paris'"})).unwrap();
    let r = s.run("edit.copy", &Value::Null).unwrap();
    assert_eq!(r["copied"], 1);
    let text = r["text"].as_str().unwrap().to_string();
    assert!(text.contains("Paris"));
    // Into the same layer, then as a new layer, then from GeoJSON text.
    let n = s.map().layer_by_name("Cities").unwrap().dataset.features.len();
    s.run("edit.paste", &json!({"layer": "Cities"})).unwrap();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().dataset.features.len(), n + 1);
    assert!(s.run("edit.paste", &json!({"layer": "Countries"})).is_err(), "points don't go in polygons");
    let r = s.run("edit.pasteSpecial", &json!({"name": "Copied"})).unwrap();
    assert_eq!(r["pasted"], 1);
    assert_eq!(s.map().layer_by_name("Copied").unwrap().dataset.features.len(), 1);
    s.run("edit.pasteSpecial", &json!({"text": text, "name": "FromText"})).unwrap();
    assert!(s.map().layer_by_name("FromText").is_some());
    assert!(s.run("edit.paste", &json!({"layer": "Cities", "text": "not json"})).is_err());
    // Cut removes the features.
    s.run("select.byAttributes", &json!({"layer": "Cities", "where": "name = 'Paris'"})).unwrap();
    let cut = s.run("edit.cut", &Value::Null).unwrap();
    assert_eq!(cut["copied"], 2);
    assert_eq!(s.map().layer_by_name("Cities").unwrap().dataset.features.len(), n - 1);
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().dataset.features.len(), n + 1);
    // The sample layers live in the project, not in files.
    assert!(s.run("layer.copyPath", &json!({"layer": "Cities"})).is_err());
}

#[test]
fn popup_modes_choose_what_identify_reports() {
    let mut s = world();
    let at = json!({"lon": 2.35, "lat": 48.85, "tolerancePx": 5});
    let top = s.run("identify", &at).unwrap();
    assert_eq!(top["layer"], "Cities");
    s.run("map.popupMode", &json!({"mode": "visible"})).unwrap();
    let all = s.run("identify", &at).unwrap();
    let layers: Vec<&str> = all["results"].as_array().unwrap().iter().map(|r| r["layer"].as_str().unwrap()).collect();
    assert_eq!(layers, ["Cities", "Countries"]);
    s.run("map.popupMode", &json!({"mode": "selectedInContents"})).unwrap();
    s.run("layer.select", &json!({"layer": "Countries"})).unwrap();
    assert_eq!(s.run("identify", &at).unwrap()["layer"], "Countries");
    s.run("map.popupMode", &json!({"mode": "none"})).unwrap();
    assert!(s.run("identify", &at).unwrap().is_null());
    assert!(s.run("map.popupMode", &json!({"mode": "bogus"})).is_err());
    // The mode is saved with the project.
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(text.contains("\"popup_mode\":\"None\""));
}

#[test]
fn identify_reports_every_overlapping_feature() {
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let mut s = world();
    // Two buoys on one spot of the South Atlantic, far from any country, under a float.
    let spot = || Some(Geometry::Point(rustgis_geom::Coord::new(-20.0, -30.0)));
    let mut d = Dataset::new("Buoys", GeometryType::Point, vec![Field::new("n", FieldType::Integer)]);
    for n in [1, 2] {
        d.push(spot(), vec![V::Int(n)]);
    }
    let id = u64::from(s.map_mut().add_dataset(d));
    let mut d = Dataset::new("Floats", GeometryType::Point, vec![Field::new("n", FieldType::Integer)]);
    d.push(spot(), vec![V::Int(1)]);
    let float = u64::from(s.map_mut().add_dataset(d));
    let at = json!({"lon": -20.0, "lat": -30.0, "tolerancePx": 5});
    let rows = |v: &Value| {
        v["results"].as_array().unwrap().iter().map(|r| (r["layerId"].as_u64().unwrap(), r["row"].as_u64().unwrap())).collect::<Vec<_>>()
    };
    // Topmost: every feature of the top layer with one; both buoys, the one drawn on top first (#232).
    assert_eq!(rows(&s.run("identify", &at).unwrap()), [(float, 0)]);
    s.run("layer.visibility", &json!({"layer": "Floats", "visible": false})).unwrap();
    let top = s.run("identify", &at).unwrap();
    assert_eq!(rows(&top), [(id, 1), (id, 0)]);
    assert_eq!(top["row"], 1);
    // Each result carries its feature id, to find the feature again after a streamed read.
    assert_eq!(top["results"][0]["fid"], 2);
    assert_eq!(top["results"][1]["fid"], 1);
    s.run("layer.visibility", &json!({"layer": "Floats", "visible": true})).unwrap();
    s.run("map.popupMode", &json!({"mode": "visible"})).unwrap();
    assert_eq!(rows(&s.run("identify", &at).unwrap()), [(float, 0), (id, 1), (id, 0)]);
    // Selectable: every selectable layer, not only the top one.
    s.run("map.popupMode", &json!({"mode": "selectable"})).unwrap();
    assert_eq!(rows(&s.run("identify", &at).unwrap()), [(float, 0), (id, 1), (id, 0)]);
    s.run("layer.selectable", &json!({"layer": "Floats", "on": false})).unwrap();
    assert_eq!(rows(&s.run("identify", &at).unwrap()), [(id, 1), (id, 0)]);
    // A definition query hides one.
    s.run("layer.definitionQuery", &json!({"layer": "Buoys", "where": "n = 1"})).unwrap();
    assert_eq!(rows(&s.run("identify", &at).unwrap()), [(id, 0)]);
}

#[test]
fn label_size_stays_within_what_text_symbol_shows() {
    // Labeling › Text Symbol offers the range `labels.style` accepts (#457): 72 pt is kept, and
    // anything outside is brought back to the nearest end.
    let mut s = world();
    let size = |s: &Session| s.map().layers.iter().find(|l| l.name == "Countries").map(|l| f64::from(l.labels.default.size));
    for (given, kept) in [(72.0, 72.0), (100.0, 72.0), (1.0, 4.0)] {
        s.run("labels.style", &json!({"layer": "Countries", "size": given})).unwrap();
        assert_eq!(size(&s), Some(kept), "size {given}");
    }
    let range = rustgis_map::symbology::LABEL_SIZE;
    assert_eq!((*range.start(), *range.end()), (4.0, 72.0));
}

#[test]
fn label_range_placement_lock_and_convert() {
    use crate::render::View;
    let mut s = world();
    s.run("labels.enable", &json!({"layer": "Countries", "on": true})).unwrap();
    s.run("map.goToXY", &json!({"lon": 10.0, "lat": 50.0, "scale": 20_000_000})).unwrap();
    let view = |s: &Session| View { width: 800.0, height: 600.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
    let count = |s: &mut Session| {
        let v = view(s);
        crate::render::render(s.map_mut(), &v).unwrap().labels.len()
    };
    let placed = count(&mut s);
    assert!(placed > 5);
    // Out beyond 1:5,000,000: no labels at 1:20,000,000.
    s.run("labels.scaleRange", &json!({"layer": "Countries", "min": 5_000_000})).unwrap();
    let n = count(&mut s);
    assert!(n < placed, "{n} < {placed}");
    s.run("labels.scaleRange", &json!({"layer": "Countries", "clear": true})).unwrap();
    assert_eq!(count(&mut s), placed);
    s.run("labels.distanceRange", &json!({"layer": "Countries", "farthest": 1000})).unwrap();
    assert!(count(&mut s) < placed);
    s.run("labels.distanceRange", &json!({"layer": "Countries", "farthest": null})).unwrap();
    assert!(s.run("labels.scaleRange", &json!({"layer": "Countries", "min": -4})).is_err());
    // Pause hides every label; unplaced labels are reported when asked for.
    s.run("labels.pause", &json!({"on": true})).unwrap();
    assert_eq!(count(&mut s), 0);
    s.run("labels.pause", &json!({"on": false})).unwrap();
    s.run("labels.viewUnplaced", &json!({"on": true})).unwrap();
    let v = view(&s);
    let r = crate::render::render(s.map_mut(), &v).unwrap();
    assert!(!r.unplaced.is_empty() && r.unplaced.iter().all(|l| l.color == crate::render::UNPLACED));
    s.run("labels.viewUnplaced", &json!({"on": false})).unwrap();
    // Placement moves labels.
    s.run("labels.placement", &json!({"layer": "Cities", "position": "right"})).unwrap();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().labels.default.placement, crate::map::LabelPlacement::Right);
    assert!(s.run("labels.placement", &json!({"position": "sideways"})).is_err());
    // Lock keeps the labelled set as the map moves.
    s.run("labels.lock", &json!({"on": true})).unwrap();
    let locked = count(&mut s);
    assert!(s.map().label_lock.is_some());
    s.run("map.zoomOut", &Value::Null).unwrap();
    assert!(count(&mut s) <= locked);
    s.run("labels.lock", &json!({"on": false})).unwrap();
    count(&mut s);
    assert!(s.map().label_lock.is_none());
    // Convert makes an annotation layer and turns the source's labels off; its labels stay on
    // their points, even when the source's classes had the other places on (#1011: refused for
    // polygons by labels.placement, but a project file may have it).
    s.run("labels.class.add", &json!({"layer": "Countries", "name": "Big", "where": "pop_est > 100000000"})).unwrap();
    let countries = s.map().layer_by_name("Countries").unwrap().id;
    let labels = &mut s.map_mut().layer_mut(countries).unwrap().labels;
    labels.default.other_positions = true;
    labels.classes.iter_mut().for_each(|c| c.other_positions = true);
    let r = s.run("labels.convert", &json!({"layer": "Countries"})).unwrap();
    assert!(r["annotations"].as_u64().unwrap() > 100);
    let a = s.map().layer_by_name("Countries Annotation").unwrap();
    assert!(a.labels.enabled && a.labels.default.field == "TEXT");
    assert!(!a.labels.default.other_positions && !a.labels.classes.is_empty());
    assert!(a.labels.classes.iter().all(|c| !c.other_positions), "every class's, not only Default's");
    assert!(!s.map().layer_by_name("Countries").unwrap().labels.enabled);
}

/// A label class's font is set by its family name, installed here or not (the project may be
/// drawn on a machine that has it), and cleared with a blank one; `labels.fonts` lists the
/// installed families.
#[test]
fn labels_take_a_font_by_family_name() {
    let mut s = world();
    let font = |s: &Session| s.map().layer_by_name("Cities").unwrap().labels.default.font.clone();
    s.run("labels.style", &json!({"layer": "Cities", "font": " Liberation Sans Narrow "})).unwrap();
    assert_eq!(font(&s).as_deref(), Some("Liberation Sans Narrow"));
    // Drawn in the label font where it isn't installed, without fail.
    s.run("labels.enable", &json!({"layer": "Cities", "on": true})).unwrap();
    let v = crate::render::View { width: 400.0, height: 300.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
    crate::render::render(s.map_mut(), &v).unwrap();
    s.run("labels.style", &json!({"layer": "Cities", "size": 12})).unwrap();
    assert!(font(&s).is_some(), "other settings leave it");
    s.run("labels.style", &json!({"layer": "Cities", "font": ""})).unwrap();
    assert_eq!(font(&s), None);
    s.run("edit.undo", &json!({})).unwrap();
    assert!(font(&s).is_some(), "undoes");
    let listed = s.run("labels.fonts", &json!({"search": "zzz-no-such-family"})).unwrap();
    assert_eq!(listed["fonts"], json!([]));
    assert!(s.run("labels.fonts", &json!({})).unwrap()["fonts"].is_array());
}

/// A streamed window cannot discard saved moves for off-window features to make space at the cap.
#[test]
fn moved_labels_preserve_off_window_features_at_the_cap() {
    use rustgis_map::symbology::{MAX_MOVED_LABELS, MovedLabel};
    let mut s = world();
    let id = s.map().layer_by_name("Cities").unwrap().id;
    let fid = s.map().layer(id).unwrap().dataset.features.first().unwrap().id;
    let layer = s.map_mut().layer_mut(id).unwrap();
    layer.dataset.windowed = true;
    layer.labels.default.moved = (0..MAX_MOVED_LABELS).map(|i| MovedLabel { id: 1_000_000 + i as u64, at: [1.0, 1.0] }).collect();
    let error = s.run("labels.move", &json!({"layer": id, "feature": fid, "to": [2, 2]})).unwrap_err();
    assert!(error.contains("at most"), "{error}");
    assert_eq!(s.map().layer(id).unwrap().labels.default.moved.len(), MAX_MOVED_LABELS);
    let error = s.run("labels.move", &json!({"layer": id, "feature": u64::MAX, "to": [2, 2]})).unwrap_err();
    assert!(error.contains("not present"), "{error}");
}

/// A class at its most drops the saved moves of features no longer in the layer to make room, and
/// says how many; a class with room drops none and says nothing.
#[test]
fn moved_labels_of_removed_features_make_room_with_a_notice() {
    use rustgis_map::symbology::{MAX_MOVED_LABELS, MovedLabel};
    let mut s = world();
    let id = s.map().layer_by_name("Cities").unwrap().id;
    let fid = s.map().layer(id).unwrap().dataset.features.first().unwrap().id;
    let layer = s.map_mut().layer_mut(id).unwrap();
    layer.labels.default.moved = (0..MAX_MOVED_LABELS).map(|i| MovedLabel { id: 1_000_000 + i as u64, at: [1.0, 1.0] }).collect();
    let mark = s.notice_mark();
    s.run("labels.move", &json!({"layer": id, "feature": fid, "to": [2, 2]})).unwrap();
    assert_eq!(s.map().layer(id).unwrap().labels.default.moved.len(), 1);
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("10000 saved label move(s) of features no longer in the layer")));
    let mark = s.notice_mark();
    s.run("labels.move", &json!({"layer": id, "feature": fid, "to": [3, 3]})).unwrap();
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("dropped to make room")));
}

/// A label moved where the map's projection can't draw it is kept, and said not to be drawn;
/// one moved inside it gets no notice.
#[test]
fn a_label_moved_outside_the_projection_says_so() {
    let mut s = world();
    let id = s.map().layer_by_name("Cities").unwrap().id;
    let fid = s.map().layer(id).unwrap().dataset.features.first().unwrap().id;
    s.run("map.projection", &json!({"type": "usaAlbers"})).unwrap();
    let mark = s.notice_mark();
    s.run("labels.move", &json!({"layer": id, "feature": fid, "to": [-100.0, 40.0]})).unwrap();
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("isn't drawn")), "inside: no notice");
    let mark = s.notice_mark();
    s.run("labels.move", &json!({"layer": id, "feature": fid, "to": [12.5, 41.9]})).unwrap();
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("outside the area the map's projection")));
    assert_eq!(s.map().layer(id).unwrap().labels.default.moved.len(), 1, "kept");
}

/// Labels are moved by hand by feature id and put back, one class's or all; bad input is refused.
#[test]
fn labels_are_moved_by_command_and_reset() {
    let mut s = world();
    let id = s.map().layer_by_name("Cities").unwrap().id;
    let fid = s.map().layer(id).unwrap().dataset.features.first().unwrap().id;
    let moved = |s: &Session| s.map().layer(id).unwrap().labels.default.moved.clone();
    s.run("labels.move", &json!({"layer": id, "feature": fid, "to": [12.5, 41.9]})).unwrap();
    assert_eq!(moved(&s), vec![rustgis_map::symbology::MovedLabel { id: fid, at: [12.5, 41.9] }]);
    // By the class's name too (Default's); again moves it again.
    let name = s.map().layer(id).unwrap().labels.default.name.clone();
    s.run("labels.move", &json!({"layer": id, "class": name, "feature": fid, "to": [13.0, 42.0]})).unwrap();
    assert_eq!(moved(&s).len(), 1);
    // Bad values change nothing.
    for bad in [
        json!({"feature": fid}),
        json!({"feature": "one", "to": [1, 1]}),
        json!({"feature": fid, "to": [1]}),
        json!({"feature": fid, "to": [1, 200]}),
        json!({"feature": fid, "to": ["a", 1]}),
        json!({"feature": fid, "to": [1, 1], "class": "No such class"}),
    ] {
        let mut p = bad.clone();
        p["layer"] = json!(id);
        assert!(s.run("labels.move", &p).is_err(), "{bad}");
    }
    assert_eq!(moved(&s)[0].at, [13.0, 42.0]);
    // Saved with the project's layer, and one undo step a move.
    let saved = serde_json::to_value(&s.map().layer(id).unwrap().labels).unwrap();
    assert_eq!(saved["moved"], json!([{"id": fid, "at": [13.0, 42.0]}]));
    s.run("edit.undo", &json!({})).unwrap();
    assert_eq!(moved(&s)[0].at, [12.5, 41.9]);
    // Put back: one, then all.
    s.run("labels.move", &json!({"layer": id, "feature": fid, "to": null})).unwrap();
    assert!(moved(&s).is_empty());
    s.run("labels.move", &json!({"layer": id, "feature": fid, "to": [1, 1]})).unwrap();
    // A bad "all" is refused, not taken as false.
    assert!(s.run("labels.resetMoved", &json!({"layer": id, "all": "tru"})).is_err());
    assert_eq!(moved(&s).len(), 1);
    s.run("labels.class.add", &json!({"layer": id, "name": "Named"})).unwrap();
    s.run("labels.move", &json!({"layer": id, "class": "Named", "feature": fid, "to": [3, 3]})).unwrap();
    s.run("labels.resetMoved", &json!({"layer": id, "all": true})).unwrap();
    assert!(moved(&s).is_empty());
    assert!(s.map().layer(id).unwrap().labels.class("Named").unwrap().moved.is_empty(), "every class's");
    s.run("labels.class.remove", &json!({"layer": id, "class": "Named"})).unwrap();
    // Locked, a move locks the labels again where they are placed next: the one moved may not
    // have been placed when the lock was taken.
    s.run("labels.lock", &json!({"on": true})).unwrap();
    let v = crate::render::View { width: 800.0, height: 600.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
    crate::render::render(s.map_mut(), &v).unwrap();
    assert!(s.map().label_lock.is_some());
    // With nothing moved, Reset Moved changes nothing and the lock holds.
    s.run("labels.resetMoved", &json!({"layer": id, "all": true})).unwrap();
    assert!(s.map().label_lock.is_some(), "a reset with nothing moved keeps the lock");
    s.run("labels.move", &json!({"layer": id, "feature": fid, "to": [2, 2]})).unwrap();
    assert!(s.map().label_lock.is_none() && s.map().label_display.locked, "locked again, not unlocked");
    // A move to where the label already is changes nothing either.
    crate::render::render(s.map_mut(), &v).unwrap();
    s.run("labels.move", &json!({"layer": id, "feature": fid, "to": [2, 2]})).unwrap();
    assert!(s.map().label_lock.is_some(), "a move that changes nothing keeps the lock");
    // Converted to annotations, a moved label's annotation is where it was put, and the
    // annotations' classes keep none moved (their ids aren't the features').
    s.run("labels.lock", &json!({"on": false})).unwrap();
    let r = s.run("labels.convert", &json!({"layer": id})).unwrap();
    let a = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap();
    // It stays moved there under its new id, so its class's offset doesn't shift it.
    let at = |g: &Option<rustgis_data::Geometry>| match g {
        Some(rustgis_data::Geometry::Point(c)) => Some([c.x, c.y]),
        _ => None,
    };
    let put = a.dataset.features.iter().find(|f| at(&f.geometry) == Some([2.0, 2.0])).expect("the moved one's annotation");
    assert_eq!(a.labels.default.moved, vec![rustgis_map::symbology::MovedLabel { id: put.id, at: [2.0, 2.0] }]);
    // The tool by its code.
    s.run("tool.set", &json!({"tool": "moveLabel"})).unwrap();
    assert_eq!(s.tool, crate::Tool::MoveLabel);
}

#[test]
fn labels_show_all_and_take_callouts() {
    // A project file's 0 is off, as the command's is; a length is kept.
    let ds = rustgis_data::Dataset::new("d", rustgis_data::GeometryType::Point, vec![]);
    let mut v = serde_json::to_value(rustgis_map::LabelClass::default_for(&ds)).unwrap();
    for (file, read) in [(json!(0), None), (json!(-3), None), (json!(30), Some(30.0))] {
        v["callout"] = file;
        assert_eq!(serde_json::from_value::<rustgis_map::LabelClass>(v.clone()).unwrap().callout, read);
    }
    let mut s = world();
    let class = |s: &Session| {
        let c = &s.map().layer_by_name("Cities").unwrap().labels.default;
        (c.show_all, c.callout)
    };
    assert_eq!(class(&s), (false, None));
    s.run("labels.placement", &json!({"layer": "Cities", "showAll": true})).unwrap();
    assert_eq!(class(&s), (true, None), "no position needed");
    // On: the default length, then one given, kept within range; on again keeps it.
    s.run("labels.placement", &json!({"layer": "Cities", "callout": true})).unwrap();
    assert_eq!(class(&s).1, Some(rustgis_map::symbology::DEFAULT_CALLOUT));
    let adjusted = |s: &Session, mark| s.notices_since(mark).iter().filter(|n| n.text.contains("callout length")).count();
    let mark = s.notice_mark();
    s.run("labels.placement", &json!({"layer": "Cities", "callout": 80})).unwrap();
    assert_eq!(class(&s).1, Some(80.0));
    assert_eq!(adjusted(&s, mark), 0, "a length in range says nothing");
    s.run("labels.placement", &json!({"layer": "Cities", "callout": 99999})).unwrap();
    assert_eq!(class(&s).1, Some(500.0), "within its range");
    assert_eq!(adjusted(&s, mark), 1, "and says it was adjusted");
    s.run("labels.placement", &json!({"layer": "Cities", "callout": true})).unwrap();
    assert_eq!(class(&s).1, Some(500.0), "on again keeps its length");
    // Saved with the layer, and read back.
    let saved = serde_json::to_value(&s.map().layer_by_name("Cities").unwrap().labels).unwrap();
    assert_eq!((saved["show_all"].clone(), saved["callout"].clone()), (json!(true), json!(500.0)));
    let back: rustgis_map::symbology::Labeling = serde_json::from_value(saved).unwrap();
    assert_eq!((back.default.show_all, back.default.callout), (true, Some(500.0)));
    // A project file's out-of-range length is brought within range.
    let mut wild = serde_json::to_value(&back).unwrap();
    wild["callout"] = json!(1e9);
    let read: rustgis_map::symbology::Labeling = serde_json::from_value(wild).unwrap();
    assert_eq!(read.default.callout, Some(500.0));
    // Off, three ways; bad values change nothing.
    for off in [json!(false), json!(0), json!(null)] {
        s.run("labels.placement", &json!({"layer": "Cities", "callout": 40})).unwrap();
        s.run("labels.placement", &json!({"layer": "Cities", "callout": off})).unwrap();
        assert_eq!(class(&s).1, None, "{off}");
    }
    for bad in [json!({"callout": "long"}), json!({"callout": -5}), json!({"showAll": "yes"})] {
        let mut p = bad.clone();
        p["layer"] = json!("Cities");
        assert!(s.run("labels.placement", &p).is_err(), "{bad}");
    }
    s.run("edit.undo", &json!({})).unwrap();
    assert_eq!(class(&s), (true, Some(40.0)), "undoes");
}

/// A label class's halo takes its own colour and width, and its letters a spacing; blank and null
/// go back to the automatic colour and the thin halo, and other settings leave them.
#[test]
fn labels_take_a_halo_colour_and_width_and_letter_spacing() {
    use rustgis_map::Rgba;
    let mut s = world();
    let class = |s: &Session| {
        let c = &s.map().layer_by_name("Cities").unwrap().labels.default;
        (c.halo_color, c.halo_width, c.spacing)
    };
    assert_eq!(class(&s), (None, None, 0.0));
    let mark = s.notice_mark();
    s.run("labels.style", &json!({"layer": "Cities", "haloColor": "#FFEE00", "haloWidth": 1.42, "spacing": "0.5"})).unwrap();
    assert!(s.notices_since(mark).iter().all(|n| !n.text.contains("ignores")), "every key is read");
    assert_eq!(class(&s), (Some(Rgba::rgb(0xFF, 0xEE, 0)), Some(1.42), 0.5));
    s.run("labels.style", &json!({"layer": "Cities", "size": 12})).unwrap();
    assert_eq!(class(&s), (Some(Rgba::rgb(0xFF, 0xEE, 0)), Some(1.42), 0.5), "other settings leave them");
    s.run("labels.style", &json!({"layer": "Cities", "haloWidth": 99, "spacing": -99})).unwrap();
    assert_eq!(class(&s), (Some(Rgba::rgb(0xFF, 0xEE, 0)), Some(10.0), -5.0), "within their ranges");
    s.run("labels.style", &json!({"layer": "Cities", "haloColor": "", "haloWidth": null})).unwrap();
    assert_eq!(class(&s), (None, None, -5.0));
    s.run("edit.undo", &json!({})).unwrap();
    assert_eq!(class(&s), (Some(Rgba::rgb(0xFF, 0xEE, 0)), Some(10.0), -5.0), "undoes");
    s.run("labels.style", &json!({"layer": "Cities", "haloColor": null})).unwrap();
    assert_eq!(class(&s).0, None);
    for bad in [
        json!({"haloColor": "pink"}),
        json!({"haloColor": 7}),
        json!({"haloWidth": "wide"}),
        json!({"spacing": null}),
        json!({"spacing": [1]}),
    ] {
        let mut p = bad.clone();
        p["layer"] = json!("Cities");
        assert!(s.run("labels.style", &p).is_err(), "{bad}");
    }
}

/// A label class takes wrapping and its lines' alignment with its text symbol, and a repeat along
/// lines with its placement; junk is refused, numbers kept within their ranges, each change undoes
/// and the project keeps them.
#[test]
fn labels_take_wrapping_and_a_repeat_along_lines() {
    use rustgis_map::layout::TextAlign;
    let mut s = world();
    let class = |s: &Session| {
        let c = &s.map().layer_by_name("Rivers").unwrap().labels.default;
        (c.wrap_char.clone(), c.wrap_length, c.line_align, c.repeat, c.placement)
    };
    let placement = class(&s).4;
    assert_eq!(class(&s), (None, 0, TextAlign::Left, None, placement));
    let mark = s.notice_mark();
    s.run("labels.style", &json!({"layer": "Rivers", "wrapChar": " ", "wrapLength": "12", "lineAlign": "CENTER"})).unwrap();
    s.run("labels.placement", &json!({"layer": "Rivers", "repeat": 144})).unwrap();
    assert!(s.notices_since(mark).iter().all(|n| !n.text.contains("ignores")), "every key is read");
    assert_eq!(class(&s), (Some(" ".into()), 12, TextAlign::Center, Some(144.0), placement), "a repeat alone keeps the position");
    // Within their ranges; none again.
    s.run("labels.style", &json!({"layer": "Rivers", "wrapChar": "abcdefghijk", "wrapLength": 1e9})).unwrap();
    s.run("labels.placement", &json!({"layer": "Rivers", "repeat": 0.5})).unwrap();
    let c = class(&s);
    assert_eq!((c.0.as_deref(), c.1, c.3), (Some("abcdefgh"), rustgis_map::symbology::MAX_WRAP_LENGTH, Some(10.0)));
    s.run("labels.placement", &json!({"layer": "Rivers", "repeat": 1e9})).unwrap();
    assert_eq!(class(&s).3, Some(10_000.0));
    s.run("labels.style", &json!({"layer": "Rivers", "wrapChar": "", "wrapLength": 0})).unwrap();
    s.run("labels.placement", &json!({"layer": "Rivers", "repeat": null})).unwrap();
    assert_eq!((class(&s).0, class(&s).1, class(&s).3), (None, 0, None));
    s.run("edit.undo", &json!({})).unwrap();
    assert_eq!(class(&s).3, Some(10_000.0), "undoes");
    s.run("labels.placement", &json!({"layer": "Rivers", "repeat": 0})).unwrap();
    assert_eq!(class(&s).3, None, "0 is none");
    for bad in [
        json!({"wrapChar": 7}),
        json!({"wrapLength": -3}),
        json!({"wrapLength": "long"}),
        json!({"lineAlign": "justify"}),
        json!({"lineAlign": 1}),
    ] {
        let mut p = bad.clone();
        p["layer"] = json!("Rivers");
        assert!(s.run("labels.style", &p).is_err(), "{bad}");
    }
    for bad in [json!({"repeat": -5}), json!({"repeat": "often"}), json!({"repeat": [1]})] {
        let mut p = bad.clone();
        p["layer"] = json!("Rivers");
        assert!(s.run("labels.placement", &p).is_err(), "{bad}");
    }
    // Kept with the project.
    s.run("labels.style", &json!({"layer": "Rivers", "wrapChar": "/", "lineAlign": "right"})).unwrap();
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "curved", "repeat": 200})).unwrap();
    let text = serde_json::to_string(&s.project).unwrap();
    let reopened = Session::new(serde_json::from_str(&text).unwrap());
    assert_eq!(class(&reopened), class(&s));
}

/// A point label class tries the other places round its point when told to (#1011): alone it keeps
/// the position, junk is refused (in it or in the position) and so is turning it on for lines at a
/// position off them and for polygons, it undoes, the project keeps it, and turning it on or off
/// while the labels are locked locks them again (the places they took no longer stand).
#[test]
fn labels_take_other_positions_round_points() {
    use crate::render::View;
    let mut s = world();
    let class = |s: &Session| {
        let c = &s.map().layer_by_name("Cities").unwrap().labels.default;
        (c.other_positions, c.placement)
    };
    let placement = class(&s).1;
    assert_eq!(class(&s), (false, placement));
    s.run("labels.placement", &json!({"layer": "Cities", "otherPositions": true})).unwrap();
    assert_eq!(class(&s), (true, placement), "alone it keeps the position");
    s.run("edit.undo", &json!({})).unwrap();
    assert!(!class(&s).0, "undoes");
    for bad in [json!("yes"), json!(1), Value::Null] {
        assert!(s.run("labels.placement", &json!({"layer": "Cities", "otherPositions": bad})).is_err(), "{bad}");
    }
    // A position that isn't a placement name is refused, not dropped for otherPositions; null is
    // none.
    for bad in [json!(123), json!(true), json!(["above"])] {
        assert!(s.run("labels.placement", &json!({"layer": "Cities", "position": bad, "otherPositions": true})).is_err(), "{bad}");
    }
    assert!(!class(&s).0);
    s.run("labels.placement", &json!({"layer": "Cities", "position": null, "otherPositions": false})).unwrap();
    assert_eq!(class(&s), (false, placement), "null is no position");
    // Only a point's label goes round it: on is refused for a line off its line (along it, see
    // labels_take_other_positions_along_lines) and for polygons, off taken anywhere.
    for layer in ["Rivers", "Countries"] {
        assert!(s.run("labels.placement", &json!({"layer": layer, "otherPositions": true})).is_err(), "{layer}");
        s.run("labels.placement", &json!({"layer": layer, "otherPositions": false})).unwrap();
    }
    s.run("labels.placement", &json!({"layer": "Cities", "otherPositions": true})).unwrap();
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(Session::new(serde_json::from_str(&text).unwrap()).map().layer_by_name("Cities").unwrap().labels.default.other_positions);
    s.run("labels.enable", &json!({"layer": "Cities", "on": true})).unwrap();
    s.run("labels.lock", &json!({"on": true})).unwrap();
    let v = View { width: 800.0, height: 600.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
    crate::render::render(s.map_mut(), &v).unwrap();
    assert!(s.map().label_lock.is_some());
    s.run("labels.placement", &json!({"layer": "Cities", "otherPositions": false})).unwrap();
    assert!(s.map().label_lock.is_none(), "turned off: locked again");
    s.run("labels.lock", &json!({"on": true})).unwrap();
    crate::render::render(s.map_mut(), &v).unwrap();
    assert!(s.map().label_lock.is_some());
    s.run("labels.placement", &json!({"layer": "Cities", "otherPositions": true})).unwrap();
    assert!(s.map().label_lock.is_none(), "turned on: locked again");
}

/// A line label class tries other places along its line when told to (#1187): only placed parallel
/// or curved and without a repeat, judged on what the call leaves, in the class it names. A refusal
/// changes nothing, a later position or repeat keeps the flag, it undoes, the project keeps it, and
/// turning it on or off locks the labels again.
#[test]
fn labels_take_other_positions_along_lines() {
    use rustgis_map::LabelPlacement::{Above, Auto, Curved, Parallel};
    let mut s = world();
    let id = s.map().layer_by_name("Rivers").unwrap().id;
    let class = |s: &Session| {
        let c = &s.map().layer(id).unwrap().labels.default;
        (c.other_positions, c.placement, c.repeat)
    };
    assert_eq!(class(&s), (false, Auto, None));
    // Not at a position off the line, nor with a repeat: each refusal leaves all of the call undone.
    assert!(s.run("labels.placement", &json!({"layer": "Rivers", "otherPositions": true})).is_err());
    assert!(s.run("labels.placement", &json!({"layer": "Rivers", "position": "above", "otherPositions": true})).is_err());
    assert!(s.run("labels.placement", &json!({"layer": "Rivers", "position": "curved", "repeat": 144, "otherPositions": true})).is_err());
    assert_eq!(class(&s), (false, Auto, None), "refused: nothing changes");
    // Along the line it's taken, the position given with it counting, and it undoes in one step.
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "curved", "otherPositions": true})).unwrap();
    assert_eq!(class(&s), (true, Curved, None));
    s.run("edit.undo", &json!({})).unwrap();
    assert_eq!(class(&s), (false, Auto, None), "undoes");
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "parallel"})).unwrap();
    s.run("labels.placement", &json!({"layer": "Rivers", "otherPositions": true})).unwrap();
    assert_eq!(class(&s), (true, Parallel, None), "alone it keeps the position");
    // Set on, a later position or repeat keeps it: it does nothing there, and is back on returning.
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "above"})).unwrap();
    assert_eq!(class(&s), (true, Above, None));
    assert!(s.run("labels.placement", &json!({"layer": "Rivers", "otherPositions": true})).is_err(), "still refused there");
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "curved", "repeat": 144})).unwrap();
    assert_eq!(class(&s), (true, Curved, Some(144.0)));
    assert!(s.run("labels.placement", &json!({"layer": "Rivers", "otherPositions": true})).is_err(), "a repeat is in the way");
    // A repeat taken away in the same call counts too.
    s.run("labels.placement", &json!({"layer": "Rivers", "repeat": null, "otherPositions": true})).unwrap();
    assert_eq!(class(&s), (true, Curved, None));
    for bad in [json!("yes"), json!(1), Value::Null] {
        assert!(s.run("labels.placement", &json!({"layer": "Rivers", "otherPositions": bad})).is_err(), "{bad}");
    }
    // Polygons have no such places, even placed parallel.
    assert!(s.run("labels.placement", &json!({"layer": "Countries", "position": "parallel", "otherPositions": true})).is_err());
    s.run("labels.placement", &json!({"layer": "Countries", "otherPositions": false})).unwrap();
    // Judged in the class named, not in Default; a class that isn't there is refused.
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "above", "otherPositions": false})).unwrap();
    s.run("labels.class.add", &json!({"layer": "Rivers", "name": "Big"})).unwrap();
    s.run("labels.placement", &json!({"layer": "Rivers", "class": "Big", "position": "curved", "otherPositions": true})).unwrap();
    let labels = &s.map().layer(id).unwrap().labels;
    assert!(labels.classes[0].other_positions && !labels.default.other_positions);
    assert!(s.run("labels.placement", &json!({"layer": "Rivers", "otherPositions": true})).is_err(), "Default is off the line");
    assert!(s.run("labels.placement", &json!({"layer": "Rivers", "class": "Nope", "otherPositions": true})).is_err());
    assert!(s.run("labels.placement", &json!({"layer": "Rivers", "class": 7, "otherPositions": true})).is_err());
    // The project keeps it.
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(Session::new(serde_json::from_str(&text).unwrap()).map().layer_by_name("Rivers").unwrap().labels.classes[0].other_positions);
    // Turned on or off, the labels are locked again, with the anchors of their places on the line.
    let key = (id, 0, 0, 0);
    for on in [false, true] {
        s.map_mut().label_lock = Some(vec![(key, rustgis_map::LockedPlace { place: 1, callout: None })]);
        s.map_mut().label_lock_line_anchors.insert(key, Default::default());
        s.run("labels.placement", &json!({"layer": "Rivers", "class": "Big", "otherPositions": on})).unwrap();
        assert!(s.map().label_lock.is_none() && s.map().label_lock_line_anchors.is_empty(), "{on}: locked again");
    }
}

/// A label class takes an offset with its placement and a background with its text symbol; junk
/// is refused, numbers kept within their ranges, and each change undoes.
#[test]
fn labels_take_an_offset_and_a_background() {
    use rustgis_map::{LabelBackground, Rgba};
    let mut s = world();
    let class = |s: &Session| {
        let c = &s.map().layer_by_name("Cities").unwrap().labels.default;
        (c.placement, c.offset, c.background.clone())
    };
    let (placement, offset, background) = class(&s);
    assert_eq!((offset, background), ([0.0; 2], None));
    // An offset alone keeps the placement; both together set both.
    let mark = s.notice_mark();
    s.run("labels.placement", &json!({"layer": "Cities", "offset": [3, "-2.5"]})).unwrap();
    assert!(s.notices_since(mark).iter().all(|n| !n.text.contains("ignores")), "every key is read");
    assert_eq!((class(&s).0, class(&s).1), (placement, [3.0, -2.5]));
    s.run("labels.placement", &json!({"layer": "Cities", "position": "right", "offset": [1e9, -1e9]})).unwrap();
    assert_eq!((class(&s).0, class(&s).1), (rustgis_map::LabelPlacement::Right, [200.0, -200.0]));
    s.run("labels.placement", &json!({"layer": "Cities", "position": "below"})).unwrap();
    assert_eq!(class(&s).1, [200.0, -200.0], "a position alone keeps the offset");
    s.run("edit.undo", &json!({})).unwrap();
    assert_eq!(class(&s).0, rustgis_map::LabelPlacement::Right, "undoes");
    for bad in [json!({}), json!({"offset": "far"}), json!({"offset": [1]}), json!({"offset": [1, "x"]}), json!({"offset": null})] {
        let mut p = bad.clone();
        p["layer"] = json!("Cities");
        assert!(s.run("labels.placement", &p).is_err(), "{bad}");
    }
    // A background: on (the default's), parts set on it, off.
    s.run("labels.style", &json!({"layer": "Cities", "background": true})).unwrap();
    assert_eq!(class(&s).2, Some(LabelBackground::default()));
    let mark = s.notice_mark();
    let parts = json!({"fill": "#FFEE00", "stroke": "", "strokeWidth": 99, "padding": [2, "1"], "radius": -1});
    s.run("labels.style", &json!({"layer": "Cities", "background": parts})).unwrap();
    assert!(s.notices_since(mark).iter().all(|n| !n.text.contains("ignores")), "every key is read");
    let want = LabelBackground { fill: Some(Rgba::rgb(0xFF, 0xEE, 0)), stroke: None, stroke_width: 10.0, padding: [2.0, 1.0], radius: 0.0 };
    assert_eq!(class(&s).2, Some(want.clone()));
    s.run("labels.style", &json!({"layer": "Cities", "background": {"radius": 1e300}})).unwrap();
    assert_eq!(class(&s).2.map(|b| b.radius), Some(50.0), "past f32's range: the most");
    s.run("labels.style", &json!({"layer": "Cities", "background": {"radius": 3}})).unwrap();
    assert_eq!(class(&s).2, Some(LabelBackground { radius: 3.0, ..want.clone() }), "what isn't given is kept");
    s.run("labels.style", &json!({"layer": "Cities", "background": true})).unwrap();
    assert_eq!(class(&s).2.map(|b| b.radius), Some(3.0), "on again keeps it");
    s.run("labels.style", &json!({"layer": "Cities", "size": 12})).unwrap();
    assert!(class(&s).2.is_some(), "other settings leave it");
    s.run("labels.style", &json!({"layer": "Cities", "background": false})).unwrap();
    assert_eq!(class(&s).2, None);
    s.run("edit.undo", &json!({})).unwrap();
    assert!(class(&s).2.is_some(), "undoes");
    s.run("labels.style", &json!({"layer": "Cities", "background": null})).unwrap();
    assert_eq!(class(&s).2, None);
    // Set on none, the parts go on the default's.
    s.run("labels.style", &json!({"layer": "Cities", "background": {"fill": ""}})).unwrap();
    assert_eq!(class(&s).2, Some(LabelBackground { fill: None, ..LabelBackground::default() }));
    for bad in [
        json!({"background": "box"}),
        json!({"background": 1}),
        json!({"background": {"fill": "pink"}}),
        json!({"background": {"stroke": 7}}),
        json!({"background": {"strokeWidth": "wide"}}),
        json!({"background": {"padding": 2}}),
        json!({"background": {"padding": [2]}}),
        json!({"background": {"radius": null}}),
    ] {
        let mut p = bad.clone();
        p["layer"] = json!("Cities");
        assert!(s.run("labels.style", &p).is_err(), "{bad}");
    }
    // The project keeps them.
    s.run("labels.placement", &json!({"layer": "Cities", "offset": [1, 2]})).unwrap();
    let text = serde_json::to_string(&s.project).unwrap();
    let reopened = Session::new(serde_json::from_str(&text).unwrap());
    assert_eq!(class(&reopened), class(&s));
}

/// A lock names the place round its point a label took by its number among its class's (#1011): a
/// class trying the others locks the labels again when its position changes, not when its offset
/// does; one that doesn't keeps the lock, as before.
#[test]
fn a_change_to_where_point_labels_go_locks_them_again() {
    use crate::render::View;
    let mut s = world();
    s.run("labels.enable", &json!({"layer": "Cities", "on": true})).unwrap();
    s.run("labels.lock", &json!({"on": true})).unwrap();
    let draw = |s: &mut Session| {
        let v = View { width: 800.0, height: 600.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
        crate::render::render(s.map_mut(), &v).unwrap();
    };
    draw(&mut s);
    s.run("labels.placement", &json!({"layer": "Cities", "position": "below"})).unwrap();
    assert!(s.map().label_lock.is_some(), "no class tries other places: the lock is kept");
    let id = s.map().layer_by_name("Cities").unwrap().id;
    s.map_mut().layer_mut(id).unwrap().labels.default.other_positions = true;
    s.run("labels.placement", &json!({"layer": "Cities", "offset": [2, 2]})).unwrap();
    assert!(s.map().label_lock.is_some(), "an offset moves every place alike: the lock is kept");
    s.run("labels.placement", &json!({"layer": "Cities", "position": "above"})).unwrap();
    assert!(s.map().label_lock.is_none(), "another position: locked again");
    draw(&mut s);
    assert!(s.map().label_lock.is_some(), "locked on the next frame");
    // A style applied counts its classes' places too.
    s.run("style.new", &json!({"layer": "Cities", "name": "Above"})).unwrap();
    s.run("labels.placement", &json!({"layer": "Cities", "position": "below"})).unwrap();
    draw(&mut s);
    assert!(s.map().label_lock.is_some());
    s.run("style.apply", &json!({"layer": "Cities", "name": "Above"})).unwrap();
    assert!(s.map().label_lock.is_none(), "a style putting the labels elsewhere: locked again");
}

#[test]
fn changing_line_repeat_relocks_alternative_positions() {
    let mut s = world();
    let id = s.map().layer_by_name("Rivers").unwrap().id;
    let c = &mut s.map_mut().layer_mut(id).unwrap().labels.default;
    c.other_positions = true;
    c.placement = rustgis_map::LabelPlacement::Parallel;
    s.map_mut().label_lock = Some(vec![((id, 0, 0, 0), rustgis_map::LockedPlace { place: 1, callout: None })]);
    s.run("labels.placement", &json!({"layer": "Rivers", "repeat": 144})).unwrap();
    assert!(s.map().label_lock.is_none());
}

/// A line class's flag counts for the lock only where it does something (#1187): set but off the
/// line or with a repeat it keeps the lock, as a class without it does; a change to or from the
/// places it has locks the labels again. A layer also holding points keeps its flag in effect.
#[test]
fn a_line_class_flag_with_no_effect_keeps_the_lock() {
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType};
    let mut s = world();
    let id = s.map().layer_by_name("Rivers").unwrap().id;
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "curved", "otherPositions": true})).unwrap();
    let held = |s: &mut Session, layer: u32, name: &str, change: Value| {
        s.map_mut().label_lock = Some(vec![((layer, 0, 0, 0), rustgis_map::LockedPlace { place: 1, callout: None })]);
        let mut p = change;
        p["layer"] = json!(name);
        s.run("labels.placement", &p).unwrap();
        s.map().label_lock.is_some()
    };
    assert!(!held(&mut s, id, "Rivers", json!({"position": "parallel"})), "another place along the line");
    assert!(!held(&mut s, id, "Rivers", json!({"position": "above"})), "off the line: its places are gone");
    assert!(s.map().layer(id).unwrap().labels.default.other_positions, "the flag is kept");
    assert!(held(&mut s, id, "Rivers", json!({"position": "below"})), "off the line it does nothing");
    assert!(held(&mut s, id, "Rivers", json!({"repeat": 144})), "nor with a repeat added there");
    assert!(held(&mut s, id, "Rivers", json!({"position": "curved"})), "nor along the line with that repeat");
    assert!(!held(&mut s, id, "Rivers", json!({"repeat": null})), "the repeat gone, its places are back");
    // A layer of lines holding a point: the point's label goes round it at any position, so the
    // command takes the flag there and it counts for the lock.
    let mut d = Dataset::new("Mixed", GeometryType::Polyline, vec![Field::new("name", FieldType::Text)]);
    d.push(Some(Geometry::Point(rustgis_geom::Coord::new(0.0, 0.0))), vec![rustgis_data::Value::Text("Spot".into())]);
    let mixed = s.map_mut().add_dataset(d);
    s.run("labels.placement", &json!({"layer": "Mixed", "position": "above", "otherPositions": true})).unwrap();
    assert!(!held(&mut s, mixed, "Mixed", json!({"position": "below"})), "its point's places change");
}

/// A lock names each label by its feature's id, not its row: deleting a feature (the rows after
/// it move up) neither shows a label left out when the lock was taken nor hides one placed (#1046).
#[test]
fn locked_labels_stay_with_their_features_when_rows_move() {
    use crate::render::View;
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let mut s = world();
    // Three buoys on one spot of the South Atlantic: only the first one's label fits.
    let mut d = Dataset::new("Buoys", GeometryType::Point, vec![Field::new("name", FieldType::Text)]);
    for name in ["Alpha", "Beta", "Gamma"] {
        d.push(Some(Geometry::Point(rustgis_geom::Coord::new(-20.0, -30.0))), vec![V::Text(name.into())]);
    }
    let id = s.map_mut().add_dataset(d);
    s.run("labels.enable", &json!({"layer": "Buoys", "on": true})).unwrap();
    let draw = |s: &mut Session| -> Vec<String> {
        let v = View { width: 800.0, height: 600.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
        let labels = crate::render::render(s.map_mut(), &v).unwrap().labels;
        labels.into_iter().map(|l| l.text).filter(|t| ["Alpha", "Beta", "Gamma"].contains(&t.as_str())).collect()
    };
    assert_eq!(draw(&mut s), ["Alpha"]);
    s.run("labels.lock", &json!({"on": true})).unwrap();
    assert_eq!(draw(&mut s), ["Alpha"]);
    s.map_mut().layer_mut(id).unwrap().selection = vec![0];
    s.run("edit.delete", &Value::Null).unwrap();
    assert!(draw(&mut s).is_empty(), "Beta's label wasn't placed when the lock was taken");
    s.run("labels.lock", &json!({"on": false})).unwrap();
    assert_eq!(draw(&mut s), ["Beta"], "unlocked, Beta's fits");
    s.run("labels.lock", &json!({"on": true})).unwrap();
    assert_eq!(draw(&mut s), ["Beta"], "and is locked in turn");
}

/// A feature added after locking has no label, even when it takes the id of a feature deleted
/// since: the lock's entry for that id goes with the feature, and undo brings it back (#1135).
#[test]
fn a_new_feature_doesnt_take_the_locked_label_of_a_deleted_one() {
    use crate::render::View;
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let mut s = world();
    let mut d = Dataset::new("Places", GeometryType::Point, vec![Field::new("name", FieldType::Text)]);
    for (name, lon) in [("Alpha", -30.0), ("Gamma", 30.0)] {
        d.push(Some(Geometry::Point(rustgis_geom::Coord::new(lon, -40.0))), vec![V::Text(name.into())]);
    }
    // The full source id must survive lock placement, pruning and undo on wasm32 too.
    d.features[0].id = 1_u64 << 32;
    d.features[1].id = (1_u64 << 32) + 1;
    let id = s.map_mut().add_dataset(d);
    let gamma = s.map().layer(id).unwrap().dataset.features[1].id;
    s.run("labels.enable", &json!({"layer": "Places", "on": true})).unwrap();
    let draw = |s: &mut Session| -> Vec<String> {
        let v = View { width: 800.0, height: 600.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
        let labels = crate::render::render(s.map_mut(), &v).unwrap().labels;
        let mut texts: Vec<String> =
            labels.into_iter().map(|l| l.text).filter(|t| ["Alpha", "Alpha 2", "Gamma", "Delta"].contains(&t.as_str())).collect();
        texts.sort();
        texts
    };
    s.run("labels.lock", &json!({"on": true})).unwrap();
    assert_eq!(draw(&mut s), ["Alpha", "Gamma"]);

    // An edit keeps the feature's id, so its label stays locked.
    s.run("edit.setValue", &json!({"layer": "Places", "row": 0, "field": "name", "value": "Alpha 2"})).unwrap();
    assert_eq!(draw(&mut s), ["Alpha 2", "Gamma"]);

    s.map_mut().layer_mut(id).unwrap().selection = vec![1];
    s.run("edit.delete", &Value::Null).unwrap();
    let locked = |s: &Session| s.map().label_lock.as_ref().is_some_and(|k| k.iter().any(|((l, f, ..), _)| *l == id && *f == gamma));
    assert!(!locked(&s), "the lock's entry goes with the feature");
    let delta = json!({"layer": "Places", "geometry": {"type": "Point", "coordinates": [0.0, -40.0]}, "attributes": {"name": "Delta"}});
    s.run("edit.addFeature", &delta).unwrap();
    assert_eq!(s.map().layer(id).unwrap().dataset.features[1].id, gamma, "the new feature takes the deleted one's id");
    assert_eq!(draw(&mut s), ["Alpha 2"], "and no label, as it wasn't placed when the lock was taken");

    s.run("edit.undo", &Value::Null).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert!(locked(&s), "undoing the delete brings the entry back");
    assert_eq!(draw(&mut s), ["Alpha 2", "Gamma"]);

    s.run("edit.redo", &Value::Null).unwrap();
    assert!(!locked(&s), "redoing the delete takes it away again");
    assert_eq!(draw(&mut s), ["Alpha 2"]);
}

/// Deleting a feature removes its saved label move before its id can be reused; undo restores it.
#[test]
fn a_new_feature_doesnt_take_the_moved_label_of_a_deleted_one() {
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let mut s = Session::new(Project::default());
    let mut data = Dataset::new("Sites", GeometryType::Point, vec![Field::new("name", FieldType::Text)]);
    data.push(Some(Geometry::Point(rustgis_geom::Coord::new(0.0, 0.0))), vec![V::Text("Old".into())]);
    let layer = s.map_mut().add_dataset(data);
    s.run("labels.enable", &json!({"layer":layer,"on":true})).unwrap();
    s.run("labels.move", &json!({"layer":layer,"feature":1,"to":[1.0,1.0]})).unwrap();
    s.map_mut().layer_mut(layer).unwrap().selection = vec![0];
    s.run("edit.delete", &Value::Null).unwrap();
    assert!(s.map().layer(layer).unwrap().labels.default.moved.is_empty());
    s.run("edit.addFeature", &json!({"layer":layer,"geometry":{"type":"Point","coordinates":[0.0,0.0]},"attributes":{"name":"New"}}))
        .unwrap();
    assert_eq!(s.map().layer(layer).unwrap().dataset.features[0].id, 1);
    let view = crate::render::View { width: 800.0, height: 600.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
    let labels = crate::render::render(s.map_mut(), &view).unwrap().labels;
    assert!(labels.iter().any(|l| l.text == "New" && !l.collide.pinned));
    s.run("edit.undo", &Value::Null).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().layer(layer).unwrap().labels.default.moved_to(1), Some([1.0, 1.0]));
    s.run("edit.redo", &Value::Null).unwrap();
    assert!(s.map().layer(layer).unwrap().labels.default.moved.is_empty());
}

/// Project opening reports discarded label settings once per kind; clean settings stay quiet.
#[test]
fn opening_projects_reports_moved_label_and_callout_adjustments() {
    use rustgis_data::{Dataset, Field, FieldType, GeometryType};
    let mut project = Project::default();
    project.maps[0].add_dataset(Dataset::new("Sites", GeometryType::Point, vec![Field::new("name", FieldType::Text)]));
    project.maps[0].layers[0].labels.default.move_label(1, Some([2.0, 3.0]));
    project.styles.push(crate::project::StyleItem {
        name: "Saved labels".into(),
        geometry: GeometryType::Point,
        renderer: project.maps[0].layers[0].renderer.clone(),
        labels: project.maps[0].layers[0].labels.clone(),
        transparency: 0.0,
    });
    project.offline_areas.push(crate::project::OfflineArea {
        name: "Field copy".into(),
        map: "Map".into(),
        extent: rustgis_geom::Extent::new(-1.0, -1.0, 1.0, 1.0),
        created: 0.0,
        synced: 0.0,
        data: project.maps[0].clone(),
    });
    let clean = serde_json::to_string(&project).unwrap();
    let clean_session = Session::new(Project::from_json(&clean).unwrap());
    assert!(clean_session.notices.is_empty());
    // Callouts written off (false, null or 0) are clean too.
    for off in [json!(false), json!(null), json!(0)] {
        let mut v: Value = serde_json::from_str(&clean).unwrap();
        v["maps"][0]["layers"][0]["labels"]["callout"] = off.clone();
        v["styles"][0]["labels"]["callout"] = off.clone();
        assert!(Session::new(Project::from_json(&v.to_string()).unwrap()).notices.is_empty(), "{off}");
    }
    let mut damaged: Value = serde_json::from_str(&clean).unwrap();
    let labels = &mut damaged["maps"][0]["layers"][0]["labels"];
    labels["moved"] = json!([
        {"id":1,"at":[2.0,3.0]}, {"id":1,"at":[4.0,5.0]},
        {"id":-1,"at":[2.0,3.0]}, {"id":1.5,"at":[2.0,3.0]}, {"id":2,"at":[2.0,100.0]}
    ]);
    labels["callout"] = json!(900);
    labels["show_all"] = json!("yes");
    damaged["styles"][0]["labels"]["moved"] = json!("damaged");
    damaged["styles"][0]["labels"]["callout"] = json!(-1);
    let text = damaged.to_string();
    let loaded = Project::from_json(&text).unwrap();
    assert_eq!(loaded.maps[0].layers[0].labels.default.moved_to(1), Some([4.0, 5.0]));
    let startup = Session::new(loaded);
    assert_eq!(startup.notices.len(), 3);
    assert!(startup.notices.iter().any(|n| n.text.contains("5 invalid, duplicate or excess moved-label")));
    assert!(startup.notices.iter().any(|n| n.text.contains("2 callout length setting(s) adjusted")));
    assert!(startup.notices.iter().any(|n| n.text.contains("1 \"show all labels\" setting(s)")));
    let mut opened = Session::new(Project::default());
    opened.run("project.openText", &json!({"text":text})).unwrap();
    assert_eq!(opened.notices.iter().filter(|n| n.text.contains("while opening the project")).count(), 3);
    assert!(!serde_json::to_string(&opened.project).unwrap().contains("label_read_notices"));
    let mut excess: Value = serde_json::from_str(&clean).unwrap();
    excess["styles"][0]["labels"]["moved"] =
        Value::Array((0..=rustgis_map::symbology::MAX_MOVED_LABELS).map(|id| json!({"id":id,"at":[0.0,0.0]})).collect());
    let capped = Session::new(Project::from_json(&excess.to_string()).unwrap());
    assert_eq!(capped.notices.len(), 1);
    assert!(capped.notices[0].text.contains("1 invalid, duplicate or excess moved-label"));
}

/// A style's saved label moves name the features of the layer it was made from: applied, the
/// layer keeps its own moves instead, and says what it left out; a style without moves is quiet.
#[test]
fn applying_a_style_keeps_the_layers_own_label_moves() {
    let mut s = world();
    let id = s.map().layer_by_name("Cities").unwrap().id;
    let ids: Vec<u64> = s.map().layer(id).unwrap().dataset.features.iter().take(2).map(|f| f.id).collect();
    let said = |s: &Session, mark| s.notices_since(mark).iter().filter(|n| n.text.contains("label move(s)")).count();
    s.run("style.new", &json!({"layer": id, "name": "Plain"})).unwrap();
    s.run("labels.move", &json!({"layer": id, "feature": ids[0], "to": [1, 1]})).unwrap();
    s.run("style.new", &json!({"layer": id, "name": "Moved"})).unwrap();
    s.run("labels.move", &json!({"layer": id, "feature": ids[0], "to": null})).unwrap();
    s.run("labels.move", &json!({"layer": id, "feature": ids[1], "to": [2, 2]})).unwrap();
    // A style that places the labels as they are keeps them locked, the layer's moves and all.
    s.run("style.new", &json!({"layer": id, "name": "Same"})).unwrap();
    s.map_mut().label_lock = Some(vec![((id, 0, 0, 0), rustgis_map::LockedPlace::default())]);
    s.run("style.apply", &json!({"layer": id, "name": "Same"})).unwrap();
    assert!(s.map().label_lock.is_some(), "placement unchanged keeps the lock");
    assert_eq!(s.map().layer(id).unwrap().labels.default.moved_to(ids[1]), Some([2.0, 2.0]));
    let mark = s.notice_mark();
    s.run("style.apply", &json!({"layer": id, "name": "Plain"})).unwrap();
    assert_eq!(said(&s, mark), 0, "{:?}", s.notices_since(mark));
    let mark = s.notice_mark();
    s.run("style.apply", &json!({"layer": id, "name": "Moved"})).unwrap();
    let labels = &s.map().layer(id).unwrap().labels.default;
    assert_eq!((labels.moved_to(ids[0]), labels.moved_to(ids[1])), (None, Some([2.0, 2.0])));
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("1 saved label move(s) in style Moved not applied")));
}

/// A project template keeps no features, so no saved label moves either, and says so.
#[test]
fn a_project_template_leaves_out_label_moves() {
    let dir = std::env::temp_dir().join(format!("rustgis-template-moves-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("t.rgis");
    let mut s = world();
    let mark = s.notice_mark();
    s.run("project.saveTemplate", &json!({"path": path})).unwrap();
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("label move(s)")));
    let id = s.map().layer_by_name("Cities").unwrap().id;
    let feature = s.map().layer(id).unwrap().dataset.features[0].id;
    s.run("labels.move", &json!({"layer": id, "feature": feature, "to": [1, 1]})).unwrap();
    // A style saved from the layer holds the move too.
    s.run("style.new", &json!({"layer": id, "name": "Moved"})).unwrap();
    let mark = s.notice_mark();
    s.run("project.saveTemplate", &json!({"path": path})).unwrap();
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("2 saved label move(s) left out of the template")));
    let saved: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    assert!(!saved.to_string().contains("\"moved\""));
    std::fs::remove_dir_all(&dir).ok();
}

/// A map file or layer file read on its own reports discarded label settings as a project does
/// (Import map, Import Styles, Add Layer File); clean files stay quiet.
#[test]
fn map_and_layer_files_report_label_setting_losses() {
    let s = world();
    let map = serde_json::to_value(s.map()).unwrap();
    let layer = serde_json::to_value(s.map().layer_by_name("Cities").unwrap()).unwrap();
    let damage = |labels: &mut Value| {
        labels["moved"] = json!("damaged");
        labels["callout"] = json!(900);
        labels["show_all"] = json!(3);
    };
    let mut bad_map = map.clone();
    let i = bad_map["layers"].as_array().unwrap().iter().position(|l| l["name"] == "Cities").unwrap();
    damage(&mut bad_map["layers"][i]["labels"]);
    let mut bad_layer = layer.clone();
    damage(&mut bad_layer["labels"]);
    let said = |cmd: &str, text: &Value| {
        let mut s = world();
        let mark = s.notice_mark();
        s.run(cmd, &json!({"text": text.to_string()})).unwrap();
        s.notices_since(mark).iter().filter(|n| n.text.contains("while opening the")).map(|n| n.text.clone()).collect::<Vec<_>>()
    };
    for (cmd, clean, bad) in [
        ("map.import", &map, &bad_map),
        ("style.import", &map, &bad_map),
        ("style.import", &layer, &bad_layer),
        ("layer.addLayerFile", &layer, &bad_layer),
    ] {
        assert!(said(cmd, clean).is_empty(), "{cmd}: {:?}", said(cmd, clean));
        let notes = said(cmd, bad);
        assert_eq!(notes.len(), 3, "{cmd}: {notes:?}");
        assert!(notes.iter().any(|n| n.contains("1 invalid, duplicate or excess moved-label")), "{cmd}: {notes:?}");
        assert!(notes.iter().any(|n| n.contains("1 callout length")), "{cmd}: {notes:?}");
        assert!(notes.iter().any(|n| n.contains("1 \"show all labels\"")), "{cmd}: {notes:?}");
    }
}

/// Two layers whose only features have the same id, each with a locked label and a line anchor.
fn two_locked_layers() -> (Session, u32, u32) {
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let mut s = Session::new(Project::default());
    let mut layer = |name: &str| {
        let mut d = Dataset::new(name, GeometryType::Point, vec![Field::new("name", FieldType::Text)]);
        d.push(Some(Geometry::Point(rustgis_geom::Coord::new(0.0, 0.0))), vec![V::Text(name.into())]);
        s.map_mut().add_dataset(d)
    };
    let (a, b) = (layer("A"), layer("B"));
    let keys = [(a, 1, 0, 0), (b, 1, 0, 0)];
    s.map_mut().label_lock = Some(keys.map(|k| (k, Default::default())).to_vec());
    s.map_mut().label_lock_line_anchors = keys.map(|k| (k, Default::default())).into_iter().collect();
    (s, a, b)
}

/// The layers a map's lock and line anchors name, each sorted.
fn locked_layers(s: &Session) -> (Vec<u32>, Vec<u32>) {
    let mut lock: Vec<u32> = s.map().label_lock.iter().flatten().map(|((l, ..), _)| *l).collect();
    let mut anchors: Vec<u32> = s.map().label_lock_line_anchors.keys().map(|(l, ..)| *l).collect();
    lock.sort_unstable();
    anchors.sort_unstable();
    (lock, anchors)
}

/// A removed layer's locked labels and line anchors go with it, and only its own; undo brings them
/// back.
#[test]
fn a_removed_layers_locked_labels_go_with_it() {
    let (mut s, a, b) = two_locked_layers();
    s.run("layer.remove", &json!({"layer": a})).unwrap();
    assert_eq!(locked_layers(&s), (vec![b], vec![b]));
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(locked_layers(&s), (vec![a, b], vec![a, b]));
    s.run("edit.redo", &Value::Null).unwrap();
    assert_eq!(locked_layers(&s), (vec![b], vec![b]));
    // The last locked layer gone, the lock holds, with nothing in it.
    s.run("layer.remove", &json!({"layer": b})).unwrap();
    assert!(s.map().label_lock.as_ref().is_some_and(Vec::is_empty));
    assert!(s.map().label_lock_line_anchors.is_empty());
}

/// A deleted feature's lock entry and line anchor go with it, not those of another layer's feature
/// with the same id; undo brings them back.
#[test]
fn a_deleted_feature_leaves_another_layers_lock_alone() {
    let (mut s, a, b) = two_locked_layers();
    s.map_mut().layer_mut(a).unwrap().selection = vec![0];
    s.run("edit.delete", &Value::Null).unwrap();
    assert_eq!(locked_layers(&s), (vec![b], vec![b]));
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(locked_layers(&s), (vec![a, b], vec![a, b]));
    s.run("edit.redo", &Value::Null).unwrap();
    assert_eq!(locked_layers(&s), (vec![b], vec![b]));
}

/// Deleting one of a layer's locked features keeps the lock entry and line anchor of the other.
#[test]
fn a_deleted_feature_leaves_its_neighbours_lock_alone() {
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let mut s = Session::new(Project::default());
    let mut d = Dataset::new("A", GeometryType::Point, vec![Field::new("name", FieldType::Text)]);
    for name in ["one", "two"] {
        d.push(Some(Geometry::Point(rustgis_geom::Coord::new(0.0, 0.0))), vec![V::Text(name.into())]);
    }
    let a = s.map_mut().add_dataset(d);
    let keys = [(a, 1, 0, 0), (a, 2, 0, 0)];
    s.map_mut().label_lock = Some(keys.map(|k| (k, Default::default())).to_vec());
    s.map_mut().label_lock_line_anchors = keys.map(|k| (k, Default::default())).into_iter().collect();
    // The feature ids the lock and the anchors name, each sorted.
    let ids = |s: &Session| {
        let mut lock: Vec<u64> = s.map().label_lock.iter().flatten().map(|((_, f, ..), _)| *f).collect();
        let mut anchors: Vec<u64> = s.map().label_lock_line_anchors.keys().map(|(_, f, ..)| *f).collect();
        lock.sort_unstable();
        anchors.sort_unstable();
        (lock, anchors)
    };
    s.map_mut().layer_mut(a).unwrap().selection = vec![0];
    s.run("edit.delete", &Value::Null).unwrap();
    assert_eq!(ids(&s), (vec![2], vec![2]));
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(ids(&s), (vec![1, 2], vec![1, 2]));
    s.run("edit.redo", &Value::Null).unwrap();
    assert_eq!(ids(&s), (vec![2], vec![2]));
}

/// A streamed layer holds only the window in view: a lock's entry for a feature outside it stays
/// when the window changes (#1135).
#[test]
fn a_lock_holds_for_a_streamed_layers_features_outside_its_window() {
    let p = line_of_points_shp("locked-window", 20);
    let mut s = world();
    let r = s.run("layer.addData", &json!({"path": p.display().to_string(), "stream": true})).unwrap();
    let id = r["layer"].as_u64().unwrap() as u32;
    s.map_mut().label_lock = Some(vec![((id, 1, 0, 0), Default::default())]);
    let before = s.project.clone();
    // The window moves off the feature: no longer shared with the copy, and without its id.
    s.map_mut().layer_mut(id).unwrap().dataset.features = Vec::new().into();
    crate::forget_label_state_of_removed_features(&before, &mut s.project);
    assert_eq!(s.map().label_lock.as_ref().map(Vec::len), Some(1));
    drop(s);
    remove_shp(&p);
}

/// A lock names each label by its class's place in the list: a change to the list (a class added,
/// moved or removed) locks the labels again on the next frame, a change within a class keeps the
/// lock (#732).
#[test]
fn a_change_to_the_label_classes_locks_the_labels_again() {
    use crate::render::View;
    let mut s = world();
    s.run("labels.enable", &json!({"layer": "Cities", "on": true})).unwrap();
    s.run("labels.lock", &json!({"on": true})).unwrap();
    let draw = |s: &mut Session| {
        let v = View { width: 800.0, height: 600.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
        crate::render::render(s.map_mut(), &v).unwrap();
    };
    draw(&mut s);
    assert!(s.map().label_lock.is_some());
    s.run("labels.style", &json!({"layer": "Cities", "size": 14})).unwrap();
    s.run("labels.class.update", &json!({"layer": "Cities", "visible": true})).unwrap();
    assert!(s.map().label_lock.is_some(), "a change within a class keeps the lock");
    for (id, p) in [
        ("labels.class.add", json!({"layer": "Cities", "name": "Big"})),
        ("labels.class.add", json!({"layer": "Cities", "name": "Small"})),
        ("labels.class.move", json!({"layer": "Cities", "class": "Small", "to": 0})),
        ("labels.class.remove", json!({"layer": "Cities", "class": "Big"})),
        ("labels.class.clear", json!({"layer": "Cities"})),
    ] {
        s.run(id, &p).unwrap();
        assert!(s.map().label_lock.is_none(), "{id} moves the classes: locked again");
        draw(&mut s);
        assert!(s.map().label_lock.is_some(), "{id}: locked on the next frame");
    }
}

/// Changes that affect collision placement discard the lock; a new class inherits styling,
/// but not feature-specific manual positions.
#[test]
fn label_collision_changes_refresh_locks_without_copying_moves() {
    let mut s = world();
    let id = s.map().layer_by_name("Cities").unwrap().id;
    let feature = s.map().layer(id).unwrap().dataset.features[0].id;
    for params in [json!({"showAll":true}), json!({"callout":true}), json!({"callout":false})] {
        s.map_mut().label_lock = Some(vec![((id, feature, 0, 0), Default::default())]);
        let mut p = params;
        p["layer"] = json!(id);
        s.run("labels.placement", &p).unwrap();
        assert!(s.map().label_lock.is_none(), "{p} changes collision placement");
    }
    s.run("labels.move", &json!({"layer":id,"feature":feature,"to":[1,1]})).unwrap();
    s.run("labels.class.add", &json!({"layer":id,"name":"New"})).unwrap();
    let labels = &s.map().layer(id).unwrap().labels;
    assert_eq!(labels.default.moved.len(), 1);
    assert!(labels.class("New").unwrap().moved.is_empty());
}

/// A service refresh assigns new ids: default and named-class moves must not attach to them,
/// and the discarded moves are counted. Undo restores the old features and positions.
#[test]
fn service_refresh_resets_saved_label_moves_with_a_notice() {
    let server = ogc_server::Server::group_fixture();
    let mut s = Session::new(Project::default());
    s.run("service.import", &json!({"url":server.root()})).unwrap();
    let id = s.map().layer_by_name("Places").unwrap().id;
    let feature = s.map().layer(id).unwrap().dataset.features[0].id;
    s.run("labels.class.add", &json!({"layer":id,"name":"Named"})).unwrap();
    for class in [None, Some("Named")] {
        let mut p = json!({"layer":id,"feature":feature,"to":[1,1]});
        if let Some(class) = class {
            p["class"] = json!(class);
        }
        s.run("labels.move", &p).unwrap();
    }
    let mark = s.notice_mark();
    s.run("service.refresh", &json!({"layer":id})).unwrap();
    assert!(s.map().layer(id).unwrap().labels.in_order().all(|c| c.moved.is_empty()));
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("2 saved label move(s) reset")));
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().layer(id).unwrap().labels.in_order().map(|c| c.moved.len()).sum::<usize>(), 2);
    s.run("edit.redo", &Value::Null).unwrap();
    let mark = s.notice_mark();
    s.run("service.refresh", &json!({"layer":id})).unwrap();
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("saved label move(s) reset")));
}

/// A refresh whose service no longer offers a layer says how many saved moves went with it.
#[test]
fn service_refresh_says_how_many_moves_go_with_a_dropped_layer() {
    let server = ogc_server::Server::group_fixture();
    let mut s = Session::new(Project::default());
    let group = s.run("service.import", &json!({"url":server.root()})).unwrap()["group"].clone();
    let routes = s.map().layer_by_name("Routes").unwrap().id;
    let feature = s.map().layer(routes).unwrap().dataset.features[0].id;
    s.run("labels.move", &json!({"layer":routes,"feature":feature,"to":[1,1]})).unwrap();
    // The service now offers only Places.
    let items = json!({"rel": "items", "type": "application/geo+json", "href": "collections/places/items?key=fixture-key"});
    server.set(ogc_server::CATALOG, &json!({"collections": [{"id": "places", "title": "Places", "links": [items]}]}).to_string());
    let mark = s.notice_mark();
    // The whole group: a refresh of one layer leaves its siblings as they are.
    s.run("service.refresh", &json!({"group":group})).unwrap();
    assert!(s.map().layer_by_name("Routes").is_none());
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("1 saved label move(s) dropped with layers")));
}

/// Label classes by command (#618): added from Default and checked before it, renamed, given
/// a clause, moved, styled and removed; refusals change nothing, and Default stays last.
#[test]
fn label_classes_by_command() {
    use crate::map::LabelPlacement;
    let mut s = world();
    let cities = s.map().layer_by_name("Cities").unwrap().id;
    s.run("layer.select", &json!({"layer": cities})).unwrap();
    let labels = |s: &Session| s.map().layer(cities).unwrap().labels.clone();
    let order = |s: &Session| labels(s).in_order().map(|c| c.name.clone()).collect::<Vec<_>>();
    assert_eq!(s.run("labels.class.add", &json!({"name": "Big", "where": "pop_max > 5000000"})).unwrap()["class"], "Big");
    s.run("labels.class.add", &json!({"name": " Medium ", "where": "pop_max > 1000000"})).unwrap();
    assert_eq!(order(&s), ["Big", "Medium", "Default"]);
    let l = labels(&s);
    assert_eq!((l.classes[0].size, l.classes[0].field.as_str()), (l.default.size, l.default.field.as_str()), "a class starts as Default");
    for bad in [
        json!({"name": "big"}),
        json!({"name": "default"}),
        json!({"name": "  "}),
        json!({"name": "X", "where": "(("}),
        json!({"name": "X", "where": "nope = 1"}),
        json!({"name": "X", "where": 5}),
        json!({"name": "X", "from": "Nope"}),
    ] {
        assert!(s.run("labels.class.add", &bad).is_err(), "{bad}");
    }
    assert!(s.run("labels.class.remove", &json!({"class": "Default"})).is_err(), "Default stays");
    assert!(s.run("labels.class.move", &json!({"class": "Default", "to": 0})).is_err(), "and stays last");
    assert!(s.run("labels.class.rename", &json!({"class": "Big", "name": "medium"})).is_err());
    assert!(s.run("labels.class.update", &json!({"class": "Big", "where": "(("})).is_err());
    assert!(s.run("labels.style", &json!({"class": "Nope", "size": 30})).is_err());
    // A class that isn't a name is refused, not taken for Default.
    for bad in [json!(3), json!("  "), json!(["Big"])] {
        assert!(s.run("labels.style", &json!({"class": bad, "size": 30})).is_err(), "{bad}");
        assert!(s.run("labels.class.add", &json!({"name": "X", "from": bad})).is_err(), "{bad}");
    }
    assert_eq!(labels(&s), l, "refusals change nothing");
    // A field for a class that isn't there turns nothing on; one for a class labels the layer.
    s.run("labels.enable", &json!({"on": false})).unwrap();
    assert!(s.run("labels.field", &json!({"class": "Nope", "field": "name"})).is_err());
    assert!(!labels(&s).enabled);
    s.run("labels.field", &json!({"class": "Big", "field": "name"})).unwrap();
    assert!(labels(&s).enabled && labels(&s).classes[0].field == "name");
    // The labels.* commands change the class named, Default when none is.
    s.run("labels.style", &json!({"class": "big", "size": 20, "bold": true})).unwrap();
    s.run("labels.placement", &json!({"class": "Big", "position": "right"})).unwrap();
    s.run("labels.scaleRange", &json!({"class": "Medium", "min": 10000000})).unwrap();
    s.run("labels.field", &json!({"class": "Medium", "field": "pop_max"})).unwrap();
    let l = labels(&s);
    assert_eq!((l.classes[0].size, l.classes[0].bold, l.classes[0].placement), (20.0, true, LabelPlacement::Right));
    assert_eq!((l.classes[1].min_scale, l.classes[1].field.as_str()), (Some(10_000_000.0), "pop_max"));
    assert!(l.default.size < 20.0 && l.default.field == "name", "Default is left as it was");
    // Renamed (Default too), moved, its clause cleared, hidden; each one undo step.
    s.run("labels.class.rename", &json!({"class": "Medium", "name": "Large"})).unwrap();
    s.run("labels.class.move", &json!({"class": "Large", "to": 0})).unwrap();
    s.run("labels.class.update", &json!({"class": "Big", "where": null, "visible": false})).unwrap();
    s.run("labels.class.rename", &json!({"class": "Default", "name": "Other"})).unwrap();
    assert_eq!(order(&s), ["Large", "Big", "Other"]);
    let l = labels(&s);
    assert_eq!((l.classes[1].where_.as_deref(), l.classes[1].visible), (None, false));
    s.run("edit.undo", &json!(null)).unwrap();
    assert_eq!(order(&s), ["Large", "Big", "Default"]);
    let info = s.run("info.project", &json!(null)).unwrap().to_string();
    assert!(info.contains("labelClasses") && info.contains("Large"), "info.project lists the classes");
    s.run("labels.class.remove", &json!({"class": "big"})).unwrap();
    assert_eq!(order(&s), ["Large", "Default"]);
    // Clear removes the rest, Default kept; again, with none left, it is no error (a script
    // that starts with it runs again).
    assert_eq!(s.run("labels.class.clear", &json!({})).unwrap()["removed"], 1);
    assert_eq!(order(&s), ["Default"]);
    assert_eq!(s.run("labels.class.clear", &json!({})).unwrap()["removed"], 0);
    // info.project lists the classes also for a Default alone that is hidden (or has a clause).
    let listed = |s: &mut Session| {
        let info = s.run("info.project", &json!(null)).unwrap();
        info["layers"].as_array().unwrap().iter().find(|l| l["name"] == "Cities").unwrap()["labelClasses"].clone()
    };
    assert!(listed(&mut s).is_null(), "a plain Default isn't listed");
    s.run("labels.class.update", &json!({"visible": false})).unwrap();
    assert_eq!(listed(&mut s)[0]["visible"], false);
    s.run("labels.class.update", &json!({"visible": true, "where": "pop_max > 0"})).unwrap();
    assert_eq!(listed(&mut s)[0]["where"], "pop_max > 0");
    s.run("labels.class.update", &json!({"where": null})).unwrap();
    // A long name is cut at 100 characters, and doesn't end in the space it was cut at.
    let long = format!("{} tail", "a".repeat(99));
    assert_eq!(s.run("labels.class.add", &json!({"name": long})).unwrap()["class"], "a".repeat(99));
}

/// Converting labels with classes keeps each class's features apart: the annotation has the same
/// classes, picking their points by a CLASS field (#618). Deleting a field a class labels with
/// moves it to another field and keeps the class.
#[test]
fn label_classes_convert_and_outlive_a_deleted_field() {
    let mut s = world();
    let cities = s.map().layer_by_name("Cities").unwrap().id;
    s.run("layer.select", &json!({"layer": cities})).unwrap();
    s.run("labels.enable", &json!({"on": true})).unwrap();
    s.run("labels.class.add", &json!({"name": "Big's", "where": "pop_max > 5000000"})).unwrap();
    s.run("labels.style", &json!({"class": "Big's", "size": 18})).unwrap();
    let big = rustgis_data::query::select("pop_max > 5000000", &s.map().layer(cities).unwrap().dataset).unwrap().len();
    assert!(big > 0);
    let r = s.run("labels.convert", &json!({})).unwrap();
    let a = s.map().layer(u32::try_from(r["layer"].as_u64().unwrap()).unwrap()).unwrap();
    let classes: Vec<_> = a.labels.in_order().map(|c| (c.name.clone(), c.where_.clone(), c.field.clone(), c.size)).collect();
    assert_eq!(classes[0], ("Big's".to_string(), Some(r#""CLASS" = 'Big''s'"#.to_string()), "TEXT".to_string(), 18.0));
    assert_eq!((classes[1].1.as_deref(), classes[1].2.as_str()), (Some(r#""CLASS" = 'Default'"#), "TEXT"), "Default picks its own");
    let picked = |w: &Option<String>| rustgis_data::query::select(w.as_deref().unwrap(), &a.dataset).unwrap().len();
    assert_eq!(picked(&classes[0].1), big, "the class's clause picks the points it labelled");
    // Default labels the big cities too (#732): each class gives them a point.
    assert_eq!(picked(&classes[1].1), a.dataset.features.len() - big);
    assert!(picked(&classes[1].1) > big, "Default labels every city, the big ones among them");
    // A deleted field: the class labels with Default's field, and is kept.
    s.run("layer.select", &json!({"layer": cities})).unwrap();
    s.run("labels.field", &json!({"class": "Big's", "field": "pop_max"})).unwrap();
    s.run("edit.deleteField", &json!({"layer": cities, "field": "pop_max"})).unwrap();
    let l = &s.map().layer(cities).unwrap().labels;
    assert_eq!(l.classes.len(), 1);
    assert_eq!(l.classes[0].field, l.default.field);
    assert!(l.default.field != "pop_max");
    assert!(l.enabled, "another class's field going leaves the labels on");
    // Default on a deleted field starts again on another, keeping its name, clause and visibility.
    assert_eq!(l.default.field, "name");
    s.run("labels.class.rename", &json!({"class": "Default", "name": "Rest"})).unwrap();
    s.run("labels.class.update", &json!({"where": "name <> 'x'", "visible": false})).unwrap();
    s.run("edit.deleteField", &json!({"layer": cities, "field": "name"})).unwrap();
    let l = &s.map().layer(cities).unwrap().labels;
    assert!(!l.enabled && l.default.field != "name", "Default's field going turns the labels off, as before classes");
    assert_eq!(
        (l.classes.len(), l.classes[0].field.as_str()),
        (1, l.default.field.as_str()),
        "the other classes are kept, on its new field"
    );
    assert_eq!((l.default.name.as_str(), l.default.visible, l.default.where_.as_deref()), ("Rest", false, Some("name <> 'x'")));
}

#[test]
fn graphics_draw_shapes_text_and_pictures() {
    use crate::render::View;
    use base64::Engine;
    let mut s = world();
    s.run("map.goToXY", &json!({"lon": 10.0, "lat": 50.0, "scale": 20_000_000})).unwrap();
    // The first graphic makes a graphics layer.
    let r = s.run("graphics.add", &json!({"shape": "rectangle", "points": [[0, 45], [10, 55]], "fill": "#FF000040"})).unwrap();
    let id = r["layer"].as_u64().unwrap() as u32;
    assert!(s.map().layer(id).unwrap().graphics);
    for (shape, pts) in [
        ("circle", json!([[5, 50], [8, 50]])),
        ("ellipse", json!([[0, 40], [20, 48]])),
        ("line", json!([[0, 40], [5, 45], [10, 40]])),
        ("curve", json!([[0, 40], [5, 45], [10, 40]])),
        ("freehand", json!([[0, 40], [1, 41], [2, 40]])),
        ("polygon", json!([[0, 40], [5, 45], [10, 40]])),
        ("lasso", json!([[0, 40], [5, 45], [10, 40], [5, 38]])),
        ("point", json!([[2, 48]])),
    ] {
        s.run("graphics.add", &json!({"shape": shape, "points": pts})).unwrap_or_else(|e| panic!("{shape}: {e}"));
    }
    assert!(s.run("graphics.add", &json!({"shape": "polygon", "points": [[0, 0], [1, 1]]})).is_err());
    assert!(s.run("graphics.add", &json!({"shape": "rectangle", "points": [[0, 0], [0, 1]]})).is_err());
    assert!(s.run("graphics.add", &json!({"shape": "text", "points": [[0, 0]]})).is_err(), "text needs text");
    assert!(s.run("graphics.add", &json!({"shape": "blob", "points": [[0, 0]]})).is_err());
    assert!(s.run("graphics.add", &json!({"shape": "point", "points": [[0, 0]], "layer": "Cities"})).is_err(), "not a graphics layer");
    // Dynamic text expands when drawn.
    let text =
        s.run("graphics.add", &json!({"shape": "text", "points": [[10, 50]], "text": "{map} {scale}", "fontSize": 20})).unwrap()["row"]
            .clone();
    let view = View { width: 800.0, height: 600.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
    let r = crate::render::render(s.map_mut(), &view).unwrap();
    assert!(
        r.labels.iter().any(|l| l.text.starts_with("World 1:") && l.size == 20.0),
        "{:?}",
        r.labels.iter().map(|l| &l.text).collect::<Vec<_>>()
    );
    // A picture: a 2×2 PNG.
    let mut png = tiny_skia::Pixmap::new(2, 2).unwrap();
    png.fill(tiny_skia::Color::from_rgba8(255, 0, 0, 255));
    let b64 = base64::engine::general_purpose::STANDARD.encode(png.encode_png().unwrap());
    s.run("graphics.add", &json!({"shape": "picture", "points": [[0, 45], [10, 55]], "image": b64})).unwrap();
    assert!(s.run("graphics.add", &json!({"shape": "picture", "points": [[0, 45], [10, 55]], "image": "bm90IGFuIGltYWdl"})).is_err());
    let v = View { width: 800.0, height: 600.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
    let r = crate::render::render(s.map_mut(), &v).unwrap();
    let (x, y) = v.to_screen(rustgis_geom::lonlat_to_merc(rustgis_geom::Coord::new(5.0, 50.0)));
    let px = r.pixmap.pixel(x as u32, y as u32).unwrap();
    assert!(px.red() > 200 && px.green() < 60, "the picture covers its rectangle: {px:?}");
    // Restyle the selection; keep the tool.
    s.run("select.rows", &json!({"layer": id, "rows": [0]})).unwrap();
    s.run("graphics.style", &json!({"fill": "#00FF00", "width": 3})).unwrap();
    assert_eq!(rustgis_map::graphics::symbol(&s.map().layer(id).unwrap().dataset, 0).fill, rustgis_map::Rgba::rgb(0, 255, 0));
    assert!(s.run("graphics.style", &json!({})).is_err(), "nothing to change");
    s.run("graphics.style", &json!({"text": "not on a rectangle"})).unwrap();
    assert!(rustgis_map::graphics::label(&s.map().layer(id).unwrap().dataset, 0).is_none(), "text only goes on text graphics");
    // Edit one text graphic by layer and row (#420): the selected rectangle stays as it was, and
    // undo takes the edit back.
    s.run("graphics.edit", &json!({"layer": id, "row": text, "text": "Edited", "fontSize": 30})).unwrap();
    let row = text.as_u64().unwrap() as usize;
    let ds = &s.map().layer(id).unwrap().dataset;
    assert_eq!((rustgis_map::graphics::label(ds, row), rustgis_map::graphics::font_size(ds, row)), (Some("Edited"), 30.0));
    assert_eq!(rustgis_map::graphics::font_size(ds, 0), 14.0, "only the graphic named");
    // A size is kept within the range it is drawn at, so Edit Text shows what the map draws.
    s.run("graphics.edit", &json!({"layer": id, "row": text, "fontSize": 0})).unwrap();
    let ds = &s.map().layer(id).unwrap().dataset;
    assert_eq!(ds.value(row, ds.field_index("font_size").unwrap()), &rustgis_data::Value::Float(*rustgis_map::graphics::FONT_SIZE.start()));
    s.run("edit.undo", &Value::Null).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    let ds = &s.map().layer(id).unwrap().dataset;
    assert_eq!((rustgis_map::graphics::label(ds, row), rustgis_map::graphics::font_size(ds, row)), (Some("{map} {scale}"), 20.0));
    for bad in [
        json!({"layer": id, "row": text, "text": "  "}),
        json!({"layer": id, "row": 999, "text": "x"}),
        json!({"layer": id, "row": 0.5, "text": "x"}),
        json!({"layer": id, "text": "x"}),
        json!({"row": text, "text": "x"}),
        json!({"layer": null, "row": text, "text": "x"}),
        json!({"layer": id, "row": 0, "text": "not on a rectangle"}),
        json!({"layer": id, "row": text, "text": format!("{}x", " ".repeat(2000))}),
        json!({"layer": id, "row": text}),
        json!({"layer": "Cities", "row": 0, "text": "x"}),
    ] {
        assert!(s.run("graphics.edit", &bad).is_err(), "{bad}");
    }
    assert_eq!(rustgis_render::picture_size(&b64), Some((2, 2)));
    assert!(s.run("graphics.keepTool", &Value::Null).unwrap()["keepTool"].as_bool().unwrap());
    s.run("tool.set", &json!({"tool": "graphicRectangle"})).unwrap();
    assert_eq!(s.tool.code(), "graphicRectangle");
    // Graphics round-trip through a project file.
    let text = serde_json::to_string(&s.project).unwrap();
    let p: crate::Project = serde_json::from_str(&text).unwrap();
    assert!(p.map().layer(id).unwrap().graphics);
    s.run("graphics.newLayer", &json!({"name": "Notes"})).unwrap();
    assert!(s.map().layer_by_name("Notes").unwrap().graphics);
}

#[test]
fn select_takes_only_drawn_features_of_selectable_layers() {
    let mut s = world();
    let selected = |s: &Session, layer: &str| s.map().layer_by_name(layer).map(|l| l.selection.clone()).unwrap_or_default();
    // A display filter shows only South America: a box over the world selects only what's drawn (#243).
    let filters = json!({"layer": "Countries", "filters": [{"name": "SA", "where": "continent = 'South America'"}]});
    s.run("layer.displayFilters", &filters).unwrap();
    let all = s.map().layer_by_name("Countries").unwrap().dataset.features.len();
    let r = s.run("select.byRect", &json!({"minLon": -180, "minLat": -85, "maxLon": 180, "maxLat": 85})).unwrap();
    let rows = selected(&s, "Countries");
    assert!(!rows.is_empty() && rows.len() < all, "{} of {all}", rows.len());
    let l = s.map().layer_by_name("Countries").unwrap();
    let continent = l.dataset.field_index("continent").unwrap();
    assert!(rows.iter().all(|r| l.dataset.value(*r, continent).to_string() == "South America"));
    assert!(r["selected"].as_u64().unwrap() >= rows.len() as u64);
    // A click on a hidden country selects nothing; on a drawn one, it.
    let r = s.run("select.atPoint", &json!({"lon": 2.35, "lat": 46.6, "tolerancePx": 0})).unwrap();
    assert!(r.is_null(), "{r}");
    assert!(selected(&s, "Countries").is_empty());
    s.run("select.atPoint", &json!({"lon": -51.0, "lat": -10.0, "tolerancePx": 0})).unwrap();
    assert_eq!(selected(&s, "Countries").len(), 1);
    // A layer that isn't selectable doesn't hide the selectable ones under it: Paris is in Cities,
    // above France in Countries.
    s.run("layer.displayFilters", &json!({"layer": "Countries", "filters": []})).unwrap();
    let paris = json!({"lon": 2.35, "lat": 48.85, "tolerancePx": 5});
    s.run("select.atPoint", &paris).unwrap();
    assert_eq!(selected(&s, "Cities").len(), 1);
    s.run("layer.selectable", &json!({"layer": "Cities", "on": false})).unwrap();
    s.run("select.atPoint", &paris).unwrap();
    assert!(selected(&s, "Cities").is_empty());
    assert_eq!(selected(&s, "Countries").len(), 1);
}

fn map_area_selection_add(
    s: &mut Session,
    name: &str,
    kind: rustgis_data::GeometryType,
    geometries: &[Option<rustgis_data::Geometry>],
) -> u32 {
    use rustgis_data::{Dataset, Field, FieldType, Value as V};
    let mut dataset = Dataset::new(name, kind, vec![Field::new("n", FieldType::Integer)]);
    for (row, geometry) in geometries.iter().enumerate() {
        dataset.push(geometry.clone(), vec![V::Int(row as i64)]);
    }
    s.map_mut().add_dataset(dataset)
}

fn map_area_selection_fixture() -> (Session, u32, u32) {
    use rustgis_data::{Geometry, GeometryType};
    use rustgis_geom::Coord;
    let mut s = Session::new(Project::default());
    let geometries: Vec<_> =
        [(0.5, 0.5), (2.0, 2.0), (3.0, 0.5), (4.0, 4.0)].into_iter().map(|(x, y)| Some(Geometry::Point(Coord::new(x, y)))).collect();
    let first = map_area_selection_add(&mut s, "Points", GeometryType::Point, &geometries);
    let second = map_area_selection_add(&mut s, "Other points", GeometryType::Point, &geometries);
    s.map_mut().layer_mut(second).unwrap().selectable = false;
    (s, first, second)
}

fn map_area_selection_rows(s: &Session, id: u32) -> Vec<usize> {
    s.map().layer(id).unwrap().selection.clone()
}

fn map_area_selection_snapshot(s: &Session) -> Vec<(u32, Vec<usize>)> {
    s.map().layers.iter().map(|layer| (layer.id, layer.selection.clone())).collect()
}

#[test]
fn map_area_selection_command_modes_count_hits_across_layers() {
    let operations = [
        (
            "select.byPolygon",
            json!({"points": [[0,0],[3,0],[3,1],[1,1],[1,3],[0,3]]}),
            json!({"points": [[10,10],[11,10],[11,11],[10,11]]}),
        ),
        ("select.byRadius", json!({"lon": 1.75, "lat": 0.5, "radius": 145000}), json!({"lon": 10, "lat": 10, "radius": 1})),
    ];
    for (command, query, disjoint) in operations {
        for second_selectable in [false, true] {
            for mode in [None, Some("NeW"), Some("ADD"), Some("ReMoVe")] {
                let (mut s, first, second) = map_area_selection_fixture();
                s.map_mut().layer_mut(second).unwrap().selectable = second_selectable;
                s.map_mut().layer_mut(first).unwrap().selection = vec![0, 1];
                s.map_mut().layer_mut(second).unwrap().selection = vec![0, 3];
                let mut params = query.clone();
                if let Some(mode) = mode {
                    params["mode"] = json!(mode);
                }
                let result = s.run(command, &params).unwrap();
                assert_eq!(result, json!({"selected": if second_selectable { 4 } else { 2 }}), "{command}: {mode:?}");
                let (first_expected, second_expected) = match mode {
                    Some("ADD") => (vec![0, 1, 2], if second_selectable { vec![0, 2, 3] } else { vec![0, 3] }),
                    Some("ReMoVe") => (vec![1], if second_selectable { vec![3] } else { vec![0, 3] }),
                    _ => (vec![0, 2], if second_selectable { vec![0, 2] } else { vec![] }),
                };
                assert_eq!(map_area_selection_rows(&s, first), first_expected, "{command}: {mode:?}");
                assert_eq!(map_area_selection_rows(&s, second), second_expected, "{command}: {mode:?}");
                let before = map_area_selection_snapshot(&s);
                let mut empty = disjoint.clone();
                if let Some(mode) = mode {
                    empty["mode"] = json!(mode);
                }
                assert_eq!(s.run(command, &empty).unwrap(), json!({"selected": 0}));
                if matches!(mode, Some("ADD" | "ReMoVe")) {
                    assert_eq!(map_area_selection_snapshot(&s), before, "{command}: {mode:?}");
                } else {
                    assert!(s.map().layers.iter().all(|layer| layer.selection.is_empty()));
                }
            }
        }
    }
}

#[test]
fn map_area_selection_ring_forms_and_even_odd_lasso_are_command_visible() {
    let (mut s, first, _) = map_area_selection_fixture();
    for points in [
        json!([[0, 0], [3, 0], [3, 1], [1, 1], [1, 3], [0, 3]]),
        json!([[0, 0], [3, 0], [3, 1], [1, 1], [1, 3], [0, 3], [0, 0]]),
        json!([[0, 0], [0, 0], [3, 0], [3, 0], [3, 1], [1, 1], [1, 3], [0, 3], [0, 0]]),
    ] {
        assert_eq!(s.run("select.byPolygon", &json!({"points": points})).unwrap(), json!({"selected": 2}));
        assert_eq!(map_area_selection_rows(&s, first), [0, 2]);
    }

    use rustgis_data::{Geometry, GeometryType};
    use rustgis_geom::{Coord, lonlat_to_merc, merc_to_lonlat};
    // Construct the bow-tie in the command's planar space, then invert it. Its crossing really
    // is (2,2), rather than the slightly different intersection of four Mercator-projected degrees.
    let origin = lonlat_to_merc(Coord::new(0.0, 0.0));
    let at = |x, y| merc_to_lonlat(Coord::new(origin.x + x * 10000.0, origin.y + y * 10000.0));
    let mut s = Session::new(Project::default());
    let geometries: Vec<_> =
        [(2.0, 0.5), (2.0, 3.5), (0.5, 2.0), (2.0, 2.0), (4.5, 4.5)].into_iter().map(|(x, y)| Some(Geometry::Point(at(x, y)))).collect();
    let id = map_area_selection_add(&mut s, "Lasso lobes", GeometryType::Point, &geometries);
    let points: Vec<_> = [(0.0, 0.0), (4.0, 4.0), (0.0, 4.0), (4.0, 0.0)]
        .into_iter()
        .map(|(x, y)| {
            let p = at(x, y);
            [p.x, p.y]
        })
        .collect();
    assert_eq!(s.run("select.byPolygon", &json!({"points": points})).unwrap(), json!({"selected": 3}));
    assert_eq!(map_area_selection_rows(&s, id), [0, 1, 3]);
}

#[test]
fn map_area_selection_rejected_inputs_preserve_exact_layer_selections() {
    let (mut s, first, second) = map_area_selection_fixture();
    s.map_mut().layer_mut(first).unwrap().selection = vec![1, 3];
    s.map_mut().layer_mut(second).unwrap().selection = vec![0, 2];
    let before = map_area_selection_snapshot(&s);
    let mut invalid = vec![
        ("select.byPolygon", Value::Null),
        ("select.byPolygon", json!({"points": []})),
        ("select.byPolygon", json!({"points": [[0,0],[1,1]]})),
        ("select.byPolygon", json!({"points": [[0,0],[0,0],[0,0],[0,0]]})),
        ("select.byPolygon", json!({"points": [[0,0],[1,0],[2,0]]})),
        ("select.byPolygon", json!({"points": [[0,0],[1,null],[1,1]]})),
        ("select.byPolygon", json!({"points": [[0,0],[1,0,2],[1,1]]})),
        ("select.byPolygon", json!({"points": [[0,0],[181,0],[1,1]]})),
        ("select.byPolygon", json!({"points": [[0,0],[1,-91],[1,1]]})),
        ("select.byPolygon", json!({"points": [[179,0],[-179,0],[-179,1],[179,1]]})),
        // Only the closing edge crosses the Mercator seam.
        ("select.byPolygon", json!({"points": [[-170,0],[-10,1],[10,1],[170,0]]})),
        ("select.byPolygon", json!({"points": [[0,86],[1,86],[1,87]]})),
        ("select.byPolygon", json!({"points": vec![[0.0,0.0]; rustgis_analysis::selection::MAX_POINTS + 1]})),
        ("select.byRadius", json!({"lon": 0, "lat": 0})),
        ("select.byRadius", json!({"lon": null, "lat": 0, "radius": 1})),
        ("select.byRadius", json!({"lon": 181, "lat": 0, "radius": 1})),
        ("select.byRadius", json!({"lon": 0, "lat": 86, "radius": 1})),
        ("select.byRadius", json!({"lon": 179.99, "lat": 0, "radius": 100000})),
        ("select.byRadius", json!({"lon": 0, "lat": 85, "radius": 100000})),
    ];
    for radius in [json!(0), json!(-1), json!(5000001), json!("not a number"), Value::Null] {
        invalid.push(("select.byRadius", json!({"lon": 0, "lat": 0, "radius": radius})));
    }
    for mode in [json!("subset"), json!("bogus"), json!(false), json!(1), json!([]), Value::Null] {
        invalid.push(("select.byPolygon", json!({"points": [[0,0],[3,0],[3,3],[0,3]], "mode": mode})));
        invalid.push(("select.byRadius", json!({"lon": 0, "lat": 0, "radius": 1000, "mode": mode})));
    }
    for (command, params) in invalid {
        assert!(s.run(command, &params).is_err(), "{command}: {params}");
        assert_eq!(map_area_selection_snapshot(&s), before, "{command}: {params}");
    }
    // Many proper crossings, but well below the vertex cap: refusal must come from the
    // normalization work guard, not an arbitrary reduction in supported lasso detail.
    let star: Vec<_> = (0..601)
        .map(|i| {
            let angle = (i * 300 % 601) as f64 * std::f64::consts::TAU / 601.0;
            [angle.cos(), angle.sin()]
        })
        .collect();
    let error = s.run("select.byPolygon", &json!({"points": star})).unwrap_err();
    assert!(error.contains("too complex"), "{error}");
    assert_eq!(map_area_selection_snapshot(&s), before);
    s.run("map.projection", &json!({"type": "robinson", "lon_0": 150})).unwrap();
    for (command, params) in [
        ("select.byPolygon", json!({"points": [[-35,5],[-25,5],[-25,15],[-35,15]]})),
        ("select.byRadius", json!({"lon": -30, "lat": 10, "radius": 100000})),
    ] {
        assert!(s.run(command, &params).is_err(), "{command}: {params}");
        assert_eq!(map_area_selection_snapshot(&s), before);
    }
}

#[test]
fn map_area_selection_detailed_low_crossing_outline_is_not_truncated() {
    let (mut s, first, _) = map_area_selection_fixture();
    let count = 12000;
    assert!(count < rustgis_analysis::selection::MAX_POINTS);
    let points: Vec<_> = (0..count)
        .map(|i| {
            let angle = i as f64 * std::f64::consts::TAU / count as f64;
            [0.5 + 0.25 * angle.cos(), 0.5 + 0.25 * angle.sin()]
        })
        .collect();
    assert_eq!(s.run("select.byPolygon", &json!({"points": points})).unwrap(), json!({"selected": 1}));
    assert_eq!(map_area_selection_rows(&s, first), [0]);
}

#[test]
fn map_area_selection_drawn_row_policy_matches_rectangle_for_every_filter() {
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    use rustgis_geom::Coord;
    let operations = [
        ("select.byRect", json!({"minLon": -1, "minLat": -1, "maxLon": 1, "maxLat": 1})),
        ("select.byPolygon", json!({"points": [[-1,-1],[1,-1],[1,1],[-1,1]]})),
        ("select.byRadius", json!({"lon": 0, "lat": 0, "radius": 100000})),
    ];
    for restriction in [
        "none",
        "invisible",
        "unselectable",
        "layer_min",
        "layer_max",
        "hidden_group",
        "group_min",
        "group_max",
        "overlapping_groups",
        "definition",
        "display",
        "time",
        "combined",
        "inactive_display",
    ] {
        let mut s = Session::new(Project::default());
        let mut dataset =
            Dataset::new("Events", GeometryType::Point, vec![Field::new("n", FieldType::Integer), Field::new("when", FieldType::Text)]);
        for (row, date) in ["2025-01-15", "2025-02-15", "2025-03-15", "2025-02-20"].into_iter().enumerate() {
            let geometry = (row != 3).then(|| Geometry::Point(Coord::new(0.1 * (row + 1) as f64, 0.1)));
            dataset.push(geometry, vec![V::Int(row as i64), V::Text(date.into())]);
        }
        let id = s.map_mut().add_dataset(dataset);
        s.active_layer = Some(id);
        s.run("map.goToXY", &json!({"lon": 0, "lat": 0, "scale": 1000000})).unwrap();
        let scale = s.scale();
        match restriction {
            "invisible" => {
                s.run("layer.visibility", &json!({"layer": id, "visible": false})).unwrap();
            }
            "unselectable" => {
                s.run("layer.selectable", &json!({"layer": id, "on": false})).unwrap();
            }
            "layer_min" => {
                s.run("layer.scaleRange", &json!({"layer": id, "min": scale * 0.5})).unwrap();
            }
            "layer_max" => {
                s.run("layer.scaleRange", &json!({"layer": id, "max": scale * 2.0})).unwrap();
            }
            "hidden_group" | "group_min" | "group_max" | "overlapping_groups" => {
                let group = s.run("group.add", &json!({"name": "Limited", "layers": [id]})).unwrap()["group"].clone();
                match restriction {
                    "group_min" => {
                        s.run("group.scaleRange", &json!({"group": group, "min": scale * 0.5})).unwrap();
                    }
                    "group_max" => {
                        s.run("group.scaleRange", &json!({"group": group, "max": scale * 2.0})).unwrap();
                    }
                    _ => {
                        s.run("group.set", &json!({"group": group, "visible": false})).unwrap();
                    }
                }
                if restriction == "overlapping_groups" {
                    // held_by_group must win even when a second, visible membership exists.
                    let mut visible = rustgis_map::LayerGroup::new("Also visible");
                    visible.id = 1000000;
                    visible.children.push(id);
                    s.map_mut().groups.push(visible);
                }
            }
            _ => {}
        }
        if matches!(restriction, "definition" | "combined") {
            s.run("layer.definitionQuery", &json!({"layer": id, "where": "n <> 0"})).unwrap();
        }
        if matches!(restriction, "display" | "combined" | "inactive_display") {
            let filters = if restriction == "inactive_display" {
                json!([{"name": "Inactive", "where": "n = -1", "minScale": scale * 0.5}])
            } else {
                json!([{"name": "Not March", "where": "n <> 2"}])
            };
            s.run("layer.displayFilters", &json!({"layer": id, "filters": filters})).unwrap();
        }
        if matches!(restriction, "time" | "combined") {
            s.run("time.bind", &json!({"layer": id, "field": "when"})).unwrap();
            s.run("time.set", &json!({"date": "2025-02-15", "unit": "month", "show": "step"})).unwrap();
        }
        let expected = match restriction {
            "none" | "inactive_display" => vec![0, 1, 2],
            "definition" => vec![1, 2],
            "display" => vec![0, 1],
            "time" | "combined" => vec![1],
            _ => vec![],
        };
        let mut rectangle = None;
        for (command, params) in &operations {
            // A new query clears even a previously selected geometry-less/filtered-out row.
            s.map_mut().layer_mut(id).unwrap().selection = vec![0, 1, 2, 3];
            assert_eq!(s.run(command, params).unwrap(), json!({"selected": expected.len()}), "{restriction}: {command}");
            let actual = map_area_selection_rows(&s, id);
            assert_eq!(actual, expected, "{restriction}: {command}");
            if let Some(rectangle) = &rectangle {
                assert_eq!(&actual, rectangle, "{restriction}: {command} differs from rectangle");
            } else {
                rectangle = Some(actual);
            }
        }
    }
}

#[test]
fn map_area_selection_radius_typed_geometries_match_network_at_zero_and_sixty() {
    use rustgis_analysis::network::{radius_boundary_point, radius_distance_m, within};
    use rustgis_data::{Geometry, GeometryType};
    use rustgis_geom::{Coord, lonlat_to_merc, merc_to_lonlat};
    for latitude in [0.0_f64, 60.0] {
        let center = Coord::new(3.0, latitude);
        let origin = lonlat_to_merc(center);
        let k = 1.0 / latitude.to_radians().cos().max(0.01);
        let at = |x: f64, y: f64| Coord::new(origin.x + x * k, origin.y + y * k);
        let ring =
            |radius: f64| vec![at(-radius, -radius), at(radius, -radius), at(radius, radius), at(-radius, radius), at(-radius, -radius)];
        let boundary = merc_to_lonlat(at(600.0, 800.0));
        // Round-trip arithmetic at an exact boundary is part of within's contract. Derive the
        // query threshold with its shared metric, not an epsilon-expanded independent distance.
        let radius = radius_distance_m(center, boundary).unwrap();
        assert!((radius - 1000.0).abs() < 1e-6, "{latitude}: {radius}");
        assert!((radius_distance_m(center, merc_to_lonlat(at(300.0, 400.0))).unwrap() - 500.0).abs() < 1e-6);
        assert!(radius_distance_m(center, merc_to_lonlat(at(606.0, 808.0))).unwrap() > radius);
        let preview_boundary = radius_boundary_point(center, radius, 800.0_f64.atan2(600.0)).unwrap();
        assert!((radius_distance_m(center, preview_boundary).unwrap() - radius).abs() < 1e-6);
        if latitude == 60.0 {
            let east = merc_to_lonlat(Coord::new(origin.x + 2000.0, origin.y));
            assert!((radius_distance_m(center, east).unwrap() - 1000.0).abs() < 1e-6);
        }
        let fixtures = [
            (
                "Points",
                GeometryType::Point,
                vec![
                    Some(Geometry::Point(at(0.0, 0.0))),
                    Some(Geometry::Point(at(300.0, 400.0))),
                    Some(Geometry::Point(at(600.0, 800.0))),
                    Some(Geometry::Point(at(606.0, 808.0))),
                    Some(Geometry::MultiPoint(vec![at(2000.0, 2000.0), at(300.0, 400.0)])),
                    None,
                ],
                vec![0, 1, 2, 4],
            ),
            (
                "Lines",
                GeometryType::Polyline,
                vec![
                    Some(Geometry::Line(vec![vec![at(-2000.0, 0.0), at(2000.0, 0.0)]])),
                    Some(Geometry::Line(vec![vec![at(600.0, 800.0), at(1200.0, 1600.0)]])),
                    Some(Geometry::Line(vec![vec![at(2000.0, -2000.0), at(2000.0, 2000.0)]])),
                ],
                vec![0, 1],
            ),
            (
                "Polygons",
                GeometryType::Polygon,
                vec![
                    Some(Geometry::Polygon(vec![vec![ring(2000.0)]])),
                    Some(Geometry::Polygon(vec![vec![ring(3000.0), ring(2000.0)]])),
                    Some(Geometry::Polygon(vec![vec![vec![at(600.0, 800.0), at(1600.0, 800.0), at(600.0, 1800.0), at(600.0, 800.0)]]])),
                    Some(Geometry::Polygon(vec![vec![vec![
                        at(400.0, 400.0),
                        at(500.0, 400.0),
                        at(500.0, 500.0),
                        at(400.0, 500.0),
                        at(400.0, 400.0),
                    ]]])),
                    Some(Geometry::Polygon(vec![vec![vec![
                        at(2000.0, 2000.0),
                        at(3000.0, 2000.0),
                        at(3000.0, 3000.0),
                        at(2000.0, 2000.0),
                    ]]])),
                ],
                vec![0, 2, 3],
            ),
        ];
        let mut s = Session::new(Project::default());
        let mut expected_layers = Vec::new();
        for (name, kind, geometries, expected) in fixtures {
            let geometries: Vec<_> = geometries.into_iter().map(|g| g.map(|g| g.map_coords(&merc_to_lonlat))).collect();
            let id = map_area_selection_add(&mut s, name, kind, &geometries);
            let dataset = &s.map().layer(id).unwrap().dataset;
            let rows: Vec<_> = (0..dataset.features.len()).collect();
            let mut direct: Vec<_> = within(dataset, &rows, center, radius).into_iter().map(|(row, _)| row).collect();
            direct.sort_unstable();
            assert_eq!(direct, expected, "{latitude}: {name} numerical fixture");
            expected_layers.push((id, direct));
        }
        // Radius hit testing must remain in its original dataset/metric space when the active
        // flat projection changes, including the regional grid used by the polygon fixture.
        for projection in ["mercator", "robinson", "EPSG:32631"] {
            s.run("map.projection", &json!({"type": projection})).unwrap();
            let total: usize = expected_layers.iter().map(|(_, rows)| rows.len()).sum();
            assert_eq!(
                s.run("select.byRadius", &json!({"lon": center.x, "lat": center.y, "radius": radius})).unwrap(),
                json!({"selected": total}),
                "{latitude}: {projection}"
            );
            for (id, expected) in &expected_layers {
                assert_eq!(&map_area_selection_rows(&s, *id), expected, "{latitude}: {projection}: {id}");
            }
        }
    }
}

#[test]
fn map_area_selection_radius_retains_legacy_geographic_prefilter() {
    use rustgis_analysis::network::{radius_distance_m, within};
    use rustgis_data::{Geometry, GeometryType};
    use rustgis_geom::Coord;
    let center = Coord::new(0.0, 60.0);
    let point = Coord::new(0.0, 59.1);
    let distance = radius_distance_m(center, point).unwrap();
    assert!(distance > 98000.0 && distance < 100000.0, "{distance}");
    let mut s = Session::new(Project::default());
    let id = map_area_selection_add(&mut s, "Legacy boundary", GeometryType::Point, &[Some(Geometry::Point(point))]);
    assert!(within(&s.map().layer(id).unwrap().dataset, &[0], center, 100000.0).is_empty());
    for mode in ["add", "remove", "new"] {
        s.map_mut().layer_mut(id).unwrap().selection = vec![0];
        assert_eq!(
            s.run("select.byRadius", &json!({"lon": 0, "lat": 60, "radius": 100000, "mode": mode})).unwrap(),
            json!({"selected": 0})
        );
        assert_eq!(map_area_selection_rows(&s, id), if mode == "new" { vec![] } else { vec![0] }, "{mode}");
    }
}

#[test]
fn map_area_selection_polygon_uses_projected_crossings_holes_and_multipart_features() {
    use rustgis_data::{Geometry, GeometryType};
    use rustgis_geom::Coord;
    for projection in ["mercator", "robinson", "EPSG:32631"] {
        let mut s = Session::new(Project::default());
        s.run("map.projection", &json!({"type": projection})).unwrap();
        let flat = s.map().flat();
        let origin = flat.forward_checked(Coord::new(3.0, 50.0)).unwrap();
        let at = |x: f64, y: f64| Coord::new(origin.x + x * 10000.0, origin.y + y * 10000.0);
        let ring = |a: f64, b: f64| vec![at(a, a), at(b, a), at(b, b), at(a, b), at(a, a)];
        let fixtures = [
            (
                "Projected points",
                GeometryType::Point,
                vec![
                    Some(Geometry::Point(at(0.5, 0.5))),
                    Some(Geometry::Point(at(2.0, 2.0))),
                    Some(Geometry::Point(at(2.5, 0.5))),
                    Some(Geometry::Point(at(4.0, 4.0))),
                    Some(Geometry::MultiPoint(vec![at(2.0, 2.0), at(0.5, 2.0)])),
                    None,
                ],
                vec![0, 2, 4],
            ),
            (
                "Projected lines",
                GeometryType::Polyline,
                vec![
                    // Neither endpoint is inside the L, but the segment traverses it.
                    Some(Geometry::Line(vec![vec![at(-1.0, 0.5), at(4.0, 0.5)]])),
                    Some(Geometry::Line(vec![vec![at(1.5, 2.0), at(2.5, 2.0)]])),
                    Some(Geometry::Line(vec![vec![at(4.0, 4.0), at(5.0, 5.0)], vec![at(0.2, 0.2), at(0.8, 0.8)]])),
                ],
                vec![0, 2],
            ),
            (
                "Projected polygons",
                GeometryType::Polygon,
                vec![
                    // The mask lies entirely inside this exterior, with no boundary crossings.
                    Some(Geometry::Polygon(vec![vec![ring(-1.0, 5.0)]])),
                    Some(Geometry::Polygon(vec![vec![ring(-1.0, 5.0), ring(-0.5, 3.5)]])),
                    Some(Geometry::Polygon(vec![vec![ring(1.5, 2.5)]])),
                    Some(Geometry::Polygon(vec![vec![ring(1.5, 2.5)], vec![ring(0.2, 0.8)]])),
                ],
                vec![0, 3],
            ),
        ];
        let mut expected_layers = Vec::new();
        for (name, kind, geometries, expected) in fixtures {
            let geometries: Vec<_> = geometries.into_iter().map(|g| g.map(|g| g.map_coords(&|p| flat.inverse(p).unwrap()))).collect();
            let id = map_area_selection_add(&mut s, name, kind, &geometries);
            expected_layers.push((id, expected));
        }
        let points: Vec<_> = [(0.0, 0.0), (3.0, 0.0), (3.0, 1.0), (1.0, 1.0), (1.0, 3.0), (0.0, 3.0)]
            .into_iter()
            .map(|(x, y)| {
                let p = flat.inverse(at(x, y)).unwrap();
                [p.x, p.y]
            })
            .collect();
        assert_eq!(s.run("select.byPolygon", &json!({"points": points})).unwrap(), json!({"selected": 7}), "{projection}");
        for (id, expected) in expected_layers {
            assert_eq!(map_area_selection_rows(&s, id), expected, "{projection}: {id}");
        }
    }
}

#[test]
fn zooms_to_a_layer_follow_its_definition_query() {
    let mut s = world();
    s.run("layer.definitionQuery", &json!({"layer": "Countries", "where": "continent = 'South America'"})).unwrap();
    let in_south_america = |c: rustgis_geom::Coord| (-85.0..-30.0).contains(&c.x) && (-60.0..15.0).contains(&c.y);
    // The frame zooms to the countries drawn, not the whole dataset (#206).
    s.run("layout.new", &json!({"page": "a4", "orientation": "portrait", "template": "map"})).unwrap();
    s.run("layout.frameZoom", &json!({"to": "layer", "layer": "Countries"})).unwrap();
    let Some(rustgis_map::layout::ElementKind::MapFrame { center, scale, .. }) =
        s.project.layouts[0].first_frame().and_then(|id| s.project.layouts[0].element(id)).map(|e| e.kind.clone())
    else {
        panic!("no frame")
    };
    assert!(in_south_america(center), "{center:?}");
    assert!(scale < 150_000_000.0, "{scale}");
    // So does the map view.
    s.run("layer.zoomTo", &json!({"layer": "Countries"})).unwrap();
    assert!(in_south_america(s.map().center_lonlat()), "{:?}", s.map().center_lonlat());
    // A query no country passes leaves nothing to zoom to.
    s.run("layer.definitionQuery", &json!({"layer": "Countries", "where": "continent = 'Atlantis'"})).unwrap();
    assert!(s.run("layer.zoomTo", &json!({"layer": "Countries"})).is_err());
    assert!(s.run("layout.frameZoom", &json!({"to": "layer", "layer": "Countries"})).is_err());
}

#[test]
fn layout_frames_print_site_plans_and_finds() {
    // Excavation plans at 1:20, finds at 1:1 and larger (#902): no longer held at 1:100.
    use rustgis_map::layout::{ElementKind, MIN_FRAME_SCALE};
    let mut s = world();
    s.run("layout.new", &json!({"page": "a4", "orientation": "landscape", "template": "map"})).unwrap();
    let scale_of = |s: &Session| {
        let l = &s.project.layouts[0];
        match l.element(l.first_frame().unwrap_or_default()).map(|e| &e.kind) {
            Some(ElementKind::MapFrame { scale, .. }) => *scale,
            _ => panic!("no frame"),
        }
    };
    let id = s.project.layouts[0].first_frame().unwrap();
    s.run("layout.update", &json!({"element": id, "scale": 20})).unwrap();
    assert_eq!(scale_of(&s), 20.0);
    s.run("layout.update", &json!({"element": id, "scale": 0.1})).unwrap();
    assert_eq!(scale_of(&s), MIN_FRAME_SCALE, "no larger than 2:1");
    // A frame matched to a view at 1:1 is a site-scale frame too.
    s.run("map.goToXY", &json!({"lon": 10.746, "lat": 46.82, "scale": 1})).unwrap();
    s.run("layout.frameZoom", &json!({"to": "view"})).unwrap();
    assert!(scale_of(&s) < 100.0, "{}", scale_of(&s));
}

#[test]
fn layout_frames_turn_and_tilt() {
    use rustgis_map::layout::ElementKind;
    let mut s = world();
    let frame_of = |s: &Session| {
        let l = &s.project.layouts[0];
        let id = l.first_frame().unwrap_or_default();
        match l.element(id).map(|e| e.kind.clone()) {
            Some(ElementKind::MapFrame { bearing, pitch, .. }) => (id, bearing, pitch),
            _ => panic!("no frame"),
        }
    };
    // A new frame shows the map view as it is, turned and tilted.
    s.run("map.setBearing", &json!({"bearing": 30})).unwrap();
    s.run("map.setPitch", &json!({"pitch": 50})).unwrap();
    s.run("layout.new", &json!({"page": "a4", "orientation": "landscape", "template": "map"})).unwrap();
    let (id, bearing, pitch) = frame_of(&s);
    assert_eq!((bearing, pitch), (30.0, 50.0));
    // Set on the frame, kept in range; a value that isn't a number changes nothing.
    s.run("layout.update", &json!({"element": id, "bearing": 400, "pitch": 200})).unwrap();
    assert_eq!(frame_of(&s), (id, 40.0, 85.0));
    assert!(s.run("layout.update", &json!({"element": id, "pitch": "steep", "bearing": 10})).is_err());
    assert_eq!(frame_of(&s), (id, 40.0, 85.0));
    // Zooming the frame to the view takes the view's bearing and pitch too.
    s.run("map.resetNorth", &json!({})).unwrap();
    s.run("layout.frameZoom", &json!({"to": "view"})).unwrap();
    assert_eq!(frame_of(&s), (id, 0.0, 0.0));
    // A flat frame saves as before; a tilted one draws differently, with its north arrow turned.
    let flat_json = serde_json::to_string(&s.project.layouts[0]).unwrap_or_default();
    assert!(!flat_json.contains("bearing") && !flat_json.contains("pitch"), "{flat_json}");
    s.run("layout.addElement", &json!({"kind": "northArrow", "frame": id})).unwrap();
    let info = rustgis_render::layout::PageInfo::default();
    let draw = |s: &mut Session| {
        rustgis_render::layout::render(&s.project.layouts[0].clone(), &mut s.project.maps, 48.0, &info).map(|p| p.data().to_vec())
    };
    let flat = draw(&mut s).expect("drawn");
    s.run("layout.update", &json!({"element": id, "bearing": 90, "pitch": 60})).unwrap();
    let tilted = draw(&mut s).expect("drawn");
    assert_ne!(flat, tilted);
    let saved = serde_json::to_string(&s.project.layouts[0]).unwrap_or_default();
    assert!(saved.contains("\"bearing\":90") && saved.contains("\"pitch\":60"), "{saved}");
}

#[test]
fn terrain_is_set_from_a_dem_or_tiles() {
    let mut s = world();
    // A source is required, and must be a raster layer or an XYZ URL.
    assert!(s.run("map.terrain", &json!({})).is_err());
    assert!(s.run("map.terrain", &json!({"layer": "Countries"})).is_err());
    assert!(s.run("map.terrain", &json!({"layer": "Nowhere"})).is_err());
    assert!(s.run("map.terrain", &json!({"tiles": "https://example.com/dem.png"})).is_err());
    assert!(s.run("map.terrain", &json!({"tiles": "file:///etc/{z}/{x}/{y}.png"})).is_err());
    assert!(s.run("map.terrain", &json!({"tiles": "https://e.com/{z}/{x}/{y}.png", "encoding": "jpeg"})).is_err());
    assert!(s.map().view.terrain.is_none());
    // Tiles, then only a new exaggeration (kept in range), then off.
    let v = s.run("map.terrain", &json!({"tiles": "https://e.com/{z}/{x}/{y}.png", "encoding": "mapbox", "exaggeration": 2})).unwrap();
    assert_eq!(v["source"]["encoding"], "mapbox");
    assert_eq!(v["exaggeration"], 2.0);
    let v = s.run("map.terrain", &json!({"exaggeration": 400})).unwrap();
    assert_eq!(v["exaggeration"], rustgis_map::view::MAX_EXAGGERATION);
    assert_eq!(v["source"]["tiles"], "https://e.com/{z}/{x}/{y}.png");
    assert!(s.run("map.terrain", &json!({"exaggeration": "steep"})).is_err());
    // Saved with the project.
    let saved = serde_json::to_string(&s.map().view).unwrap_or_default();
    let back: rustgis_map::view::ViewSettings = serde_json::from_str(&saved).unwrap_or_default();
    assert_eq!(back.terrain, s.map().view.terrain);
    s.run("map.terrain", &json!({"off": true})).unwrap();
    assert!(s.map().view.terrain.is_none());
    // Nothing named: the active layer, when it is a raster, is the DEM; a vector one is refused,
    // saying to make a DEM the active layer.
    s.active_layer = s.map().layer_by_name("Countries").map(|l| l.id);
    assert!(s.run("map.terrain", &json!({})).unwrap_err().contains("make a DEM raster layer the active layer"));
    s.run("layer.addDataBytes", &json!({"fileName": "dem.tif", "data": dem_b64()})).unwrap();
    let dem = s.map().layers.iter().find(|l| l.is_raster()).unwrap();
    let (id, name) = (dem.id, dem.name.clone());
    s.active_layer = Some(id);
    let v = s.run("map.terrain", &json!({"exaggeration": 3})).unwrap();
    assert_eq!((v["source"]["layer"].as_str(), v["exaggeration"].as_f64()), (Some(name.as_str()), Some(3.0)));
    // On a map looked at straight down, a notice names the layer picked and says to tilt it.
    let said = s.notices.last().unwrap().text.clone();
    assert!(said.contains(&format!("heights from '{name}'")) && said.contains("tilt the map"), "{said}");
    // A change of exaggeration alone says nothing again.
    let mark = s.notice_mark();
    s.run("map.terrain", &json!({"exaggeration": 2})).unwrap();
    assert!(s.notices_since(mark).iter().all(|n| !n.text.contains("Terrain is on")), "{:?}", s.notices_since(mark));
    // Two layers of the DEM's name: refused, since the terrain keeps it by name.
    s.run("map.terrain", &json!({"off": true})).unwrap();
    s.run("layer.addDataBytes", &json!({"fileName": "dem.tif", "data": dem_b64()})).unwrap();
    let second = s.map().layers.iter().filter(|l| l.is_raster()).map(|l| l.id).max().unwrap();
    s.active_layer = Some(second);
    s.run("layer.rename", &json!({"name": name})).unwrap();
    let e = s.run("map.terrain", &json!({})).unwrap_err();
    assert!(e.contains("more than one layer is called"), "{e}");
    s.run("layer.rename", &json!({"name": "dem 2"})).unwrap();
    s.active_layer = Some(id);
    s.run("map.terrain", &json!({})).unwrap();
    // A project saved with a terrain on a shared DEM name says so as it opens.
    {
        let mut saved = s.project.clone();
        let m = &mut saved.maps[0];
        let first = m.layers.iter().find(|l| l.is_raster()).map(|l| l.name.clone()).unwrap();
        if let Some(l) = m.layers.iter_mut().filter(|l| l.is_raster()).nth(1) {
            l.name = first.clone();
        }
        m.view.terrain = Some(rustgis_map::view::Terrain { source: rustgis_map::view::TerrainSource::Layer(first), exaggeration: 1.0 });
        let mut opened = Session::new(Project::default());
        crate::cmd::project::reset_to(&mut opened, saved);
        assert!(opened.notices.iter().any(|n| n.text.contains("is shared by two layers")), "{:?}", opened.notices);
    }
    // Renaming another layer leaves the terrain as it is.
    s.run("layer.rename", &json!({"layer": "Countries", "name": "Paises"})).unwrap();
    assert!(s.map().view.terrain.is_some());
    s.run("layer.rename", &json!({"layer": "Paises", "name": "Countries"})).unwrap();
    // Renaming the DEM onto another layer's name turns the terrain off, said.
    s.active_layer = Some(id);
    s.run("layer.rename", &json!({"name": "dem 2"})).unwrap();
    assert!(s.map().view.terrain.is_none());
    assert!(s.notices.last().unwrap().text.contains("two layers are now called 'dem 2'"), "{:?}", s.notices.last());
    s.run("layer.rename", &json!({"name": name})).unwrap();
    s.run("map.terrain", &json!({"layer": name})).unwrap();
    // Removing the DEM turns the terrain off, said.
    {
        let mut t = Session::new(Project::default());
        t.run("layer.addDataBytes", &json!({"fileName": "dem.tif", "data": dem_b64()})).unwrap();
        t.run("map.terrain", &json!({})).unwrap();
        t.run("layer.remove", &json!({})).unwrap();
        assert!(t.map().view.terrain.is_none());
        assert!(t.notices.last().unwrap().text.contains("was removed"), "{:?}", t.notices.last());
        // A mobile map package keeps a hidden DEM, which still gives the heights.
        t.run("layer.addDataBytes", &json!({"fileName": "dem.tif", "data": dem_b64()})).unwrap();
        t.run("map.terrain", &json!({})).unwrap();
        t.run("layer.visibility", &json!({})).unwrap();
        assert!(t.map().layers.iter().any(|l| l.is_raster() && !l.visible));
        let pkg = std::env::temp_dir().join(format!("rustgis-terrain-{}.rgismpk", std::process::id()));
        t.run("map.package", &json!({"path": pkg.display().to_string(), "mobile": true})).unwrap();
        t.run("map.import", &json!({"path": pkg.display().to_string()})).unwrap();
        let _ = std::fs::remove_file(&pkg);
        let packaged = t.project.maps.last().unwrap();
        assert!(packaged.layers.iter().any(|l| l.is_raster()), "the hidden DEM is in the package");
        assert!(packaged.view.terrain.is_some());
        t.run("layer.remove", &json!({"layer": t.map().layers.iter().find(|l| l.is_raster()).map(|l| l.id).unwrap()})).unwrap();
        // So does removing a group that holds it.
        t.run("layer.addDataBytes", &json!({"fileName": "dem.tif", "data": dem_b64()})).unwrap();
        let dem = t.map().layers.iter().find(|l| l.is_raster()).map(|l| l.id).unwrap();
        let group = t.run("group.add", &json!({"name": "Relevo", "layers": [dem]})).unwrap()["group"].clone();
        t.active_layer = Some(dem);
        t.run("map.terrain", &json!({})).unwrap();
        t.run("group.remove", &json!({"group": group})).unwrap();
        assert!(t.map().view.terrain.is_none());
        assert!(t.notices.last().unwrap().text.contains("was removed"), "{:?}", t.notices.last());
    }
    // Renaming the DEM keeps the terrain on it.
    s.run("layer.rename", &json!({"name": "Relevo"})).unwrap();
    assert_eq!(s.run("map.terrain", &json!({"exaggeration": 1})).unwrap()["source"]["layer"], "Relevo");
    // A second layer renamed to the DEM's name: the terrain, now ambiguous, is turned off, and
    // said.
    s.active_layer = Some(second);
    s.run("layer.rename", &json!({"name": "relevo"})).unwrap();
    assert!(s.map().view.terrain.is_none());
    assert!(s.notices.last().unwrap().text.contains("Terrain turned off: two layers are now called"), "{:?}", s.notices.last());
    s.run("layer.rename", &json!({"name": "dem 2"})).unwrap();
    s.active_layer = Some(id);
    s.run("map.terrain", &json!({"layer": "Relevo"})).unwrap();
    let name = "Relevo".to_string();
    // Once on, nothing named changes nothing but what is given: the active layer doesn't replace it.
    s.active_layer = s.map().layer_by_name("Countries").map(|l| l.id);
    let v = s.run("map.terrain", &json!({})).unwrap();
    assert_eq!(v["source"]["layer"].as_str(), Some(name.as_str()));
    s.run("map.terrain", &json!({"off": true})).unwrap();
}

#[test]
fn graduated_symbology_skips_a_current_text_field() {
    let mut s = world();
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "unique", "field": "income_grp"})).unwrap();

    s.run("layer.symbology", &json!({"layer": "Countries", "type": "graduated"})).unwrap();
    let layer = s.map().layer_by_name("Countries").unwrap();
    let rustgis_map::Renderer::Graduated { field, .. } = &layer.renderer else { panic!("Graduated Colors renderer expected") };
    assert_ne!(field, "income_grp", "the text field from the previous renderer is not reused");
    assert!(layer.dataset.field_index(field).and_then(|i| layer.dataset.fields.get(i)).is_some_and(|f| f.ty.is_numeric()));
}

#[test]
fn symbology_chooses_fields_by_renderer_requirements() {
    let mut s = Session::new(Project::default());
    s.run(
        "layer.addDataText",
        &json!({
            "fileName": "text-fields.geojson",
            "text": r#"{"type":"FeatureCollection","features":[
                {"type":"Feature","properties":{"g_id":"61259","g_name":"Liezen"},"geometry":{"type":"Point","coordinates":[14.24,47.57]}},
                {"type":"Feature","properties":{"g_id":"61260","g_name":"Graz"},"geometry":{"type":"Point","coordinates":[15.44,47.07]}}
            ]}"#
        }),
    )
    .unwrap();

    s.run("layer.symbology", &json!({"layer": "text-fields", "type": "unique"})).unwrap();
    let rustgis_map::Renderer::Unique { field, classes, .. } = &s.map().layer_by_name("text-fields").unwrap().renderer else {
        panic!("Unique Values renderer expected")
    };
    assert_eq!(field, "g_id");
    assert_eq!(classes.len(), 2);

    let before = s.map().layer_by_name("text-fields").unwrap().renderer.clone();
    let depth = s.undo_depth();
    let err = s.run("layer.symbology", &json!({"layer": "text-fields", "type": "graduated"})).unwrap_err();
    assert_eq!(err, "no numeric field is available for this symbology");
    assert_eq!(s.map().layer_by_name("text-fields").unwrap().renderer, before, "failed mode switch leaves current styling intact");
    assert_eq!(s.undo_depth(), depth, "failed mode switch adds no undo step");
}

#[test]
fn symbology_classes_follow_the_definition_query() {
    let mut s = world();
    s.run("layer.definitionQuery", &json!({"layer": "Countries", "where": "continent = 'Europe'"})).unwrap();
    let shown = |s: &Session, field: &str| -> Vec<rustgis_data::Value> {
        let l = s.map().layer_by_name("Countries").unwrap();
        let fi = l.dataset.field_index(field).unwrap();
        l.visible_rows().iter().enumerate().filter(|(_, v)| **v).map(|(r, _)| l.dataset.value(r, fi).clone()).collect()
    };
    // The top class ends at the largest country drawn, not at China (#236).
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "graduated", "field": "pop_est", "classes": 5})).unwrap();
    let top = shown(&s, "pop_est").iter().filter_map(|v| v.as_f64()).fold(f64::MIN, f64::max);
    let rustgis_map::Renderer::Graduated { breaks, .. } = &s.map().layer_by_name("Countries").unwrap().renderer else {
        panic!("graduated renderer expected")
    };
    assert_eq!(breaks.last().copied(), Some(top));
    // Unique values list only the values drawn.
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "unique", "field": "income_grp"})).unwrap();
    let mut drawn: Vec<String> = shown(&s, "income_grp").iter().map(|v| v.to_string()).collect();
    drawn.sort();
    drawn.dedup();
    let rustgis_map::Renderer::Unique { classes, .. } = &s.map().layer_by_name("Countries").unwrap().renderer else {
        panic!("unique renderer expected")
    };
    assert_eq!(classes.iter().map(|(k, _)| k.clone()).collect::<Vec<_>>(), drawn);
    // Classes are taken once: changing the query keeps them.
    let before = s.map().layer_by_name("Countries").unwrap().renderer.clone();
    s.run("layer.definitionQuery", &json!({"layer": "Countries", "where": ""})).unwrap();
    assert_eq!(s.map().layer_by_name("Countries").unwrap().renderer, before);
    // A query no country passes leaves nothing to class.
    s.run("layer.definitionQuery", &json!({"layer": "Countries", "where": "continent = 'Atlantis'"})).unwrap();
    let err = s.run("layer.symbology", &json!({"layer": "Countries", "type": "graduated", "field": "pop_est"})).unwrap_err();
    assert!(err.contains("definition query"), "{err}");
}

#[test]
fn layer_class_style_edits_one_class() {
    // #314: one class's colour and legend label, by command (the Symbology pane runs the same).
    let mut s = world();
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "unique", "field": "income_grp"})).unwrap();
    let renderer = |s: &Session| s.map().layer_by_name("Countries").unwrap().renderer.clone();
    let value = renderer(&s).legend().into_iter().next().unwrap().label;
    // Legend rows are sorted by label (#218), so a renamed class moves: find its row from its
    // value, not its label, so an edit landing on another class can't pass.
    let class = |s: &Session| {
        let r = renderer(s);
        let rustgis_map::Renderer::Unique { classes, .. } = &r else { panic!("unique renderer expected") };
        let i = classes.iter().position(|(k, _)| *k == value).unwrap();
        let row = r.class_order().into_iter().position(|o| o == i).unwrap();
        r.legend().into_iter().nth(row).unwrap()
    };
    let r = s.run("layer.classStyle", &json!({"layer": "Countries", "value": value, "color": "#123456", "label": "Rich"})).unwrap();
    assert_eq!(r["label"], "Rich");
    assert!(r["color"].as_str().is_some_and(|c| c.starts_with("#123456")), "{r}");
    assert_eq!(class(&s).label, "Rich");
    // The renamed class sorts to a new legend row and keeps its own colour there.
    assert!(class(&s).symbol.fill.hex().starts_with("#123456"), "{:?}", class(&s));
    // One undo step, as every command is.
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(class(&s).label, value);
    s.run("edit.redo", &Value::Null).unwrap();
    let edited = class(&s);
    assert_eq!(edited.label, "Rich");
    // Applying the symbology again on the same field keeps the edit; a new scheme recolours
    // every class and keeps the label.
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "unique", "field": "income_grp"})).unwrap();
    assert_eq!(class(&s), edited);
    s.run("layer.ramp", &json!({"layer": "Countries", "ramp": "Ember"})).unwrap();
    assert_eq!(class(&s).label, "Rich");
    assert_ne!(class(&s).symbol, edited.symbol);
    // The fallback class.
    s.run("layer.classStyle", &json!({"layer": "Countries", "other": true, "label": "Rest"})).unwrap();
    assert_eq!(renderer(&s).legend().last().map(|e| e.label.clone()).as_deref(), Some("Rest"));
    // Refused: no such class, the wrong way to name one, two at once, or nothing to change.
    for bad in [
        json!({"layer": "Countries", "value": "Atlantis", "color": "#000000"}),
        json!({"layer": "Countries", "index": 0, "color": "#000000"}),
        json!({"layer": "Countries", "value": value, "other": true, "label": "x"}),
        json!({"layer": "Countries", "value": value}),
        json!({"layer": "Countries", "value": value, "color": "red"}),
        json!({"layer": "Countries", "value": value, "color": "#000000", "label": 5}),
        json!({"layer": "Countries", "value": value, "label": null}),
        json!({"layer": "Countries", "value": value, "label": "x", "color": 5}),
        json!({"layer": "Countries", "value": value, "label": "x", "outline": true}),
    ] {
        assert!(s.run("layer.classStyle", &bad).is_err(), "{bad}");
    }
    // A malformed index says what is wrong with it.
    for index in [json!(0.5), json!(-1), json!("first")] {
        let err = s.run("layer.classStyle", &json!({"layer": "Countries", "index": index, "label": "x"})).unwrap_err();
        assert!(err.contains("whole number"), "{index}: {err}");
    }
    // A numeric value names its class as the data prints it, whether sent as an integer or not.
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "unique", "field": "pop_est"})).unwrap();
    // A whole value among the first classes (the smallest, as they're in numeric order).
    let rustgis_map::Renderer::Unique { classes, .. } = renderer(&s) else { panic!("unique renderer expected") };
    let whole = classes.iter().find_map(|(k, _)| k.parse::<i64>().ok().filter(|n| *n > 1000)).unwrap();
    for v in [json!(whole), json!(whole as f64)] {
        let r = s.run("layer.classStyle", &json!({"layer": "Countries", "value": v, "label": "Brazil"})).unwrap();
        assert_eq!(r["label"], "Brazil", "{v}");
    }
    // Graduated Colors, by number: the label replaces the range.
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "graduated", "field": "pop_est", "classes": 3})).unwrap();
    s.run("layer.classStyle", &json!({"layer": "Countries", "index": 2, "label": "Most populous"})).unwrap();
    assert_eq!(renderer(&s).legend().get(2).map(|e| e.label.clone()).as_deref(), Some("Most populous"));
    assert!(s.run("layer.classStyle", &json!({"layer": "Countries", "index": 3, "label": "x"})).is_err());
}

/// Read classes by their command identity, not their sorted legend position.
fn class_style_rows(s: &Session, layer: &str) -> Vec<(Value, rustgis_map::Symbol)> {
    match &s.map().layer_by_name(layer).unwrap().renderer {
        rustgis_map::Renderer::Graduated { symbols, .. } => {
            symbols.iter().enumerate().map(|(i, symbol)| (json!({"layer": layer, "index": i}), *symbol)).collect()
        }
        rustgis_map::Renderer::Unique { classes, other, .. } => classes
            .iter()
            .map(|(value, symbol)| (json!({"layer": layer, "value": value}), *symbol))
            .chain(std::iter::once((json!({"layer": layer, "other": true}), *other)))
            .collect(),
        _ => panic!("class renderer expected"),
    }
}

#[test]
fn layer_class_style_polygon_alpha_targets_only_the_named_class() {
    use rustgis_map::Rgba;
    for (kind, field) in [("graduated", "pop_est"), ("unique", "income_grp")] {
        let mut s = world();
        s.run("layer.symbology", &json!({"layer": "Countries", "type": kind, "field": field, "classes": 3})).unwrap();
        let rows = class_style_rows(&s, "Countries");
        // A middle graduated class, a unique value, and the unique fallback all use the same rules.
        let targets = if kind == "unique" { vec![1, rows.len() - 1] } else { vec![1] };
        for target in targets {
            for (color, alpha) in [
                ("#123456", 170),
                (" #123456FF ", 255),
                ("12345600", 0),
                ("#12345640", 64),
                ("#123456", 150),
                ("#123456C8", 200),
                (" 123456 ", 200),
            ] {
                let before = class_style_rows(&s, "Countries");
                let mut params = before[target].0.clone();
                params["color"] = json!(color);
                let result = s.run("layer.classStyle", &params).unwrap();
                let after = class_style_rows(&s, "Countries");
                let fill = Rgba::rgb(0x12, 0x34, 0x56).with_alpha(alpha);
                assert_eq!(after[target].1.fill, fill, "{kind}: {params}");
                assert_eq!(Rgba::from_hex(result["color"].as_str().unwrap()), Some(fill));
                for (i, (old, new)) in before.iter().zip(&after).enumerate() {
                    assert_eq!(new.0, old.0);
                    if i != target {
                        assert_eq!(new.1, old.1, "{kind}: {params} changed class {i}");
                    }
                }
                if alpha == 0 {
                    s.run("edit.undo", &Value::Null).unwrap();
                    assert_eq!(class_style_rows(&s, "Countries"), before);
                    s.run("edit.redo", &Value::Null).unwrap();
                    assert_eq!(class_style_rows(&s, "Countries"), after);
                    let saved = serde_json::to_string(&s.project).unwrap();
                    let reopened = Session::new(Project::from_json(&saved).unwrap());
                    assert_eq!(class_style_rows(&reopened, "Countries"), after);
                }
            }
        }
    }
}

#[test]
fn layer_class_alpha_survives_reclassification_and_ramp() {
    for (kind, field, scheme, next_scheme) in [("graduated", "pop_est", "Ember", "Harbour"), ("unique", "income_grp", "Harbour", "Ember")] {
        let mut s = world();
        let mut symbology = json!({"layer": "Countries", "type": kind, "field": field, "classes": 3, "ramp": scheme});
        s.run("layer.symbology", &symbology).unwrap();
        let original = class_style_rows(&s, "Countries");
        for (i, (mut params, symbol)) in original.iter().cloned().enumerate() {
            // Keep exactly the ramp's RGB: an alpha-only edit must not be mistaken for an untouched fill.
            params["color"] = json!(symbol.fill.with_alpha([0, 64, 255][i % 3]).hex8());
            s.run("layer.classStyle", &params).unwrap();
        }
        let edited = s.map().layer_by_name("Countries").unwrap().renderer.clone();
        let before = class_style_rows(&s, "Countries");
        for (i, ((_, old), (_, new))) in original.iter().zip(&before).enumerate() {
            assert_eq!((new.fill.r(), new.fill.g(), new.fill.b()), (old.fill.r(), old.fill.g(), old.fill.b()));
            assert_eq!(new.fill.a(), [0, 64, 255][i % 3]);
        }
        // Both an omitted scheme and an explicit unchanged scheme are reapplications, not resets.
        let mut same = symbology.clone();
        same.as_object_mut().unwrap().remove("ramp");
        for params in [&same, &symbology] {
            s.run("layer.symbology", params).unwrap();
            assert_eq!(s.map().layer_by_name("Countries").unwrap().renderer, edited, "{kind}");
        }
        // Recolouring through layer.ramp keeps every class's exact alpha, including the fallback's.
        s.run("layer.ramp", &json!({"layer": "Countries", "ramp": next_scheme})).unwrap();
        let recolored = class_style_rows(&s, "Countries");
        for ((old_target, old), (new_target, new)) in before.iter().zip(&recolored) {
            assert_eq!(new_target, old_target);
            assert_eq!(new.fill.a(), old.fill.a(), "{kind}: {new_target}");
        }
        assert!(
            before
                .iter()
                .zip(&recolored)
                .any(|((_, old), (_, new))| { (old.fill.r(), old.fill.g(), old.fill.b()) != (new.fill.r(), new.fill.g(), new.fill.b()) })
        );
        // A different scheme chosen through layer.symbology still resets polygon opacity as before.
        symbology["ramp"] = json!(scheme);
        s.run("layer.symbology", &symbology).unwrap();
        assert!(class_style_rows(&s, "Countries").iter().all(|(_, symbol)| symbol.fill.a() == 170), "{kind}");
    }
}

#[test]
fn layer_class_creation_keeps_explicit_layer_fill_alpha() {
    for (kind, field) in [("graduated", "pop_est"), ("unique", "income_grp")] {
        for alpha in [0, 64, 255] {
            let mut s = world();
            s.run("layer.color", &json!({"layer": "Countries", "color": format!("#336699{alpha:02X}")})).unwrap();
            s.run("layer.symbology", &json!({"layer": "Countries", "type": kind, "field": field, "classes": 3})).unwrap();
            for (target, symbol) in class_style_rows(&s, "Countries") {
                assert_eq!(symbol.fill.a(), alpha, "{kind}: {target}");
            }
        }
    }
}

#[test]
fn layer_class_style_point_and_line_colors_keep_their_supplied_alpha() {
    use rustgis_map::Rgba;
    let mut s = world();
    for layer in ["Cities", "Rivers"] {
        let field = s.map().layer_by_name(layer).unwrap().dataset.fields[0].name.clone();
        s.run("layer.symbology", &json!({"layer": layer, "type": "unique", "field": field})).unwrap();
        let mut params = class_style_rows(&s, layer)[0].0.clone();
        for color in ["#12345600", "#12345640", "#123456FF", "#123456"] {
            let before = class_style_rows(&s, layer);
            params["color"] = json!(color);
            s.run("layer.classStyle", &params).unwrap();
            let after = class_style_rows(&s, layer);
            let fill = Rgba::from_hex(color).unwrap();
            assert_eq!(after[0].1.fill, fill, "{layer}: {color}");
            assert_eq!(after[0].1.stroke, if layer == "Rivers" { fill } else { before[0].1.stroke });
            assert_eq!(&after[1..], &before[1..], "{layer}: other classes are untouched");
        }
    }
}

#[test]
fn layer_class_style_polygon_alpha_reaches_exported_pixels() {
    isolate_plugins();
    let fixture = json!({"type": "FeatureCollection", "features": [{
        "type": "Feature", "properties": {"value": 1},
        "geometry": {"type": "Polygon", "coordinates": [[[-0.25, -0.25], [0.25, -0.25], [0.25, 0.25], [-0.25, 0.25], [-0.25, -0.25]]]}
    }]});
    for kind in ["graduated", "unique"] {
        let mut s = Session::new(Project::default());
        s.run("layer.addDataText", &json!({"fileName": "square.geojson", "text": fixture.to_string()})).unwrap();
        s.run("layer.symbology", &json!({"layer": "square", "type": kind, "field": "value", "classes": 1})).unwrap();
        s.view_size = (128.0, 128.0);
        s.map_mut().basemap = rustgis_map::Basemap::Blank;
        s.map_mut().graticule = false;
        s.map_mut().camera = rustgis_map::Camera { center: rustgis_geom::Coord::new(0.0, 0.0), res: 1000.0, bearing: 0.0, pitch: 0.0 };
        let mut params = class_style_rows(&s, "square")[0].0.clone();
        for alpha in [255, 0, 64] {
            params["color"] = json!(format!("#FF0000{alpha:02X}"));
            s.run("layer.classStyle", &params).unwrap();
            let png = crate::cmd::share::map_png(&mut s, Some(128.0), Some(128.0), None).unwrap();
            let pixels = crate::render::decode_png(&png).unwrap();
            let center = pixels.pixel(64, 64).unwrap();
            let background = pixels.pixel(0, 0).unwrap();
            assert_eq!(center.alpha(), 255, "the export composites onto the blank basemap");
            for (actual, source, behind) in
                [(center.red(), 255, background.red()), (center.green(), 0, background.green()), (center.blue(), 0, background.blue())]
            {
                let expected = (source * alpha + u32::from(behind) * (255 - alpha) + 127) / 255;
                assert!((i64::from(actual) - i64::from(expected)).abs() <= 1, "{kind}, alpha {alpha}: {center:?} over {background:?}");
            }
        }
    }
}

#[test]
fn layout_legends_list_what_the_frame_draws() {
    // #207's repro: classes taken before the query (or from a style) name values no drawn country has.
    let mut s = world();
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "unique", "field": "income_grp"})).unwrap();
    s.run("layer.definitionQuery", &json!({"layer": "Countries", "where": "continent = 'South America'"})).unwrap();
    let l = s.map().layer_by_name("Countries").unwrap();
    let rustgis_map::Renderer::Unique { classes, .. } = &l.renderer else { panic!("unique renderer expected") };
    assert!(classes.len() > 2, "{classes:?}");
    let shown: Vec<String> = l.shown_legend(4e7).unwrap().into_iter().map(|e| e.label).collect();
    let mut drawn: Vec<String> = {
        let fi = l.dataset.field_index("income_grp").unwrap();
        l.visible_rows().iter().enumerate().filter(|(_, v)| **v).map(|(r, _)| l.dataset.value(r, fi).to_string()).collect()
    };
    drawn.sort();
    drawn.dedup();
    let mut sorted = shown.clone();
    sorted.sort();
    assert_eq!(sorted, drawn, "only the classes South America has, and no <all other values>");
    assert!(shown.len() < classes.len());
    // The legend element lists what its frame draws unless told to list every class.
    s.run("layout.new", &json!({"page": "a4", "orientation": "portrait", "template": "map"})).unwrap();
    let legend =
        |s: &Session| s.project.layouts[0].elements.iter().find(|e| e.kind.code() == "legend").map(|e| (e.id, e.kind.clone())).unwrap();
    let (id, kind) = legend(&s);
    assert!(matches!(kind, rustgis_map::layout::ElementKind::Legend { all_classes: false, .. }), "{kind:?}");
    s.run("layout.update", &json!({"element": id, "allClasses": true})).unwrap();
    assert!(matches!(legend(&s).1, rustgis_map::layout::ElementKind::Legend { all_classes: true, hide_other: false, .. }));
    // <all other values> can be left out on its own, in either mode.
    s.run("layout.update", &json!({"element": id, "hideOther": true})).unwrap();
    assert!(matches!(legend(&s).1, rustgis_map::layout::ElementKind::Legend { all_classes: true, hide_other: true, .. }));
    // Read like every other on/off parameter (`b`): a value that is neither a bool nor text keeps
    // the setting, and text other than true/yes/1/on turns it off.
    s.run("layout.update", &json!({"element": id, "hideOther": 5})).unwrap();
    assert!(matches!(legend(&s).1, rustgis_map::layout::ElementKind::Legend { hide_other: true, .. }), "a number keeps the setting");
    s.run("layout.update", &json!({"element": id, "hideOther": "off"})).unwrap();
    assert!(matches!(legend(&s).1, rustgis_map::layout::ElementKind::Legend { hide_other: false, .. }));
    let r = s.run("layout.addElement", &json!({"kind": "legend", "allClasses": true})).unwrap();
    let added = r["element"].as_u64().unwrap() as u32;
    let kind = s.project.layouts[0].element(added).map(|e| e.kind.clone()).unwrap();
    assert!(matches!(kind, rustgis_map::layout::ElementKind::Legend { all_classes: true, .. }), "{kind:?}");
    // Layouts saved before the option open with it off.
    let old: rustgis_map::layout::ElementKind = serde_json::from_str(r#"{"Legend":{"frame":1,"title":"L"}}"#).unwrap();
    assert!(matches!(old, rustgis_map::layout::ElementKind::Legend { all_classes: false, hide_other: false, .. }));
}

/// A map frame's grid can be a measured grid (#1008): eastings and northings in a projected
/// system its step apart in metres, with whole or short labels; a system that isn't projected, or
/// isn't one, is refused; a change of type starts its step afresh.
#[test]
fn a_frames_grid_can_be_a_measured_grid() {
    use rustgis_map::layout::{ElementKind, GridKind};
    let mut s = world();
    s.run("layout.new", &json!({"page": "a4", "template": "map"})).unwrap();
    let frame = s.project.layouts[0].elements.iter().find(|e| e.kind.code() == "mapFrame").unwrap().id;
    let grid = |s: &Session| match &s.project.layouts[0].element(frame).unwrap().kind {
        ElementKind::MapFrame { grid, .. } => grid.clone(),
        k => panic!("{k:?}"),
    };
    s.run("layout.addElement", &json!({"kind": "grid", "step": 15})).unwrap();
    assert_eq!(grid(&s).unwrap().step, 15.0);
    // Measured: the step in metres (a graticule's 15° isn't carried over), the system named.
    s.run("layout.update", &json!({"element": frame, "grid": {"type": "measured", "crs": " EPSG:25832 "}})).unwrap();
    let g = grid(&s).unwrap();
    assert_eq!((g.kind, g.step, g.crs.as_deref(), g.short), (GridKind::Measured, 0.0, Some("EPSG:25832"), false));
    s.run("layout.update", &json!({"element": frame, "grid": {"step": 1000, "short": true}})).unwrap();
    let g = grid(&s).unwrap();
    assert_eq!((g.step, g.short), (1000.0, true));
    // Steps in metres: from a metre to 10,000 km, 0 picks one; past 90 isn't a graticule's limit.
    for (step, want) in [(0.25, 1.0), (1e12, rustgis_map::layout::MAX_MEASURED_STEP), (-5.0, 0.0), (250_000.0, 250_000.0)] {
        s.run("layout.update", &json!({"element": frame, "grid": {"step": step}})).unwrap();
        assert_eq!(grid(&s).unwrap().step, want, "{step}");
    }
    // A system by WKT or PROJ string too; "" goes back to the map's (or the UTM zone).
    s.run("layout.update", &json!({"element": frame, "grid": {"crs": "+proj=utm +zone=33 +datum=WGS84 +units=m +no_defs"}})).unwrap();
    assert!(grid(&s).unwrap().crs.unwrap().starts_with("+proj=utm"));
    s.run("layout.update", &json!({"element": frame, "grid": {"crs": ""}})).unwrap();
    assert_eq!(grid(&s).unwrap().crs, None);
    let before = grid(&s);
    for bad in [
        json!({"type": "utm"}),
        json!({"crs": "EPSG:4326"}),
        json!({"crs": "EPSG:1"}),
        json!({"crs": "not a system"}),
        json!({"crs": 25832}),
        json!({"crs": format!("EPSG:25832 {}", "x".repeat(rustgis_map::layout::MAX_GRID_CRS))}),
    ] {
        assert!(s.run("layout.update", &json!({"element": frame, "grid": bad})).is_err(), "{bad}");
        let mut p = bad.clone();
        p["kind"] = json!("grid");
        assert!(s.run("layout.addElement", &p).is_err(), "{bad}");
    }
    assert_eq!(grid(&s), before, "a refusal changes nothing");
    // Back to a graticule: degrees again, the step starting afresh; kept with the project.
    s.run("layout.update", &json!({"element": frame, "grid": {"type": "measured", "crs": "EPSG:2056", "step": 500}})).unwrap();
    let text = serde_json::to_string(&s.project).unwrap();
    let reopened = Session::new(serde_json::from_str(&text).unwrap());
    assert_eq!(
        match &reopened.project.layouts[0].element(frame).unwrap().kind {
            ElementKind::MapFrame { grid, .. } => grid.clone(),
            _ => None,
        },
        grid(&s)
    );
    s.run("layout.update", &json!({"element": frame, "grid": {"type": "graticule"}})).unwrap();
    let g = grid(&s).unwrap();
    assert_eq!((g.kind, g.step), (GridKind::Graticule, 0.0));
    s.run("layout.update", &json!({"element": frame, "grid": {"step": 500}})).unwrap();
    assert_eq!(grid(&s).unwrap().step, 90.0, "a graticule's step is degrees");
    // It draws (a PNG of the page).
    let path = std::env::temp_dir().join(format!("rustgis-measured-{}.png", std::process::id()));
    s.run("layout.update", &json!({"element": frame, "grid": {"type": "measured", "step": 1000000}})).unwrap();
    s.run("layout.export", &json!({"path": path, "dpi": 72})).unwrap();
    assert!(std::fs::metadata(&path).is_ok_and(|m| m.len() > 1000));
    let _ = std::fs::remove_file(&path);
}

/// Grids, north arrows and scale bars take their cartographic options through commands (#327):
/// checked before anything changes, kept when other options change, and saved with the layout.
#[test]
fn layout_surrounds_take_cartographic_options() {
    use rustgis_map::Rgba;
    use rustgis_map::layout::{ArrowStyle, CoordFormat, ElementKind, GridEdges, GridStyle, ScaleBarStyle, ScaleUnits};
    let mut s = world();
    s.run("layout.new", &json!({"page": "a4", "orientation": "landscape", "template": "map"})).unwrap();
    let find = |s: &Session, code: &str| s.project.layouts[0].elements.iter().find(|e| e.kind.code() == code).unwrap().clone();
    let frame = find(&s, "mapFrame").id;
    let grid = |s: &Session| match &s.project.layouts[0].element(frame).unwrap().kind {
        ElementKind::MapFrame { grid, .. } => grid.clone(),
        k => panic!("{k:?}"),
    };
    // A grid with ticks along the top and right edges, in degrees and minutes.
    s.run(
        "layout.addElement",
        &json!({"kind": "grid", "step": 0.5, "style": "ticks", "tickLength": 3, "format": "dms", "edges": ["top", "right"], "labelOrientation": "vertical"}),
    )
    .unwrap();
    let g = grid(&s).unwrap();
    assert_eq!((g.step, g.style, g.tick_length, g.format), (0.5, GridStyle::Ticks, 3.0, CoordFormat::Dms));
    assert_eq!(g.edges, GridEdges { top: true, bottom: false, left: false, right: true });
    // Adding it again changes only what is named; a bad value changes nothing.
    s.run("layout.addElement", &json!({"kind": "grid", "width": 1.5, "hemisphere": false})).unwrap();
    let g2 = grid(&s).unwrap();
    assert_eq!((g2.width, g2.hemisphere, g2.style, g2.step), (1.5, false, GridStyle::Ticks, 0.5));
    for bad in [json!({"style": "dotted"}), json!({"format": "utm"}), json!({"edges": ["middle"]}), json!({"labelOrientation": "diagonal"})]
    {
        let mut p = bad.clone();
        p["kind"] = json!("grid");
        assert!(s.run("layout.addElement", &p).is_err(), "{bad}");
        assert!(s.run("layout.update", &json!({"element": frame, "grid": bad})).is_err(), "{bad}");
    }
    assert_eq!(grid(&s).unwrap(), g2);
    // The frame's properties edit, remove and restore its grid; sizes are clamped.
    s.run("layout.update", &json!({"element": frame, "grid": {"style": "linesAndTicks", "tickLength": 1e9, "edges": "bottom, left"}}))
        .unwrap();
    let g3 = grid(&s).unwrap();
    assert_eq!((g3.style, g3.tick_length, g3.edges), (GridStyle::LinesAndTicks, rustgis_map::layout::MAX_TICK_MM, GridEdges::default()));
    s.run("layout.update", &json!({"element": frame, "grid": null})).unwrap();
    assert_eq!(grid(&s), Some(g3), "null is not set: the grid stays");
    s.run("layout.update", &json!({"element": frame, "grid": false})).unwrap();
    assert!(grid(&s).is_none());
    s.run("layout.update", &json!({"element": frame, "grid": true})).unwrap();
    assert_eq!(grid(&s), Some(rustgis_map::layout::Grid::default()));
    let arrow = find(&s, "northArrow").id;
    assert!(s.run("layout.update", &json!({"element": arrow, "grid": true})).is_err(), "only frames have grids");
    // North arrows: a style and colours.
    s.run("layout.update", &json!({"element": arrow, "style": "compass", "fill": "#AA0000"})).unwrap();
    assert!(matches!(
        find(&s, "northArrow").kind,
        ElementKind::NorthArrow { style: ArrowStyle::Compass, fill, outline, .. } if fill == Rgba::rgb(0xAA, 0, 0) && outline == Rgba::rgb(0x22, 0x22, 0x22)
    ));
    assert!(s.run("layout.update", &json!({"element": arrow, "style": "sundial"})).is_err());
    assert!(s.run("layout.update", &json!({"element": arrow, "outline": "red"})).is_err());
    assert!(matches!(find(&s, "northArrow").kind, ElementKind::NorthArrow { style: ArrowStyle::Compass, .. }));
    let star = s.run("layout.addElement", &json!({"kind": "northArrow", "style": "STAR"})).unwrap()["element"].as_u64().unwrap() as u32;
    assert!(matches!(s.project.layouts[0].element(star).unwrap().kind, ElementKind::NorthArrow { style: ArrowStyle::Star, .. }));
    // Scale bars: units, divisions and a style; divisions are clamped.
    let bar = find(&s, "scaleBar").id;
    s.run("layout.update", &json!({"element": bar, "units": "mi", "divisions": 99, "style": "stepped"})).unwrap();
    assert!(matches!(
        find(&s, "scaleBar").kind,
        ElementKind::ScaleBar { units: ScaleUnits::Miles, divisions: 10, style: ScaleBarStyle::Stepped, .. }
    ));
    s.run("layout.update", &json!({"element": bar, "divisions": "2"})).unwrap();
    assert!(matches!(find(&s, "scaleBar").kind, ElementKind::ScaleBar { units: ScaleUnits::Miles, divisions: 2, .. }));
    // Its colours: the lines and labels, and the alternating bar's light divisions; one given
    // leaves the other as it was.
    assert!(matches!(
        find(&s, "scaleBar").kind,
        ElementKind::ScaleBar { color, fill, .. } if color == Rgba::rgb(0x22, 0x22, 0x22) && fill == Rgba::rgb(0xFF, 0xFF, 0xFF)
    ));
    s.run("layout.update", &json!({"element": bar, "color": "#1F4E79"})).unwrap();
    s.run("layout.update", &json!({"element": bar, "fill": "#00000080"})).unwrap();
    assert!(matches!(find(&s, "scaleBar").kind, ElementKind::ScaleBar { fill, .. } if fill == Rgba::new(0, 0, 0, 0x80)));
    s.run("layout.update", &json!({"element": bar, "fill": "#FDE68A"})).unwrap();
    assert!(matches!(
        find(&s, "scaleBar").kind,
        ElementKind::ScaleBar { color, fill, divisions: 2, .. }
            if color == Rgba::rgb(0x1F, 0x4E, 0x79) && fill == Rgba::rgb(0xFD, 0xE6, 0x8A)
    ));
    let bad = [
        json!({"units": "parsecs"}),
        json!({"divisions": "many"}),
        json!({"style": "zigzag"}),
        json!({"color": "red"}),
        json!({"fill": "#12"}),
        json!({"fill": 5}),
        json!({"color": [255, 0, 0]}),
    ];
    for bad in bad {
        let mut p = bad.clone();
        p["element"] = json!(bar);
        assert!(s.run("layout.update", &p).is_err(), "{bad}");
    }
    // A text's colour is refused as anything but text, when updated as when added; null keeps it.
    let text = s.run("layout.addElement", &json!({"kind": "text", "text": "T", "color": "#1F4E79"})).unwrap();
    let text = text["element"].as_u64().unwrap() as u32;
    let text_color = |s: &Session| match &s.project.layouts[0].element(text).unwrap().kind {
        ElementKind::Text { color, .. } => *color,
        _ => panic!("a text"),
    };
    for bad in [json!(5), json!([255, 0, 0]), json!(true)] {
        assert!(s.run("layout.addElement", &json!({"kind": "text", "text": "U", "color": bad})).is_err(), "{bad}");
        assert!(s.run("layout.update", &json!({"element": text, "color": bad})).is_err(), "{bad}");
    }
    s.run("layout.update", &json!({"element": text, "color": null, "text": "V"})).unwrap();
    assert_eq!(text_color(&s), Rgba::rgb(0x1F, 0x4E, 0x79));
    s.run("layout.update", &json!({"element": text, "color": "#B91C1C"})).unwrap();
    assert_eq!(text_color(&s), Rgba::rgb(0xB9, 0x1C, 0x1C));
    let added = s.run("layout.addElement", &json!({"kind": "scaleBar", "units": "feet", "style": "line", "color": "#B91C1C"})).unwrap();
    let added = added["element"].as_u64().unwrap() as u32;
    assert!(matches!(
        s.project.layouts[0].element(added).unwrap().kind,
        ElementKind::ScaleBar { units: ScaleUnits::Feet, divisions: 4, style: ScaleBarStyle::Line, color, fill, .. }
            if color == Rgba::rgb(0xB9, 0x1C, 0x1C) && fill == Rgba::rgb(0xFF, 0xFF, 0xFF)
    ));
    // The page draws with them all, and they survive a save.
    let out = std::env::temp_dir().join(format!("rustgis-surrounds-{}.png", std::process::id()));
    s.run("layout.export", &json!({"path": out.to_string_lossy()})).unwrap();
    let _ = std::fs::remove_file(&out);
    let text = serde_json::to_string(&s.project.layouts[0]).unwrap();
    let back: rustgis_map::layout::Layout = serde_json::from_str(&text).unwrap();
    assert_eq!(back, s.project.layouts[0]);
}

/// A layout element refuses a colour, fill or outline its kind doesn't draw, before anything
/// changes: added and edited through commands, with the layouts unchanged after a refusal.
#[test]
fn layout_colours_are_refused_for_elements_without_them() {
    use rustgis_map::Rgba;
    use rustgis_map::layout::ElementKind;
    let mut s = world();
    s.run("layout.new", &json!({"page": "a4", "orientation": "landscape", "template": "map"})).unwrap();
    let layouts = |s: &Session| serde_json::to_string(&s.project.layouts).unwrap();
    let find = |s: &Session, code: &str| s.project.layouts[0].elements.iter().find(|e| e.kind.code() == code).unwrap().id;
    let frame = find(&s, "mapFrame");
    let red = "#B91C1C";
    // Added: a kind without the colour is refused, nothing added; with it, it is applied.
    let refused = [
        ("legend", "color", "only text, lines"),
        ("table", "color", "only text, lines"),
        ("colorbar", "color", "only text, lines"),
        ("northArrow", "color", "only text, lines"),
        ("legend", "fill", "take a fill"),
        ("table", "fill", "take a fill"),
        ("text", "fill", "take a fill"),
        ("line", "fill", "take a fill"),
        ("grid", "fill", "take a fill"),
        ("legend", "outline", "take an outline"),
        ("scaleBar", "outline", "take an outline"),
        ("text", "outline", "take an outline"),
        ("line", "outline", "take an outline"),
        ("extentIndicator", "outline", "take an outline"),
    ];
    for (kind, key, said) in refused {
        let before = layouts(&s);
        let e = s.run("layout.addElement", &json!({"kind": kind, key: red})).unwrap_err();
        assert!(e.contains(said) && layouts(&s) == before, "{kind} {key}: {e}");
        // null is not given.
        let mut p = json!({"kind": kind});
        p[key] = Value::Null;
        let after = s.run("layout.addElement", &p);
        assert!(after.as_ref().err().is_none_or(|e| !e.contains("take a")), "{kind} {key} null: {after:?}");
    }
    let before = layouts(&s);
    let e = s.run("layout.addElement", &json!({"kind": "picture", "color": red})).unwrap_err();
    assert!(e.contains("take a color") && layouts(&s) == before, "{e}");
    for (kind, key) in [
        ("text", "color"),
        ("dynamicText", "color"),
        ("line", "color"),
        ("arrow", "color"),
        ("rectangle", "color"),
        ("ellipse", "color"),
        ("circle", "color"),
        ("grid", "color"),
        ("scaleBar", "color"),
        ("scaleBar", "fill"),
        ("northArrow", "fill"),
        ("northArrow", "outline"),
        ("rectangle", "fill"),
        ("rectangle", "outline"),
        ("ellipse", "fill"),
        ("circle", "outline"),
    ] {
        s.run("layout.addElement", &json!({"kind": kind, key: red})).unwrap_or_else(|e| panic!("{kind} {key}: {e}"));
    }
    // An extent indicator's colour is its frame's: the template has one map frame, so add another.
    let inset = s.run("layout.addFrame", &json!({"x": 150, "y": 150, "w": 40, "h": 40})).unwrap()["element"].as_u64().unwrap();
    s.run("layout.addElement", &json!({"kind": "extentIndicator", "frame": inset, "of": frame, "color": red})).unwrap();
    let Some(ElementKind::MapFrame { extent_of, extent_color, .. }) = s.project.layouts[0].element(inset as u32).map(|e| &e.kind) else {
        panic!("the inset is a map frame")
    };
    assert_eq!((*extent_of, extent_color.hex()), (Some(frame), red.to_string()));
    // A rectangle's outline is its "outline", else its "color".
    let r =
        s.run("layout.addElement", &json!({"kind": "rectangle", "outline": "#112233", "color": red})).unwrap()["element"].as_u64().unwrap();
    let outline = |s: &Session, id: u64| match &s.project.layouts[0].element(id as u32).unwrap().kind {
        ElementKind::Rectangle { outline, .. } | ElementKind::Ellipse { outline, .. } => *outline,
        k => panic!("{k:?}"),
    };
    assert_eq!(outline(&s, r), Rgba::rgb(0x11, 0x22, 0x33));
    // Updated: the same, the element unchanged when refused.
    let legend = s.run("layout.addElement", &json!({"kind": "legend"})).unwrap()["element"].as_u64().unwrap();
    let scale = find(&s, "scaleBar");
    let table = s.run("layout.addElement", &json!({"kind": "table"})).unwrap()["element"].as_u64().unwrap();
    for (el, key, said) in [
        (legend, "color", "take a color"),
        (u64::from(frame), "color", "take a color"),
        (table, "color", "take a color"),
        (legend, "fill", "take a fill"),
        (table, "fill", "take a fill"),
        (legend, "outline", "take an outline"),
        (u64::from(frame), "outline", "take an outline"),
    ] {
        let before = layouts(&s);
        let e = s.run("layout.update", &json!({"element": el, key: red, "name": "Renamed"})).unwrap_err();
        assert!(e.contains(said) && layouts(&s) == before, "{el} {key}: {e}");
        s.run("layout.update", &json!({"element": el, key: null})).unwrap();
    }
    let arrow = find(&s, "northArrow");
    let e = s.run("layout.update", &json!({"element": arrow, "color": red})).unwrap_err();
    assert!(e.contains("take a color"), "{e}");
    let scale = u64::from(scale);
    for (el, key) in [
        (u64::from(arrow), "fill"),
        (u64::from(arrow), "outline"),
        (r, "fill"),
        (r, "outline"),
        (r, "color"),
        (scale, "color"),
        (scale, "fill"),
    ] {
        s.run("layout.update", &json!({"element": el, key: red})).unwrap_or_else(|e| panic!("{el} {key}: {e}"));
    }
    let text = find(&s, "text");
    s.run("layout.update", &json!({"element": text, "color": red})).unwrap();
    let ElementKind::Text { color, .. } = &s.project.layouts[0].element(text).unwrap().kind else { panic!() };
    assert_eq!(*color, Rgba::rgb(0xB9, 0x1C, 0x1C));
    let e = s.run("layout.update", &json!({"element": text, "fill": red})).unwrap_err();
    assert!(e.contains("take a fill"), "{e}");
}

/// A colorbar shows a raster's colour scale on a layout (#326): added and edited through
/// commands, checked against the frame's map, and saved with the layout.
#[test]
fn layout_colorbars_follow_a_raster() {
    use rustgis_map::layout::{ElementKind, Orientation, TickSide};
    let mut s = world();
    s.run("layout.new", &json!({"page": "a4", "orientation": "landscape", "template": "map"})).unwrap();
    let kind = |s: &Session, id: u32| s.project.layouts[0].element(id).unwrap().kind.clone();
    // No raster yet: it follows the top visible one once there is one.
    let id = s.run("layout.addElement", &json!({"kind": "colorbar"})).unwrap()["element"].as_u64().unwrap() as u32;
    assert!(matches!(kind(&s, id), ElementKind::Colorbar { layer: None, ticks: 5, reverse: false, .. }), "{:?}", kind(&s, id));
    assert!(s.run("layout.addElement", &json!({"kind": "colorbar", "layer": "Countries"})).is_err(), "a feature layer has no colour scale");
    s.run("layer.addDataBytes", &json!({"fileName": "dem.tif", "data": dem_b64()})).unwrap();
    let dem = s.map().layers.iter().find(|l| l.is_raster()).unwrap().name.clone();
    let named = s
        .run("layout.addElement", &json!({"kind": "colorbar", "layer": dem.to_uppercase(), "orientation": "vertical", "ticks": 1e9, "tickSide": "left", "reverse": true}))
        .unwrap()["element"]
        .as_u64()
        .unwrap() as u32;
    // "" follows the top raster, as in layout.update.
    let blank = s.run("layout.addElement", &json!({"kind": "colorbar", "layer": " "})).unwrap()["element"].as_u64().unwrap() as u32;
    assert!(matches!(kind(&s, blank), ElementKind::Colorbar { layer: None, .. }), "{:?}", kind(&s, blank));
    let e = s.project.layouts[0].element(named).unwrap().clone();
    assert!(e.h > e.w, "a vertical bar is tall: {} × {}", e.w, e.h);
    match &e.kind {
        ElementKind::Colorbar { layer, title, orientation, ticks, tick_side, reverse, .. } => {
            assert_eq!(layer.as_deref(), Some(dem.as_str()), "the layer's own name");
            assert_eq!(title, &dem, "titled after the layer");
            assert_eq!(
                (*orientation, *ticks, *tick_side, *reverse),
                (Orientation::Vertical, rustgis_map::layout::MAX_COLORBAR_TICKS, TickSide::Start, true)
            );
        }
        k => panic!("{k:?}"),
    }
    // Edited: a bad value changes nothing.
    for bad in [json!({"orientation": "diagonal"}), json!({"tickSide": "inside"}), json!({"layer": "Countries"}), json!({"layer": "nope"})]
    {
        let mut p = bad.clone();
        p["element"] = json!(named);
        assert!(s.run("layout.update", &p).is_err(), "{bad}");
    }
    assert_eq!(s.project.layouts[0].element(named).unwrap(), &e);
    // Turned horizontal, it swaps its length and thickness; "" follows the top raster again.
    s.run(
        "layout.update",
        &json!({"element": named, "orientation": "horizontal", "title": "Elevation (m)", "ticks": 3, "tickSide": "below", "layer": ""}),
    )
    .unwrap();
    let turned = s.project.layouts[0].element(named).unwrap().clone();
    assert_eq!((turned.w, turned.h), (e.h, e.w));
    assert!(
        matches!(
            &turned.kind,
            ElementKind::Colorbar { layer: None, orientation: Orientation::Horizontal, ticks: 3, tick_side: TickSide::End, reverse: true, title, .. } if title == "Elevation (m)"
        ),
        "{:?}",
        turned.kind
    );
    // It draws the raster's ramp: the export differs from the page without it.
    let png = |s: &mut Session| crate::cmd::layout::layout_bytes(s, 0, false, 72.0, false).unwrap();
    let with = png(&mut s);
    s.run("layout.update", &json!({"element": named, "visible": false})).unwrap();
    s.run("layout.update", &json!({"element": id, "visible": false})).unwrap();
    assert_ne!(with, png(&mut s));
    // Saved and read back, and layouts from before colorbars had their defaults read as before.
    let text = serde_json::to_string(&s.project.layouts[0]).unwrap();
    let back: rustgis_map::layout::Layout = serde_json::from_str(&text).unwrap();
    assert_eq!(back, s.project.layouts[0]);
    let old: ElementKind = serde_json::from_str(r#"{"Colorbar":{"frame":1}}"#).unwrap();
    assert!(matches!(
        old,
        ElementKind::Colorbar { layer: None, ticks: 5, orientation: Orientation::Horizontal, tick_side: TickSide::End, reverse: false, .. }
    ));
    // Undone with the rest of the layout's edits.
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.project.layouts[0].element(id).map(|e| e.visible), Some(true), "undo brings it back");
}

/// `layout.publication` (#682): every profile builds a layout that fits its page, the map frame
/// at a round scale that still fits the extent, the footer boxed in two columns below the map
/// with long lines wrapped, the tokens filled from the map; a figure leaves its title to the
/// caption.
#[test]
fn publication_layouts_fit_their_pages() {
    use rustgis_map::layout::ElementKind;
    let dir = std::env::temp_dir().join(format!("rustgis-publication-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = world();
    let piaui = json!([-46.8, -11.6, -38.5, -2.2]);
    let long =
        "NDVI: MOD13Q1 v6.1 (NASA LP DAAC), 16-day composites at 250 m, read through the Brazil Data Cube (INPE) and averaged to 1 km";
    let profiles = [
        "a4-portrait",
        "a4-landscape",
        "a3-portrait",
        "a3-landscape",
        "a2-portrait",
        "a2-landscape",
        "figure-1col",
        "figure-1.5col",
        "figure-2col",
        "thesis-full",
        "thesis-half",
    ];
    for profile in profiles {
        let r = s
            .run(
                "layout.publication",
                &json!({"profile": profile, "extent": piaui, "name": profile, "title": "PIAUÍ", "subtitle": "Greening and browning of vegetation: NDVI trend, 2001–2025",
                        "sources": [long, "Boundaries: IBGE 2022"], "note": "Only cells with a significant trend (p < 0.05) are coloured."}),
            )
            .unwrap_or_else(|e| panic!("{profile}: {e}"));
        let l = s.project.layouts.last().unwrap();
        assert_eq!(r["name"], profile);
        let sheet = profile.starts_with('a');
        for e in &l.elements {
            assert!(
                e.x >= -1e-9 && e.y >= -1e-9 && e.x + e.w <= l.width + 1e-6 && e.y + e.h <= l.height + 1e-6,
                "{profile}: {} at ({}, {}, {}, {}) is off the {} × {} page",
                e.name,
                e.x,
                e.y,
                e.w,
                e.h,
                l.width,
                l.height
            );
        }
        let frame = l.elements.iter().find(|e| e.kind.code() == "mapFrame").unwrap();
        let ElementKind::MapFrame { scale, grid: Some(grid), .. } = &frame.kind else { panic!("{profile}: no grid") };
        // The legend stops short of the scale bar's box, whichever corners they take, however
        // narrow the frame.
        let named = |n: &str| l.elements.iter().find(|e| e.name == n).unwrap();
        let (a, b) = (named("Legend Box"), named("Scale Box"));
        let apart = a.x + a.w <= b.x || b.x + b.w <= a.x || a.y + a.h <= b.y || b.y + b.h <= a.y;
        assert!(apart, "{profile}: the legend reaches the scale bar");
        // A round scale, two significant figures, at which the extent still fits.
        let unit = 10f64.powf(scale.log10().floor() - 1.0);
        assert!(((scale / unit) - (scale / unit).round()).abs() < 1e-6, "{profile}: 1:{scale}");
        let extent = rustgis_geom::Extent::new(-46.8, -11.6, -38.5, -2.2);
        // Fitted within the graticule's label strips (9 mm beside the frame's sides, 6 mm along its
        // top and bottom), so the labels cover none of the extent.
        let (_, fits) = rustgis_map::layout::fit_scale(s.map(), &extent, frame.w - 18.0, frame.h - 12.0).unwrap();
        assert!(fits <= *scale && *scale < fits * 1.1, "{profile}: 1:{scale} for 1:{fits}");
        assert_eq!(grid.step, 2.0, "{profile}: Piauí's 9.4° take a 2° graticule");
        let text = |name: &str| {
            l.elements.iter().find(|e| e.name == name).map(|e| match &e.kind {
                ElementKind::Text { text, .. } => text.clone(),
                _ => panic!("{name} isn't text"),
            })
        };
        if sheet {
            assert_eq!(text("Title").as_deref(), Some("PIAUÍ"), "{profile}");
            // The footer under the map, the long source wrapped within its box.
            let foot = l.elements.iter().find(|e| e.name == "Sources Box").unwrap();
            assert!(foot.y >= frame.y + frame.h, "{profile}: the footer is under the map");
            let sources = l.elements.iter().find(|e| e.name == "Sources").unwrap();
            assert!(sources.x + sources.w <= foot.x + foot.w + 1e-6);
            let lines = text("Sources").unwrap();
            assert!(lines.lines().count() >= 3, "{profile}: {lines}");
            for line in lines.lines() {
                assert!(
                    crate::render::report::width_mm(line, 7.0 * l.width.min(l.height) as f32 / 210.0, false) <= sources.w + 1e-6,
                    "{profile}: {line}"
                );
            }
            // The tokens filled from the map: Web Mercator over WGS 84, the 2° graticule.
            let reference = text("Reference").unwrap();
            assert!(reference.contains("Web Mercator") && reference.contains("WGS 84") && reference.contains("2°"), "{reference}");
            assert!(text("Author").unwrap().contains("{date}"), "the date stays a token the layout fills");
            // Nothing said but, over the sample world's land, the surrounds sharing its one corner
            // of sea (placement has its own test).
            let said: Vec<&str> = r["warnings"].as_array().unwrap().iter().filter_map(|w| w.as_str()).collect();
            assert!(said.len() <= 1 && said.iter().all(|w| w.contains("on what the map shows")), "{profile}: {r}");
        } else {
            assert!(text("Title").is_none() && text("Sources").is_none(), "{profile}: a figure's texts are its caption's");
            assert!(r["warnings"].as_array().unwrap().iter().any(|w| w.as_str().unwrap().contains("caption")), "{r}");
            assert!(text("Reference").unwrap().contains("Datum: WGS 84"), "{profile}");
            assert_eq!(l.width, r["page"][0].as_f64().unwrap());
        }
        let png = dir.join(format!("{profile}.png"));
        s.run("layout.export", &json!({"path": png.display().to_string(), "dpi": 72})).unwrap();
        assert!(std::fs::metadata(&png).unwrap().len() > 1000, "{profile}");
    }
    assert_eq!(s.project.layouts.len(), profiles.len(), "a layout each, the earlier ones untouched");
    // A long title wraps within the frame, and pushes the map down; the result names every
    // element for layout.update.
    let r = s.run("layout.publication", &json!({"extent": piaui, "title": long})).unwrap();
    let l = s.project.layouts.last().unwrap();
    let title = l.elements.iter().find(|e| e.name == "Title").unwrap();
    let ElementKind::Text { text, size, .. } = &title.kind else { panic!() };
    assert!(text.lines().count() >= 2, "{text}");
    for line in text.lines() {
        assert!(crate::render::report::width_mm(line, *size as f32, true) <= title.w, "{line}: measured bold, as drawn");
    }
    let frame = l.elements.iter().find(|e| e.kind.code() == "mapFrame").unwrap();
    assert!(frame.y >= title.y + title.h);
    let listed = r["elements"].as_array().unwrap();
    assert_eq!(listed.len(), l.elements.len());
    assert!(listed.iter().any(|e| e["name"] == "Map Frame" && e["element"] == frame.id && e["kind"] == "mapFrame"), "{r}");
    s.project.layouts.pop();
    // Undone as one command: the layout goes, and the map is as it was (its layers, view and
    // projection), the legend's sync of streamed layers included.
    let (layouts, map) = (s.project.layouts.len(), s.map().clone());
    s.run("layout.publication", &json!({"extent": piaui})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.project.layouts.len(), layouts);
    let ids = |m: &rustgis_map::Map| m.layers.iter().map(|l| (l.id, l.name.clone(), l.visible)).collect::<Vec<_>>();
    assert_eq!(ids(s.map()), ids(&map));
    assert_eq!((s.map().projection.code(), s.map().camera.center), (map.projection.code(), map.camera.center));
    // A figure says it left out an author and headings given to it, as it does a title.
    let r =
        s.run("layout.publication", &json!({"profile": "figure-1col", "extent": piaui, "author": "Me", "headings": ["A", "B"]})).unwrap();
    let said = r["warnings"].to_string();
    assert!(said.contains("author goes") && said.contains("headings goes"), "{said}");
    s.project.layouts.pop();
    let r = s.run("layout.publication", &json!({"profile": "figure-1col", "extent": piaui, "author": ""})).unwrap();
    assert!(!r["warnings"].to_string().contains("author"), "an empty author asks for none: {r}");
    s.project.layouts.pop();
    // An empty author leaves the authorship out.
    for none in [json!(""), json!([]), json!(["  "])] {
        s.run("layout.publication", &json!({"extent": piaui, "author": none})).unwrap();
        assert!(s.project.layouts.last().unwrap().elements.iter().all(|e| e.name != "Author"), "{none}");
        s.project.layouts.pop();
    }
    // With no sources, the reference alone takes the footer's width; no empty box beside it.
    s.run("layout.publication", &json!({"extent": piaui})).unwrap();
    let l = s.project.layouts.last().unwrap();
    let frame = l.elements.iter().find(|e| e.kind.code() == "mapFrame").unwrap();
    assert!(l.elements.iter().all(|e| !e.name.starts_with("Sources")));
    let reference = l.elements.iter().find(|e| e.name == "Reference Box").unwrap();
    assert!((reference.x - frame.x).abs() < 1e-9 && (reference.w - frame.w).abs() < 1e-9, "{} of {}", reference.w, frame.w);
    s.project.layouts.pop();
    // Headings rename what the columns read, filled and wrapped; their elements keep their names.
    let r = s
        .run(
            "layout.publication",
            &json!({"extent": piaui, "sources": "IBGE", "headings": ["Fontes dos dados, {date}", "Referência cartográfica na projeção {projection}, a mais longa que se possa imaginar"]}),
        )
        .unwrap();
    let l = s.project.layouts.last().unwrap();
    let heading = l.elements.iter().find(|e| e.name == "Reference Heading").unwrap();
    let ElementKind::Text { text, .. } = &heading.kind else { panic!() };
    // Where the wrap breaks depends on the font found, so the words are read across the lines.
    assert!(text.replace('\n', " ").contains("WEB MERCATOR") && !text.contains('{') && text.lines().count() >= 2, "{text}");
    // A live token in a heading keeps its case, so the layout still fills it when it draws.
    let sources = l.elements.iter().find(|e| e.name == "Sources Heading").unwrap();
    let ElementKind::Text { text, .. } = &sources.kind else { panic!() };
    assert_eq!(text, "FONTES DOS DADOS, {date}");
    assert!(l.elements.iter().any(|e| e.name == "Sources Heading") && l.elements.iter().any(|e| e.name == "Reference"), "{r}");
    let body = l.elements.iter().find(|e| e.name == "Reference").unwrap();
    assert!(body.y >= heading.y + heading.h - 1e-9, "the reference starts under its wrapped heading");
    s.project.layouts.pop();
    // A journal figure is as tall as the map's shape asks: Piauí in Web Mercator is taller than wide.
    let one = s.project.layouts.iter().find(|l| l.name == "figure-1col").unwrap();
    assert!(one.width == 90.0 && one.height > 90.0, "{} × {}", one.width, one.height);
    // Graticule steps and round scales.
    use crate::cmd::layout::{capitals, datum_of, grid_step, round_scale, step_text};
    assert_eq!(datum_of("+proj=aea +lat_1=29.5 +datum=NAD83 +units=m").as_deref(), Some("NAD83"));
    assert_eq!(datum_of("+proj=robin +ellps=WGS84").as_deref(), Some("WGS 84"));
    assert_eq!(datum_of("+proj=eqearth +R=6371008.8").as_deref(), Some("a sphere"));
    assert_eq!(datum_of("+proj=moll"), None);
    // A UTM zone's code is named by its zone and datum, not its ellipsoid.
    s.run("map.projection", &json!({"type": "EPSG:31983"})).unwrap();
    s.run("layout.publication", &json!({"extent": [-46, -11, -40, -2.7]})).unwrap();
    let l = s.project.layouts.last().unwrap();
    let ElementKind::Text { text, .. } = &l.elements.iter().find(|e| e.name == "Reference").unwrap().kind else { panic!() };
    assert!(text.contains("Projection: UTM zone 23S") && text.contains("Datum: SIRGAS 2000"), "{text}");
    s.project.layouts.pop();
    // A preset on NAD83 says so, though its name holds no datum.
    s.run("map.projection", &json!({"type": "usaAlbers"})).unwrap();
    s.run("layout.publication", &json!({"extent": [-100, 35, -90, 45]})).unwrap();
    let l = s.project.layouts.last().unwrap();
    let ElementKind::Text { text, .. } = &l.elements.iter().find(|e| e.name == "Reference").unwrap().kind else { panic!() };
    assert!(text.contains("Datum: NAD83"), "{text}");
    s.project.layouts.pop();
    assert_eq!(capitals("Fontes, {date} e {pageName}"), "FONTES, {date} E {pageName}");
    assert_eq!(capitals("Dados {2024 e {só} }"), "DADOS {2024 E {SÓ} }", "a lone or odd brace is text");
    assert_eq!(grid_step(&rustgis_geom::Extent::new(10.0, 45.0, 11.0, 46.0)), 0.25);
    assert_eq!(grid_step(&rustgis_geom::Extent::new(-180.0, -90.0, 180.0, 90.0)), 30.0);
    assert_eq!((step_text(2.0), step_text(0.25), step_text(0.02)), ("2°".to_string(), "15′".to_string(), "1′12″".to_string()));
    assert_eq!(step_text(0.01), "36″");
    assert_eq!((round_scale(1_234_567.0), round_scale(4_500_000.0), round_scale(999.0)), (1_300_000.0, 4_500_000.0, 1_000.0));
    // Refused: an unknown profile, a malformed extent, a footer that leaves the map no room.
    for (p, said) in [
        (json!({"profile": "a5-portrait"}), "unknown profile"),
        (json!({"profile": 5}), "profile is"),
        (json!({"extent": [10, 0, 5, 1]}), "extent is"),
        (json!({"extent": [10, 0, 11], "profile": "a4-portrait"}), "extent is"),
        (json!({"sources": vec![long; 40], "profile": "a4-landscape", "extent": piaui}), "no room"),
        (json!({"reference": vec![long; 50], "profile": "thesis-half", "extent": piaui}), "no room"),
    ] {
        let e = s.run("layout.publication", &p).unwrap_err();
        assert!(e.contains(said), "{p}: {e}");
    }
    let _ = std::fs::remove_dir_all(&dir);
}

/// Each sheet style the New Layout menu offers is one `layout.publication` takes, by its name.
#[test]
fn every_publication_style_in_the_menu_is_taken() {
    let mut s = world();
    for (style, _) in crate::cmd::layout::PUBLICATION_STYLES {
        let r =
            s.run("layout.publication", &json!({"extent": [-46.8, -11.6, -38.5, -2.2], "profile": "a4-portrait", "style": style})).unwrap();
        assert_eq!(r["style"], *style);
    }
}

/// A publication sheet's style (#682): `classic` (the default) as before; `banner` the title and
/// subtitle in a band of the accent colour across the top; `panel` the map at the left and a panel
/// at the right holding the title, the locator, the legend, the sources and the reference;
/// `editorial` the title large in serif and a column at the right with the note, the locator and
/// the legend; `modular` cards with rounded corners; `poster` the page in the accent colour.
///
/// A figure leaves a style to its caption; an unknown style or a bad accent is refused.
#[test]
fn publication_layouts_take_a_style() {
    use rustgis_map::layout::{ElementKind, FontFamily};
    let dir = std::env::temp_dir().join(format!("rustgis-styles-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = world();
    let piaui = json!([-46.8, -11.6, -38.5, -2.2]);
    // On a portrait sheet (the arrangement is what is checked; the orientation chosen for an area
    // has its own check below).
    let texts = json!({"extent": piaui, "profile": "a4-portrait", "title": "PIAUÍ", "subtitle": "Greening and browning of the vegetation, 2001–2025",
        "sources": ["NDVI: MOD13Q1 v6.1", "Boundaries: IBGE"], "note": "Only the cells with a significant trend are coloured.",
        "headings": ["Sources", "Reference", "About this map"]});
    let make = |s: &mut Session, style: &str, extra: Value| {
        let mut p = texts.clone();
        p["style"] = json!(style);
        for (k, v) in extra.as_object().unwrap() {
            p[k] = v.clone();
        }
        let r = s.run("layout.publication", &p).unwrap();
        s.run("layout.export", &json!({"path": dir.join(format!("{style}.png")).display().to_string(), "dpi": 48})).unwrap();
        r
    };
    let inside = |a: &rustgis_map::layout::Element, b: &rustgis_map::layout::Element| {
        a.x >= b.x - 1e-6 && a.y >= b.y - 1e-6 && a.x + a.w <= b.x + b.w + 1e-6 && a.y + a.h <= b.y + b.h + 1e-6
    };
    // Classic, the default: no band, no panel.
    let r = s.run("layout.publication", &texts).unwrap();
    assert_eq!(r["style"], "classic");
    let l = s.project.layouts.last().unwrap();
    assert!(l.elements.iter().all(|e| !matches!(e.name.as_str(), "Banner" | "Panel Box" | "Column Rule")));
    // Banner: a band of the accent colour at the top, the title on it in white, the map under it.
    let r = make(&mut s, "banner", json!({"accent": "#123456"}));
    let l = s.project.layouts.last().unwrap();
    let named = |n: &str| l.elements.iter().find(|e| e.name == n).unwrap_or_else(|| panic!("no {n}: {r}"));
    let (band, title, frame) = (named("Banner"), named("Title"), named("Map Frame"));
    let ElementKind::Rectangle { fill, .. } = &band.kind else { panic!() };
    assert_eq!(*fill, rustgis_map::Rgba::rgb(0x12, 0x34, 0x56));
    let ElementKind::Text { color, .. } = &title.kind else { panic!() };
    assert_eq!(*color, rustgis_map::Rgba::rgb(0xFF, 0xFF, 0xFF));
    assert!(inside(title, band) && inside(named("Subtitle"), band) && frame.y >= band.y + band.h, "{r}");
    // Panel: the map at the left, the panel at the right holding the texts, the locator and the
    // legend; no boxed footer.
    // An area as tall as the map's narrow column (its frame filled, not cut): everything in the
    // panel.
    let tall = json!([-46.0, -34.0, -40.0, 4.0]);
    let r = make(&mut s, "panel", json!({"extent": tall}));
    let l = s.project.layouts.last().unwrap();
    let named = |n: &str| l.elements.iter().find(|e| e.name == n).unwrap_or_else(|| panic!("no {n}: {r}"));
    let (panel, frame) = (named("Panel Box"), named("Map Frame"));
    assert!(frame.x + frame.w <= panel.x, "the map left of the panel: {r}");
    for n in ["Title", "Subtitle", "Locator", "Legend Box", "Sources Heading", "Sources", "Reference"] {
        assert!(inside(named(n), panel), "{n} in the panel: {r}");
    }
    assert!(l.elements.iter().all(|e| e.name != "Sources Box"));
    // The legend under the locator, apart from it.
    assert!(named("Legend Box").y >= named("Locator").y + named("Locator").h, "{r}");
    let full = frame.h;
    // A less tall area (Piauí) on that narrow column: the frame cut to its shape (a seventh more of its
    // surroundings), the sources and reference boxed under the map, and all of it in the middle of
    // the page; the neatline still round the whole sheet.
    let r = make(&mut s, "panel", json!({}));
    let l = s.project.layouts.last().unwrap();
    let named = |n: &str| l.elements.iter().find(|e| e.name == n).unwrap_or_else(|| panic!("no {n}: {r}"));
    let (panel, frame, sources) = (named("Panel Box"), named("Map Frame"), named("Sources Box"));
    assert!(frame.h < 0.9 * full && (panel.h - frame.h).abs() < 1e-6, "{} of {full}: {r}", frame.h);
    assert!(sources.y >= frame.y + frame.h && inside(named("Legend Box"), panel), "{r}");
    let (top, bottom) = (frame.y, l.height - named("Author").y - named("Author").h);
    assert!((top - bottom).abs() < 1.0, "the content in the middle: {top} above, {bottom} below");
    let neat = named("Frame");
    assert!((neat.y + neat.h - (l.height - neat.y)).abs() < 1e-6, "the neatline round the sheet");
    // In landscape too, every style on any sheet: the panel at the right of a wide map.
    for style in ["banner", "panel", "editorial"] {
        let r = make(&mut s, style, json!({"profile": "a4-landscape"}));
        let l = s.project.layouts.last().unwrap();
        let frame = l.elements.iter().find(|e| e.name == "Map Frame").unwrap();
        assert!(frame.w > frame.h, "{style}: a wide map on a landscape sheet: {r}");
        if style != "banner" {
            assert!(
                l.elements.iter().filter(|e| e.name == "Locator" || e.name == "Legend Box").all(|e| e.x >= frame.x + frame.w),
                "{style}: {r}"
            );
            // The locator no larger than on a portrait sheet, though the column is wider.
            let locator = l.elements.iter().find(|e| e.name == "Locator").unwrap();
            assert!(locator.w <= 52.0 + 1e-6, "{style}: {}", locator.w);
        }
    }
    // No locator: the legend takes its place at the top of the panel's free room.
    let r = make(&mut s, "panel", json!({"locator": "none"}));
    let l = s.project.layouts.last().unwrap();
    assert!(l.elements.iter().all(|e| e.name != "Locator") && l.elements.iter().any(|e| e.name == "Legend Box"), "{r}");
    // Editorial: the title in serif in the accent colour, a column at the right with its heading,
    // the note, the locator and the legend.
    let r = make(&mut s, "editorial", json!({}));
    let l = s.project.layouts.last().unwrap();
    let named = |n: &str| l.elements.iter().find(|e| e.name == n).unwrap_or_else(|| panic!("no {n}: {r}"));
    let ElementKind::Text { font, color, .. } = &named("Title").kind else { panic!() };
    assert_eq!((*font, *color), (FontFamily::Serif, rustgis_map::Rgba::rgb(0x1F, 0x2D, 0x4D)));
    // Drawn in the sans where no serif is installed, said.
    let said = r["warnings"].to_string().contains("the editorial title and subtitle: no serif font");
    assert_eq!(said, !crate::render::fonts::serif_available(), "{r}");
    let frame = named("Map Frame");
    for n in ["Column Heading", "Note", "Locator", "Legend Box"] {
        assert!(named(n).x >= frame.x + frame.w, "{n} right of the map: {r}");
    }
    // Modular: the map in a card drawn under it, the locator and the legend each in a card at the
    // right, the footer's boxes with rounded corners and no neatline.
    let radius = |e: &rustgis_map::layout::Element| match &e.kind {
        ElementKind::Rectangle { radius, .. } => *radius,
        _ => 0.0,
    };
    let r = make(&mut s, "modular", json!({}));
    let l = s.project.layouts.last().unwrap();
    let at = |n: &str| l.elements.iter().position(|e| e.name == n).unwrap_or_else(|| panic!("no {n}: {r}"));
    let named = |n: &str| &l.elements[at(n)];
    assert!(at("Map Card") < at("Map Frame") && inside(named("Map Frame"), named("Map Card")), "{r}");
    let frame = named("Map Frame");
    for n in ["Locator Card", "Locator", "Legend Box"] {
        assert!(named(n).x >= frame.x + frame.w, "{n} right of the map: {r}");
    }
    assert!(inside(named("Locator"), named("Locator Card")) && named("Legend Box").y >= named("Locator Card").y + named("Locator Card").h);
    assert!((named("Legend Box").w - named("Locator Card").w).abs() < 1e-6, "the two cards as wide: {r}");
    assert!(radius(named("Map Card")) > 0.0 && radius(named("Legend Box")) > 0.0 && radius(named("Sources Box")) > 0.0);
    assert!(l.elements.iter().all(|e| e.name != "Frame"));
    // Poster: the page in the accent colour under everything, the title in white, the map in a
    // light card, the footer in rounded blocks.
    let r = make(&mut s, "poster", json!({}));
    let l = s.project.layouts.last().unwrap();
    let at = |n: &str| l.elements.iter().position(|e| e.name == n).unwrap_or_else(|| panic!("no {n}: {r}"));
    let named = |n: &str| &l.elements[at(n)];
    let back = named("Background");
    assert_eq!((at("Background"), back.w, back.h), (0, l.width, l.height));
    let ElementKind::Rectangle { fill, .. } = &back.kind else { panic!() };
    assert_eq!(*fill, rustgis_map::Rgba::rgb(0x3A, 0x26, 0x18));
    let ElementKind::Text { color, .. } = &named("Title").kind else { panic!() };
    assert_eq!(*color, rustgis_map::Rgba::rgb(0xFF, 0xFF, 0xFF));
    assert!(at("Map Card") < at("Map Frame") && inside(named("Map Frame"), named("Map Card")) && radius(named("Sources Box")) > 0.0);
    assert!(l.elements.iter().all(|e| e.name != "Banner" && e.name != "Frame"));
    // A rectangle's rounded corners by hand: added, changed, kept when its colour changes, saved only
    // when rounded.
    let id = s.run("layout.addElement", &json!({"kind": "rectangle", "x": 10, "y": 10, "w": 40, "h": 20, "radius": 4})).unwrap()["element"]
        .clone();
    let rect = |s: &Session| s.project.layouts.last().unwrap().elements.iter().find(|e| json!(e.id) == id).unwrap().kind.clone();
    assert!(matches!(rect(&s), ElementKind::Rectangle { radius, .. } if radius == 4.0));
    s.run("layout.update", &json!({"element": id, "fill": "#FFFFFF"})).unwrap();
    assert!(matches!(rect(&s), ElementKind::Rectangle { radius, .. } if radius == 4.0));
    s.run("layout.update", &json!({"element": id, "radius": 0})).unwrap();
    assert!(!serde_json::to_string(&rect(&s)).unwrap().contains("radius"), "square corners aren't saved");
    assert!(s.run("layout.update", &json!({"element": id, "radius": -1})).is_err());
    assert!(s.run("layout.addElement", &json!({"kind": "rectangle", "radius": "x"})).is_err());
    // Anything but a rectangle refuses rounded corners, rather than taking them as applied.
    let n = s.project.layouts.last().unwrap().elements.len();
    let e = s.run("layout.addElement", &json!({"kind": "ellipse", "radius": 4})).unwrap_err();
    assert!(e.contains("only a rectangle rounds its corners") && s.project.layouts.last().unwrap().elements.len() == n, "{e}");
    let oval = s.run("layout.addElement", &json!({"kind": "circle"})).unwrap()["element"].clone();
    let e = s.run("layout.update", &json!({"element": oval, "radius": 4, "fill": "#FF0000"})).unwrap_err();
    assert!(e.contains("only a rectangle rounds its corners"), "{e}");
    let fill = |s: &Session| {
        s.project.layouts.last().unwrap().elements.iter().find(|e| json!(e.id) == oval).and_then(|e| match e.kind {
            ElementKind::Ellipse { fill, .. } => Some(fill),
            _ => None,
        })
    };
    assert!(fill(&s).is_some_and(|f| f != rustgis_map::Rgba::rgb(0xFF, 0, 0)), "an ellipse, unchanged");
    // A sheet given its size alone (or none) is turned to the area's shape: portrait for a tall
    // one, landscape for a wide one, the size kept; one given its orientation keeps it.
    let wide = json!([-75.0, -14.0, -35.0, -2.0]);
    for (p, want) in [
        (json!({"extent": piaui}), "a4-portrait"),
        (json!({"extent": wide}), "a4-landscape"),
        (json!({"extent": wide, "profile": "a3"}), "a3-landscape"),
        (json!({"extent": wide, "profile": "a4-portrait"}), "a4-portrait"),
        (json!({"extent": piaui, "profile": "a4-landscape"}), "a4-landscape"),
    ] {
        let r = s.run("layout.publication", &p).unwrap();
        assert_eq!(r["profile"], want, "{p}");
        let l = s.project.layouts.last().unwrap();
        assert_eq!(l.width > l.height, want.ends_with("landscape"), "{p}");
    }
    // A figure leaves the style to its caption; refused: an unknown style, a bad accent, either not
    // given as text, and an unknown profile (its message naming the sizes turned to the area).
    let r = s.run("layout.publication", &json!({"extent": piaui, "profile": "figure-1col", "style": "banner"})).unwrap();
    assert!(r["warnings"].to_string().contains("style \\\"banner\\\""), "{r}");
    let before = s.project.layouts.len();
    for bad in [
        json!({"extent": piaui, "style": "magazine"}),
        json!({"extent": piaui, "style": "banner", "accent": "blue"}),
        json!({"extent": piaui, "style": 3}),
        json!({"extent": piaui, "accent": 7}),
        json!({"extent": piaui, "style": "poster", "accent": "#1F2D4D80"}),
    ] {
        assert!(s.run("layout.publication", &bad).is_err(), "{bad}");
    }
    let e = s.run("layout.publication", &json!({"extent": piaui, "profile": "a5"})).unwrap_err();
    assert!(e.contains("a4, a3 or a2") && e.contains("a4-portrait"), "{e}");
    assert_eq!(s.project.layouts.len(), before);
    let _ = std::fs::remove_dir_all(&dir);
}

/// A publication layout's locator (#682, part 2): on a sheet, by default, a globe (a new map of
/// the vector layers on the globe, its diameter nearly the frame's) in a round frame at the map's
/// top left, the area outlined by the map frame's extent indicator; `"inset"` the surrounding
/// region on the map itself; `"none"`, or a figure by default, none. The legend stops short of it,
/// and undo takes the globe's map away with the layout.
#[test]
fn publication_layouts_locate_their_area() {
    use rustgis_map::layout::{ElementKind, FrameShape};
    let dir = std::env::temp_dir().join(format!("rustgis-locator-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = world();
    let piaui = json!([-46.8, -11.6, -38.5, -2.2]);
    let maps = s.project.maps.len();
    let main = s.map().name.clone();
    let r = s.run("layout.publication", &json!({"extent": piaui, "title": "PIAUÍ"})).unwrap();
    let globe = r["locator"].as_str().unwrap().to_string();
    assert_eq!((s.project.maps.len(), globe.as_str()), (maps + 1, format!("{main} Locator").as_str()));
    let m = s.project.maps.iter().find(|m| m.name == globe).unwrap();
    assert!(m.projection.is_globe() && m.layers.iter().all(|l| !l.is_raster()));
    assert_eq!(s.map().name, main, "the map in view stays the active one");
    let l = s.project.layouts.last().unwrap();
    let named = |n: &str| l.elements.iter().find(|e| e.name == n).unwrap_or_else(|| panic!("no {n}"));
    let (frame, locator) = (named("Map Frame"), named("Locator"));
    let ElementKind::MapFrame { map, shape, extent_of, scale, .. } = &locator.kind else { panic!() };
    assert_eq!((map.as_str(), shape, *extent_of), (globe.as_str(), &FrameShape::Circle, Some(frame.id)));
    // Inside the map frame (in a corner of its own: see publication_surrounds_keep_off_the_data),
    // clear of the legend.
    assert!(
        locator.x > frame.x
            && locator.y > frame.y
            && locator.x + locator.w < frame.x + frame.w
            && locator.y + locator.h < frame.y + frame.h
    );
    let legend = named("Legend Box");
    let apart = legend.x + legend.w <= locator.x
        || locator.x + locator.w <= legend.x
        || legend.y + legend.h <= locator.y
        || locator.y + locator.h <= legend.y;
    assert!(apart, "the legend stops short of the locator");
    // The globe nearly fills its frame: drawn, its ink spans most of the frame's width.
    assert!(*scale > 1e7, "1:{scale}");
    let png = dir.join("globe.png");
    s.run("layout.export", &json!({"path": png.display().to_string(), "dpi": 96})).unwrap();
    // The surrounding region on the map itself: no new map, a coarser scale.
    let r = s.run("layout.publication", &json!({"extent": piaui, "locator": "inset"})).unwrap();
    assert_eq!((s.project.maps.len(), r["locator"].as_str()), (maps + 1, Some(main.as_str())));
    let l = s.project.layouts.last().unwrap();
    let main_scale = r["scale"].as_f64().unwrap();
    let inset = l.elements.iter().find(|e| e.name == "Locator").unwrap();
    let ElementKind::MapFrame { map, shape, scale, extent_of, .. } = &inset.kind else { panic!() };
    assert!(map == &main && shape == &FrameShape::Rectangle && *scale > main_scale * 3.0 && extent_of.is_some(), "1:{scale}");
    s.run("layout.export", &json!({"path": dir.join("inset.png").display().to_string(), "dpi": 96})).unwrap();
    // None asked, or a figure by default: no locator, and the legend stays, the narrowest
    // figure (90 mm) included: only a locator takes its room.
    for p in [json!({"extent": piaui, "locator": "none"}), json!({"extent": piaui, "profile": "figure-1col"})] {
        let r = s.run("layout.publication", &p).unwrap();
        let l = s.project.layouts.last().unwrap();
        assert!(r["locator"].is_null() && l.elements.iter().all(|e| e.name != "Locator"), "{p}");
        assert!(l.elements.iter().any(|e| e.name == "Legend Box"), "{p}: {r}");
    }
    let e = s.run("layout.publication", &json!({"extent": piaui, "locator": "moon"})).unwrap_err();
    assert!(e.contains("locator is"), "{e}");
    // Undone, a globe locator's map goes with its layout.
    let before = s.project.maps.len();
    s.run("layout.publication", &json!({"extent": piaui})).unwrap();
    assert_eq!(s.project.maps.len(), before + 1);
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.project.maps.len(), before);
    // A sheet made again after its layout was deleted replaces the locator no layout shows any
    // more, rather than leaving it beside a new one; one still shown is kept.
    let r = s.run("layout.publication", &json!({"extent": piaui, "name": "Again"})).unwrap();
    let first = r["locator"].as_str().unwrap().to_string();
    s.run("layout.remove", &json!({"name": "Again"})).unwrap();
    // Made anew, not kept: a polygon layer hidden meanwhile is gone from the reused map.
    let (gone, gone_name) =
        s.map().layers.iter().find(|l| l.geometry_type() == rustgis_data::GeometryType::Polygon).map(|l| (l.id, l.name.clone())).unwrap();
    let globe_has =
        |s: &Session, name: &str| s.project.maps.iter().find(|m| m.name == first).unwrap().layers.iter().any(|l| l.name == name);
    assert!(globe_has(&s, &gone_name));
    s.map_mut().layer_mut(gone).unwrap().visible = false;
    let r = s.run("layout.publication", &json!({"extent": piaui, "name": "Again"})).unwrap();
    assert_eq!((s.project.maps.len(), r["locator"].as_str()), (before + 1, Some(first.as_str())));
    assert!(r["warnings"].to_string().contains("which no layout showed, is replaced"), "{r}");
    assert!(!globe_has(&s, &gone_name), "the reused map is rebuilt");
    s.map_mut().layer_mut(gone).unwrap().visible = true;
    let r = s.run("layout.publication", &json!({"extent": piaui})).unwrap();
    assert!(s.project.maps.len() == before + 2 && r["locator"].as_str() != Some(first.as_str()), "{r}");
    // A globe map made by hand under such a name (its layers labelled) is never taken for one.
    let mut hand = rustgis_map::Map::new(format!("{main} Locator 9"));
    hand.set_projection(rustgis_map::Projection::Globe);
    let mut labelled = s.map().layers.iter().find(|l| l.geometry_type() == rustgis_data::GeometryType::Polygon).unwrap().clone();
    labelled.labels.enabled = true;
    hand.layers.push(labelled);
    s.project.maps.push(hand);
    let r = s.run("layout.publication", &json!({"extent": piaui})).unwrap();
    assert_ne!(r["locator"].as_str(), Some(format!("{main} Locator 9").as_str()), "{r}");
    let kept = s.project.maps.iter().find(|m| m.name == format!("{main} Locator 9")).unwrap();
    assert!(kept.layers.iter().all(|l| l.labels.enabled));
    // The globe is a new map of what it draws: the polygon layers that show (a hidden one left
    // out) on the map's basemap, without its web tiles, swipe or groups.
    let polygon = |l: &rustgis_map::Layer| l.geometry_type() == rustgis_data::GeometryType::Polygon;
    let hidden = s.map().layers.iter().find(|l| polygon(l)).map(|l| (l.id, l.name.clone())).unwrap();
    s.map_mut().layer_mut(hidden.0).unwrap().visible = false;
    s.map_mut().tiles.push(rustgis_map::TileLayer::new(
        "Streets",
        rustgis_map::TileKind::Raster,
        "https://tiles.example.com/{z}/{x}/{y}.png",
    ));
    s.map_mut().swipe = Some((hidden.0, 0.5));
    let shown: Vec<String> = s.map().layers.iter().filter(|l| polygon(l) && s.map().shows(l)).map(|l| l.name.clone()).collect();
    let r = s.run("layout.publication", &json!({"extent": piaui})).unwrap();
    let m = s.project.maps.iter().find(|m| Some(m.name.as_str()) == r["locator"].as_str()).unwrap();
    assert_eq!(m.layers.iter().map(|l| l.name.clone()).collect::<Vec<_>>(), shown, "not {}", hidden.1);
    assert!(m.tiles.is_empty() && m.swipe.is_none() && m.groups.is_empty() && m.basemap == s.map().basemap);
    assert!(m.layers.iter().all(|l| !l.labels.enabled && l.selection.is_empty()));
    // A sketch of each layer for the small disc: every feature kept, far fewer vertices.
    for g in &m.layers {
        let l = s.map().layers.iter().find(|l| l.name == g.name).unwrap();
        let vertices =
            |l: &rustgis_map::Layer| l.dataset.features.iter().filter_map(|f| f.geometry.as_ref()).map(|g| g.coord_count()).sum::<usize>();
        assert_eq!(g.dataset.features.len(), l.dataset.features.len());
        assert!(vertices(g) * 2 < vertices(l), "{}: {} of {} vertices", g.name, vertices(g), vertices(l));
    }
    // An island far smaller than the tolerance keeps its own ring rather than collapsing; no ring
    // on the globe has under four points.
    let island = dir.join("island.geojson");
    std::fs::write(
        &island,
        r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {}, "geometry": {"type": "Polygon", "coordinates": [[[-40, -5], [-39.999, -5], [-39.999, -4.999], [-40, -4.999], [-40, -5]]]}}]}"#,
    )
    .unwrap();
    s.run("layer.addData", &json!({"path": island.display().to_string()})).unwrap();
    let r = s.run("layout.publication", &json!({"extent": piaui})).unwrap();
    let m = s.project.maps.iter().find(|m| Some(m.name.as_str()) == r["locator"].as_str()).unwrap();
    let rings = |name: &str| -> Vec<usize> {
        m.layers
            .iter()
            .filter(|l| l.name == name || name.is_empty())
            .flat_map(|l| l.dataset.features.iter())
            .filter_map(|f| match &f.geometry {
                Some(rustgis_data::Geometry::Polygon(polys)) => Some(polys.iter().flatten().map(Vec::len).collect::<Vec<_>>()),
                _ => None,
            })
            .flatten()
            .collect()
    };
    assert_eq!(rings("island"), [5]);
    assert!(rings("").iter().all(|n| *n >= 4));
    // Sheets with ever more source lines, so ever smaller frames, down to the smallest a sheet
    // takes: the legend is never drawn over the locator, whichever corners they take (the search
    // keeps them apart), and if the locator leaves it no room it is left out, said.
    for n in 1..80 {
        let sources: Vec<String> = (0..n).map(|i| format!("Source {i}: a line long enough to take a line of its own")).collect();
        let Ok(r) = s.run("layout.publication", &json!({"profile": "a4-landscape", "extent": piaui, "sources": sources})) else { break };
        let l = s.project.layouts.last().unwrap();
        let named = |name: &str| l.elements.iter().find(|e| e.name == name);
        let locator = named("Locator").unwrap();
        match named("Legend Box") {
            Some(b) => {
                let apart = b.x >= locator.x + locator.w - 1e-6
                    || locator.x >= b.x + b.w - 1e-6
                    || b.y >= locator.y + locator.h - 1e-6
                    || locator.y >= b.y + b.h - 1e-6;
                assert!(apart, "{n} lines: the legend over the locator");
            }
            None => {
                let said = r["warnings"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|w| w.as_str().unwrap_or("").contains("the frame leaves the legend no room beside the locator"));
                assert!(said, "{n} lines: {r}");
            }
        }
    }
    // The sheets above may never leave the legend that little room (the search keeps it off the
    // locator's side), so the rule itself: short of the arrow or the scale bar it keeps 10 mm, short
    // of the locator under 10 mm it is left out.
    use crate::cmd::layout::{Surround, legend_room};
    assert_eq!(legend_room(40.0, 30.0, 100.0, 80.0, None, None), Some((40.0, 30.0)));
    assert_eq!(legend_room(40.0, 30.0, 100.0, 80.0, Some((Surround::Arrow, 70.0)), Some((Surround::Locator, 60.0))), Some((30.0, 20.0)));
    assert_eq!(legend_room(40.0, 30.0, 100.0, 80.0, Some((Surround::Arrow, 95.0)), Some((Surround::Scale, 75.0))), Some((10.0, 10.0)));
    assert_eq!(legend_room(40.0, 30.0, 100.0, 80.0, None, Some((Surround::Locator, 75.0))), None);
    assert_eq!(legend_room(40.0, 30.0, 100.0, 80.0, Some((Surround::Locator, 95.0)), None), None);
    let _ = std::fs::remove_dir_all(&dir);
}

/// Arrangements of a publication layout's surrounds (#1379): by name, corner by corner, the
/// favourite (`layout.arrangement`, kept by the app) and `best`, the default, which keeps the
/// favourite unless another keeps more surrounds in their own corners. Bad ones are refused before
/// anything changes.
#[test]
fn publication_arrangements_and_the_favourite() {
    let dir = std::env::temp_dir().join(format!("rustgis-arrangement-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let square = |name: &str, (w, so, e, n): (f64, f64, f64, f64)| {
        let path = dir.join(format!("{name}.geojson"));
        let ring = format!("[[{w},{so}],[{e},{so}],[{e},{n}],[{w},{n}],[{w},{so}]]");
        std::fs::write(
            &path,
            format!(r#"{{"type": "FeatureCollection", "features": [{{"type": "Feature", "properties": {{"name": "{name}"}}, "geometry": {{"type": "Polygon", "coordinates": [{ring}]}}}}]}}"#),
        )
        .unwrap();
        path.display().to_string()
    };
    let corner_of = |s: &Session, name: &str| {
        let l = s.project.layouts.last().unwrap();
        let frame = l.elements.iter().find(|e| e.name == "Map Frame").unwrap();
        let e = l.elements.iter().find(|e| e.name == name).unwrap_or_else(|| panic!("no {name}"));
        let (right, low) = (e.x + e.w / 2.0 > frame.x + frame.w / 2.0, e.y + e.h / 2.0 > frame.y + frame.h / 2.0);
        match (low, right) {
            (false, false) => "top left",
            (false, true) => "top right",
            (true, false) => "bottom left",
            (true, true) => "bottom right",
        }
    };
    let corners = |s: &Session| ["Locator", "North Arrow", "Legend Box", "Scale Box"].map(|n| corner_of(s, n));
    let extent = json!([0, 0, 10, 10]);
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": square("middle", (4.0, 4.0, 6.0, 6.0))})).unwrap();
    // Nothing asked: classic, as before there was a choice.
    let r = s.run("layout.publication", &json!({"extent": extent, "author": ""})).unwrap();
    assert_eq!(
        (r["arrangement"].as_str(), corners(&s)),
        (Some("classic"), ["top left", "top right", "bottom left", "bottom right"]),
        "{r}"
    );
    // By name, and corner by corner.
    let r = s.run("layout.publication", &json!({"extent": extent, "author": "", "arrangement": "legendRight"})).unwrap();
    assert_eq!(corners(&s), ["top left", "top right", "bottom right", "bottom left"], "{r}");
    let custom = json!({"locator": "bottom-left", "northArrow": "top-left", "legend": "top-right", "scaleBar": "bottom-right"});
    let r = s.run("layout.publication", &json!({"extent": extent, "author": "", "arrangement": custom})).unwrap();
    assert_eq!((r["arrangement"].as_str(), corners(&s)), (Some("custom"), ["bottom left", "top left", "top right", "bottom right"]), "{r}");
    // Corner names, like arrangement names, are read whatever their case.
    let shouted = json!({"locator": "Bottom-Left", "northArrow": "TOP-LEFT", "legend": "top-Right", "scaleBar": "bottom-right"});
    let r = s.run("layout.publication", &json!({"extent": extent, "author": "", "arrangement": shouted})).unwrap();
    assert_eq!(corners(&s), ["bottom left", "top left", "top right", "bottom right"], "{r}");
    // The favourite: shown, set, then the one the default and "favourite" take.
    let shown = s.run("layout.arrangement", &json!({})).unwrap();
    assert_eq!((shown["favourite"].as_str(), shown["corners"]["legend"].as_str()), (Some("classic"), Some("bottom-left")));
    let set = s.run("layout.arrangement", &json!({"favourite": "mirrored"})).unwrap();
    assert_eq!(set["favourite"], "mirrored");
    for p in [json!({"extent": extent, "author": ""}), json!({"extent": extent, "author": "", "arrangement": "favourite"})] {
        let r = s.run("layout.publication", &p).unwrap();
        assert_eq!(
            (r["arrangement"].as_str(), corners(&s)),
            (Some("mirrored"), ["top right", "top left", "bottom right", "bottom left"]),
            "{r}"
        );
    }
    // Refused, naming what is wrong, with nothing changed.
    let layouts = s.project.layouts.len();
    for (bad, why) in [
        (json!("tidy"), "arrangement is \"classic\""),
        (
            json!({"locator": "top-left", "northArrow": "top-left", "legend": "bottom-left", "scaleBar": "bottom-right"}),
            "a corner of its own",
        ),
        (json!({"locator": "top-left", "arrow": "top-right", "legend": "bottom-left", "scaleBar": "bottom-right"}), "not \"arrow\""),
        (json!({"locator": "top-left", "northArrow": "middle", "legend": "bottom-left", "scaleBar": "bottom-right"}), "\"northArrow\" is"),
        (json!(3), "arrangement is"),
    ] {
        let e = s.run("layout.publication", &json!({"extent": extent, "arrangement": bad})).unwrap_err();
        assert!(e.contains(why), "{bad}: {e}");
        let e = s.run("layout.arrangement", &json!({"favourite": bad})).unwrap_err();
        assert!(e.contains(why), "{bad}: {e}");
    }
    assert_eq!((s.project.layouts.len(), s.layout_favourite.as_str()), (layouts, Some("mirrored")));
    // Best: data filling the top right, where the favourite (mirrored) has the locator at home;
    // classic has its small north arrow there and moves only that, less than mirrored's locator, so
    // it wins. "favourite" keeps mirrored, the locator off the data.
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": square("corner", (5.0, 5.0, 30.0, 30.0))})).unwrap();
    s.run("layout.arrangement", &json!({"favourite": "mirrored"})).unwrap();
    let best = s.run("layout.publication", &json!({"extent": extent, "author": ""})).unwrap();
    assert_eq!(best["arrangement"], "classic", "{best}");
    assert_eq!(corner_of(&s, "Locator"), "top left", "{best}");
    let fav = s.run("layout.publication", &json!({"extent": extent, "author": "", "arrangement": "favourite"})).unwrap();
    assert_eq!(fav["arrangement"], "mirrored", "{fav}");
    assert_ne!(corner_of(&s, "Locator"), "top right", "{fav}");
    let _ = std::fs::remove_dir_all(&dir);
}

/// `best` never wins by leaving the legend out (#1379): on sheets ever smaller, once classic's
/// locator leaves the legend under it no room, the default still keeps a legend, in an arrangement
/// that has room for it.
#[test]
fn best_keeps_the_legend_an_arrangement_would_leave_out() {
    let mut s = world();
    let piaui = json!([-46.8, -11.6, -38.5, -2.2]);
    let dropped = "the frame leaves the legend no room beside the locator";
    let mut checked = false;
    for n in 1..80 {
        let sources: Vec<String> = (0..n).map(|i| format!("Source {i}: a line long enough to take a line of its own")).collect();
        let p = json!({"profile": "a4-landscape", "extent": piaui, "sources": sources, "arrangement": "classic"});
        let Ok(r) = s.run("layout.publication", &p) else { break };
        if !r["warnings"].to_string().contains(dropped) {
            continue;
        }
        let best = s.run("layout.publication", &json!({"profile": "a4-landscape", "extent": piaui, "sources": sources})).unwrap();
        let l = s.project.layouts.last().unwrap();
        assert!(l.elements.iter().any(|e| e.name == "Legend Box"), "{n} lines: {best}");
        assert!(!best["warnings"].to_string().contains(dropped), "{n} lines: {best}");
        checked = true;
        break;
    }
    assert!(checked, "no sheet left classic's legend out");
}

/// How `best` picks among the arrangements tried (#1379): the least area moved, within a square
/// millimetre, then the least left over the data, within one, the first tried on a tie; the bands
/// are measured from the best value, so they don't add up from one try to the next.
#[test]
fn best_picks_by_area_moved_then_area_over_the_data() {
    use crate::cmd::layout::pick_arrangement;
    // Each moves under a millimetre more than the one before, and leaves less over the data: the
    // third moves 1.8 mm² more than the first, out of the band, so the second wins.
    assert_eq!(pick_arrangement(&[(10.0, 50.0), (10.9, 40.0), (11.8, 30.0)]), Some(1));
    // Clearly less moved wins whatever it leaves over the data.
    assert_eq!(pick_arrangement(&[(100.0, 0.0), (20.0, 90.0)]), Some(1));
    // Ties go to the first tried (the favourite), within a millimetre either way.
    assert_eq!(pick_arrangement(&[(10.0, 20.0), (10.5, 19.5), (9.8, 20.4)]), Some(0));
    assert_eq!(pick_arrangement(&[(f64::NAN, 1.0), (5.0, 5.0)]), Some(1));
    assert_eq!(pick_arrangement(&[(f64::NAN, f64::NAN)]), None);
    assert_eq!(pick_arrangement(&[]), None);
    // Surrounds left over each other count ten times their overlap in the area moved.
    use crate::cmd::layout::overlap_area;
    assert_eq!(overlap_area(&[(0.0, 0.0, 10.0, 10.0), (5.0, 5.0, 10.0, 10.0), (30.0, 0.0, 5.0, 5.0)]), 25.0);
    assert_eq!(overlap_area(&[(0.0, 0.0, 10.0, 10.0), (10.0, 0.0, 10.0, 10.0)]), 0.0);
}

/// The legend is placed first (#1379): with data everywhere but the top right, it leaves its own
/// covered corner for the free quarter, the north arrow's, and the two don't overlap.
#[test]
fn the_legend_is_placed_before_the_smaller_surrounds() {
    let dir = std::env::temp_dir().join(format!("rustgis-legend-first-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("l.geojson");
    let square = |(w, so, e, n): (f64, f64, f64, f64)| format!("[[[{w},{so}],[{e},{so}],[{e},{n}],[{w},{n}],[{w},{so}]]]");
    std::fs::write(
        &path,
        format!(
            r#"{{"type": "FeatureCollection", "features": [{{"type": "Feature", "properties": {{}}, "geometry": {{"type": "MultiPolygon", "coordinates": [{}, {}]}}}}]}}"#,
            square((-20.0, -20.0, 30.0, 5.0)),
            square((-20.0, 5.0, 5.0, 30.0))
        ),
    )
    .unwrap();
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
    let r =
        s.run("layout.publication", &json!({"extent": [0, 0, 10, 10], "author": "", "arrangement": "classic", "locator": "none"})).unwrap();
    let l = s.project.layouts.last().unwrap();
    let rect = |name: &str| l.elements.iter().find(|e| e.name == name).map(|e| (e.x, e.y, e.w, e.h)).unwrap();
    let (frame, legend, arrow) = (rect("Map Frame"), rect("Legend Box"), rect("North Arrow"));
    let moved = r["moved"].as_array().unwrap();
    assert!(moved.contains(&json!("legend")), "{r}");
    assert!(!r["warnings"].to_string().contains("overlap"), "{r}");
    // The legend in the free quarter, the top right.
    assert!(legend.0 + legend.2 / 2.0 > frame.0 + frame.2 / 2.0 && legend.1 + legend.3 / 2.0 < frame.1 + frame.3 / 2.0, "{r}");
    // The arrow off it.
    let apart =
        legend.0 + legend.2 <= arrow.0 || arrow.0 + arrow.2 <= legend.0 || legend.1 + legend.3 <= arrow.1 || arrow.1 + arrow.3 <= legend.1;
    assert!(apart, "{r} {legend:?} {arrow:?}");
    let _ = std::fs::remove_dir_all(&dir);
}

/// Where a surround that leaks off its corner goes (#1379): the free part of the frame, clear of
/// the other surrounds, in line with them, near its corner; nowhere when it can't fit.
#[test]
fn a_leaking_surround_finds_the_free_part_of_the_frame() {
    use crate::cmd::layout::free_spot;
    let area = (0.0, 0.0, 100.0, 100.0);
    // Data over the left half (a continent), the frame's right half free (an ocean).
    let left_half = |(x, _, w, _): (f64, f64, f64, f64)| ((50.0 - x).clamp(0.0, w)) / w;
    let home = (2.0, 70.0, 20.0, 20.0);
    let r = free_spot(home, area, &[], left_half).unwrap();
    assert!(left_half(r) == 0.0 && r.0 >= 50.0, "{r:?}");
    // Near its corner: at the data's edge, and 10 mm lower, its bottom on the frame's (in line
    // with it costs less than the 10 mm away).
    assert_eq!(r, (50.0, 80.0, 20.0, 20.0));
    // Another surround there: it keeps 2 mm clear of it, and lines up with its edge.
    let legend = (50.0, 60.0, 40.0, 38.0);
    let r = free_spot(home, area, &[legend], left_half).unwrap();
    let clear = r.1 + r.3 + 2.0 <= legend.1 || r.0 >= legend.0 + legend.2 + 2.0;
    assert!(clear && left_half(r) == 0.0, "{r:?}");
    assert!([legend.0, legend.0 + legend.2].contains(&r.0) || [legend.0, legend.0 + legend.2].contains(&(r.0 + r.2)), "in line: {r:?}");
    // The same frame, the same place.
    assert_eq!(free_spot(home, area, &[legend], left_half), Some(r));
    // Too big for the frame, or nowhere clear: none.
    assert_eq!(free_spot((0.0, 0.0, 120.0, 10.0), area, &[], left_half), None);
    assert_eq!(free_spot(home, area, &[(0.0, 0.0, 100.0, 100.0)], left_half), None);
}

/// A publication layout's surrounds keep off the map's data (#682, part 3): with a polygon filling
/// the bottom left of the frame, the surround each arrangement puts there leaves it for a free place
/// in the frame, the smallest to move winning: here the classic legend of one row (#1379); with
/// data everywhere, nothing moves and nothing is said; with none, they stay in their own corners. `"decimal": ","` gives the layout a decimal comma, which
/// `layout.page` also sets.
#[test]
fn publication_surrounds_keep_off_the_data() {
    let dir = std::env::temp_dir().join(format!("rustgis-placement-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let square = |name: &str, (w, so, e, n): (f64, f64, f64, f64)| {
        let path = dir.join(format!("{name}.geojson"));
        let ring = format!("[[{w},{so}],[{e},{so}],[{e},{n}],[{w},{n}],[{w},{so}]]");
        std::fs::write(
            &path,
            format!(r#"{{"type": "FeatureCollection", "features": [{{"type": "Feature", "properties": {{"name": "{name}"}}, "geometry": {{"type": "Polygon", "coordinates": [{ring}]}}}}]}}"#),
        )
        .unwrap();
        path.display().to_string()
    };
    let corner_of = |s: &Session, name: &str| {
        let l = s.project.layouts.last().unwrap();
        let frame = l.elements.iter().find(|e| e.name == "Map Frame").unwrap();
        let e = l.elements.iter().find(|e| e.name == name).unwrap_or_else(|| panic!("no {name}"));
        let (right, low) = (e.x + e.w / 2.0 > frame.x + frame.w / 2.0, e.y + e.h / 2.0 > frame.y + frame.h / 2.0);
        match (low, right) {
            (false, false) => "top left",
            (false, true) => "top right",
            (true, false) => "bottom left",
            (true, true) => "bottom right",
        }
    };
    let extent = json!([0, 0, 10, 10]);
    // No data in any corner: each in its own.
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": square("middle", (4.0, 4.0, 6.0, 6.0))})).unwrap();
    let r = s.run("layout.publication", &json!({"extent": extent, "author": ""})).unwrap();
    let corners: Vec<_> = ["Locator", "North Arrow", "Legend Box", "Scale Box"].iter().map(|n| corner_of(&s, n)).collect();
    assert_eq!(corners, ["top left", "top right", "bottom left", "bottom right"], "{r}");
    assert!(r["warnings"].as_array().unwrap().is_empty() && r["moved"] == json!([]), "{r}");
    // A polygon filling the bottom left: the legend keeps out of it.
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": square("corner", (-20.0, -20.0, 5.0, 5.0))})).unwrap();
    // The coverage is drawn on the map itself, its basemap set aside meanwhile and put back.
    // Web tiles, a background like the basemap, are set aside too: they don't make every corner
    // look covered (a closed port, never asked).
    s.map_mut().basemap = rustgis_map::Basemap::Ocean;
    s.map_mut().tiles.push(rustgis_map::TileLayer::new("Streets", rustgis_map::TileKind::Raster, "http://127.0.0.1:9/{z}/{x}/{y}.png"));
    let r = s.run("layout.publication", &json!({"extent": extent, "author": ""})).unwrap();
    assert!(s.map().basemap == rustgis_map::Basemap::Ocean && s.map().label_lock.is_none() && s.map().tiles.len() == 1);
    assert_ne!(corner_of(&s, "Legend Box"), "bottom left", "{r}");
    s.map_mut().tiles.clear();
    // Four surrounds, three free corners: the legend of one row is smaller to move than the scale
    // bar or the locator other arrangements put there, so classic wins; its legend leaves the
    // covered corner for a free place, out of the data's quarter, and nothing is left to say (#1379).
    assert_eq!((r["arrangement"].as_str(), &r["moved"]), (Some("classic"), &json!(["legend"])), "{r}");
    assert!(!r["warnings"].to_string().contains("on what the map shows"), "{r}");
    // A pale fill with no outline counts as data too: the legend leaves it the same way.
    let mut pale = Session::new(Project::default());
    pale.run("layer.addData", &json!({"path": square("pale", (-20.0, -20.0, 5.0, 5.0))})).unwrap();
    pale.run("layer.color", &json!({"layer": "pale", "color": "#FAFAF5"})).unwrap();
    pale.run("layer.outline", &json!({"layer": "pale", "color": "#00000000", "width": 0})).unwrap();
    let rp = pale.run("layout.publication", &json!({"extent": extent, "author": ""})).unwrap();
    assert_ne!(corner_of(&pale, "Legend Box"), "bottom left", "{rp}");
    s.run("layout.export", &json!({"path": dir.join("corner.png").display().to_string(), "dpi": 72})).unwrap();
    // Data everywhere (a context layer filling the frame): nowhere better, so nothing said and each
    // in its own corner.
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": square("all", (-30.0, -30.0, 40.0, 40.0))})).unwrap();
    let r = s.run("layout.publication", &json!({"extent": extent, "author": "", "decimal": ","})).unwrap();
    assert!(!r["warnings"].to_string().contains("on what the map shows") && r["moved"] == json!([]), "{r}");
    assert_eq!(corner_of(&s, "Legend Box"), "bottom left");
    // A decimal comma, set by the command and by layout.page; anything else refused.
    assert!(s.project.layouts.last().unwrap().decimal_comma);
    let r = s.run("layout.page", &json!({"decimal": "."})).unwrap();
    assert_eq!(r["decimal"], ".");
    assert!(!s.project.layouts.last().unwrap().decimal_comma);
    for p in [json!({"decimal": ";"}), json!({"decimal": 1})] {
        assert!(s.run("layout.page", &p).unwrap_err().contains("decimal is"), "{p}");
        assert!(s.run("layout.publication", &json!({"extent": extent, "decimal": p["decimal"]})).unwrap_err().contains("decimal is"));
    }
    s.run("layout.export", &json!({"path": dir.join("comma.png").display().to_string(), "dpi": 72})).unwrap();
    let _ = std::fs::remove_dir_all(&dir);
}

/// A publication legend sized to its rows fits them: its box, less the padding, may come out a
/// rounding error short of the rows' width, which isn't "more than fits" (macOS CI, whose fonts
/// gave one such width). Layer names of many widths, so some land on a rounding error with any font.
#[test]
fn a_publication_legend_sized_to_its_rows_fits_them() {
    let dir = std::env::temp_dir().join(format!("rustgis-legend-fit-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let names: Vec<String> = (0..300).map(|i| format!("{}{i}", &"WmilQxkaRb"[i % 10..])).collect();
    for name in &names {
        let path = dir.join(format!("{name}.geojson"));
        std::fs::write(
            &path,
            r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {}, "geometry": {"type": "Polygon", "coordinates": [[[4,4],[6,4],[6,6],[4,6],[4,4]]]}}]}"#,
        )
        .unwrap();
        let mut s = Session::new(Project::default());
        s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
        let r = s.run("layout.publication", &json!({"extent": [0, 0, 10, 10], "author": ""})).unwrap();
        assert!(!r["warnings"].to_string().contains("more than fits"), "{name}: {r}");
    }
    let _ = std::fs::remove_dir_all(&dir);
}

/// A publication legend too long for its corner goes into columns, the fewest that hold it (#1379),
/// and past three says what it leaves out; a short one stays in one, saved as it always was.
/// The largest rectangle with nothing drawn, inside the part of the grid asked for.
#[test]
fn the_largest_free_rectangle_of_a_grid() {
    use crate::cmd::layout::largest_free_cells;
    let grid = |rows: &[&str]| -> Vec<bool> { rows.iter().flat_map(|r| r.chars().map(|c| c == '#')).collect() };
    let cells = grid(&["....#.", "....#.", "##..#.", "##...."]);
    assert_eq!(largest_free_cells(6, &cells, (0, 0, 6, 4)), (4, 2));
    // Inside a part of it: the columns and rows outside don't count.
    assert_eq!(largest_free_cells(6, &cells, (2, 2, 6, 4)), (2, 2));
    // A wide run under a taller narrow one, and the other way round.
    assert_eq!(largest_free_cells(3, &grid(&["#.#", "#.#", "..."]), (0, 0, 3, 3)), (1, 3));
    assert_eq!(largest_free_cells(4, &grid(&["#..#", "....", "...."]), (0, 0, 4, 3)), (4, 2));
    // All drawn, all free, nothing asked for.
    assert_eq!(largest_free_cells(2, &grid(&["##", "##"]), (0, 0, 2, 2)), (0, 0));
    assert_eq!(largest_free_cells(2, &grid(&["..", ".."]), (0, 0, 2, 2)), (2, 2));
    assert_eq!(largest_free_cells(2, &grid(&["..", ".."]), (1, 1, 1, 1)), (0, 0));
}

/// A long legend takes the fewest columns that fit the largest rectangle the map leaves free: data
/// along the bottom of the frame leaves a wide band above it, too low for one column. Layers that
/// only outline their polygons don't take that room.
#[test]
fn a_publication_legend_takes_the_columns_that_fit_the_free_rectangle() {
    let dir = std::env::temp_dir().join(format!("rustgis-legend-free-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let polygon = |name: &str, [w, s, e, n]: [f64; 4]| {
        let path = dir.join(name);
        let json = json!({"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {}, "geometry":
            {"type": "Polygon", "coordinates": [[[w, s], [e, s], [e, n], [w, n], [w, s]]]}}]});
        std::fs::write(&path, json.to_string()).unwrap();
        path.display().to_string()
    };
    let low = polygon("low.geojson", [0.0, 0.0, 10.0, 6.5]);
    let border = polygon("border.geojson", [1.0, 7.0, 9.0, 9.0]);
    let columns = |outline: bool| {
        let mut s = Session::new(Project::default());
        for _ in 0..24 {
            s.run("layer.addData", &json!({"path": low})).unwrap();
        }
        if outline {
            s.run("layer.addData", &json!({"path": border})).unwrap();
            s.run("layer.color", &json!({"layer": "border", "color": "#00000000"})).unwrap();
        }
        let r = s
            .run("layout.publication", &json!({"profile": "a4-portrait", "extent": [0, 0, 10, 10], "author": "", "locator": "none"}))
            .unwrap();
        (r["legendColumns"].as_u64().unwrap(), s.map().layers.iter().all(|l| l.visible))
    };
    assert_eq!(columns(false), (2, true));
    assert_eq!(columns(true), (2, true), "the border doesn't count, and is shown again");
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn a_publication_legend_too_long_goes_into_columns() {
    use rustgis_map::layout::ElementKind;
    let dir = std::env::temp_dir().join(format!("rustgis-legend-columns-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("a.geojson");
    std::fs::write(
        &path,
        r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {}, "geometry": {"type": "Polygon", "coordinates": [[[4,4],[6,4],[6,6],[4,6],[4,4]]]}}]}"#,
    )
    .unwrap();
    // Filling the frame below 60% of its height: a long legend in one column would cover it, and two
    // sit above it. A short one stays in one, whatever it covers.
    let low = dir.join("low.geojson");
    std::fs::write(
        &low,
        r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {}, "geometry": {"type": "Polygon", "coordinates": [[[0,0],[10,0],[10,6],[0,6],[0,0]]]}}]}"#,
    )
    .unwrap();
    // Labels too long for two columns side by side: they close up, and it says so.
    let mut s = Session::new(Project::default());
    for i in 0..60 {
        s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
        s.run(
            "layer.rename",
            &json!({"layer": "a", "name": format!("{i} a layer's name long enough to take more than half of the frame's width")}),
        )
        .unwrap();
    }
    let r = s.run("layout.publication", &json!({"extent": [0, 0, 10, 10], "author": "", "locator": "none"})).unwrap();
    assert!(r["legendColumns"].as_u64().unwrap() > 1, "{r}");
    assert!(r["warnings"].to_string().contains("run into the next"), "{r}");
    for (layers, columns) in [(3, 1), (30, 2)] {
        let mut s = Session::new(Project::default());
        for _ in 0..layers {
            s.run("layer.addData", &json!({"path": low.display().to_string()})).unwrap();
        }
        let r = s.run("layout.publication", &json!({"extent": [0, 0, 10, 10], "author": "", "locator": "none"})).unwrap();
        assert_eq!(r["legendColumns"], columns, "{layers} layers: {r}");
    }
    for (layers, columns, cut) in [(3, 1, false), (60, 3, false), (100, 3, false), (200, 3, true)] {
        let mut s = Session::new(Project::default());
        for _ in 0..layers {
            s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
        }
        let r = s.run("layout.publication", &json!({"extent": [0, 0, 10, 10], "author": "", "locator": "none"})).unwrap();
        assert_eq!(r["legendColumns"], columns, "{layers} layers: {r}");
        assert_eq!(r["warnings"].to_string().contains("more than fits"), cut, "{layers} layers: {r}");
        let l = s.project.layouts.last().unwrap();
        let legend = l.elements.iter().find(|e| matches!(e.kind, ElementKind::Legend { .. })).unwrap();
        assert!(matches!(legend.kind, ElementKind::Legend { columns: c, .. } if c == columns), "{:?}", legend.kind);
        assert_eq!(serde_json::to_string(&legend.kind).unwrap().contains("columns"), columns > 1);
    }
    let _ = std::fs::remove_dir_all(&dir);
}

/// A legend that one column shows whole, in a free rectangle wider than the legend's usual box, stays
/// in one: a second column would only widen the box. A long one too, in a rectangle taller than that
/// box.
#[test]
fn a_publication_legend_that_fits_whole_stays_in_one_column() {
    let dir = std::env::temp_dir().join(format!("rustgis-legend-whole-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let polygon = |name: &str, [w, s, e, n]: [f64; 4]| {
        let path = dir.join(name);
        let json = json!({"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {}, "geometry":
            {"type": "Polygon", "coordinates": [[[w, s], [e, s], [e, n], [w, n], [w, s]]]}}]});
        std::fs::write(&path, json.to_string()).unwrap();
        path.display().to_string()
    };
    let low = polygon("low.geojson", [0.0, 0.0, 10.0, 6.0]);
    let mut s = Session::new(Project::default());
    for name in ["first", "second", "a layer's name long enough to take a little over the share of the frame's width a legend starts with"]
    {
        s.run("layer.addData", &json!({"path": low})).unwrap();
        s.run("layer.rename", &json!({"layer": "low", "name": name})).unwrap();
    }
    let p = json!({"profile": "a4-landscape", "extent": [0, 0, 10, 10], "author": "", "locator": "none"});
    let r = s.run("layout.publication", &p).unwrap();
    assert_eq!(r["legendColumns"], 1, "{r}");
    let l = s.project.layouts.last().unwrap();
    let legend = l.elements.iter().find(|e| e.name == "Legend Box").unwrap();
    let frame = l.element(l.first_frame().unwrap()).unwrap();
    assert!(legend.w > 0.45 * frame.w, "the whole of its width: {r}");
    assert!(!r["warnings"].to_string().contains("more than fits"), "{r}");

    let left = polygon("left.geojson", [0.0, 0.0, 3.0, 10.0]);
    let mut s = Session::new(Project::default());
    for _ in 0..28 {
        s.run("layer.addData", &json!({"path": left})).unwrap();
    }
    let p = json!({"profile": "a4-landscape", "extent": [0, 0, 10, 10], "author": "", "locator": "none"});
    let r = s.run("layout.publication", &p).unwrap();
    assert_eq!(r["legendColumns"], 1, "{r}");
    let l = s.project.layouts.last().unwrap();
    let legend = l.elements.iter().find(|e| e.name == "Legend Box").unwrap();
    let frame = l.element(l.first_frame().unwrap()).unwrap();
    assert!(legend.h > 0.6 * frame.h, "the whole of its height: {r}");
    assert!(!r["warnings"].to_string().contains("more than fits"), "{r}");
    let _ = std::fs::remove_dir_all(&dir);
}

/// A legend left out isn't in any columns, whatever the frame leaves free.
#[test]
fn a_publication_legend_left_out_has_one_column() {
    let dir = std::env::temp_dir().join(format!("rustgis-legend-out-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("a.geojson");
    std::fs::write(
        &path,
        r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {}, "geometry": {"type": "Polygon", "coordinates": [[[4.8,4.8],[5.2,4.8],[5.2,5.2],[4.8,5.2],[4.8,4.8]]]}}]}"#,
    )
    .unwrap();
    let mut checked = false;
    for layers in [6, 8, 10, 12, 16, 20, 30, 40, 80] {
        let mut s = Session::new(Project::default());
        for _ in 0..layers {
            s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
        }
        for n in 1..120 {
            let sources: Vec<String> = (0..n).map(|i| format!("Source {i}: a line long enough to take a line of its own")).collect();
            let p = json!({"profile": "a4-landscape", "extent": [0, 0, 10, 10], "sources": sources, "arrangement": "classic"});
            let Ok(r) = s.run("layout.publication", &p) else { break };
            if r["warnings"].to_string().contains("the frame leaves the legend no room beside the locator") {
                assert_eq!(r["legendColumns"], 1, "{layers} layers, {n} lines: {r}");
                checked = true;
            }
        }
    }
    assert!(checked, "no sheet left the legend out");
    let _ = std::fs::remove_dir_all(&dir);
}

/// A publication legend takes another column to show more of itself, or as much and cover at least
/// a quarter less of what the map draws.
#[test]
fn more_columns_win_by_showing_more_or_covering_less() {
    use crate::cmd::layout::more_columns_win;
    assert!(more_columns_win((1.0, 500.0), (0.6, 0.0)), "more shown, whatever it covers");
    assert!(!more_columns_win((0.6, 0.0), (1.0, 500.0)), "less shown, whatever it covers");
    assert!(more_columns_win((1.0, 300.0), (1.0, 500.0)), "as much shown, covering 40% less");
    assert!(!more_columns_win((1.0, 400.0), (1.0, 500.0)), "only 20% less");
    assert!(!more_columns_win((1.0, 0.0), (1.0, 0.0)), "nothing to gain");
}

/// `"columns"` on a legend: given and changed, refused outside 1 to 3 and on anything else.
#[test]
fn a_legend_takes_columns_from_one_to_three() {
    use rustgis_map::layout::ElementKind;
    let mut s = Session::new(Project::default());
    s.run("layout.new", &json!({"template": "map"})).unwrap();
    let columns = |s: &Session, id: u64| match s.project.layouts[0].element(id as u32).map(|e| &e.kind) {
        Some(ElementKind::Legend { columns, .. }) => *columns,
        other => panic!("{other:?}"),
    };
    let added = s.run("layout.addElement", &json!({"kind": "legend"})).unwrap();
    let id = added["element"].as_u64().unwrap();
    assert_eq!(columns(&s, id), 1);
    let two = s.run("layout.addElement", &json!({"kind": "legend", "columns": 2})).unwrap();
    assert_eq!(columns(&s, two["element"].as_u64().unwrap()), 2);
    s.run("layout.update", &json!({"element": id, "columns": 3})).unwrap();
    assert_eq!(columns(&s, id), 3);
    s.run("layout.update", &json!({"element": id, "title": "Key"})).unwrap();
    assert_eq!(columns(&s, id), 3, "another change leaves them");
    for bad in [json!(0), json!(4), json!(1.5), json!("2"), json!(-1)] {
        assert!(s.run("layout.update", &json!({"element": id, "columns": bad})).unwrap_err().contains("1 to 3"), "{bad}");
        assert!(s.run("layout.addElement", &json!({"kind": "legend", "columns": bad})).unwrap_err().contains("1 to 3"), "{bad}");
    }
    assert_eq!(columns(&s, id), 3);
    let err = s.run("layout.addElement", &json!({"kind": "northArrow", "columns": 2})).unwrap_err();
    assert!(err.contains("only legends"), "{err}");
    let arrow = s.run("layout.addElement", &json!({"kind": "northArrow"})).unwrap();
    let err = s.run("layout.update", &json!({"element": arrow["element"], "columns": 2})).unwrap_err();
    assert!(err.contains("only legends"), "{err}");
    let err = s.run("layout.update", &json!({"element": 999, "columns": 2})).unwrap_err();
    assert!(err.contains("no element 999"), "{err}");
    // A layout saved before them has one.
    let old: ElementKind = serde_json::from_str(r#"{"Legend":{"frame":1,"title":"L"}}"#).unwrap();
    assert!(matches!(old, ElementKind::Legend { columns: 1, .. }), "{old:?}");
    // A value out of range, from a file edited by hand, is saved as the nearest.
    for (given, kept) in [(0, 1), (999, 3)] {
        let mut l = s.project.layouts[0].clone();
        let Some(ElementKind::Legend { columns, .. }) = l.element_mut(id as u32).map(|e| &mut e.kind) else { panic!() };
        *columns = given;
        l.clamp();
        assert!(matches!(l.element(id as u32).map(|e| &e.kind), Some(ElementKind::Legend { columns, .. }) if *columns == kept), "{given}");
    }
}

/// A legend given `"columns"` says when its box doesn't hold them, and only then.
#[test]
fn a_legends_columns_say_when_its_box_is_too_small() {
    let dir = std::env::temp_dir().join(format!("rustgis-legend-box-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("a.geojson");
    std::fs::write(
        &path,
        r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {}, "geometry": {"type": "Polygon", "coordinates": [[[4,4],[6,4],[6,6],[4,6],[4,4]]]}}]}"#,
    )
    .unwrap();
    let mut s = Session::new(Project::default());
    for _ in 0..12 {
        s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
    }
    s.run("layout.new", &json!({"template": "map"})).unwrap();
    let said = |s: &Session, mark: u64| s.notices_since(mark).iter().map(|n| n.text.clone()).collect::<Vec<_>>().join(" | ");
    // One big enough: nothing to say, added or changed.
    let mark = s.notice_mark();
    let added = s.run("layout.addElement", &json!({"kind": "legend", "columns": 2, "x": 10, "y": 10, "w": 150, "h": 150})).unwrap();
    let id = added["element"].as_u64().unwrap();
    s.run("layout.update", &json!({"element": id, "columns": 3})).unwrap();
    s.run("layout.update", &json!({"element": id, "columns": 1})).unwrap();
    assert_eq!(said(&s, mark), "");
    // Too short: its last rows are left out.
    let mark = s.notice_mark();
    s.run("layout.update", &json!({"element": id, "h": 15, "columns": 2})).unwrap();
    assert!(said(&s, mark).contains("its last rows are left out"), "{}", said(&s, mark));
    // Too narrow: its columns close up.
    let mark = s.notice_mark();
    s.run("layout.update", &json!({"element": id, "w": 12, "h": 150, "columns": 3})).unwrap();
    assert!(said(&s, mark).contains("they close up"), "{}", said(&s, mark));
    // Added too small, in one column.
    let mark = s.notice_mark();
    s.run("layout.addElement", &json!({"kind": "legend", "columns": 1, "x": 10, "y": 10, "w": 150, "h": 15})).unwrap();
    assert!(said(&s, mark).contains("its last rows or the ends of long labels are left out"), "{}", said(&s, mark));
    // No title leaves its rows the height it would take.
    let mark = s.notice_mark();
    s.run("layout.update", &json!({"element": id, "w": 150, "h": 150, "title": "", "columns": 2})).unwrap();
    assert_eq!(said(&s, mark), "");
    // In columns, its box or what it lists changing without "columns": told, and told nothing when
    // it still fits or only moves.
    let mark = s.notice_mark();
    s.run("layout.update", &json!({"element": id, "h": 15})).unwrap();
    assert!(said(&s, mark).contains("its last rows are left out"), "{}", said(&s, mark));
    let mark = s.notice_mark();
    s.run("layout.update", &json!({"element": id, "x": 20})).unwrap();
    assert_eq!(said(&s, mark), "");
    let mark = s.notice_mark();
    s.run("layout.update", &json!({"element": id, "allClasses": true})).unwrap();
    assert!(said(&s, mark).contains("its last rows are left out"), "{}", said(&s, mark));
    let mark = s.notice_mark();
    s.run("layout.update", &json!({"element": id, "h": 150})).unwrap();
    s.run("layout.update", &json!({"element": id, "hideOther": true})).unwrap();
    assert_eq!(said(&s, mark), "");
    let mark = s.notice_mark();
    s.run("layout.update", &json!({"element": id, "w": 12})).unwrap();
    assert!(said(&s, mark).contains("they close up"), "{}", said(&s, mark));
    // In one column a change of its box says nothing, as before columns.
    s.run("layout.update", &json!({"element": id, "w": 150, "h": 150, "columns": 1})).unwrap();
    let mark = s.notice_mark();
    s.run("layout.update", &json!({"element": id, "h": 15})).unwrap();
    assert_eq!(said(&s, mark), "");
    // Nothing listed: nothing to lose, in a box shorter than its title too.
    let mut empty = Session::new(Project::default());
    empty.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
    empty.run("layout.new", &json!({"template": "map"})).unwrap();
    let mark = empty.notice_mark();
    let p = json!({"kind": "legend", "columns": 2, "exclude": ["a"], "x": 10, "y": 10, "w": 150, "h": 1});
    empty.run("layout.addElement", &p).unwrap();
    assert_eq!(said(&empty, mark), "");
    // A frame whose map is gone: said rather than left unchecked.
    s.project.maps[0].name = "Elsewhere".into();
    let mark = s.notice_mark();
    s.run("layout.update", &json!({"element": id, "columns": 2})).unwrap();
    assert!(said(&s, mark).contains("shows no map of this project"), "{}", said(&s, mark));
    let _ = std::fs::remove_dir_all(&dir);
}

/// A publication layout keys a raster theme with a colorbar: the topmost visible raster drawn on a
/// ramp gets one at the bottom of the legend's box; a map of vectors only gets none.
#[test]
fn a_publication_layouts_raster_gets_a_colorbar() {
    use rustgis_map::layout::ElementKind;
    let dir = std::env::temp_dir().join(format!("rustgis-colorbar-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let tif = dir.join("ramp.tif");
    std::fs::write(&tif, rustgis_data::raster::cog::example(256, 128)).unwrap();
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": tif.display().to_string()})).unwrap();
    let r = s.run("layout.publication", &json!({"extent": [10, 45, 11, 46], "author": "", "locator": "none"})).unwrap();
    let l = s.project.layouts.last().unwrap();
    let named = |n: &str| l.elements.iter().find(|e| e.name == n);
    let (bar, then) = (named("Colorbar").unwrap_or_else(|| panic!("no colorbar: {r}")), named("Legend Box").unwrap());
    let ElementKind::Colorbar { layer, title, .. } = &bar.kind else { panic!() };
    assert_eq!((layer.as_deref(), title.as_str()), (Some("ramp"), "ramp"));
    assert!(
        bar.x >= then.x && bar.x + bar.w <= then.x + then.w + 1e-9 && bar.y + bar.h <= then.y + then.h + 1e-9,
        "inside the legend's box"
    );
    s.run("layout.export", &json!({"path": dir.join("colorbar.png").display().to_string(), "dpi": 72})).unwrap();
    // Smaller boxes (figures, a locator taking room): the colorbar stays wholly inside its box, never
    // above its top, and a box too small for it says so, not that legend rows were cut.
    for profile in ["figure-1col", "thesis-half", "a4-landscape"] {
        let r = s.run("layout.publication", &json!({"extent": [10, 45, 11, 46], "profile": profile, "locator": "globe"})).unwrap();
        let l = s.project.layouts.last().unwrap();
        let named = |n: &str| l.elements.iter().find(|e| e.name == n);
        let (Some(bar), Some(then)) = (named("Colorbar"), named("Legend Box")) else { continue };
        let inside = bar.x >= then.x - 1e-9
            && bar.y >= then.y - 1e-9
            && bar.x + bar.w <= then.x + then.w + 1e-9
            && bar.y + bar.h <= then.y + then.h + 1e-9;
        assert!(inside, "{profile}: the colorbar outside its box: {r}");
    }
    // Vectors only: no colorbar.
    let mut s = world();
    s.run("layout.publication", &json!({"extent": [10, 45, 11, 46]})).unwrap();
    assert!(s.project.layouts.last().unwrap().elements.iter().all(|e| e.name != "Colorbar"));
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn layouts_compose_export_and_round_trip() {
    use base64::Engine;
    let dir = std::env::temp_dir().join(format!("rustgis-layout-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = world();
    s.run("map.goToXY", &json!({"lon": 10.0, "lat": 50.0, "scale": 20_000_000})).unwrap();
    let r = s.run("layout.new", &json!({"name": "Europe", "page": "a4", "orientation": "landscape"})).unwrap();
    assert_eq!(r["layout"], 0);
    assert_eq!(s.active_layout, Some(0));
    let l = &s.project.layouts[0];
    assert!((l.width - 297.0).abs() < 1e-9 && l.elements.len() == 6, "the map template adds a frame and five surrounds");
    let frame = l.first_frame().unwrap();
    // Frames, surrounds and the rest.
    for shape in ["circle", "ellipse", "polygon", "lasso"] {
        s.run("layout.addFrame", &json!({"shape": shape, "points": [[0, 0], [1, 0], [0.5, 1]]})).unwrap();
    }
    assert!(s.run("layout.addFrame", &json!({"shape": "polygon", "points": [[0, 0], [1, 0]]})).is_err());
    let mut png = tiny_skia::Pixmap::new(4, 4).unwrap();
    png.fill(tiny_skia::Color::from_rgba8(0, 128, 255, 255));
    let b64 = base64::engine::general_purpose::STANDARD.encode(png.encode_png().unwrap());
    for p in [
        json!({"kind": "table", "layer": "Countries", "rows": 5}),
        json!({"kind": "chart", "layer": "Countries", "field": "pop_est", "label": "name"}),
        json!({"kind": "rectangle"}),
        json!({"kind": "dynamicText", "text": "Page {page} of {pages} · {scale}"}),
        json!({"kind": "picture", "image": b64}),
        json!({"kind": "grid", "step": 10}),
    ] {
        s.run("layout.addElement", &p).unwrap_or_else(|e| panic!("{p}: {e}"));
    }
    // A chart moved to a layer without its field charts that layer's first numeric field.
    let chart = s.project.layouts[0].elements.iter().find(|e| e.kind.code() == "chart").unwrap().id;
    s.run("layout.update", &json!({"element": chart, "layer": "Cities"})).unwrap();
    let Some(rustgis_map::layout::ElementKind::Chart { layer, field, .. }) = s.project.layouts[0].element(chart).map(|e| &e.kind) else {
        panic!()
    };
    let cities = &s.map().layer_by_name("Cities").unwrap().dataset;
    assert_eq!(layer, "Cities");
    assert!(cities.field_index(field).is_some_and(|i| cities.fields[i].ty.is_numeric()), "{field}");
    s.run("layout.update", &json!({"element": chart, "layer": "Countries", "field": "pop_est"})).unwrap();
    let inset = s.run("layout.addFrame", &json!({"shape": "rectangle", "x": 200, "y": 150, "w": 60, "h": 40})).unwrap()["element"]
        .as_u64()
        .unwrap();
    s.run("layout.update", &json!({"element": inset, "scale": 200_000_000})).unwrap();
    s.run("layout.addElement", &json!({"kind": "extentIndicator", "frame": inset, "of": frame})).unwrap();
    assert!(s.run("layout.addElement", &json!({"kind": "extentIndicator", "frame": inset, "of": inset})).is_err());
    // Its colour and width (#213): red and 2 pt by default, set when added or later, and kept
    // through a save; `false` takes it away.
    let indicator = |s: &Session| match s.project.layouts[0].element(inset as u32).map(|e| &e.kind) {
        Some(rustgis_map::layout::ElementKind::MapFrame { extent_of, extent_color, extent_width, .. }) => {
            (*extent_of, extent_color.hex(), *extent_width)
        }
        _ => panic!("the inset is a map frame"),
    };
    assert_eq!(indicator(&s), (Some(frame), "#D01C1C".to_string(), 2.0));
    let saved = serde_json::to_string(&s.project.layouts[0]).unwrap();
    assert!(!saved.contains("extent_color") && !saved.contains("extent_width"), "defaults aren't written");
    s.run("layout.addElement", &json!({"kind": "extentIndicator", "frame": inset, "of": frame, "color": "#1F4E9A", "width": 0.75}))
        .unwrap();
    assert_eq!(indicator(&s), (Some(frame), "#1F4E9A".to_string(), 0.75));
    s.run("layout.update", &json!({"element": inset, "extentIndicator": {"width": 99}})).unwrap();
    assert_eq!(indicator(&s).2, rustgis_map::layout::MAX_INDICATOR_WIDTH, "clamped, and the colour kept");
    assert_eq!(indicator(&s).1, "#1F4E9A");
    let saved: rustgis_map::layout::Layout = serde_json::from_str(&serde_json::to_string(&s.project.layouts[0]).unwrap()).unwrap();
    assert!(saved.element(inset as u32).is_some_and(
        |e| matches!(&e.kind, rustgis_map::layout::ElementKind::MapFrame { extent_color, .. } if extent_color.hex() == "#1F4E9A")
    ));
    assert!(s.run("layout.update", &json!({"element": inset, "extentIndicator": {"color": "blue-ish"}})).is_err());
    assert!(s.run("layout.update", &json!({"element": inset, "extentIndicator": 3})).is_err());
    // A value given but not a colour or a number is refused, naming it, and changes nothing.
    for (bad, field) in [(json!({"width": "wide"}), "width"), (json!({"color": 123}), "color")] {
        let err = s.run("layout.update", &json!({"element": inset, "extentIndicator": bad})).unwrap_err();
        assert!(err.starts_with(field), "{err}");
        let mut add = json!({"kind": "extentIndicator", "frame": inset, "of": frame});
        add[field] = bad[field].clone();
        assert!(s.run("layout.addElement", &add).is_err_and(|e| e.starts_with(field)));
    }
    assert_eq!((indicator(&s).1.as_str(), indicator(&s).2), ("#1F4E9A", rustgis_map::layout::MAX_INDICATOR_WIDTH));
    s.run("layout.update", &json!({"element": inset, "extentIndicator": false})).unwrap();
    assert_eq!(indicator(&s).0, None);
    let err = s.run("layout.update", &json!({"element": inset, "extentIndicator": {"color": "#000000"}})).unwrap_err();
    assert!(err.contains("no extent indicator"), "{err}");
    s.run("layout.addElement", &json!({"kind": "extentIndicator", "frame": inset, "of": frame})).unwrap();
    assert!(s.run("layout.addElement", &json!({"kind": "sparkles"})).is_err());
    // A hairline rule keeps its height when added and when edited (#211).
    let rule = s.run("layout.addElement", &json!({"kind": "rectangle", "color": "#000000", "w": 136, "h": 0.15})).unwrap()["element"]
        .as_u64()
        .unwrap() as u32;
    assert_eq!(s.project.layouts[0].element(rule).map(|e| e.h), Some(0.15));
    s.run("layout.update", &json!({"element": rule, "h": 0.35})).unwrap();
    assert_eq!(s.project.layouts[0].element(rule).map(|e| e.h), Some(0.35));
    let err = s.run("layout.addElement", &json!({"kind": "rectangle", "h": 0})).unwrap_err();
    assert!(err.contains("more than 0"), "{err}");
    // Frame zooms and edits.
    s.run("layout.frameZoom", &json!({"element": frame, "to": "layer", "layer": "Lakes"})).unwrap();
    s.run("layout.update", &json!({"element": frame, "x": 12, "w": 180, "center": [10, 50]})).unwrap();
    assert!(s.run("layout.update", &json!({"element": 9999, "x": 1})).is_err());
    s.run("layout.update", &json!({"element": frame, "name": "Main map"})).unwrap();
    assert!(s.run("layout.update", &json!({"element": frame, "x": 99, "center": "Paris"})).is_err());
    assert!((s.project.layouts[0].element(frame).unwrap().x - 12.0).abs() < 1e-9, "a bad update changes nothing");
    let chart = s.project.layouts[0].elements.iter().find(|e| matches!(e.kind, rustgis_map::layout::ElementKind::Chart { .. })).unwrap().id;
    assert!(s.run("layout.update", &json!({"element": chart, "field": "no_such_field"})).is_err());
    assert!(s.run("layout.update", &json!({"element": chart, "layer": "Atlantis"})).is_err());
    s.run("layout.update", &json!({"element": chart, "field": "gdp_md"})).unwrap();
    assert_eq!(s.project.layouts[0].element(frame).unwrap().name, "Main map");
    // A map series over the lakes: one page each.
    let r = s.run("layout.series", &json!({"layer": "Lakes", "nameField": "name"})).unwrap();
    let pages = r["pages"].as_u64().unwrap();
    assert!(pages > 5);
    let next = s.run("layout.seriesPage", &json!({"page": "next"})).unwrap();
    assert_eq!(next["page"], 1);
    s.run("layout.seriesRefresh", &Value::Null).unwrap();
    // A manual zoom of the series frame survives exports.
    s.run("layout.update", &json!({"element": frame, "scale": 3_000_000})).unwrap();
    let scale_of = |s: &Session| match &s.project.layouts[0].element(frame).unwrap().kind {
        rustgis_map::layout::ElementKind::MapFrame { scale, .. } => *scale,
        _ => 0.0,
    };
    // Export PNG and a PDF of every page.
    let png_path = dir.join("europe.png");
    s.run("layout.export", &json!({"path": png_path.display().to_string(), "dpi": 72})).unwrap();
    let bytes = std::fs::read(&png_path).unwrap();
    assert!(bytes.starts_with(b"\x89PNG"));
    let pdf_path = dir.join("europe.pdf");
    let mark = s.notice_mark();
    s.run("layout.export", &json!({"path": pdf_path.display().to_string(), "dpi": 36})).unwrap();
    let pdf = std::fs::read(&pdf_path).unwrap();
    let count = format!("/Count {pages}");
    assert!(pdf.windows(count.len()).any(|w| w == count.as_bytes()), "one PDF page per series page");
    // Kept as vectors: its text in outline fonts, no page a picture, and nothing too large.
    let has = |needle: &[u8]| pdf.windows(needle.len()).any(|w| w == needle);
    assert!(has(b"/Subtype /Type3") && has(b"/ToUnicode") && has(b"/Contents"));
    assert!(!has(b"/Im0 Do"), "no page is one picture");
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("as pictures, not vectors")));
    assert_eq!(s.project.layouts[0].series.as_ref().unwrap().page, 1, "the shown page is restored");
    assert_eq!(scale_of(&s), 3_000_000.0, "and so is the frame's zoom");
    // A format the export has no writer for is refused.
    assert!(s.run("layout.export", &json!({"path": dir.join("x.tiff").display().to_string()})).is_err());
    // Layout files.
    let file = dir.join("europe.rgislayout");
    s.run("layout.save", &json!({"path": file.display().to_string()})).unwrap();
    s.run("layout.import", &json!({"path": file.display().to_string()})).unwrap();
    assert_eq!(s.project.layouts.len(), 2);
    assert_eq!(s.project.layouts[1].name, "Europe 2");
    assert!(s.run("layout.import", &json!({"text": "{}"})).is_err());
    // Removing the frame removes its surrounds; undo brings them back.
    let before = s.project.layouts[1].elements.len();
    let first = s.project.layouts[1].first_frame().unwrap();
    s.run("layout.removeElement", &json!({"layout": 1, "element": first})).unwrap();
    assert!(s.project.layouts[1].elements.len() < before - 3);
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.project.layouts[1].elements.len(), before);
    // Layouts are saved with the project.
    let text = serde_json::to_string(&s.project).unwrap();
    let p = crate::Project::from_json(&text).unwrap();
    assert_eq!(p.layouts.len(), 2);
    let r = s.run("layout.rename", &json!({"name": "Europe 2", "newName": "europe"})).unwrap();
    assert_eq!(r["name"], "europe 2", "renaming keeps names unique");
    s.run("layout.rename", &json!({"name": "europe 2", "newName": "Europe 2"})).unwrap();
    s.run("layout.close", &Value::Null).unwrap();
    assert_eq!(s.active_layout, None);
    s.run("layout.remove", &json!({"name": "Europe 2"})).unwrap();
    assert_eq!(s.project.layouts.len(), 1);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn custom_colour_ramps_add_apply_save_and_travel() {
    use rustgis_map::{Ramp, RasterRenderer, Renderer, Rgba};
    let dir = std::env::temp_dir().join(format!("rustgis-ramps-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = |n: &str| dir.join(n).display().to_string();
    let mut s = world();
    let file = r##"[
        {"name": "Phosphor Frostfire", "kind": "diverging", "stops": ["#eff6ff", "#7b5ca6", "#fff5da"]},
        {"name": "Brand", "kind": "qualitative", "stops": ["#112233", "#445566"]}
    ]"##;
    let r = s.run("ramp.add", &json!({"text": file})).unwrap();
    assert_eq!(r["added"], json!(["Phosphor Frostfire", "Brand"]));
    // One ramp on its own is a file too; the same name replaces it.
    s.run("ramp.add", &json!({"text": r##"{"name": "brand", "kind": "qualitative", "stops": ["#112233", "#445566", "#778899"]}"##}))
        .unwrap();
    assert_eq!(s.project.ramps.len(), 2);
    for bad in
        [r##"{"name": "Ember", "stops": ["#000000", "#ffffff"]}"##, r##"[]"##, r##"{"name": "x", "stops": ["#000000"]}"##, "not json"]
    {
        assert!(s.run("ramp.add", &json!({"text": bad})).is_err(), "{bad}");
    }
    assert_eq!(s.project.ramps.len(), 2, "a refused file adds nothing");
    assert_eq!(s.run("project.connections", &Value::Null).unwrap()["ramps"], json!(["Phosphor Frostfire", "brand"]));

    // Three classes from a three-stop ramp take its colours as they are.
    s.run(
        "layer.symbology",
        &json!({"layer": "Cities", "type": "graduated", "field": "pop_max", "classes": 3, "ramp": "phosphor frostfire"}),
    )
    .unwrap();
    let fills = |s: &Session| match &s.map().layer_by_name("Cities").unwrap().renderer {
        Renderer::Graduated { symbols, ramp, .. } => (symbols.iter().map(|y| y.fill).collect::<Vec<_>>(), ramp.name().to_string()),
        r => panic!("{r:?}"),
    };
    let stops = vec![Rgba::rgb(0xef, 0xf6, 0xff), Rgba::rgb(0x7b, 0x5c, 0xa6), Rgba::rgb(0xff, 0xf5, 0xda)];
    assert_eq!(fills(&s), (stops.clone(), "Phosphor Frostfire".to_string()));
    // Color Scheme recolours with a custom ramp too.
    s.run("layer.ramp", &json!({"layer": "Countries", "ramp": "Brand"})).unwrap();
    assert!(s.run("layer.ramp", &json!({"layer": "Countries", "ramp": "Nope"})).is_err());

    // Saved with the project, and inside the layer's renderer.
    let p = crate::Project::from_json(&serde_json::to_string(&s.project).unwrap()).unwrap();
    assert_eq!(p.ramps, s.project.ramps);
    // A layer file carries the ramp to a project that doesn't have it.
    s.run("layer.save", &json!({"layer": "Cities", "path": path("cities.rgislyr")})).unwrap();
    s.run("ramp.save", &json!({"path": path("mine.rgisramp")})).unwrap();
    s.run("ramp.remove", &json!({"name": "PHOSPHOR FROSTFIRE"})).unwrap();
    assert!(s.run("ramp.remove", &json!({"name": "Phosphor Frostfire"})).is_err());
    assert_eq!(fills(&s).0, stops, "removing a ramp leaves layers that use it alone");
    // ...which can still be restyled with it, by name or by leaving the ramp out.
    let grad = json!({"layer": "Cities", "type": "graduated", "field": "pop_max", "classes": 3, "method": "quantile"});
    let mut named = grad.clone();
    named["ramp"] = json!("Phosphor Frostfire");
    s.run("layer.symbology", &named).unwrap();
    assert_eq!(fills(&s), (stops.clone(), "Phosphor Frostfire".to_string()));
    s.run("layer.symbology", &grad).unwrap();
    assert_eq!(fills(&s).1, "Phosphor Frostfire", "a ramp left out is kept");
    named["ramp"] = json!("Nope");
    assert!(s.run("layer.symbology", &named).is_err(), "an unknown ramp is an error");
    // A hand-edited project's repeated or built-in names are made unique, keeping every ramp.
    let mut p = s.project.clone();
    p.ramps = serde_json::from_str(
        r##"[{"name": "Brand", "stops": ["#000000", "#ffffff"]}, {"name": "brand", "stops": ["#111111", "#ffffff"]},
            {"name": "Ember", "stops": ["#222222", "#ffffff"]}, {"name": "jet", "stops": ["#333333", "#ffffff"]}]"##,
    )
    .unwrap();
    let jet = p.ramps.last().cloned().unwrap();
    fn graduated(p: &mut Project) -> Option<&mut Renderer> {
        p.maps.iter_mut().flat_map(|m| m.layers.iter_mut()).find(|l| l.name == "Cities").map(|l| &mut l.renderer)
    }
    if let Some(Renderer::Graduated { ramp, .. }) = graduated(&mut p) {
        *ramp = Ramp::Custom(Box::new(jet.clone()));
    }
    p.normalize();
    // The matplotlib library's names are built-in too: an older project's own "jet" is kept as
    // "jet (custom)", while layers keep the copy of it they hold.
    assert_eq!(p.ramps.iter().map(|r| r.name()).collect::<Vec<_>>(), ["Brand", "brand 2", "Ember (custom)", "jet (custom)"]);
    assert!(matches!(graduated(&mut p), Some(Renderer::Graduated { ramp: Ramp::Custom(c), .. }) if **c == jet));
    let mut t = world();
    t.run("layer.addData", &json!({"path": path("cities.rgislyr")})).unwrap();
    match &t.map().layer_by_name("Cities (2)").unwrap().renderer {
        Renderer::Graduated { symbols, ramp: Ramp::Custom(c), .. } => {
            assert_eq!(c.name(), "Phosphor Frostfire");
            assert_eq!(symbols.iter().map(|y| y.fill).collect::<Vec<_>>(), stops);
        }
        r => panic!("{r:?}"),
    }
    // The saved file adds them back.
    t.run("ramp.add", &json!({"path": path("mine.rgisramp")})).unwrap();
    assert_eq!(t.project.ramps.len(), 2);
    assert!(Session::new(Project::default()).run("ramp.save", &json!({"path": path("none.rgisramp")})).is_err());

    // Rasters: stretch and classify with a custom ramp.
    let mut r = with_raster();
    r.run("ramp.add", &json!({"path": path("mine.rgisramp")})).unwrap();
    r.run("raster.symbology", &json!({"type": "stretch", "ramp": "Phosphor Frostfire"})).unwrap();
    let style = |r: &Session| r.map().layers.first().unwrap().raster.as_ref().unwrap().style.renderer.clone();
    assert!(matches!(style(&r), RasterRenderer::Stretch { ramp: Ramp::Custom(_), .. }));
    r.run("raster.symbology", &json!({"type": "classify", "classes": 3})).unwrap();
    assert!(matches!(style(&r), RasterRenderer::Classify { ramp: Ramp::Custom(_), .. }), "classify keeps the ramp");
    r.run("ramp.remove", &json!({"name": "Phosphor Frostfire"})).unwrap();
    r.run("raster.symbology", &json!({"type": "classify", "classes": 4, "ramp": "Phosphor Frostfire"})).unwrap();
    assert!(matches!(style(&r), RasterRenderer::Classify { ramp: Ramp::Custom(_), .. }), "the raster's own copy is found by name");
    assert!(r.run("raster.symbology", &json!({"type": "stretch", "ramp": "Nope"})).is_err());
    assert!(crate::cmd::share::map_png(&mut r, Some(200.0), Some(150.0), None).unwrap().len() > 1000);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn colour_ramps_from_qgis_gdal_and_gmt_files() {
    use rustgis_map::color::RampKind;
    let dir = std::env::temp_dir().join(format!("rustgis-palettes-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = |n: &str| dir.join(n).display().to_string();
    let mut s = world();
    // A GMT palette by path: named after the file, with the kind given.
    std::fs::write(path("relief.cpt"), "-100 0/0/255 0 255/255/255\n0 255/255/255 100 255/0/0\n").unwrap();
    let r = s.run("ramp.add", &json!({"path": path("relief.cpt"), "kind": "diverging"})).unwrap();
    assert_eq!(r["added"], json!(["relief"]));
    assert_eq!(s.project.ramps[0].kind(), RampKind::Diverging);
    // GDAL colour-relief text, as the web app passes a picked file: its bytes and name.
    use base64::Engine;
    let data = base64::engine::general_purpose::STANDARD.encode("0, 0, 0, 0, 255\n10, 255, 255, 255, 255\nnv, 0, 0, 0, 0\n");
    let r = s.run("ramp.add", &json!({"data": data, "file": "Grey.txt"})).unwrap();
    assert_eq!(r["added"], json!(["Grey"]));
    // A QGIS style as text, with the format named.
    let xml = r#"<!DOCTYPE qgis_style><qgis_style version="2"><colorramps><colorramp type="gradient" name="Q"><Option type="Map">
        <Option type="QString" name="color1" value="0,0,0,255"/><Option type="QString" name="color2" value="255,255,255,255"/>
        </Option></colorramp></colorramps></qgis_style>"#;
    s.run("ramp.add", &json!({"text": xml, "format": "qgis", "name": "From QGIS"})).unwrap();
    assert_eq!(s.project.ramps.iter().map(|r| r.name()).collect::<Vec<_>>(), ["relief", "Grey", "From QGIS"]);
    s.run("layer.ramp", &json!({"layer": "Countries", "ramp": "relief"})).unwrap();
    for bad in [
        json!({"text": xml, "format": "svg"}),
        json!({"text": xml, "kind": "round"}),
        json!({"text": r##"{"name": "Ember", "stops": ["#000000", "#ffffff"]}"##}),
    ] {
        assert!(s.run("ramp.add", &bad).is_err(), "{bad}");
    }
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn project_items_files_styles_packages_tasks_and_3d() {
    let dir = std::env::temp_dir().join(format!("rustgis-items-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = |n: &str| dir.join(n).display().to_string();
    let mut s = world();
    // Folder connections.
    s.run("project.addFolder", &json!({"path": dir.display().to_string()})).unwrap();
    assert!(s.run("project.addFolder", &json!({"path": path("missing")})).is_err());
    assert_eq!(s.run("project.connections", &Value::Null).unwrap()["folders"][0]["available"], true);
    // Map and layer files.
    s.run("map.save", &json!({"path": path("world.rgismap")})).unwrap();
    s.run("map.import", &json!({"path": path("world.rgismap")})).unwrap();
    assert_eq!(s.project.maps.len(), 2);
    assert_eq!(s.project.maps[1].name, "World (2)");
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "single", "color": "#AA00FF"})).ok();
    s.run("layer.save", &json!({"layer": "Cities", "path": path("cities.rgislyr")})).unwrap();
    let n = s.map().layers.len();
    s.run("layer.addData", &json!({"path": path("cities.rgislyr")})).unwrap();
    assert_eq!(s.map().layers.len(), n + 1);
    assert!(s.map().layer_by_name("Cities (2)").is_some());
    // Styles.
    s.run("style.new", &json!({"layer": "Countries", "name": "Choropleth"})).unwrap();
    s.run("style.save", &json!({"path": path("styles.rgisstyle")})).unwrap();
    s.run("style.remove", &json!({"name": "Choropleth"})).unwrap();
    s.run("style.add", &json!({"path": path("styles.rgisstyle")})).unwrap();
    assert!(s.run("style.apply", &json!({"name": "Choropleth", "layer": "Cities"})).is_err(), "polygon style on points");
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "single"})).unwrap();
    s.run("style.apply", &json!({"name": "Choropleth", "layer": "Countries"})).unwrap();
    assert_eq!(s.map().layer_by_name("Countries").unwrap().renderer.kind_label(), "Graduated Colors");
    let r = s.run("style.import", &json!({"path": path("world.rgismap")})).unwrap();
    assert!(r["imported"].as_u64().unwrap() >= 4);
    // Templates keep the setup, not the features.
    s.run("project.saveTemplate", &json!({"path": path("atlas.rgistemplate")})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.fromTemplate", &json!({"path": path("atlas.rgistemplate"), "name": "From template"})).unwrap();
    assert_eq!(t.project.name, "From template");
    assert!(t.map().layer_by_name("Countries").unwrap().dataset.features.is_empty());
    assert!(!t.project.styles.is_empty());
    // Packages open again.
    s.run("project.package", &json!({"path": path("atlas.rgispkg")})).unwrap();
    let mut o = Session::new(Project::default());
    o.run("project.open", &json!({"path": path("atlas.rgispkg")})).unwrap();
    assert_eq!(o.project.maps.len(), 2);
    assert!(o.path.is_none(), "a package opens unsaved");
    // The desktop app's command line and a dropped file open it as a project too (#411).
    let pkg = path("atlas.rgispkg");
    assert_eq!(crate::project::open_command(&pkg), "project.open");
    let mut d = Session::new(Project::default());
    d.run(crate::project::open_command(&pkg), &json!({"path": pkg})).unwrap();
    assert_eq!(d.project.maps.len(), 2);
    assert!(d.path.is_none(), "a package opens unsaved, so Save asks where to write a project");
    s.run("map.package", &json!({"path": path("world.rgismpk"), "mobile": true, "tolerance": 0.05})).unwrap();
    s.run("map.import", &json!({"path": path("world.rgismpk")})).unwrap();
    let full: usize = s.project.maps[0]
        .layer_by_name("Countries")
        .unwrap()
        .dataset
        .features
        .iter()
        .filter_map(|f| f.geometry.as_ref())
        .map(|g| g.coord_count())
        .sum();
    let mobile: usize = s
        .project
        .maps
        .last()
        .unwrap()
        .layer_by_name("Countries")
        .unwrap()
        .dataset
        .features
        .iter()
        .filter_map(|f| f.geometry.as_ref())
        .map(|g| g.coord_count())
        .sum();
    assert!(mobile < full, "mobile packages simplify: {mobile} < {full}");
    assert!(s.run("gp.package", &json!({"path": path("results.rgisgpk")})).is_err(), "no runs yet");
    s.run("map.activate", &json!({"name": "World"})).unwrap();
    s.run("gp.run", &json!({"tool": "buffer", "params": {"input": "Cities", "distance": 100}})).unwrap();
    s.run("gp.package", &json!({"path": path("results.rgisgpk")})).unwrap();
    let entries = rustgis_data::zip::read(&std::fs::read(path("results.rgisgpk")).unwrap()).unwrap();
    assert!(entries.iter().any(|(n, _)| n == "history.json") && entries.iter().any(|(n, _)| n.starts_with("results/")));
    // Layer templates.
    let id = s.run("layer.template", &json!({"template": "places"})).unwrap()["layer"].as_u64().unwrap() as u32;
    assert_eq!(s.map().layer(id).unwrap().dataset.fields.len(), 4);
    assert!(s.run("layer.template", &json!({"template": "unicorns"})).is_err());
    // Tasks.
    s.run("task.new", &json!({"name": "Explore", "steps": [{"title": "Zoom to Europe", "command": "map.goToXY", "params": {"lon": 10, "lat": 50, "scale": 20000000}}, {"title": "Select big countries", "command": "select.byAttributes", "params": {"layer": "Countries", "where": "pop_est > 50000000"}}]})).unwrap();
    assert!(s.run("task.new", &json!({"steps": [{"title": "x", "command": "no.such"}]})).is_err());
    let r = s.run("task.run", &json!({"task": "Explore"})).unwrap();
    assert_eq!(r["ran"].as_array().unwrap().len(), 2);
    assert!(s.map().selection_count() > 5);
    s.run("task.addStep", &json!({"task": "Explore", "title": "Clear", "command": "select.clear"})).unwrap();
    s.run("task.run", &json!({"task": "Explore", "step": 2})).unwrap();
    assert_eq!(s.map().selection_count(), 0);
    s.run("task.new", &json!({"name": "Replay", "fromHistory": true})).unwrap();
    assert!(s.item_trusted("task", "replay"), "history run in this session");
    // History that came with an opened project is someone else's.
    s.history_from_file = 1;
    s.run("task.new", &json!({"name": "Replay file", "fromHistory": true})).unwrap();
    assert!(!s.item_trusted("task", "replay file"));
    s.history_from_file = 0;
    assert_eq!(s.project.tasks.last().unwrap().steps.len(), 1);
    s.run("task.save", &json!({"task": "Explore", "path": path("explore.rgistask")})).unwrap();
    s.run("task.import", &json!({"path": path("explore.rgistask")})).unwrap();
    assert_eq!(s.project.tasks.last().unwrap().name, "Explore 2");
    // A task file may not touch files or run scripts.
    let sneaky =
        json!({"name": "Sneaky", "steps": [{"title": "Overwrite", "command": "share.exportMap", "params": {"path": path("x.png")}}]});
    assert!(s.run("task.import", &json!({"text": sneaky.to_string()})).is_err());
    let nested = json!({"name": "Nested", "steps": [{"title": "Run", "command": "script.run", "params": {"script": "map.zoomFull"}}]});
    assert!(s.run("task.import", &json!({"text": nested.to_string()})).is_err());
    // A task arriving inside a project file is vetted when it runs.
    s.project.tasks.push(crate::project::Task {
        name: "From a file".into(),
        description: String::new(),
        steps: vec![crate::project::TaskStep {
            title: "Export".into(),
            instructions: String::new(),
            command: "share.exportMap".into(),
            params: json!({"path": path("y.png")}),
        }],
    });
    assert!(s.run("task.run", &json!({"task": "From a file"})).is_err());
    assert!(!std::path::Path::new(&path("y.png")).exists());
    // A step naming a feature layer runs even when a raster is selected.
    s.run("task.new", &json!({"name": "Layered", "steps": [{"title": "Zoom", "command": "layer.zoomTo", "params": {"layer": "Lakes"}}]}))
        .unwrap();
    s.run("task.run", &json!({"task": "Layered"})).unwrap();
    // 3D export: polygons extruded by a field.
    s.run("share.export3d", &json!({"layer": "Countries", "path": path("countries.obj"), "heightField": "pop_est", "zScale": 0.00001}))
        .unwrap();
    let obj = std::fs::read_to_string(path("countries.obj")).unwrap();
    assert!(obj.lines().filter(|l| l.starts_with("v ")).count() > 1000 && obj.contains("\nf "));
    // Caps are triangles, and every face refers to a written vertex.
    let verts = obj.lines().filter(|l| l.starts_with("v ")).count();
    assert!(obj.lines().filter(|l| l.starts_with("f ")).all(|l| {
        let ids: Vec<usize> = l[2..].split_whitespace().map(|x| x.parse().unwrap()).collect();
        (3..=4).contains(&ids.len()) && ids.iter().all(|i| (1..=verts).contains(i))
    }));
    let (name, bytes) = crate::cmd::items::item_bytes(&mut s, "obj", &json!({"layer": "Cities"})).unwrap();
    assert!(name.ends_with(".obj") && !bytes.is_empty());
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn data_design_rules_hold_on_every_edit() {
    let mut s = world();
    s.run("layer.template", &json!({"template": "routes", "name": "Roads"})).unwrap();
    s.run("edit.addField", &json!({"layer": "Roads", "name": "kind", "type": "long"})).unwrap();
    s.run("edit.addField", &json!({"layer": "Roads", "name": "lanes", "type": "long"})).unwrap();
    // Domains.
    s.run("data.domain", &json!({"layer": "Roads", "field": "surface", "coded": [["paved", "Paved"], ["gravel", "Gravel"]]})).unwrap();
    s.run("data.domain", &json!({"layer": "Roads", "field": "lanes", "min": 1, "max": 8})).unwrap();
    assert!(s.run("data.domain", &json!({"layer": "Roads", "field": "name", "min": 1, "max": 2})).is_err(), "text takes coded values");
    let line = json!({"type": "LineString", "coordinates": [[0, 0], [1, 1]]});
    s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line, "attributes": {"surface": "paved", "lanes": 2}})).unwrap();
    assert!(s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line, "attributes": {"surface": "ice"}})).is_err());
    assert!(s.run("edit.setValue", &json!({"layer": "Roads", "row": 0, "field": "lanes", "value": 12})).is_err());
    assert_eq!(s.map().layer_by_name("Roads").unwrap().dataset.features.len(), 1, "the failed edits were undone");
    // Subtypes fill defaults on new features.
    s.run("data.subtypes", &json!({"layer": "Roads", "field": "kind", "subtypes": [{"code": 1, "name": "Highway", "defaults": {"lanes": 4}}, {"code": 2, "name": "Street", "defaults": {"lanes": 1}}]})).unwrap();
    assert!(s.run("data.subtypes", &json!({"layer": "Roads", "field": "name", "subtypes": [{"code": 1, "name": "x"}]})).is_err());
    let r = s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line, "attributes": {"kind": 1}})).unwrap();
    let row = r["row"].as_u64().unwrap() as usize;
    let lanes = |s: &Session, row: usize| {
        let l = s.map().layer_by_name("Roads").unwrap();
        l.dataset.value(row, l.dataset.field_index("lanes").unwrap()).clone()
    };
    assert_eq!(lanes(&s, row).as_f64(), Some(4.0));
    // Attribute rules: a calculation and a constraint.
    s.run(
        "data.attributeRule",
        &json!({"layer": "Roads", "name": "Length", "kind": "calculation", "field": "length_km", "expression": "lanes * 10"}),
    )
    .unwrap();
    s.run(
        "data.attributeRule",
        &json!({"layer": "Roads", "name": "Named highways", "kind": "constraint", "expression": "kind <> 1 OR name IS NOT NULL"}),
    )
    .unwrap();
    assert!(
        s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line, "attributes": {"kind": 1}})).is_err(),
        "highways need names"
    );
    let r = s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line, "attributes": {"kind": 1, "name": "A1"}})).unwrap();
    let row = r["row"].as_u64().unwrap() as usize;
    let l = s.map().layer_by_name("Roads").unwrap();
    assert_eq!(l.dataset.value(row, l.dataset.field_index("length_km").unwrap()).as_f64(), Some(40.0));
    assert!(s.run("data.attributeRule", &json!({"layer": "Roads", "name": "Bad", "kind": "constraint", "expression": "(("})).is_err());
    s.run("data.attributeRule", &json!({"layer": "Roads", "name": "Named highways", "remove": true})).unwrap();
    // Deleting a field a rule uses drops the rule, so editing isn't blocked.
    s.run("edit.addField", &json!({"layer": "Roads", "name": "temp", "type": "double"})).unwrap();
    s.run("data.attributeRule", &json!({"layer": "Roads", "name": "Temp", "kind": "constraint", "expression": "temp IS NULL OR temp > 0"}))
        .unwrap();
    let r = s.run("edit.deleteField", &json!({"layer": "Roads", "field": "temp"})).unwrap();
    assert_eq!(r["rulesRemoved"], 1);
    s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line, "attributes": {"kind": 2}})).unwrap();
    // Contingent values.
    s.run("data.contingentValues", &json!({"layer": "Roads", "name": "Surface by kind", "fields": ["kind", "surface"], "combos": [[1, "paved"], [2, "paved"], [2, "gravel"]]})).unwrap();
    assert!(
        s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line, "attributes": {"kind": 1, "surface": "gravel"}})).is_err()
    );
    s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line, "attributes": {"kind": 2, "surface": "gravel"}})).unwrap();
    // Templates.
    s.run("edit.template", &json!({"layer": "Roads", "name": "Gravel street", "defaults": {"kind": 2, "surface": "gravel"}})).unwrap();
    let r = s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line, "template": "Gravel street"})).unwrap();
    assert_eq!(lanes(&s, r["row"].as_u64().unwrap() as usize).as_f64(), Some(1.0), "template, then subtype defaults");
    // Archive and restore.
    s.run("data.archive", &json!({"layer": "Roads"})).unwrap();
    let t0 = web_time::SystemTime::now().duration_since(web_time::UNIX_EPOCH).unwrap().as_secs_f64() - 0.001;
    let n = s.map().layer_by_name("Roads").unwrap().dataset.features.len();
    s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line, "template": "Gravel street"})).unwrap();
    s.run("edit.setValue", &json!({"layer": "Roads", "row": 0, "field": "name", "value": "Main"})).unwrap();
    let h = s.run("data.archiveHistory", &json!({"layer": "Roads"})).unwrap();
    assert_eq!(h["edits"], 2);
    s.run("data.archiveRestore", &json!({"layer": "Roads", "time": t0})).unwrap();
    let l = s.map().layer_by_name("Roads").unwrap();
    assert_eq!(l.dataset.features.len(), n);
    assert!(l.dataset.value(0, l.dataset.field_index("name").unwrap()).is_null());
    // Edit status, and turning editing off.
    let st = s.run("edit.status", &Value::Null).unwrap();
    assert!(st["layers"].as_array().unwrap().iter().any(|l| l["layer"] == "Roads" && l["added"].as_u64().unwrap() >= 5));
    s.run("edit.enable", &json!({"on": false})).unwrap();
    assert!(s.run("edit.addFeature", &json!({"layer": "Roads", "geometry": line})).is_err());
    s.run("edit.enable", &json!({"on": true})).unwrap();
}

#[test]
fn split_refuses_a_line_with_a_latitude_past_the_poles() {
    let mut s = world();
    s.run("layer.template", &json!({"template": "lines", "name": "Paths"})).unwrap();
    let add = |s: &mut Session, coords: Value| {
        s.run("edit.addFeature", &json!({"layer": "Paths", "geometry": {"type": "LineString", "coordinates": coords}})).unwrap()
    };
    add(&mut s, json!([[0, 88], [5, 88]]));
    let bad = add(&mut s, json!([[0, 88], [0, 95], [10, 88]]))["row"].as_u64().unwrap() as usize;
    let before = s.map().layer_by_name("Paths").unwrap().dataset.features.clone();
    // Both lines are selected: the one past the pole is refused, and neither is split.
    s.run("select.rows", &json!({"layer": "Paths", "rows": [0, bad]})).unwrap();
    assert!(s.run("edit.split", &json!({"lon": 2, "lat": 88})).is_err());
    assert_eq!(s.map().layer_by_name("Paths").unwrap().dataset.features, before);
    // Without it, the same split works.
    s.run("select.rows", &json!({"layer": "Paths", "rows": [0]})).unwrap();
    s.run("edit.split", &json!({"lon": 2, "lat": 88})).unwrap();
    assert_eq!(s.map().layer_by_name("Paths").unwrap().dataset.features.len(), before.len() + 1);
}

#[test]
fn modify_tools_snapping_topology_relationships_and_elevation() {
    let mut s = with_raster();
    s.run("layer.template", &json!({"template": "lines", "name": "Paths"})).unwrap();
    let add = |s: &mut Session, coords: Value| {
        s.run("edit.addFeature", &json!({"layer": "Paths", "geometry": {"type": "LineString", "coordinates": coords}})).unwrap()["row"]
            .as_u64()
            .unwrap() as usize
    };
    let a = add(&mut s, json!([[0, 0], [1, 0]]));
    // Move one degree east (about 111 km at the equator), then rotate and scale.
    s.run("select.rows", &json!({"layer": "Paths", "rows": [a]})).unwrap();
    s.run("edit.move", &json!({"dx": 111_319.5, "dy": 0})).unwrap();
    let first = |s: &Session, row: usize| match s.map().layer_by_name("Paths").unwrap().dataset.features[row].geometry.as_ref().unwrap() {
        rustgis_data::Geometry::Line(p) => p[0][0],
        _ => panic!("not a line"),
    };
    assert!((first(&s, a).x - 1.0).abs() < 1e-3, "{:?}", first(&s, a));
    s.run("edit.rotate", &json!({"angle": 90})).unwrap();
    s.run("edit.scale", &json!({"factor": 2})).unwrap();
    s.run("edit.flip", &Value::Null).unwrap();
    // Split, then merge back, then explode.
    let b = add(&mut s, json!([[10, 10], [12, 10]]));
    s.run("select.rows", &json!({"layer": "Paths", "rows": [b]})).unwrap();
    s.run("edit.split", &json!({"lon": 11, "lat": 10.2})).unwrap();
    let n = s.map().layer_by_name("Paths").unwrap().dataset.features.len();
    s.run("select.rows", &json!({"layer": "Paths", "rows": [b, n - 1]})).unwrap();
    // A merge the rules reject leaves the layer as it was.
    s.run("data.attributeRule", &json!({"layer": "Paths", "name": "Never", "kind": "constraint", "expression": "name = 'never'"})).unwrap();
    let before = s.map().layer_by_name("Paths").unwrap().dataset.features.clone();
    assert!(s.run("edit.merge", &Value::Null).is_err());
    assert_eq!(s.map().layer_by_name("Paths").unwrap().dataset.features, before);
    s.run("data.attributeRule", &json!({"layer": "Paths", "name": "Never", "remove": true})).unwrap();
    s.run("select.rows", &json!({"layer": "Paths", "rows": [b, n - 1]})).unwrap();
    s.run("edit.merge", &Value::Null).unwrap();
    assert_eq!(s.map().layer_by_name("Paths").unwrap().dataset.features.len(), n - 1);
    s.run("edit.explode", &Value::Null).unwrap();
    assert_eq!(s.map().layer_by_name("Paths").unwrap().dataset.features.len(), n);
    assert!(s.run("edit.setGeometry", &json!({"layer": "Paths", "row": 0, "geometry": {"type": "Point", "coordinates": [0, 0]}})).is_err());
    s.run("edit.setGeometry", &json!({"layer": "Paths", "row": 0, "geometry": {"type": "LineString", "coordinates": [[0, 0], [0, 1]]}}))
        .unwrap();
    // Vertex editing (the Edit Vertices tool): insert, move and delete, one undo step each.
    let line = |s: &Session| match s.map().layer_by_name("Paths").unwrap().dataset.features[0].geometry.as_ref().unwrap() {
        rustgis_data::Geometry::Line(p) => p[0].iter().map(|c| [c.x, c.y]).collect::<Vec<_>>(),
        _ => panic!("not a line"),
    };
    let r = s.run("edit.vertex", &json!({"layer": "Paths", "row": 0, "action": "insert", "index": 0, "lon": 0.5, "lat": 0.5})).unwrap();
    assert_eq!(r["index"], 1, "the new vertex");
    assert_eq!(line(&s), [[0.0, 0.0], [0.5, 0.5], [0.0, 1.0]]);
    s.run("edit.vertex", &json!({"layer": "Paths", "row": 0, "action": "move", "index": 2, "lon": 1, "lat": 1})).unwrap();
    assert_eq!(line(&s), [[0.0, 0.0], [0.5, 0.5], [1.0, 1.0]]);
    s.run("edit.vertex", &json!({"layer": "Paths", "row": 0, "action": "delete", "index": 1})).unwrap();
    assert_eq!(line(&s), [[0.0, 0.0], [1.0, 1.0]]);
    assert!(s.run("edit.vertex", &json!({"layer": "Paths", "row": 0, "action": "delete", "index": 1})).is_err(), "a line keeps two");
    assert!(s.run("edit.vertex", &json!({"layer": "Paths", "row": 0, "action": "move", "index": 7, "lon": 1, "lat": 1})).is_err());
    assert!(s.run("edit.vertex", &json!({"layer": "Paths", "row": 0, "action": "move", "index": 0, "lon": 1e9, "lat": 1})).is_err());
    for bad in [json!(-1), json!("2"), json!(0.5)] {
        assert!(
            s.run("edit.vertex", &json!({"layer": "Paths", "row": 0, "action": "move", "part": bad, "index": 0, "lon": 1, "lat": 1}))
                .is_err(),
            "part {bad}"
        );
    }
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(line(&s), [[0.0, 0.0], [0.5, 0.5], [1.0, 1.0]], "undo brings the deleted vertex back");
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(line(&s), [[0.0, 0.0], [0.5, 0.5], [0.0, 1.0]]);
    // Traverse: two legs from a start, ground to grid off and on.
    s.run("layer.select", &json!({"layer": "Paths"})).unwrap();
    let r = s
        .run("edit.traverse", &json!({"start": [20, 0], "legs": [{"distance": 1000, "bearing": 90}, {"distance": 1000, "bearing": 0}]}))
        .unwrap();
    let row = r["row"].as_u64().unwrap() as usize;
    let end = |s: &Session, row: usize| match s.map().layer_by_name("Paths").unwrap().dataset.features[row].geometry.as_ref().unwrap() {
        rustgis_data::Geometry::Line(p) => *p[0].last().unwrap(),
        _ => panic!("not a line"),
    };
    let e = end(&s, row);
    assert!((e.x - 20.008983).abs() < 1e-5 && (e.y - 0.009043).abs() < 1e-4, "{e:?}");
    s.run("edit.groundToGrid", &json!({"scale": 1.5, "rotation": 0})).unwrap();
    let r = s.run("edit.traverse", &json!({"start": [20, 0], "legs": [{"distance": 1000, "bearing": 90}]})).unwrap();
    assert!((end(&s, r["row"].as_u64().unwrap() as usize).x - 20.013475).abs() < 1e-5);
    assert!(s.run("edit.groundToGrid", &json!({"scale": 9})).is_err());
    s.run("edit.groundToGrid", &json!({"on": false})).unwrap();
    // Snapping to a vertex near the pointer.
    s.run("map.goToXY", &json!({"lon": 20, "lat": 0, "scale": 50_000})).unwrap();
    let off = s.run("edit.snap", &json!({"lon": 20.0001, "lat": 0.0001})).unwrap();
    assert_eq!(off["snapped"], false, "snapping is off");
    s.run("edit.snapping", &json!({"on": true, "tolerancePx": 20})).unwrap();
    let on = s.run("edit.snap", &json!({"lon": 20.0001, "lat": 0.0001})).unwrap();
    assert_eq!(on["snapped"], true);
    assert!((on["lon"].as_f64().unwrap() - 20.0).abs() < 1e-9 && on["lat"].as_f64().unwrap().abs() < 1e-9, "{on}");
    // A dragged vertex doesn't snap to the feature it belongs to.
    s.run("map.goToXY", &json!({"lon": 0.5, "lat": 0.5, "scale": 50_000})).unwrap();
    let paths = s.map().layer_by_name("Paths").unwrap().id;
    let near = rustgis_geom::Coord::new(0.5001, 0.5001);
    let own = crate::cmd::design::snap_except(&mut s, near, None).map(|(c, _)| c);
    assert!(own.is_some_and(|c| (c.x - 0.5).abs() < 1e-9 && (c.y - 0.5).abs() < 1e-9), "the line's own vertex: {own:?}");
    assert_eq!(crate::cmd::design::snap_except(&mut s, near, Some((paths, 0))), None);
    // Topology: overlapping countries? Lakes inside countries? Dangling paths.
    s.run("topology.rules", &json!({"add": {"rule": "mustNotHaveDangles", "layer": "Paths"}})).unwrap();
    s.run("topology.rules", &json!({"add": {"rule": "mustBeCoveredBy", "layer": "Cities", "by": "Countries"}})).unwrap();
    assert!(s.run("topology.rules", &json!({"add": {"rule": "mustNotOverlap", "layer": "Paths"}})).is_err(), "overlap is for polygons");
    let v = s.run("topology.validate", &Value::Null).unwrap();
    assert!(v["errors"].as_u64().unwrap() > 0);
    assert_eq!(s.topology_errors.len() as u64, v["errors"].as_u64().unwrap());
    // Relationships: cities to their country by ISO code.
    s.run("data.relate", &json!({"name": "Country of city", "origin": "Countries", "originKey": "name", "destination": "Cities", "destinationKey": "adm0name"})).unwrap();
    assert!(
        s.run(
            "data.relate",
            &json!({"name": "x", "origin": "Countries", "originKey": "nope", "destination": "Cities", "destinationKey": "adm0name"})
        )
        .is_err()
    );
    s.run("select.byAttributes", &json!({"layer": "Countries", "where": "name = 'France'"})).unwrap();
    let rel = s.run("data.related", &Value::Null).unwrap();
    assert!(rel["related"].as_u64().unwrap() >= 1, "{rel}");
    // Elevation from the raster surface goes in z.
    s.run("edit.elevation", &json!({"mode": "constant", "z": 125})).unwrap();
    s.run("layer.template", &json!({"template": "points", "name": "Spots"})).unwrap();
    s.run("edit.addFeature", &json!({"layer": "Spots", "geometry": {"type": "Point", "coordinates": [0, 0]}})).unwrap();
    let l = s.map().layer_by_name("Spots").unwrap();
    assert_eq!(l.dataset.value(0, l.dataset.field_index("z").unwrap()).as_f64(), Some(125.0));
    assert!(s.run("edit.elevation", &json!({"mode": "surface", "surface": "Cities"})).is_err(), "not a raster");
    let tools = s.run("edit.tools", &Value::Null).unwrap();
    assert!(tools.as_array().unwrap().len() >= 9);
}

/// A 40×40 lon/lat DEM near (10°E, 45°N): a hill in the middle, with a wall to its east.
fn dem_b64() -> String {
    use base64::Engine;
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let gt = GeoTransform { origin_x: 10.0, origin_y: 45.04, pixel_width: 0.001, pixel_height: -0.001 };
    let z: Vec<f32> = (0..1600)
        .map(|i| {
            let (c, r) = ((i % 40) as f32 - 20.0, (i / 40) as f32 - 20.0);
            let hill = 100.0 * (-(c * c + r * r) / 60.0).exp();
            if i % 40 == 30 { 400.0 } else { 200.0 + hill }
        })
        .collect();
    let r = Raster::new("dem", 40, 40, vec![z], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    base64::engine::general_purpose::STANDARD.encode(geotiff::write(&r, 0).unwrap())
}

#[test]
fn analysis_workflows_models_scripts_and_raster_functions() {
    let mut s = world();
    s.run("layer.addDataBytes", &json!({"fileName": "dem.tif", "data": dem_b64()})).unwrap();
    let dem = s.map().layers.iter().find(|l| l.is_raster()).unwrap().name.clone();
    // Raster functions and a chain.
    for (func, extra) in [
        ("slope", json!({})),
        ("aspect", json!({})),
        ("hillshade", json!({"azimuth": 300})),
        ("threshold", json!({"value": 250})),
        ("bandMath", json!({"expression": "b1 * 2 - 100"})),
    ] {
        let mut p = json!({"layer": dem, "function": func});
        p.as_object_mut().unwrap().extend(extra.as_object().unwrap().clone());
        s.run("raster.function", &p).unwrap_or_else(|e| panic!("{func}: {e}"));
    }
    assert!(s.run("raster.function", &json!({"layer": dem, "function": "warp"})).is_err());
    assert!(s.run("raster.function", &json!({"layer": dem, "function": "bandMath", "expression": "b2"})).is_err());
    let r = s
        .run(
            "raster.functionChain",
            &json!({"layer": dem, "steps": [{"function": "slope"}, {"function": "threshold", "value": 10}], "name": "Steep"}),
        )
        .unwrap();
    let steep = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap();
    assert_eq!(steep.name, "Steep");
    let data = steep.raster.as_ref().unwrap().data.as_ref().unwrap();
    assert!(data.bands[0].stats.max == 1.0 && data.bands[0].stats.min == 0.0);
    // Rasters made by functions save with the project.
    let text = serde_json::to_string(&s.project).unwrap();
    let back = crate::Project::from_json(&text).unwrap();
    assert!(back.map().layer_by_name("Steep").unwrap().raster.as_ref().unwrap().data.is_some());
    // Suitability: high and flat.
    let slope_name = format!("{dem}_slope");
    let r = s
        .run(
            "analysis.suitability",
            &json!({"criteria": [
        {"layer": dem, "ranges": [[0, 250, 1], [250, 1000, 10]], "weight": 2},
        {"layer": slope_name, "ranges": [[0, 5, 10], [5, 90, 1]], "weight": 1}]}),
        )
        .unwrap();
    assert!(r["layer"].as_u64().is_some());
    // Viewshed and line of sight: the wall at column 30 hides what's beyond it.
    // On the flat northern edge: everything west of the wall is in view.
    let v = s.run("analysis.viewshed", &json!({"layer": dem, "lon": 10.0055, "lat": 45.0395, "height": 2})).unwrap();
    assert!(v["visibleCells"].as_u64().unwrap() > 100, "{v}");
    let los = s.run("analysis.lineOfSight", &json!({"layer": dem, "from": [10.0205, 45.0395], "to": [10.0355, 45.0395]})).unwrap();
    assert_eq!(los["visible"], false);
    let los = s.run("analysis.lineOfSight", &json!({"layer": dem, "from": [10.0205, 45.0395], "to": [10.0055, 45.0395]})).unwrap();
    assert_eq!(los["visible"], true);
    // IDW of city populations, with an environment extent and cell size.
    s.run("gp.env", &json!({"extent": [-10, 35, 30, 60], "cellSize": 0.5})).unwrap();
    let r = s.run("analysis.interpolate", &json!({"layer": "Cities", "field": "pop_max"})).unwrap();
    let idw = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    assert_eq!((idw.width, idw.height), (80, 50));
    // The environment extent limits tools to the features meeting it.
    s.run("gp.run", &json!({"tool": "buffer", "params": {"input": "Cities", "distance": 10, "output": "Europe buffers"}})).unwrap();
    let europe = s.map().layer_by_name("Europe buffers").unwrap().dataset.features.len();
    let all = s.map().layer_by_name("Cities").unwrap().dataset.features.len();
    assert!(europe > 10 && europe < all / 2, "{europe} of {all}");
    let env = s.run("gp.env", &json!({"extent": null, "cellSize": null})).unwrap();
    // This computer's memory limits are said, never below the browser's fixed ones (#1291 step 2).
    let limit = |k: &str| env["limits"][k].as_u64().unwrap_or(0) as usize;
    assert!(limit("rasterSamples") >= rustgis_data::raster::SAMPLES_FLOOR, "{env}");
    assert!(limit("outputPixels") >= rustgis_analysis::rasterops::PIXELS_FLOOR, "{env}");
    assert!(limit("pagedFeatures") >= rustgis_data::ogc::PAGED_FEATURES_FLOOR, "{env}");
    assert!(limit("densityCells") >= rustgis_analysis::DENSITY_CELLS_FLOOR, "{env}");
    assert!(limit("bufferBytes") >= 512 << 20 && limit("threadScratchBytes") >= 256 << 20, "{env}");
    // Network route along the rivers: two points on the same river.
    let rivers = s.map().layer_by_name("Rivers").unwrap();
    let (a, b2) = match rivers.dataset.features.iter().filter_map(|f| f.geometry.as_ref()).find_map(|g| match g {
        rustgis_data::Geometry::Line(p) if p[0].len() > 10 => Some((p[0][0], p[0][p[0].len() - 1])),
        _ => None,
    }) {
        Some(x) => x,
        None => panic!("no river"),
    };
    let r = s.run("analysis.route", &json!({"layer": "Rivers", "from": [a.x, a.y], "to": [b2.x, b2.y]})).unwrap();
    assert!(r["lengthKm"].as_f64().unwrap() > 10.0, "{r}");
    // Neighbourhood, simulation, profile, exploration, similarity, conversion.
    let n = s
        .run("analysis.neighborhood", &json!({"lon": 2.35, "lat": 48.85, "radius": 300000, "layers": ["Cities"], "select": true}))
        .unwrap();
    assert!(n["layers"][0]["count"].as_u64().unwrap() >= 2);
    // A center that's no place is refused, not taken as a pole (#1033).
    assert!(s.run("analysis.neighborhood", &json!({"lon": 2.35, "lat": 1000, "radius": 300000})).is_err());
    // Lines near a pole with more vertices than one search measures: those past its steps are
    // counted at the least distance they could be, and it says how many (#1033); a search that
    // measures every one says nothing.
    let mut ds = rustgis_data::Dataset::new("Spirals", rustgis_data::GeometryType::Polyline, vec![]);
    for _ in 0..300 {
        let line = (0..=348).map(|i| rustgis_data::Coord::new(if i % 2 == 0 { -179.5 } else { 179.5 }, 89.95)).collect();
        ds.push(Some(rustgis_data::Geometry::Line(vec![line])), vec![]);
    }
    s.map_mut().add_dataset(ds);
    let mark = s.notice_mark();
    let n = s.run("analysis.neighborhood", &json!({"lon": 0, "lat": 89.9, "radius": 10000, "layers": ["Spirals"]})).unwrap();
    assert_eq!(n["layers"][0]["count"], 300);
    let said: Vec<&str> = s.notices_since(mark).iter().map(|n| n.text.as_str()).collect();
    assert!(said.iter().any(|t| t.starts_with("299 feature(s) near a pole (Spirals 299)") && t.contains("beyond the radius")), "{said:?}");
    let mark = s.notice_mark();
    s.run("analysis.neighborhood", &json!({"lon": 0, "lat": 89.9, "radius": 10000, "layers": ["Cities"]})).unwrap();
    assert!(s.notices_since(mark).iter().all(|n| !n.text.contains("near a pole")), "{:?}", s.notices_since(mark));
    s.run("select.byAttributes", &json!({"layer": "Countries", "where": "name = 'France'"})).unwrap();
    let sim = s.run("analysis.simulate", &json!({"layer": "Countries", "count": 20, "seed": 3})).unwrap();
    assert_eq!(sim["points"], 20);
    s.run("select.clear", &Value::Null).unwrap();
    let prof = s.run("data.profile", &json!({"layer": "Countries"})).unwrap();
    assert!(prof["fields"].as_array().unwrap().iter().any(|f| f["field"] == "pop_est" && f["min"].as_f64().is_some()));
    let ex = s.run("data.explore", &json!({"layer": "Countries", "fields": ["pop_est", "gdp_md"]})).unwrap();
    assert!(ex["correlation"][0][1].as_f64().unwrap() > 0.3, "population and GDP correlate");
    let fr = s.map().layer_by_name("Countries").unwrap().dataset.features.iter().position(|_| true).unwrap();
    let sm = s.run("data.similar", &json!({"layer": "Countries", "row": fr, "fields": ["pop_est", "gdp_md"], "count": 3})).unwrap();
    assert_eq!(sm["similar"].as_array().unwrap().len(), 3);
    for fmt in ["kml", "gpx", "wkt", "geojson", "csv"] {
        let t = s.run("data.convert", &json!({"layer": "Cities", "format": fmt})).unwrap();
        assert!(t["text"].as_str().unwrap().len() > 1000, "{fmt}");
    }
    // Models chain tools; scripts run commands.
    s.run(
        "model.new",
        &json!({"name": "Buffer then dissolve", "steps": [
        {"tool": "buffer", "params": {"input": "Cities", "distance": 50}},
        {"tool": "dissolve", "params": {"input": "%1"}}]}),
    )
    .unwrap();
    let r = s.run("model.run", &json!({"name": "Buffer then dissolve"})).unwrap();
    assert_eq!(r["ran"].as_array().unwrap().len(), 2);
    assert!(s.run("model.new", &json!({"steps": [{"tool": "nope", "params": {}}]})).is_err());
    // A model carried in a file can't touch files.
    s.project.models.push(crate::project::Model {
        name: "From a file".into(),
        steps: vec![crate::project::ModelStep {
            tool: "buffer".into(),
            params: json!({"input": "Cities", "distance": 5, "output": "/tmp/x.shp"}),
        }],
        ..Default::default()
    });
    let e = s.run("model.run", &json!({"name": "From a file"})).unwrap_err();
    assert!(e.contains("from a file"), "{e}");
    let m = s.run("model.new", &json!({"name": "Replay", "fromHistory": true})).unwrap();
    assert!(m["steps"].as_u64().unwrap() >= 2);
    let dissolve = s.project.models.last().unwrap().steps.iter().find(|st| st.tool == "dissolve").unwrap();
    assert!(dissolve.params["input"].as_str().unwrap().starts_with('%'), "history inputs wire to earlier steps");
    let r = s.run("script.run", &json!({"script": "# zoom then select\nmap.goToXY {\"lon\": 2, \"lat\": 48, \"scale\": 5000000}\nselect.byAttributes {\"layer\": \"Cities\", \"where\": \"pop_max > 1000000\"}"})).unwrap();
    assert_eq!(r["ran"].as_array().unwrap().len(), 2);
    assert!(s.run("script.run", &json!({"script": "no.such {}"})).is_err());
    model_graphs(&mut s);
    let g = s.run("gp.gallery", &json!({"kind": "raster"})).unwrap();
    assert!(g.as_array().unwrap().iter().any(|t| t["id"] == "raster.function"));
}

/// A 100 × 80 scan whose value is `ramp(col, row)` (so a bilinear warp reproduces it exactly), with
/// a bright pixel at (50, 40), added as a layer with a placeholder position.
fn scan_layer(s: &mut Session, name: &str) -> (fn(f64, f64) -> f32, (f64, f64)) {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    fn ramp(c: f64, r: f64) -> f32 {
        (c * 2.0 + r * 0.5) as f32
    }
    let (w, h) = (100u32, 80u32);
    let mut z: Vec<f32> = (0..w * h).map(|i| ramp(f64::from(i % w) + 0.5, f64::from(i / w) + 0.5)).collect();
    z[(40 * w + 50) as usize] = 5000.0;
    let gt = GeoTransform { origin_x: 0.0, origin_y: 80.0, pixel_width: 1.0, pixel_height: -1.0 };
    let r = Raster::new(name, w, h, vec![z], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    let bytes = geotiff::write(&r, 0).unwrap();
    crate::cmd::raster::add_raster(s, name, rustgis_map::RasterLayer::from_bytes(r, format!("{name}.tif"), bytes)).unwrap();
    (ramp, (50.5, 40.5))
}

/// The control points of a known map from the scan's corners and middle: `f` takes a pixel position
/// to map coordinates.
fn points_of(f: impl Fn(f64, f64) -> (f64, f64)) -> Value {
    let pts: Vec<Value> = [(0.0, 0.0), (100.0, 0.0), (0.0, 80.0), (100.0, 80.0), (50.0, 40.0), (25.0, 60.0)]
        .iter()
        .map(|&(c, r)| {
            let (x, y) = f(c, r);
            json!([c, r, x, y])
        })
        .collect();
    Value::Array(pts)
}

fn out_raster(s: &Session, v: &Value) -> std::sync::Arc<rustgis_data::raster::Raster> {
    let id = v["layer"].as_u64().unwrap() as u32;
    s.map().layer(id).unwrap().raster.as_ref().unwrap().data.clone().unwrap()
}

/// Warping through a known sheared affine puts every pixel where the matrix says: a bilinear
/// warp of a ramp reproduces the ramp at the pixel each output cell comes from, and the bright
/// pixel lands within half a cell of its place.
#[test]
fn a_warp_through_a_known_affine_puts_pixels_where_the_matrix_says() {
    let mut s = world();
    let (ramp, bright) = scan_layer(&mut s, "scan");
    // x = 500000 + 10 col + 2 row, y = 4000000 - 10 row + 1 col, in UTM 13N.
    let map = |c: f64, r: f64| (500_000.0 + 10.0 * c + 2.0 * r, 4_000_000.0 - 10.0 * r + c);
    let v = s
        .run(
            "raster.georeference",
            &json!({"layer": "scan", "transform": "affine", "pointsCrs": 32613, "crs": 32613, "points": points_of(map), "name": "warped", "resampling": "bilinear"}),
        )
        .unwrap();
    assert_eq!(v["crs"], "EPSG:32613", "{v}");
    let out = out_raster(&s, &v);
    assert!(s.map().layer_by_name("scan").unwrap().raster.as_ref().unwrap().data.as_ref().unwrap().width == 100, "the scan is kept");
    // The cell is the root of the pixel's area: |10 × -10 - 2 × 1| = 102.
    let cell = 102f64.sqrt();
    assert!((out.transform.pixel_width - cell).abs() < 1e-9 && (out.transform.pixel_height + cell).abs() < 1e-9);
    // The grid covers the footprint, whose corners are the matrix's corners.
    let corners = [(0.0, 0.0), (100.0, 0.0), (0.0, 80.0), (100.0, 80.0)].map(|(c, r)| map(c, r));
    let (min_x, max_x) = corners.iter().fold((f64::MAX, f64::MIN), |(a, b), (x, _)| (a.min(*x), b.max(*x)));
    let (min_y, max_y) = corners.iter().fold((f64::MAX, f64::MIN), |(a, b), (_, y)| (a.min(*y), b.max(*y)));
    assert_eq!((out.transform.origin_x, out.transform.origin_y), (min_x, max_y));
    assert!(out.transform.origin_x + out.transform.pixel_width * f64::from(out.width) >= max_x);
    assert!(out.transform.origin_y + out.transform.pixel_height * f64::from(out.height) <= min_y);
    // The matrix's inverse takes a map position back to the scan.
    let det = 10.0 * -10.0 - 2.0 * 1.0;
    let back = |x: f64, y: f64| {
        let (dx, dy) = (x - 500_000.0, y - 4_000_000.0);
        ((-10.0 * dx - 2.0 * dy) / det, (-dx + 10.0 * dy) / det)
    };
    let (mut checked, mut empty) = (0, 0);
    for row in (0..i64::from(out.height)).step_by(7) {
        for col in (0..i64::from(out.width)).step_by(5) {
            let c = out.transform.to_world(col as f64 + 0.5, row as f64 + 0.5);
            let (sc, sr) = back(c.x, c.y);
            match out.value(0, col, row) {
                // Away from the scan's edge and its bright pixel the value is the ramp's there.
                Some(v) if (1.5..98.5).contains(&sc) && (1.5..78.5).contains(&sr) && (sc - 50.5).abs() > 2.0 && (sr - 40.5).abs() > 2.0 => {
                    assert!((v - ramp(sc, sr)).abs() < 1e-3, "cell {col},{row}: {v} against {}", ramp(sc, sr));
                    checked += 1;
                }
                Some(_) => {}
                None => {
                    assert!(!(0.0..100.0).contains(&sc) || !(0.0..80.0).contains(&sr), "cell {col},{row} comes from inside the scan");
                    empty += 1;
                }
            }
        }
    }
    assert!(checked > 100 && empty > 0, "{checked} checked, {empty} outside the scan");
    // The bright pixel: its intensity-weighted position is within half a cell of the matrix's.
    let (mut sum, mut sx, mut sy) = (0.0f64, 0.0f64, 0.0f64);
    for row in 0..i64::from(out.height) {
        for col in 0..i64::from(out.width) {
            if let Some(v) = out.value(0, col, row).filter(|v| *v > 1000.0) {
                let c = out.transform.to_world(col as f64 + 0.5, row as f64 + 0.5);
                sum += f64::from(v);
                sx += f64::from(v) * c.x;
                sy += f64::from(v) * c.y;
            }
        }
    }
    let (ex, ey) = map(bright.0, bright.1);
    assert!(
        sum > 0.0 && (sx / sum - ex).abs() <= cell / 2.0 && (sy / sum - ey).abs() <= cell / 2.0,
        "({}, {}) against ({ex}, {ey})",
        sx / sum,
        sy / sum
    );
}

/// A 30° rotation, nearest sampling, replacing the layer's raster: the cells of the bright pixel
/// are centred within half a cell of its place, and the grid's corners outside the turned image
/// are no data.
#[test]
fn a_warp_through_a_known_rotation_puts_pixels_where_the_turn_says() {
    let mut s = world();
    let (_, bright) = scan_layer(&mut s, "scan");
    let (sin, cos) = 30f64.to_radians().sin_cos();
    // Ten metres a pixel, turned 30° about the origin (rows still run down the picture).
    let map = |c: f64, r: f64| (500_000.0 + 10.0 * (c * cos + r * sin), 4_000_000.0 + 10.0 * (c * sin - r * cos));
    let v = s
        .run(
            "raster.georeference",
            &json!({"layer": "scan", "transform": "similarity", "pointsCrs": 32613, "crs": "EPSG:32613", "points": points_of(map), "resampling": "nearest", "cellSize": 2.5}),
        )
        .unwrap();
    let out = out_raster(&s, &v);
    assert_eq!(
        s.map().layer_by_name("scan").unwrap().raster.as_ref().unwrap().data.as_ref().unwrap().width,
        out.width,
        "replaced in place"
    );
    assert!(out.width > 400, "the turned image needs a wider grid than its 1000 m / 2.5 m: {}", out.width);
    // Nearest keeps the values: the bright pixel's cells are 5000, a square 10 m across turned 30°.
    let (mut n, mut sx, mut sy) = (0.0f64, 0.0f64, 0.0f64);
    for row in 0..i64::from(out.height) {
        for col in 0..i64::from(out.width) {
            if out.value(0, col, row) == Some(5000.0) {
                let c = out.transform.to_world(col as f64 + 0.5, row as f64 + 0.5);
                n += 1.0;
                sx += c.x;
                sy += c.y;
            }
        }
    }
    let (ex, ey) = map(bright.0, bright.1);
    let cell = out.transform.pixel_width;
    // About 100 / 6.25 = 16 cells.
    assert!((10.0..=22.0).contains(&n), "{n} cells");
    assert!((sx / n - ex).abs() <= cell / 2.0 && (sy / n - ey).abs() <= cell / 2.0, "({}, {}) against ({ex}, {ey})", sx / n, sy / n);
    // The turned rectangle leaves the box's corners empty.
    assert_eq!(out.value(0, 0, 0), None);
    assert_eq!(out.value(0, i64::from(out.width) - 1, i64::from(out.height) - 1), None);
    // At its default the cell is the pixel's 10 m.
    let d = s
        .run(
            "raster.georeference",
            &json!({"layer": "scan", "transform": "similarity", "pointsCrs": 32613, "crs": 32613, "points": points_of(map), "name": "d"}),
        )
        .unwrap();
    assert!((out_raster(&s, &d).transform.pixel_width - 10.0).abs() < 1e-6);
}

/// Control points in longitude/latitude, warped into UTM: every cell holds the scan's value at
/// the pixel the projection takes the cell's centre back to.
#[test]
fn a_warp_reprojects_from_the_points_crs() {
    use rustgis_data::raster::Crs;
    let mut s = world();
    let (ramp, bright) = scan_layer(&mut s, "scan");
    // A north-up block at 40°N, 105°W, a thousandth of a degree a pixel.
    let map = |c: f64, r: f64| (-105.0 + c * 0.001, 40.0 - r * 0.001);
    let v = s
        .run(
            "raster.georeference",
            &json!({"layer": "scan", "transform": "affine", "crs": 32613, "pointsCrs": "EPSG:4326", "points": points_of(map), "name": "utm"}),
        )
        .unwrap();
    let out = out_raster(&s, &v);
    assert_eq!(out.crs.epsg(), 32613);
    let t = Crs::from_epsg(32613).unwrap().transformer().unwrap();
    let mut checked = 0;
    for row in (0..i64::from(out.height)).step_by(3) {
        for col in (0..i64::from(out.width)).step_by(3) {
            let c = out.transform.to_world(col as f64 + 0.5, row as f64 + 0.5);
            let ll = t.to_lonlat(c).unwrap();
            let (sc, sr) = ((ll.x + 105.0) / 0.001, (40.0 - ll.y) / 0.001);
            if (2.0..98.0).contains(&sc) && (2.0..78.0).contains(&sr) && (sc - 50.5).abs() > 2.5 && (sr - 40.5).abs() > 2.5 {
                let got = out.value(0, col, row).unwrap();
                assert!((got - ramp(sc, sr)).abs() < 0.05, "cell {col},{row}: {got} against {}", ramp(sc, sr));
                checked += 1;
            }
        }
    }
    assert!(checked > 100, "{checked}");
    // The bright pixel's own UTM position is within a cell of a bright cell.
    let (lon, lat) = map(bright.0, bright.1);
    let at = t.from_lonlat(rustgis_geom::Coord::new(lon, lat)).unwrap();
    let (col, row) = out.transform.to_pixel(at);
    let (col, row) = (col.floor() as i64, row.floor() as i64);
    let near = (-1..=1)
        .flat_map(|dy| (-1..=1).map(move |dx| (dx, dy)))
        .filter_map(|(dx, dy)| out.value(0, col + dx, row + dy))
        .fold(f32::MIN, f32::max);
    assert!(near > 500.0, "{near}");
}

/// A 48-bit colour scan (UInt16 RGB) warps with alpha the renderer reads as opaque (it takes
/// alpha as 0–255 in every type), and the COG keeps the 16-bit type.
#[test]
fn a_sixteen_bit_colour_warp_is_opaque_to_the_renderer() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster};
    let mut s = world();
    let n = 60 * 40;
    let bands = vec![vec![60_000.0; n], vec![30_000.0; n], vec![1000.0; n]];
    let gt = GeoTransform { origin_x: 0.0, origin_y: 40.0, pixel_width: 1.0, pixel_height: -1.0 };
    let r = Raster::new("deep", 60, 40, bands, gt, Crs::LonLat, None, ColorHint::Rgb { alpha: false }, "UInt16").unwrap();
    let bytes = rustgis_data::raster::geotiff::write(&r, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "deep", rustgis_map::RasterLayer::from_bytes(r, "deep.tif", bytes)).unwrap();
    let (sin, cos) = 20f64.to_radians().sin_cos();
    let map = |c: f64, r: f64| (500_000.0 + 10.0 * (c * cos + r * sin), 4_000_000.0 + 10.0 * (c * sin - r * cos));
    let pts: Vec<Value> =
        [(0.0, 0.0), (60.0, 0.0), (0.0, 40.0), (60.0, 40.0)].iter().map(|&(c, r)| json!([c, r, map(c, r).0, map(c, r).1])).collect();
    let path = std::env::temp_dir().join(format!("rustgis-deep-{}.tif", std::process::id()));
    let v = s
        .run("raster.georeference", &json!({"layer": "deep", "transform": "similarity", "pointsCrs": 32613, "points": pts, "name": "w", "path": path.display().to_string()}))
        .unwrap();
    let out = out_raster(&s, &v);
    assert_eq!(out.color, ColorHint::Rgb { alpha: true });
    let (mid_c, mid_r) = (i64::from(out.width) / 2, i64::from(out.height) / 2);
    // The renderer clamps alpha to 0–255: inside is 255, the collar 0.
    let alpha = |c, r| out.value(3, c, r).map(|v| v.clamp(0.0, 255.0) as u8);
    assert_eq!((alpha(mid_c, mid_r), alpha(0, 0)), (Some(255), Some(0)));
    let back = rustgis_data::raster::read_path(&path).unwrap();
    assert_eq!((back.data_type.as_str(), back.band_count()), ("UInt16", 4));
    assert_eq!(back.value(0, mid_c, mid_r), Some(60_000.0));
    std::fs::remove_file(&path).ok();
}

/// A scan that would span the globe in degrees is refused, and a long thin grid can't slip past
/// the size limit through its row buffers.
#[test]
fn a_warp_refuses_a_globe_in_degrees_and_bounds_its_memory() {
    use rustgis_analysis::georef::{self, Gcp, Kind};
    use rustgis_analysis::warp::{self, Options, Resampling};
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster};
    let (w, h) = (40u32, 40u32);
    let gt = GeoTransform { origin_x: 0.0, origin_y: 40.0, pixel_width: 1.0, pixel_height: -1.0 };
    let r = Raster::new("s", w, h, vec![vec![1.0; 1600]], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    // A square of 2000 km centred on the pole, in polar stereographic (EPSG:3413).
    let gcps = |f: &dyn Fn(f64, f64) -> (f64, f64)| -> Vec<Gcp> {
        [(0.0, 0.0), (40.0, 0.0), (0.0, 40.0), (40.0, 40.0)]
            .iter()
            .map(|&(c, r)| {
                let (x, y) = f(c, r);
                Gcp { col: c, row: r, x, y, on: true }
            })
            .collect()
    };
    let fit = georef::fit(Kind::Affine, &gcps(&|c, r| (-1_000_000.0 + 50_000.0 * c, 1_000_000.0 - 50_000.0 * r))).unwrap();
    let o = |crs: Crs, points: Crs, cell| Options { crs, points_crs: points, resampling: Resampling::Nearest, cell, name: "o".into() };
    let polar = Crs::from_epsg(3413).unwrap();
    // In degrees the scan spans every longitude: refused, with a hint.
    let e = warp::warp(&r, &fit, &o(Crs::LonLat, polar, Some(0.05))).unwrap_err();
    assert!(e.contains("projected crs"), "{e}");
    // In Web Mercator it is placed (to its latitude limit), with the pole inside it.
    assert!(warp::warp(&r, &fit, &o(Crs::WebMercator, polar, Some(100_000.0))).is_ok());
    // A strip a billion metres long and a metre tall, from hostile points: past the most samples
    // any computer is allowed (rustgis_data::raster::SAMPLES_CEILING), its row buffers counted.
    let strip = georef::fit(Kind::Affine, &gcps(&|c, r| (500_000.0 + c * 2.5e7, 4_000_000.0 - r * 0.025))).unwrap();
    let utm13 = Crs::from_epsg(32613).unwrap();
    let e = warp::warp(&r, &strip, &o(utm13, utm13, Some(1.0))).unwrap_err();
    assert!(e.contains("cellSize"), "{e}");
}

/// A warp written as a COG becomes the layer's file; the options are checked.
#[test]
fn a_warp_can_write_a_cog_and_refuses_what_it_cannot_place() {
    let mut s = world();
    scan_layer(&mut s, "scan");
    let map = |c: f64, r: f64| (500_000.0 + 10.0 * c, 4_000_000.0 - 10.0 * r);
    let dir = std::env::temp_dir().join(format!("rustgis-warp-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("warped.tif");
    let v = s
        .run(
            "raster.georeference",
            &json!({"layer": "scan", "transform": "affine", "pointsCrs": 32613, "crs": 32613, "points": points_of(map), "resampling": "cubic", "cellSize": 5, "name": "w", "path": path.display().to_string()}),
        )
        .unwrap();
    assert_eq!(v["cog"]["overviews"], 0, "200 × 160 is one tile: {v}");
    assert_eq!((v["width"].as_u64(), v["height"].as_u64()), (Some(200), Some(160)), "half-size cells double the grid");
    let back = rustgis_data::raster::read_path(&path).unwrap();
    assert_eq!((back.width, back.height, back.crs.epsg()), (200, 160, 32613));
    assert_eq!(back.transform.origin_x, 500_000.0);
    let layer = s.map().layer_by_name("w").unwrap().raster.as_ref().unwrap();
    assert_eq!(layer.path.as_deref(), Some(path.display().to_string().as_str()), "the file is the layer's source");
    // The same command without a transform is the old north-up fit.
    s.run("raster.georeference", &json!({"layer": "scan", "extent": [10.0, 45.0, 10.1, 45.08]})).unwrap();
    let ok = json!({"layer": "scan", "transform": "affine", "pointsCrs": 32613, "crs": 32613, "points": points_of(map)});
    s.run("raster.georeference", &ok).unwrap();
    for (k, bad) in [
        ("transform", json!("warp")),
        ("transform", json!(7)),
        ("crs", json!("EPSG:99999999")),
        ("crs", json!(-1)),
        ("crs", json!(1e30)),
        ("pointsCrs", json!([])),
        ("resampling", json!("lanczos")),
        ("cellSize", json!(0)),
        ("cellSize", json!(-3)),
        ("cellSize", json!(1e-9)),
        ("cellSize", json!("x")),
        ("path", json!("warped.png")),
        ("path", json!(5)),
        ("points", json!([[0, 0, 1, 1]])),
    ] {
        let mut p = ok.clone();
        p[k] = bad.clone();
        assert!(s.run("raster.georeference", &p).is_err(), "{k} = {bad}");
    }
    // A fit that collapses the image onto a line has no grid.
    assert!(
        s.run(
            "raster.georeference",
            &json!({"layer": "scan", "transform": "affine", "pointsCrs": 32613, "crs": 32613, "points": points_of(|c, _| (c, c))})
        )
        .is_err()
    );
    std::fs::remove_dir_all(&dir).ok();
}

/// A scan opened from a PNG and warped onto its points has coordinates for real: the cell is the
/// fit's pixel on the ground, not the stand-in size it was laid over the view at; the pixels land
/// where the fit says; it can be exported; and the project reopens it where the warp put it, not
/// laid over the view again.
#[test]
fn a_scan_warped_onto_its_points_is_placed_for_real() {
    let dir = std::env::temp_dir().join(format!("rustgis-scan-warp-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let png = dir.join("plate.png");
    image::DynamicImage::ImageRgb8(image::RgbImage::from_fn(40, 20, |x, y| image::Rgb([x as u8, y as u8, 9])))
        .save_with_format(&png, image::ImageFormat::Png)
        .unwrap();
    let mut s = world();
    let r = s.run("layer.addData", &json!({"path": png.display().to_string()})).unwrap();
    assert_eq!(r["georeferenced"], false, "{r}");
    let laid = s.map().layer_by_name("plate").unwrap().raster.clone().unwrap();
    assert!(laid.placement.is_some());
    let stand_in = laid.data.as_ref().unwrap().transform.pixel_width;
    // 7.5 m a pixel in UTM 13N, from the scan's corners and two points inside it; the output's
    // system is the points'.
    let map = |c: f64, r: f64| (500_000.0 + 7.5 * c, 4_000_000.0 - 7.5 * r);
    let pts: Vec<Value> = [(0.0, 0.0), (40.0, 0.0), (0.0, 20.0), (40.0, 20.0), (20.0, 10.0), (10.0, 15.0)]
        .iter()
        .map(|&(c, r)| {
            let (x, y) = map(c, r);
            json!([c, r, x, y])
        })
        .collect();
    let v = s
        .run(
            "raster.georeference",
            &json!({"layer": "plate", "transform": "affine", "pointsCrs": 32613, "points": pts, "resampling": "nearest"}),
        )
        .unwrap();
    assert_eq!(v["crs"], "EPSG:32613", "{v}");
    let l = s.map().layer_by_name("plate").unwrap().raster.clone().unwrap();
    assert!(l.placement.is_none(), "no longer laid over the view");
    let out = l.data.clone().unwrap();
    assert!(out.georeferenced && out.crs.epsg() == 32613);
    assert!(
        (out.transform.pixel_width - 7.5).abs() < 1e-6 && (out.transform.pixel_height + 7.5).abs() < 1e-6 && (stand_in - 7.5).abs() > 0.5,
        "{:?}, laid at {stand_in}",
        out.transform
    );
    // Red is the column and green the row, so a pixel reads back where the fit puts it; the scan
    // had no alpha or no data, so it gains an opaque alpha band.
    assert_eq!(out.band_count(), 4);
    let (x, y) = map(10.5, 5.5);
    let (col, row) = out.transform.to_pixel(rustgis_geom::Coord { x, y });
    let (col, row) = (col.floor() as i64, row.floor() as i64);
    let px: Vec<Option<f32>> = (0..4).map(|b| out.value(b, col, row)).collect();
    assert_eq!(px, [Some(10.0), Some(5.0), Some(9.0), Some(255.0)], "cell {col},{row}");
    // Exporting is no longer refused.
    let tif = dir.join("plate.tif");
    s.run("share.exportRaster", &json!({"layer": "plate", "path": tif.display().to_string(), "cog": true})).unwrap();
    let back = rustgis_data::raster::read_path(&tif).unwrap();
    assert!(back.georeferenced && back.crs.epsg() == 32613 && back.transform == out.transform);
    // The project reopens it where the warp put it.
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let again = t.map().layer_by_name("plate").unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    assert!(again.georeferenced && again.transform == out.transform, "{:?} vs {:?}", again.transform, out.transform);
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn exporting_a_raster_as_a_cog() {
    let mut s = world();
    s.run("layer.addDataBytes", &json!({"fileName": "dem.tif", "data": dem_b64()})).unwrap();
    let dem = s.map().layers.iter().find(|l| l.is_raster()).unwrap().name.clone();
    let dir = std::env::temp_dir().join(format!("rustgis-cog-export-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let (plain, cog) = (dir.join("plain.tif"), dir.join("cog.tif"));
    let v = s.run("share.exportRaster", &json!({"layer": dem, "path": plain.display().to_string()})).unwrap();
    assert!(v.get("cog").is_none(), "an untiled GeoTIFF unless asked");
    let v = s.run("share.exportRaster", &json!({"layer": dem, "path": cog.display().to_string(), "cog": true})).unwrap();
    assert_eq!(v["cog"]["bigTiff"], false, "{v}");
    let (a, b) = (rustgis_data::raster::read_path(&plain).unwrap(), rustgis_data::raster::read_path(&cog).unwrap());
    assert_eq!((a.width, a.height, a.transform), (b.width, b.height, b.transform));
    assert!(a.bands.iter().zip(&b.bands).all(|(x, y)| x.data == y.data));
    // Tiled, not stripped: the tile tags are in the file.
    let bytes = std::fs::read(&cog).unwrap();
    assert!(bytes.windows(2).any(|w| w == [0x42, 0x01]), "TileWidth (322) is in a directory");
    assert!(s.run("share.exportRaster", &json!({"layer": dem, "path": cog.display().to_string(), "cog": true, "band": 99})).is_err());
    assert!(
        s.run("share.exportRaster", &json!({"layer": dem, "path": dir.join("no").join("x.tif").display().to_string(), "cog": true}))
            .is_err()
    );
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn layer_effects_and_imagery_tools() {
    use crate::render::View;
    let mut s = world();
    s.run("layer.addDataBytes", &json!({"fileName": "dem.tif", "data": dem_b64()})).unwrap();
    let dem = s.map().layers.iter().find(|l| l.is_raster()).unwrap().name.clone();
    s.run("map.goToXY", &json!({"lon": 10.0, "lat": 48.0, "scale": 20_000_000})).unwrap();
    let view = |s: &Session| View { width: 400.0, height: 300.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
    let png = |s: &mut Session| {
        let v = view(s);
        crate::render::render(s.map_mut(), &v).unwrap().pixmap
    };
    // Every effect renders.
    s.run("layer.blend", &json!({"layer": "Countries", "mode": "multiply"})).unwrap();
    assert!(s.run("layer.blend", &json!({"layer": "Countries", "mode": "dodge"})).is_err());
    s.run("layer.mask", &json!({"layer": "Cities", "mask": "Countries"})).unwrap();
    assert!(s.run("layer.mask", &json!({"layer": "Countries", "mask": "Countries"})).is_err());
    assert!(s.run("layer.mask", &json!({"layer": "Countries", "mask": "Cities"})).is_err(), "masks are polygons");
    s.run("layer.swipe", &json!({"layer": "Countries", "position": 0.5})).unwrap();
    let swiped = png(&mut s);
    // Right of the divider the countries are gone: only water and basemap land remain.
    s.run("layer.swipe", &json!({"layer": "Countries", "off": true})).unwrap();
    let full = png(&mut s);
    assert_ne!(swiped.data(), full.data());
    s.run("layer.displayFilters", &json!({"layer": "Cities", "filters": [{"name": "Big at small scales", "minScale": 1e12, "maxScale": 5_000_000, "where": "pop_max > 5000000"}]})).unwrap();
    assert!(s.run("layer.displayFilters", &json!({"layer": "Cities", "filters": [{"where": "(("}]})).is_err());
    s.run("layer.aggregation", &json!({"layer": "Cities", "shape": "hexagon", "size": 30})).unwrap();
    assert!(s.run("layer.aggregation", &json!({"layer": "Countries", "shape": "hexagon"})).is_err());
    png(&mut s);
    s.run("layer.aggregation", &json!({"layer": "Cities", "shape": "square"})).unwrap();
    png(&mut s);
    s.run("layer.extrusion", &json!({"layer": "Countries", "type": "field", "field": "pop_est", "factor": 0.002})).unwrap();
    s.run("layer.faces", &json!({"layer": "Countries", "culling": false, "lighting": true})).unwrap();
    s.run("layer.lightShadow", &json!({"layer": "Countries", "shadows": true})).unwrap();
    let extruded = png(&mut s);
    assert_ne!(extruded.data(), full.data());
    assert!(s.run("layer.faces", &json!({"layer": "Lakes", "culling": true})).is_err(), "no extrusion yet");
    s.run("raster.rotation", &json!({"layer": dem, "angle": 30})).unwrap();
    s.run("map.goToXY", &json!({"lon": 10.02, "lat": 45.02, "scale": 50_000})).unwrap();
    png(&mut s);
    assert!(s.run("raster.rotation", &json!({"layer": "Countries", "angle": 30})).is_err());
    s.run("raster.rotation", &json!({"layer": dem, "angle": 0})).unwrap();
    // Imagery.
    let r = s.run("raster.georeference", &json!({"layer": dem, "points": [[0, 0, 20.0, 50.0], [40, 40, 20.4, 49.6]]})).unwrap();
    let e = r["extent"].as_array().unwrap();
    assert!((e[0].as_f64().unwrap() - 20.0).abs() < 1e-6 && (e[3].as_f64().unwrap() - 50.0).abs() < 1e-6, "{r}");
    assert!(
        s.run("raster.georeference", &json!({"layer": dem, "points": [[0, 0, 20.0, 50.0], [40, 40, 19.0, 51.0]]})).is_err(),
        "north up only"
    );
    s.run("raster.georeference", &json!({"layer": dem, "extent": [10.0, 45.0, 10.04, 45.04]})).unwrap();
    // Control point fits: a sheared grid is affine, a point switched off still gets a residual,
    // and comparing the transforms recommends the simplest that predicts the points left out.
    let sheared: Vec<Value> = (0..16)
        .map(|i| {
            let (c, r) = (f64::from(i % 4) * 100.0, f64::from(i / 4) * 100.0);
            json!([c, r, 20.0 + c * 0.001 + r * 0.0002, 50.0 - r * 0.001])
        })
        .collect();
    let mut pts = sheared.clone();
    pts[5] = json!([100, 100, 20.5, 49.0, 0]);
    let fit = s.run("raster.gcpFit", &json!({"points": pts, "transform": "affine"})).unwrap();
    assert_eq!(fit["used"], 15);
    assert!(fit["rmse"]["map"].as_f64().unwrap() < 1e-9, "{fit}");
    assert!(fit["residuals"][5]["map"][0].as_f64().unwrap() < -0.3, "the switched-off point misses");
    let g: Vec<f64> = fit["affine"].as_array().unwrap().iter().map(|v| v.as_f64().unwrap()).collect();
    assert!((g[1] - 0.001).abs() < 1e-12 && (g[2] - 0.0002).abs() < 1e-12 && (g[5] + 0.001).abs() < 1e-12, "{g:?}");
    let cmp = s.run("raster.gcpFit", &json!({"points": sheared, "compare": true})).unwrap();
    assert_eq!(cmp["recommended"], "affine", "{cmp}");
    assert!(s.run("raster.gcpFit", &json!({"points": [[0, 0, 1, 1]]})).is_err());
    assert!(s.run("raster.gcpFit", &json!({"points": [[0, 0, 1, 1], [1, 1, 2, 2]], "transform": "magic"})).is_err());
    let sp = s.run("raster.spectral", &json!({"layer": dem, "lon": 10.0205, "lat": 45.0195})).unwrap();
    assert!(sp["values"][0].as_f64().unwrap() > 290.0);
    s.run("raster.index", &json!({"layer": dem, "index": "ndvi", "nir": 1, "red": 1})).unwrap();
    let r = s.run("raster.classify", &json!({"layer": dem, "classes": 3})).unwrap();
    // Forms send numbers as floats; whole ones are accepted.
    s.run("raster.classify", &json!({"layer": dem, "classes": 3.0, "name": "float_classes"})).unwrap();
    assert!(s.run("raster.classify", &json!({"layer": dem, "classes": 2.5})).is_err());
    assert!(r["layer"].as_u64().is_some());
    s.run("raster.function", &json!({"layer": dem, "function": "bandMath", "expression": "b1 + 10", "name": "dem_later"})).unwrap();
    let ch = s.run("raster.change", &json!({"before": dem, "after": "dem_later", "method": "difference"})).unwrap();
    let ch_layer = s.map().layer(ch["layer"].as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    assert!((ch_layer.bands[0].stats.mean - 10.0).abs() < 0.01);
    s.run("raster.process", &json!({"layer": dem, "operation": "clip", "extent": [10.005, 45.005, 10.02, 45.02]})).unwrap();
    let r = s.run("raster.process", &json!({"layer": dem, "operation": "resample", "factor": 4})).unwrap();
    let small = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    assert_eq!((small.width, small.height), (10, 10));
    let r = s
        .run(
            "raster.editPixels",
            &json!({"layer": dem, "polygon": [[10.0, 45.0], [10.01, 45.0], [10.01, 45.01], [10.0, 45.01]], "value": 0}),
        )
        .unwrap();
    assert_eq!(r["pixels"], 100);
    // Supervised classification from two training squares.
    s.run("layer.template", &json!({"template": "polygons", "name": "Training"})).unwrap();
    for (name, x) in [("low", 10.002), ("high", 10.018)] {
        s.run("edit.addFeature", &json!({"layer": "Training", "geometry": {"type": "Polygon", "coordinates": [[[x, 45.018], [x + 0.004, 45.018], [x + 0.004, 45.022], [x, 45.022], [x, 45.018]]]}, "attributes": {"name": name}})).unwrap();
    }
    let r = s.run("raster.classifySupervised", &json!({"layer": dem, "training": "Training", "classField": "name"})).unwrap();
    assert_eq!(r["classes"].as_array().unwrap().len(), 2, "{r}");
    // Mensuration.
    let m = s.run("raster.measure", &json!({"layer": dem, "kind": "height", "points": [[10.0015, 45.0385], [10.0205, 45.0195]]})).unwrap();
    assert!(m["metres"].as_f64().unwrap() > 50.0, "{m}");
    let volume =
        json!({"layer": dem, "kind": "volume", "points": [[10.015, 45.015], [10.025, 45.015], [10.025, 45.025], [10.015, 45.025]]});
    let on_earth = s.run("raster.measure", &volume).unwrap()["cubicMetresAbove"].as_f64().unwrap();
    s.run("raster.measure", &json!({"kind": "area", "points": [[0, 0], [1, 0], [1, 1]]})).unwrap();
    assert_eq!(s.run("raster.measurements", &Value::Null).unwrap().as_array().unwrap().len(), 3);
    // On Mars the degree cells of this raster are Mars' size: the same heights over a smaller
    // ground (#223).
    s.run("map.body", &json!({"name": "mars", "basemap": false})).unwrap();
    let on_mars = s.run("raster.measure", &volume).unwrap()["cubicMetresAbove"].as_f64().unwrap();
    let k = rustgis_geom::Body::get("mars").ratio();
    assert!(on_earth > 0.0 && (on_mars / on_earth - k * k).abs() < 1e-9, "{on_earth} {on_mars}");
    s.run("map.body", &json!({"name": "earth"})).unwrap();
    // Workspaces: an orthomosaic of two rasters, a DSM mosaic and its mesh.
    s.run("imagery.workspace", &json!({"kind": "ortho", "name": "Valley", "images": [dem, "dem_later"]})).unwrap();
    s.run("imagery.workspaceOptions", &json!({"name": "Valley", "cellSize": 0.002})).unwrap();
    let r = s.run("imagery.mosaic", &json!({"name": "Valley"})).unwrap();
    let mo = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    assert_eq!((mo.width, mo.height), (20, 20));
    s.run("imagery.workspace", &json!({"kind": "reality", "images": ["dem_later"]})).unwrap();
    let r = s.run("imagery.mosaic", &json!({"name": "Reality Mapping"})).unwrap();
    let dsm = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().name.clone();
    let mesh = s.run("imagery.mesh", &json!({"layer": dsm})).unwrap();
    assert!(mesh["faces"].as_u64().unwrap() > 100);
    // Meshes go to .obj files; workspace methods are first or mean, checked on creation too.
    assert!(s.run("imagery.mesh", &json!({"layer": dsm, "path": "/tmp/dsm.png"})).is_err());
    assert!(s.run("imagery.workspace", &json!({"kind": "ortho", "images": [dem], "method": "median"})).is_err());
    assert!(s.run("imagery.workspace", &json!({"kind": "ortho", "images": [dem], "cellSize": 20})).is_err());
    // A mean mosaic keeps fractional values.
    s.run("imagery.workspaceOptions", &json!({"name": "Valley", "method": "mean"})).unwrap();
    let r = s.run("imagery.mosaic", &json!({"name": "Valley"})).unwrap();
    let mo = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    assert_eq!(mo.data_type, "Float32");
    assert!(s.run("imagery.workspace", &json!({"kind": "lidar", "images": [dem]})).is_err());
    // Effects and workspaces save with the project.
    let p = crate::Project::from_json(&serde_json::to_string(&s.project).unwrap()).unwrap();
    assert!(p.map().layer_by_name("Countries").unwrap().extrusion.is_some() && p.workspaces.len() == 2);
}

#[test]
fn the_globe_has_stars_that_turn_off() {
    use crate::render::View;
    let mut s = world();
    s.run("map.viewMode", &json!({"mode": "global"})).unwrap();
    // The space in the corner, away from the globe.
    let corner = |s: &mut Session| {
        let v = View { width: 1200.0, height: 800.0, pixels_per_point: 1.0, camera: s.map().camera, sky: true };
        let pm = crate::render::render(s.map_mut(), &v).unwrap().pixmap;
        let mut px = Vec::new();
        for y in 0..150 {
            for x in 0..150 {
                px.push(pm.pixel(x, y).map(|c| (c.red(), c.green(), c.blue())));
            }
        }
        px
    };
    let starry = corner(&mut s);
    assert!(s.map().view.effects.stars && starry.iter().any(|p| p != &starry[0]), "stars by default");
    s.run("map.effects", &json!({"stars": false})).unwrap();
    let plain = corner(&mut s);
    assert!(plain.iter().all(|p| p == &plain[0]), "plain space");
    // Saved with the project; a project from before stars has them.
    let p = crate::Project::from_json(&serde_json::to_string(&s.project).unwrap()).unwrap();
    assert!(!p.map().view.effects.stars);
    assert!(serde_json::from_str::<rustgis_map::view::ViewEffects>("{}").unwrap().stars);
    s.run("map.effects", &json!({"reset": true})).unwrap();
    assert!(corner(&mut s) == starry);
}

#[test]
fn exports_draw_the_globe_in_light_space() {
    // #352: the dark, starry space is the interactive view's; exports and layouts print a light
    // one, as globe insets on a light page need.
    let mut s = world();
    s.run("map.viewMode", &json!({"mode": "global"})).unwrap();
    let rgb = |pm: &tiny_skia::Pixmap, x: u32, y: u32| pm.pixel(x, y).map(|c| (c.red(), c.green(), c.blue())).unwrap();
    let corner = |s: &mut Session| {
        let png = crate::cmd::share::map_png(s, Some(1200.0), Some(800.0), None).unwrap();
        let pm = crate::render::decode_png(&png).unwrap();
        let px: Vec<_> = (0..100).flat_map(|y| (0..100).map(move |x| (x, y))).map(|(x, y)| rgb(&pm, x, y)).collect();
        px
    };
    let light = corner(&mut s);
    assert!(light.iter().all(|p| *p == (0xEC, 0xEF, 0xF3)), "light space without stars: {:?}", light[0]);
    // The Midnight basemap keeps a dark space, still without stars.
    s.run("map.basemap", &json!({"name": "midnight"})).unwrap();
    let dark = corner(&mut s);
    assert!(dark.iter().all(|p| *p == (0x08, 0x0B, 0x10)), "dark space without stars: {:?}", dark[0]);
    s.run("map.basemap", &json!({"name": "paper"})).unwrap();
    // A layout's map frame on the globe map: the space in its corner is light too.
    s.run("layout.new", &json!({"page": "a4", "orientation": "landscape", "template": "blank"})).unwrap();
    s.run("layout.addFrame", &json!({"x": 20, "y": 20, "w": 150, "h": 150})).unwrap();
    let dir = std::env::temp_dir().join(format!("rustgis-globe-space-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("inset.png");
    s.run("layout.export", &json!({"path": path.display().to_string(), "dpi": 72})).unwrap();
    let pm = crate::render::decode_png(&std::fs::read(&path).unwrap()).unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    // 25 mm from the page's corner: 5 mm inside the frame's.
    let at = (25.0 * 72.0 / 25.4) as u32;
    assert_eq!(rgb(&pm, at, at), (0xEC, 0xEF, 0xF3), "a light space around the globe in the layout");
}

#[test]
fn view_effects_scene_and_navigation() {
    use crate::render::View;
    let mut s = world();
    s.run("map.goToXY", &json!({"lon": 10.0, "lat": 48.0, "scale": 20_000_000})).unwrap();
    let png = |s: &mut Session| {
        let v = View { width: 300.0, height: 200.0, pixels_per_point: 1.0, camera: s.map().camera, sky: false };
        crate::render::render(s.map_mut(), &v).unwrap().pixmap.data().to_vec()
    };
    let plain = png(&mut s);
    for p in [
        json!({"sunTime": 1_710_979_200.0}),
        json!({"weather": "fog"}),
        json!({"weather": "snow", "vignette": true, "edges": true}),
        json!({"tiltShift": true, "grain": true}),
        json!({"brightness": 20, "contrast": 10, "saturation": -50, "sepia": 30}),
    ] {
        s.run("map.effects", &p).unwrap_or_else(|e| panic!("{p}: {e}"));
        assert!(png(&mut s) != plain, "{p}");
    }
    assert!(s.run("map.effects", &json!({"weather": "hail"})).is_err());
    s.run("map.effects", &json!({"reset": true})).unwrap();
    assert!(png(&mut s) == plain, "reset restores the map");
    s.run("map.colorVision", &json!({"mode": "deuteranopia"})).unwrap();
    assert!(png(&mut s) != plain);
    // Exports aren't simulated.
    let export = crate::cmd::share::map_png(&mut s, Some(300.0), Some(200.0), None).unwrap();
    s.run("map.colorVision", &json!({"mode": "normal"})).unwrap();
    assert!(export == crate::cmd::share::map_png(&mut s, Some(300.0), Some(200.0), None).unwrap());
    s.run("map.drawingMode", &json!({"mode": "wireframe"})).unwrap();
    assert!(png(&mut s) != plain);
    s.run("map.drawingMode", &json!({"mode": "standard"})).unwrap();
    s.run("layer.priority", &json!({"layer": "Countries", "value": 5})).unwrap();
    assert!(png(&mut s) != plain, "countries now draw over the cities");
    s.run("layer.priority", &json!({"layer": "Countries", "value": 0})).unwrap();
    s.run("map.clipping", &json!({"mode": "distance", "distance": 500_000})).unwrap();
    assert!(png(&mut s) != plain);
    s.run("map.clipping", &json!({"mode": "none"})).unwrap();
    s.run("map.displayType", &json!({"mode": "speed"})).unwrap();
    assert!(png(&mut s) != plain, "no antialiasing");
    s.run("map.displayType", &json!({"mode": "quality"})).unwrap();
    assert!(png(&mut s) == plain);
    // Views and navigation.
    if rustgis_map::projection::local_views_supported() {
        s.run("map.viewMode", &json!({"mode": "local"})).unwrap();
        assert!(s.map().projection.code().starts_with("local:"));
        let local = png(&mut s);
        // The local view is azimuthal equidistant, not Web Mercator under another name (#208).
        s.run("map.projection", &json!({"type": "mercator"})).unwrap();
        assert!(png(&mut s) != local, "a local view draws in its own projection");
    } else {
        let e = s.run("map.viewMode", &json!({"mode": "local"})).unwrap_err();
        assert!(e.contains("web app"), "{e}");
    }
    s.run("map.viewMode", &json!({"mode": "global"})).unwrap();
    assert!(s.map().projection.is_globe());
    s.run("map.navigation", &json!({"mode": "planar"})).unwrap();
    assert!(!s.map().projection.is_globe(), "planar navigation is flat");
    s.run("map.navigation", &json!({"mode": "firstPerson"})).unwrap();
    let before = s.map().center_lonlat();
    s.run("map.walk", &json!({"forward": 1})).unwrap();
    assert!(s.map().center_lonlat().y > before.y, "walking forward goes north");
    let cam = s.run("map.camera", &json!({"lon": 2.35, "lat": 48.85, "scale": 1_000_000})).unwrap();
    assert!((cam["lon"].as_f64().unwrap() - 2.35).abs() < 1e-6);
    assert!(s.run("map.navigator", &Value::Null).unwrap()["navigator"].as_bool().unwrap());
}

fn offline_field_session(layers: &[&str], empty: bool) -> Session {
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value as Attr};
    use rustgis_geom::Coord;

    isolate_plugins();
    let mut s = Session::new(Project::default());
    for name in layers.iter().rev() {
        let mut data = Dataset::new(
            *name,
            GeometryType::Point,
            vec![Field::new("name", FieldType::Text), Field::new("region", FieldType::Text), Field::new("population", FieldType::Integer)],
        );
        if !empty {
            data.push_next(
                Some(Geometry::Point(Coord::new(1.0, 1.0))),
                vec![Attr::Text("Original".into()), Attr::Text("North".into()), Attr::Int(10)],
            );
        }
        s.active_layer = Some(s.map_mut().add_dataset(data));
    }
    s.run("offline.download", &json!({"name": "Fieldwork", "extent": [0.0, 0.0, 2.0, 2.0]})).unwrap();
    s.run("offline.open", &json!({"name": "Fieldwork"})).unwrap();
    s
}

#[test]
fn offline_sync_rejects_incompatible_fields_and_preserves_safe_refreshes() {
    use rustgis_data::{FieldType, Geometry, Value as Attr};
    use rustgis_geom::Coord;

    for mode in ["unchanged", "display_metadata", "source_refresh", "matching_schema_changes"] {
        let mut s = offline_field_session(&["Assets"], false);
        if mode != "source_refresh" {
            s.run("edit.setValue", &json!({"layer": "Assets", "row": 0, "field": "population", "value": 20})).unwrap();
        }
        if mode == "matching_schema_changes" {
            s.run("edit.deleteField", &json!({"layer": "Assets", "field": "region"})).unwrap();
        }
        s.run("map.activate", &json!({"name": "Map"})).unwrap();
        if mode == "display_metadata" {
            let fields = &mut s.map_mut().layers.iter_mut().find(|l| l.name == "Assets").unwrap().dataset.fields;
            fields[0].name = "NAME".into();
            fields[2].alias = Some("Population estimate".into());
        } else if mode == "source_refresh" || mode == "matching_schema_changes" {
            s.run("edit.deleteField", &json!({"layer": "Assets", "field": "region"})).unwrap();
        }
        s.run("offline.sync", &json!({"name": "Fieldwork"})).unwrap();
        let source = &s.map().layer_by_name("Assets").unwrap().dataset;
        let expected = if mode == "source_refresh" { 10 } else { 20 };
        assert_eq!(source.value(0, source.field_index("population").unwrap()), &Attr::Int(expected), "{mode}");
        let offline = &s.project.maps.iter().find(|m| m.name == "Fieldwork (offline)").unwrap().layer_by_name("Assets").unwrap().dataset;
        assert_eq!(offline.fields, source.fields, "{mode}");
        assert_eq!(offline.features, source.features, "{mode}");
        // The synced copy is a map, with layers, of its own (a background run finds its map by it).
        let ids: Vec<u64> = s.project.maps.iter().map(|m| m.instance_id()).collect();
        assert!(ids.iter().enumerate().all(|(i, a)| ids[..i].iter().all(|b| a != b)), "{mode}: {ids:?}");
        let offline_map = s.project.maps.iter().find(|m| m.name == "Fieldwork (offline)").unwrap();
        assert_ne!(
            offline_map.layer_by_name("Assets").unwrap().instance_id(),
            s.map().layer_by_name("Assets").unwrap().instance_id(),
            "{mode}"
        );
    }

    for mode in ["source_deleted", "geometry_only", "offline_added", "source_reordered", "source_type_changed", "empty_offline_schema"] {
        let mut s = offline_field_session(&["Assets"], mode == "empty_offline_schema");
        if mode == "geometry_only" {
            s.map_mut().layers[0].dataset.features[0].geometry = Some(Geometry::Point(Coord::new(1.1, 1.0)));
        } else if mode != "empty_offline_schema" {
            s.run("edit.setValue", &json!({"layer": "Assets", "row": 0, "field": "population", "value": 20})).unwrap();
        }
        if mode == "offline_added" || mode == "empty_offline_schema" {
            s.run("edit.addField", &json!({"layer": "Assets", "name": "survey", "type": "long"})).unwrap();
        }
        s.run("map.activate", &json!({"name": "Map"})).unwrap();
        match mode {
            "source_deleted" | "geometry_only" => {
                s.run("edit.deleteField", &json!({"layer": "Assets", "field": "region"})).unwrap();
            }
            "source_reordered" => {
                let source = &mut s.map_mut().layers.iter_mut().find(|l| l.name == "Assets").unwrap().dataset;
                source.fields.swap(0, 1);
                source.features[0].attrs.swap(0, 1);
            }
            "source_type_changed" => {
                let source = &mut s.map_mut().layers.iter_mut().find(|l| l.name == "Assets").unwrap().dataset;
                source.fields[2].ty = FieldType::Text;
                source.features[0].attrs[2] = Attr::Text("10".into());
            }
            _ => {}
        }
        s.mark_saved();
        let before = serde_json::to_value(&s.project).unwrap();
        let undo_depth = s.undo_depth();
        for _ in 0..2 {
            let error = s.run("offline.sync", &json!({"name": "Fieldwork"})).unwrap_err();
            assert!(error.contains("Assets") && error.contains("fields"), "{mode}: {error}");
            assert_eq!(serde_json::to_value(&s.project).unwrap(), before, "{mode}");
            assert_eq!(s.undo_depth(), undo_depth, "{mode}");
            assert!(!s.dirty(), "{mode}");
        }
    }
}

#[test]
fn offline_sync_schema_refusal_rolls_back_other_layers_and_can_retry() {
    use rustgis_data::Value as Attr;

    let mut s = offline_field_session(&["Other", "Assets"], false);
    assert_eq!(s.map().layers[0].name, "Other", "sync the compatible layer before reaching the incompatible one");
    for (name, population) in [("Other", 99), ("Assets", 20)] {
        s.run("edit.setValue", &json!({"layer": name, "row": 0, "field": "population", "value": population})).unwrap();
    }
    s.run("map.activate", &json!({"name": "Map"})).unwrap();
    s.run("edit.deleteField", &json!({"layer": "Assets", "field": "region"})).unwrap();
    let before = serde_json::to_value(&s.project).unwrap();
    let undo_depth = s.undo_depth();
    assert!(s.run("offline.sync", &json!({"name": "Fieldwork"})).is_err());
    assert_eq!(serde_json::to_value(&s.project).unwrap(), before);
    assert_eq!(s.undo_depth(), undo_depth);

    // Undo and redo invalidate map geometry caches even while restoring the same project data.
    let undo_snapshot = |s: &Session| {
        let mut project = s.project.clone();
        for map in &mut project.maps {
            for layer in &mut map.layers {
                layer.geometry_rev = 0;
            }
        }
        serde_json::to_value(project).unwrap()
    };
    assert!(s.undo(), "restore the source field before retrying");
    let before_retry = undo_snapshot(&s);
    let synced = s.run("offline.sync", &json!({"name": "Fieldwork"})).unwrap();
    assert_eq!(synced["updated"], 2);
    for (name, population) in [("Other", 99), ("Assets", 20)] {
        let data = &s.map().layer_by_name(name).unwrap().dataset;
        assert_eq!(data.value(0, data.field_index("population").unwrap()), &Attr::Int(population));
    }
    let after_retry = undo_snapshot(&s);
    assert!(s.undo());
    assert_eq!(undo_snapshot(&s), before_retry);
    assert!(s.redo());
    assert_eq!(undo_snapshot(&s), after_retry);
}

#[test]
fn workspace_links_thumbnails_animation_profiles_offline_and_cache() {
    let dir = std::env::temp_dir().join(format!("rustgis-ws-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = world();
    s.run("layer.addDataBytes", &json!({"fileName": "dem.tif", "data": dem_b64()})).unwrap();
    let dem = s.map().layers.iter().find(|l| l.is_raster()).unwrap().name.clone();
    // Linked views.
    s.run("map.new", &json!({"name": "Second"})).unwrap();
    s.run("map.activate", &json!({"name": "World"})).unwrap();
    s.run("view.linkViews", &json!({"on": true})).unwrap();
    s.run("map.goToXY", &json!({"lon": 12.5, "lat": 41.9, "scale": 2_000_000})).unwrap();
    let second = s.project.maps.iter().find(|m| m.name == "Second").unwrap();
    let c = second.center_lonlat();
    assert!((c.x - 12.5).abs() < 1e-6 && (second.scale() / 2_000_000.0 - 1.0).abs() < 0.01, "{c:?}");
    // Thumbnails.
    s.run("project.thumbnail", &json!({"create": true})).unwrap();
    assert!(s.project.thumbnail.as_ref().is_some_and(|t| t.len() > 100));
    s.run("map.thumbnail", &json!({"image": s.project.thumbnail.clone().unwrap()})).unwrap();
    assert!(s.run("map.thumbnail", &json!({"image": "bm90"})).is_err());
    s.run("project.thumbnail", &json!({"clear": true})).unwrap();
    assert!(s.project.thumbnail.is_none());
    // Jobs.
    let j = s.run("job.new", &json!({"name": "Check roads", "viewExtent": true})).unwrap()["job"].as_u64().unwrap();
    s.run("job.update", &json!({"job": j, "status": "in progress", "assigned": "field team"})).unwrap();
    assert!(s.run("job.update", &json!({"job": j, "status": "abandoned"})).is_err());
    assert_eq!(s.project.jobs[0].status, "in progress");
    // Animation: two keyframes, exported as frames.
    s.run("animation.add", &Value::Null).unwrap();
    s.run("map.goToXY", &json!({"lon": 2.35, "lat": 48.85, "scale": 4_000_000})).unwrap();
    s.run("animation.add", &json!({"seconds": 1})).unwrap();
    let path = dir.join("anim.zip");
    s.run("animation.export", &json!({"path": path.display().to_string(), "fps": 5, "width": 160, "height": 100})).unwrap();
    let frames = rustgis_data::zip::read(&std::fs::read(&path).unwrap()).unwrap();
    assert_eq!(frames.len(), 6, "five frames for the second, then the last view");
    assert!(frames.iter().all(|(n, b)| n.ends_with(".png") && b.starts_with(b"\x89PNG")));
    s.run("animation.remove", &json!({"all": true})).unwrap();
    // Profiles over the hill.
    let p = s.run("profile.create", &json!({"layer": dem, "points": [[10.0015, 45.0195], [10.0385, 45.0195]]})).unwrap();
    assert!(p["max"].as_f64().unwrap() > 380.0 && p["gain"].as_f64().unwrap() > 150.0, "{}", p["max"]);
    let auto = s.run("profile.autoComplete", &json!({"layer": dem, "points": [[10.0015, 45.0195], [10.005, 45.0195]]})).unwrap();
    assert!(auto["length"].as_f64().unwrap() > 2500.0, "continues to the edge");
    let cross =
        s.run("profile.crossSection", &json!({"layer": dem, "points": [[10.0015, 45.0195], [10.0385, 45.0195]], "width": 2000})).unwrap();
    assert!((cross["length"].as_f64().unwrap() - 2000.0).abs() < 50.0);
    s.run("layer.template", &json!({"template": "lines", "name": "Trails"})).unwrap();
    s.run(
        "edit.addFeature",
        &json!({"layer": "Trails", "geometry": {"type": "LineString", "coordinates": [[10.002, 45.002], [10.038, 45.038]]}}),
    )
    .unwrap();
    let along = s.run("profile.alongLine", &json!({"layer": dem, "lines": "Trails"})).unwrap();
    assert!(along["samples"].as_array().unwrap().len() > 10);
    assert_eq!(s.run("profile.alongSelected", &json!({"layer": dem, "lines": "Trails"})).unwrap().as_array().unwrap().len(), 1);
    // Infographics and diagnostics.
    s.run("map.goToXY", &json!({"lon": 10.0, "lat": 48.0, "scale": 20_000_000})).unwrap();
    let info = s.run("info.infographic", &Value::Null).unwrap();
    assert!(info["layers"].as_array().unwrap().iter().any(|c| c["layer"] == "Cities" && c["count"].as_u64().unwrap() > 10));
    let d = s.run("info.diagnostics", &Value::Null).unwrap();
    assert!(d["features"].as_u64().unwrap() > 100 && d["rasterPixels"].as_u64().unwrap() == 1600);
    // Offline: download, edit offline, sync back.
    let r = s.run("offline.download", &json!({"name": "Paris", "extent": [1.0, 48.0, 4.0, 50.0]})).unwrap();
    assert!(r["features"].as_u64().unwrap() >= 2);
    s.run("offline.open", &json!({"name": "Paris"})).unwrap();
    assert_eq!(s.map().name, "Paris (offline)");
    s.run("select.byAttributes", &json!({"layer": "Cities", "where": "name = 'Paris'"})).unwrap();
    let row = s.map().layer_by_name("Cities").unwrap().selection[0];
    s.run("edit.setValue", &json!({"layer": "Cities", "row": row, "field": "pop_max", "value": 1})).unwrap();
    for (name, x) in [("Field camp", 2.0), ("Field hut", 2.2)] {
        s.run(
            "edit.addFeature",
            &json!({"layer": "Cities", "geometry": {"type": "Point", "coordinates": [x, 49.0]}, "attributes": {"name": name}}),
        )
        .unwrap();
    }
    // Meanwhile France is edited in the source map; the area's untouched copy mustn't undo that.
    let set_france = |s: &mut Session, v: i64| {
        let world = s.project.maps.iter_mut().find(|m| m.name == "World").unwrap();
        let countries = world.layers.iter_mut().find(|l| l.name == "Countries").unwrap();
        let (ni, pi) = (countries.dataset.field_index("name").unwrap(), countries.dataset.field_index("pop_est").unwrap());
        let f = countries.dataset.features.iter_mut().find(|f| f.attrs[ni].to_string() == "France").unwrap();
        if v >= 0 {
            f.attrs[pi] = rustgis_data::Value::Int(v);
        }
        f.attrs[pi].clone()
    };
    set_france(&mut s, 12_345);
    let mark = s.notice_mark();
    let sync = s.run("offline.sync", &json!({"name": "Paris"})).unwrap();
    let clean = s.notices_since(mark);
    assert!(clean.iter().all(|n| !n.text.starts_with("Offline area")), "{clean:?}");
    assert_eq!((sync["updated"].as_u64(), sync["added"].as_u64()), (Some(1), Some(2)), "{sync}");
    assert_eq!(set_france(&mut s, -1), rustgis_data::Value::Int(12_345), "the source edit survives the sync");
    let world_map = s.project.maps.iter().find(|m| m.name == "World").unwrap();
    let cities = world_map.layer_by_name("Cities").unwrap();
    assert!(cities.dataset.features.iter().any(|f| f.attrs.iter().any(|v| v.to_string() == "Field camp")));
    assert_eq!(sync["conflicts"], 0, "a change made only in the source is no conflict");
    // Paris changed in both, and the field camp deleted offline but changed in the map: the area's
    // version wins, a warning names both, and Undo restores the map's. The field hut, changed only
    // in the map, is no conflict.
    let paris = |s: &mut Session, map: &str, v: Option<i64>| {
        let m = s.project.maps.iter_mut().find(|m| m.name == map).unwrap();
        let cities = m.layers.iter_mut().find(|l| l.name == "Cities").unwrap();
        let (ni, pi) = (cities.dataset.field_index("name").unwrap(), cities.dataset.field_index("pop_max").unwrap());
        let f = cities.dataset.features.iter_mut().find(|f| f.attrs[ni].to_string() == "Paris").unwrap();
        if let Some(v) = v {
            f.attrs[pi] = rustgis_data::Value::Int(v);
        }
        (f.id, f.attrs[pi].clone())
    };
    paris(&mut s, "Paris (offline)", Some(2));
    let (id, _) = paris(&mut s, "World", Some(3));
    /// The features of `map`'s Cities layer, and the row of the one named `name` among them.
    fn named<'a>(s: &'a mut Session, map: &str, name: &str) -> (&'a mut Vec<rustgis_data::Feature>, usize) {
        let m = s.project.maps.iter_mut().find(|m| m.name == map).unwrap();
        let features = &mut m.layers.iter_mut().find(|l| l.name == "Cities").unwrap().dataset.features;
        let i = features.iter().position(|f| f.attrs.iter().any(|v| v.to_string() == name)).unwrap();
        (features, i)
    }
    let (features, i) = named(&mut s, "Paris (offline)", "Field camp");
    let camp_id = features.remove(i).id;
    let (features, i) = named(&mut s, "World", "Field camp");
    features[i].geometry = Some(rustgis_data::Geometry::Point(rustgis_geom::Coord::new(2.5, 49.0)));
    let (features, i) = named(&mut s, "World", "Field hut");
    features[i].geometry = Some(rustgis_data::Geometry::Point(rustgis_geom::Coord::new(2.2, 49.3)));
    let mark = s.notice_mark();
    let sync = s.run("offline.sync", &json!({"name": "Paris"})).unwrap();
    assert_eq!((sync["updated"].as_u64(), sync["deleted"].as_u64(), sync["conflicts"].as_u64()), (Some(1), Some(1), Some(2)), "{sync}");
    assert_eq!(paris(&mut s, "World", None).1, rustgis_data::Value::Int(2));
    let warned = s.notices_since(mark);
    assert!(
        warned.iter().any(|n| n.text.contains(&format!("Cities #{id}")) && n.text.contains(&format!("Cities #{camp_id}"))),
        "{warned:?}"
    );
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(paris(&mut s, "World", None).1, rustgis_data::Value::Int(3), "Undo restores the map's version");
    let (features, i) = named(&mut s, "World", "Field camp");
    assert_eq!(features[i].id, camp_id, "Undo restores the deleted field camp");
    // Paris edited offline but deleted from the map meanwhile: the edit is dropped, and said.
    let world = s.project.maps.iter_mut().find(|m| m.name == "World").unwrap();
    let cities = world.layers.iter_mut().find(|l| l.name == "Cities").unwrap();
    cities.dataset.features.retain(|f| f.id != id);
    let mark = s.notice_mark();
    let sync = s.run("offline.sync", &json!({"name": "Paris"})).unwrap();
    assert_eq!(sync["skipped"], 1, "{sync}");
    let warned = s.notices_since(mark);
    assert!(warned.iter().any(|n| n.text.contains("deleted from the map") && n.text.contains(&format!("Cities #{id}"))), "{warned:?}");
    s.run("offline.remove", &json!({"name": "Paris"})).unwrap();
    assert!(s.project.maps.iter().all(|m| m.name != "Paris (offline)"));
    // Feature cache.
    s.run("map.activate", &json!({"name": "World"})).unwrap();
    s.run("cache.empty", &Value::Null).unwrap();
    assert_eq!(s.run("info.diagnostics", &Value::Null).unwrap()["cachedLayers"], 0);
    s.run("cache.fill", &Value::Null).unwrap();
    assert!(s.run("info.diagnostics", &Value::Null).unwrap()["cachedLayers"].as_u64().unwrap() >= 4);
    s.run("cache.auto", &json!({"on": true})).unwrap();
    s.run("map.projection", &json!({"type": "mollweide"})).unwrap();
    assert!(s.map().layers.iter().filter(|l| !l.is_raster()).all(|l| l.is_cached("mollweide")));
    s.run("cache.cancel", &Value::Null).unwrap();
    assert!(!s.auto_cache);
    let _ = std::fs::remove_dir_all(&dir);
}

// ---------------------------------------------------------------------------------------------
// plugins

/// Loads the test plugin as `id` with `perms`.
fn plugin(id: &str, perms: &[&str]) {
    let pkg = rustgis_plugins::Package::from_zip(&rustgis_plugins::testing::package(id, perms)).unwrap();
    rustgis_plugins::load(pkg, "test").unwrap();
}

/// Runs the test plugin's forwarding command: it sends `op` with `params` to the host.
fn forward(s: &mut Session, id: &str, op: &str, params: Value) -> crate::CmdResult {
    s.run(&format!("plugin:{id}/f"), &json!({"op": op, "params": params}))
}

#[test]
fn plugin_commands_run_like_commands() {
    let mut s = world();
    plugin("eng-view", &[]);
    assert_eq!(s.run("plugin:eng-view/h", &Value::Null).unwrap(), json!({"hello": "world"}));
    assert!(!s.can_undo(), "a plugin without 'edit' doesn't take undo snapshots");
    // Reading the map needs no permission.
    let layers = forward(&mut s, "eng-view", "host.layers", json!({})).unwrap();
    assert!(layers.as_array().unwrap().iter().any(|l| l["name"] == "Cities"));
    let fc = forward(&mut s, "eng-view", "host.features", json!({"layer": "Cities", "limit": 2})).unwrap();
    assert_eq!(fc["features"].as_array().unwrap().len(), 2);
    assert_eq!(fc["features"][1]["row"], 1);
    assert!(forward(&mut s, "eng-view", "map.zoomIn", json!({})).is_ok(), "view commands are fine");
    // Changing the project isn't.
    let e = forward(&mut s, "eng-view", "layer.remove", json!({"layer": "Cities"})).unwrap_err();
    assert!(e.contains("'edit' permission"), "{e}");
    let e = forward(&mut s, "eng-view", "host.addLayer", json!({"geojson": {"type": "Point", "coordinates": [1, 2]}})).unwrap_err();
    assert!(e.contains("'edit' permission"), "{e}");
    assert!(s.map().layer_by_name("Cities").is_some());
    // Listed with the built-in commands; unknown and disabled ones are errors.
    let all = s.run("info.commands", &Value::Null).unwrap();
    assert!(all.as_array().unwrap().iter().any(|c| c["id"] == "plugin:eng-view/h"));
    assert!(s.run("plugin:eng-view/nope", &Value::Null).unwrap_err().contains("unknown command"));
    s.run("plugin.enable", &json!({"id": "eng-view", "enabled": false})).unwrap();
    assert!(s.run("plugin:eng-view/h", &Value::Null).unwrap_err().contains("disabled"));
    rustgis_plugins::unload("eng-view");
}

#[test]
fn plugin_edits_are_one_undo_step() {
    let mut s = world();
    plugin("eng-edit", &["edit"]);
    let r =
        forward(&mut s, "eng-edit", "host.addLayer", json!({"name": "Pins", "geojson": {"type": "Point", "coordinates": [1, 2]}})).unwrap();
    assert!(r["layer"].as_u64().is_some());
    assert!(s.map().layer_by_name("Pins").is_some());
    assert_eq!(s.undo_label(), Some("Forward"));
    s.run("edit.undo", &Value::Null).unwrap();
    assert!(s.map().layer_by_name("Pins").is_none());
    forward(&mut s, "eng-edit", "layer.remove", json!({"layer": "Cities"})).unwrap();
    assert!(s.map().layer_by_name("Cities").is_none());
    // A failing command restores the project.
    let n = s.map().layers.len();
    assert!(forward(&mut s, "eng-edit", "layer.remove", json!({"layer": "Nope"})).is_err());
    assert_eq!(s.map().layers.len(), n);
    // Some things are off limits whatever the permissions.
    for op in ["script.run", "project.new", "edit.undo", "plugin.uninstall", "plugin:eng-edit/h", "gp.setGeolibre", "gp.uninstallGeolibre"]
    {
        assert!(forward(&mut s, "eng-edit", op, json!({})).is_err(), "{op}");
    }
    // Files need their own permission.
    let e = forward(&mut s, "eng-edit", "layer.addData", json!({"path": "/etc/passwd"})).unwrap_err();
    assert!(e.contains("'files' permission"), "{e}");
    for (op, params) in [
        ("share.exportMap", json!({})),
        ("project.save", json!({})),
        ("layer.rename", json!({"layer": "Cities", "name": "x", "output": 1})),
        ("layer.rename", json!({"layer": "Cities", "name": "https://example.com/x"})),
        ("layer.rename", json!({"layer": "Cities", "name": "../../x"})),
        ("layer.rename", json!({"layer": "Cities", "name": {"nested": {"url": "x"}}})),
    ] {
        let e = forward(&mut s, "eng-edit", op, params.clone()).unwrap_err();
        assert!(e.contains("'files' permission"), "{op} {params}: {e}");
    }
    assert!(forward(&mut s, "eng-edit", "layer.rename", json!({"layer": "Rivers", "name": "Streams"})).is_ok());
    rustgis_plugins::unload("eng-edit");
}

/// A built-in tool's output layer stays in the session, so a plugin with `edit` alone may name
/// it, as a task from a file may. A name that could be a path, and tools that may write files
/// (GeoLibre's, those that save one), still need `files`.
#[test]
fn plugin_tools_name_their_output_layer_with_edit_alone() {
    use crate::cmd::plugins::reaches;
    let mut s = world();
    plugin("eng-out", &["edit"]);
    #[cfg(feature = "geolibre")]
    crate::cmd::gp::external_load_manifests(
        &json!([{
            "id":"slope", "display_name":"Slope", "params":[
                {"name":"input","data_kind":"raster","io_role":"input","required":true},
                {"name":"output","data_kind":"raster","io_role":"output"}
            ]
        }])
        .to_string(),
    )
    .unwrap();
    let clip = json!({"tool": "clip", "params": {"input": "Cities", "clip": "Countries", "output": "Cities in countries"}});
    let gp = s.registry.get("gp.run").copied().unwrap();
    assert!(reaches(&gp, &clip).is_none(), "the assistant doesn't ask either");
    forward(&mut s, "eng-out", "gp.run", clip).unwrap();
    assert!(s.map().layer_by_name("Cities in countries").is_some());
    for params in [
        json!({"tool": "clip", "params": {"input": "Cities", "clip": "Countries", "output": "out/cities"}}),
        json!({"tool": "clip", "params": {"input": "Cities", "clip": "Countries", "output": "cities.shp"}}),
        json!({"tool": "clip", "params": {"input": "Cities", "clip": "Countries", "output": "C:\\cities"}}),
        #[cfg(feature = "geolibre")]
        json!({"tool": "geolibre:slope", "params": {"input": "Cities", "output": "slope"}}),
        json!({"tool": "vectorToPmtiles", "params": {"input": "Cities", "minZoom": 0, "maxZoom": 0, "output": "cities"}}),
    ] {
        let e = forward(&mut s, "eng-out", "gp.run", params.clone()).unwrap_err();
        assert!(e.contains("'files' permission"), "{params}: {e}");
    }
    rustgis_plugins::unload("eng-out");
}

/// The real Wasm forwarding command may run only its own tool, resolved by id or display
/// name, with edit and file requirements preserved. Process tools share the same boundary.
#[test]
fn plugin_bridges_cannot_run_another_plugins_tools() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::plugin_bridges_cannot_run_another_plugins_tools") {
        return;
    }
    let mut s = world();
    for id in ["eng-bridge-owner", "eng-bridge-other"] {
        let mut pkg = rustgis_plugins::Package::from_zip(&rustgis_plugins::testing::package(id, &["edit"])).unwrap();
        pkg.manifest.tools[0].name = format!("Points for {id}");
        rustgis_plugins::load(pkg, "test").unwrap();
    }
    let before = s.map().layers.len();
    for tool in ["plugin:eng-bridge-other/m", "Points for eng-bridge-other"] {
        let why = forward(&mut s, "eng-bridge-owner", "gp.run", json!({"tool": tool, "params": {"input": "Cities"}})).unwrap_err();
        assert!(why.contains("another plugin") && why.contains("eng-bridge-other"), "{why}");
        assert_eq!(s.map().layers.len(), before);
    }
    for tool in ["plugin:eng-bridge-owner/m", "Points for eng-bridge-owner"] {
        forward(&mut s, "eng-bridge-owner", "gp.run", json!({"tool": tool, "params": {"input": "Cities"}})).unwrap();
    }
    assert_eq!(s.map().layers.len(), before + 2);
    plugin("eng-bridge-readonly", &[]);
    let why =
        forward(&mut s, "eng-bridge-readonly", "gp.run", json!({"tool": "plugin:eng-bridge-readonly/m", "params": {"input": "Cities"}}))
            .unwrap_err();
    assert!(why.contains("'edit' permission"), "{why}");
    // File-shaped parameters to an own tool still require files before the tool runs.
    let why = forward(
        &mut s,
        "eng-bridge-owner",
        "gp.run",
        json!({"tool": "plugin:eng-bridge-owner/m", "params": {"input": "Cities", "path": "never-opened.nc"}}),
    )
    .unwrap_err();
    assert!(why.contains("'files' permission"), "{why}");
    #[cfg(not(target_arch = "wasm32"))]
    {
        let run = rustgis_plugins::testing::child_run("tests::plugin_process_child");
        let manifest =
            rustgis_plugins::Manifest::parse(&rustgis_plugins::testing::process_manifest("eng-bridge-process", &[], &run)).unwrap();
        let pkg =
            rustgis_plugins::Package { manifest, wasm: vec![], sha256: "test".into(), dir: Some(std::env::temp_dir()), skills: vec![] };
        rustgis_plugins::load(pkg, "test").unwrap();
        let why =
            forward(&mut s, "eng-bridge-owner", "gp.run", json!({"tool": "plugin:eng-bridge-process/m", "params": {"input": "Cities"}}))
                .unwrap_err();
        assert!(why.contains("another plugin"), "{why}");
        assert_eq!(s.map().layers.len(), before + 2, "no process tool ran");
        rustgis_plugins::unload("eng-bridge-process");
    }
    for id in ["eng-bridge-owner", "eng-bridge-other", "eng-bridge-readonly"] {
        rustgis_plugins::unload(id);
    }
}

/// A plugin's command the app runs leaves its downloads to the app, which fetches them off the
/// frame (as the browser does): nothing waits, and nothing is an undo step until the data lands,
/// with what the plugin asked (how a table's points are read) kept. Run another way (the command
/// line, a script), the same command waits for the download and says how it went.
#[test]
fn plugin_downloads_are_left_to_the_app() {
    let mut s = world();
    plugin("eng-url", &["edit", "network"]);
    let (undo, layers) = (s.undo.len(), s.map().layers.len());
    // Nothing answers there: a download that waited fails.
    let url = "http://127.0.0.1:9/places.csv";
    let p = json!({"op": "layer.addUrl", "params": {"url": url, "name": "Places", "x": "lon", "y": "lat"}});
    // The command waits for the download, to run again once it is added (#1202).
    assert_eq!(s.run_leaving_downloads("plugin:eng-url/f", &p).unwrap(), json!({"pending": true, "downloading": [url]}));
    assert_eq!((s.undo.len(), s.map().layers.len()), (undo, layers));
    let asked = s.take_url_requests();
    assert_eq!(asked.len(), 1);
    assert_eq!(
        (asked[0].params()["name"].as_str(), asked[0].params()["x"].as_str(), asked[0].params()["y"].as_str()),
        (Some("Places"), Some("lon"), Some("lat"))
    );
    assert!(asked[0].params()["request"].is_u64());
    s.request_failed(asked[0].params(), "dropped");
    s.poll_plugin_retries();
    assert!(s.run("plugin:eng-url/f", &p).is_err(), "run otherwise, it waits");
    assert!(s.take_url_requests().is_empty());
    // An edit run that way is an undo step still.
    let p = json!({"op": "layer.rename", "params": {"layer": "Rivers", "name": "Streams"}});
    s.run_leaving_downloads("plugin:eng-url/f", &p).unwrap();
    assert_eq!(s.undo.len(), undo + 1);
    rustgis_plugins::unload("eng-url");
}

/// A command that gives up says which of its downloads now won't start; one another command
/// waits for still comes, so it isn't named.
#[test]
fn a_command_giving_up_names_the_downloads_it_leaves() {
    let mut s = world();
    plugin("eng-giveup", &["edit", "network"]);
    plugin("eng-giveup-other", &["edit", "network"]);
    let add = |url: &str| json!({"op": "layer.addUrl", "params": {"url": url}});
    s.retry_tries = crate::cmd::plugins::fetch::MAX_RETRIES;
    let e = s.run_leaving_downloads("plugin:eng-giveup/f", &add("https://x.org/new.csv?token=hunter2")).unwrap_err();
    assert!(e.contains("gave up") && e.contains("its download of https://x.org/new.csv") && !e.contains("hunter2"), "{e}");
    assert!(s.take_url_requests().is_empty(), "not started");
    s.retry_tries = 0;
    s.run_leaving_downloads("plugin:eng-giveup-other/f", &add("https://x.org/shared.csv")).unwrap();
    s.retry_tries = crate::cmd::plugins::fetch::MAX_RETRIES;
    let e = s.run_leaving_downloads("plugin:eng-giveup/f", &add("https://x.org/shared.csv")).unwrap_err();
    assert!(e.contains("gave up") && e.contains("wasn't started"), "{e}: another plugin gets its own request");
    assert_eq!(s.take_url_requests()[0].params()["url"], "https://x.org/shared.csv", "the other command's still comes");
    rustgis_plugins::unload("eng-giveup");
    rustgis_plugins::unload("eng-giveup-other");
}

/// A plugin command whose `layer.addUrl` left a download to the app runs again once the app
/// has added it, and that call then answers the layer added, so the command goes on with it
/// (#1202). A failed download is the call's error then; a command clicked twice waits for the
/// one download.
#[test]
fn a_plugin_command_runs_again_when_its_download_is_added() {
    let mut s = world();
    plugin("eng-rerun", &["edit", "network"]);
    let layers = s.map().layers.len();
    let url = "https://x.org/places.csv";
    let p = json!({"op": "layer.addUrl", "params": {"url": url, "name": "Places", "x": "lon", "y": "lat"}});
    assert_eq!(s.run_leaving_downloads("plugin:eng-rerun/f", &p).unwrap()["downloading"], json!([url]));
    let asked = s.take_url_requests();
    assert_eq!(asked.len(), 1);
    assert_eq!(asked[0].params()["anonymous"], json!(true), "no saved login goes with a plugin's download");
    // Clicked again while it downloads: the same download, not a second one.
    s.run_leaving_downloads("plugin:eng-rerun/f", &p).unwrap();
    assert!(s.take_url_requests().is_empty(), "one download");
    assert!(s.poll_plugin_retries().is_empty(), "nothing landed yet");
    // The app downloads it and adds it, with the request's number, as its own step.
    let id = s.download_started_for(&asked[0]).unwrap();
    assert!(
        s.download_landed(
            id,
            b"name,lon,lat
A,10,50
B,11,51
"
            .to_vec()
        )
    );
    let mut add = asked[0].params().clone();
    add["id"] = json!(id);
    s.complete_download(id, &add).unwrap();
    assert_eq!(s.map().layers.len(), layers + 1);
    let added = s.map().layer_by_name("Places").unwrap().id;
    // The command runs again: its `layer.addUrl` answers the layer added, and adds nothing (nor
    // an undo step of its own, having changed nothing).
    let undo = s.undo.len();
    let ran = s.poll_plugin_retries();
    assert_eq!(ran.len(), 1, "{ran:?}");
    let (cmd, answer) = &ran[0];
    assert_eq!(cmd, "plugin:eng-rerun/f");
    assert_eq!(answer.as_ref().unwrap()["layer"], json!(added), "{answer:?}");
    assert_eq!((s.map().layers.len(), s.undo.len()), (layers + 1, undo), "added once");
    assert!(s.take_url_requests().is_empty() && !s.plugin_retries_waiting());
    assert!(s.poll_plugin_retries().is_empty(), "run once");
    // A download that fails: the command runs again, and its `layer.addUrl` answers the error.
    let q = json!({"op": "layer.addUrl", "params": {"url": "https://x.org/gone.csv"}});
    s.run_leaving_downloads("plugin:eng-rerun/f", &q).unwrap();
    let asked = s.take_url_requests();
    s.request_failed(asked[0].params(), "https://x.org/gone.csv?token=hunter2: 404 Not Found");
    let ran = s.poll_plugin_retries();
    let e = ran[0].1.as_ref().unwrap_err();
    assert!(e.contains("404") && !e.contains("hunter2"), "{ran:?}");
    assert!(!s.plugin_retries_waiting());
    // A native request and a plugin request get distinct engine routing numbers.
    let next = s.next_request + 1;
    s.request_url(&json!({"url": "https://x.org/other.csv", "request": next})).unwrap();
    let q = json!({"op": "layer.addUrl", "params": {"url": "https://x.org/mine.csv"}});
    s.run_leaving_downloads("plugin:eng-rerun/f", &q).unwrap();
    let asked = s.take_url_requests();
    let urls: Vec<_> = asked.iter().map(|q| (q.params()["url"].as_str(), q.params()["request"].as_u64())).collect();
    assert_eq!(urls, [(Some("https://x.org/other.csv"), Some(next)), (Some("https://x.org/mine.csv"), Some(next + 1))]);
    // A run replaced by one asking for another address before its download was started: that
    // download is never started, and the notice of the replaced run says so.
    let first = json!({"op": "layer.addUrl", "params": {"url": "https://x.org/first.csv"}});
    s.run_leaving_downloads("plugin:eng-rerun/f", &first).unwrap();
    let mark = s.notice_mark();
    let second = json!({"op": "layer.addUrl", "params": {"url": "https://x.org/second.csv"}});
    s.run_leaving_downloads("plugin:eng-rerun/f", &second).unwrap();
    let said: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
    assert!(
        said.iter().any(|t| t.contains("replaced by this one") && t.contains("its download of https://x.org/first.csv wasn't started")),
        "{said:?}"
    );
    let left = s.take_url_requests();
    assert!(left.iter().all(|q| q.params()["url"] != "https://x.org/first.csv"), "{} remaining requests", left.len());
    rustgis_plugins::unload("eng-rerun");
}

/// Retry metadata and queued capabilities obey the same outer transaction as actual plugin edits.
#[test]
fn plugin_download_retries_roll_back_with_their_outer_command() {
    let mut s = world();
    plugin("eng-outer-url", &["edit", "network"]);
    let call = |url: &str| json!({"op":"layer.addUrl", "params":{"url":url}});
    s.run_leaving_downloads("plugin:eng-outer-url/f", &call("https://x.org/kept.csv")).unwrap();
    let before = serde_json::to_value(&s.project).unwrap();
    let mut pending = Value::Null;
    let result = s.guarded("Failed plugin composite", true, |s| {
        pending = s.run_leaving_downloads("plugin:eng-outer-url/f", &call("https://x.org/rolled-back.csv"))?;
        s.run("layer.addDataText", &json!({"fileName":"broken.geojson", "text":"{"}))
    });
    assert_eq!(pending["downloading"], json!(["https://x.org/rolled-back.csv"]), "the real plugin suspended before the outer failure");
    assert!(result.is_err(), "{result:?}");
    assert_eq!(serde_json::to_value(&s.project).unwrap(), before);
    let kept = s.take_url_requests();
    assert_eq!(kept.len(), 1);
    assert_eq!(kept[0].params()["url"], "https://x.org/kept.csv");
    assert!(s.plugin_retries_waiting() && s.poll_plugin_retries().is_empty());
    s.request_failed(kept[0].params(), "cancelled");
    assert_eq!(s.poll_plugin_retries().len(), 1);
    // An opaque request taken during a failed outer guard stays retired, not just hidden.
    let mut escaped = None;
    let result = s.guarded("Failed plugin wrapper", true, |s| {
        s.run_leaving_downloads("plugin:eng-outer-url/f", &call("https://x.org/escaped.csv"))?;
        escaped = s.take_url_requests().pop();
        Err("outer command failed".into())
    });
    assert!(result.is_err());
    let escaped = escaped.unwrap();
    assert!(s.download_started_for(&escaped).is_err());
    assert!(!s.plugin_retries_waiting() && s.poll_plugin_retries().is_empty() && s.take_url_requests().is_empty());
    // A prior queued key consumed inside a failed guard is never restored by its checkpoint.
    s.request_url(&json!({"url":"https://x.org/consumed.csv"})).unwrap();
    let issued = s.take_url_requests();
    let result = s.guarded("Claim then fail", true, |s| {
        let id = s.download_started_for(&issued[0])?;
        s.download_failed(id);
        Err("failed after claim".into())
    });
    assert!(result.is_err() && s.download_started_for(&issued[0]).is_err());
    rustgis_plugins::unload("eng-outer-url");
}

/// A routing number cannot consume another session's claim or wait; a revoked original owner
/// is retired before dequeue and never rerun as a fresh native User.
#[test]
fn plugin_download_retries_keep_their_original_owner() {
    use crate::policy::{Call, Effects, Outcome, Revocation, Scope};
    use std::sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    };
    struct Live(AtomicBool);
    impl Revocation for Live {
        fn allows(&self, _: Effects) -> bool {
            self.0.load(Ordering::SeqCst)
        }
    }
    let mut s = world();
    plugin("eng-owned-url", &["edit", "network"]);
    let params = json!({"op":"layer.addUrl","params":{"url":"https://x.org/owned.csv"}});
    let live = Arc::new(Live(AtomicBool::new(true)));
    let scope = Scope::assistant(146101, live.clone());
    let call = Call::command("plugin:eng-owned-url/f", params.clone());
    let Outcome::NeedsApproval(prepared) = s.review(&scope, &call) else { panic!("plugin must ask") };
    let pending = s.with_deferred_downloads(|s| s.run_permitted(scope, prepared.allow(), &call)).unwrap();
    assert_eq!(pending["downloading"], json!(["https://x.org/owned.csv"]));
    assert!(s.plugin_retries_waiting(), "approved work is pending before revocation");
    let before = serde_json::to_value(&s.project).unwrap();
    live.0.store(false, Ordering::SeqCst);
    assert!(s.take_url_requests().is_empty());
    let ran = s.poll_plugin_retries();
    assert_eq!(ran.len(), 1);
    assert!(ran[0].1.is_err());
    assert!(!s.plugin_retries_waiting() && s.poll_plugin_retries().is_empty());
    assert_eq!(serde_json::to_value(&s.project).unwrap(), before);
    let mut first = world();
    let mut second = world();
    first.run_leaving_downloads("plugin:eng-owned-url/f", &params).unwrap();
    second.run_leaving_downloads("plugin:eng-owned-url/f", &params).unwrap();
    let foreign = first.take_url_requests();
    let rightful = second.take_url_requests();
    assert_eq!(foreign[0].params()["request"], rightful[0].params()["request"], "routing numbers are session-local");
    assert!(second.download_started_for(&foreign[0]).is_err());
    let other = Scope::assistant(146102, Arc::new(Live(AtomicBool::new(true))));
    second.with_scope(other, |s| s.request_failed(rightful[0].params(), "foreign cancellation")).unwrap();
    assert!(second.poll_plugin_retries().is_empty() && second.plugin_retries_waiting());
    let id = second.download_started_for(&rightful[0]).unwrap();
    assert!(second.download_landed(id, b"name,lon,lat\nA,1,2\n".to_vec()));
    let mut p = rightful[0].params().clone();
    p["id"] = json!(id);
    second.complete_download(id, &p).unwrap();
    let ran = second.poll_plugin_retries();
    assert_eq!(ran.len(), 1);
    assert!(ran[0].1.is_ok());
    assert!(second.download_started_for(&rightful[0]).is_err());
    assert!(first.poll_plugin_retries().is_empty() && first.plugin_retries_waiting());
    rustgis_plugins::unload("eng-owned-url");
}

#[test]
fn plugin_panels_keep_their_state_between_calls() {
    let mut s = world();
    let pkg = rustgis_plugins::Package::from_zip(&rustgis_plugins::testing::panel_package("eng-panel")).unwrap();
    rustgis_plugins::load(pkg, "test").unwrap();
    // Opening it runs its state command, whose answer the session keeps.
    let st = s.run("plugin.panel", &json!({"id": "eng-panel", "refresh": true})).unwrap();
    assert_eq!(st["values"]["release"], 12);
    assert_eq!(st["items"]["release"]["labels"][12], "2025-12-18");
    assert_eq!(st["items"]["newer"]["enabled"], false);
    assert!(!s.can_undo(), "a state command that changes nothing is no undo step");
    // A widget's command gets the values, the one it set among them, and not as a parameter.
    let got = s.run("plugin:eng-panel/q", &json!({"panel": {"release": 4, "nope": 1}, "keep": true})).unwrap();
    assert_eq!(got["panel"], json!({"values": {"local": false, "release": 4}, "changed": ["release"]}));
    assert_eq!(got["params"], json!({"keep": true}));
    assert_eq!(s.plugin_panels["eng-panel"].slider("release"), 4);
    // Any command gets them, from the ribbon or a script, and widgets that run nothing set them.
    s.run("plugin.panel", &json!({"id": "eng-panel", "values": {"local": true, "release": 99}})).unwrap();
    let got = s.run("plugin:eng-panel/h", &json!({})).unwrap();
    assert_eq!(got, json!({"hello": "world"}));
    let got = s.run("plugin:eng-panel/q", &json!({})).unwrap();
    assert_eq!(got["panel"], json!({"values": {"local": true, "release": 12}, "changed": []}), "kept within the slider's ends");
    // A failed command leaves the values as they were.
    assert!(s.run("plugin:eng-panel/e", &json!({"panel": {"release": 1}})).is_err());
    assert_eq!(s.plugin_panels["eng-panel"].slider("release"), 12);
    // Hostile values and answers never panic, and never leave the slider outside its ends.
    for junk in [json!(null), json!(7), json!("x"), json!([1]), json!({"release": "1"}), json!({"release": 1e300}), json!({"local": {}})] {
        let _ = s.run("plugin:eng-panel/q", &json!({"panel": junk.clone()}));
        let _ = s.run("plugin.panel", &json!({"id": "eng-panel", "values": junk}));
        let st = &s.plugin_panels["eng-panel"];
        assert!((0..=12).contains(&st.slider("release")));
    }
    // Plugins without a panel get no `panel`, and keep a `panel` parameter of their own.
    plugin("eng-nopanel", &[]);
    assert!(s.run("plugin.panel", &json!({"id": "eng-nopanel"})).unwrap_err().contains("no panel"));
    assert!(s.plugin_panel("eng-nopanel").is_none());
    assert_eq!(forward(&mut s, "eng-nopanel", "host.info", json!({})).unwrap()["plugin"], "eng-nopanel");
    assert!(s.run("plugin.panel", &json!({"id": "nope"})).is_err());
    assert!(s.run("plugin.panel", &json!({})).is_err());
    // A plugin can't drive panels.
    let e = forward(&mut s, "eng-nopanel", "plugin.panel", json!({"id": "eng-panel"})).unwrap_err();
    assert!(e.contains("can't run"), "{e}");
    // A disabled plugin's panel is gone.
    rustgis_plugins::set_enabled("eng-panel", false).unwrap();
    assert!(s.plugin_panel("eng-panel").is_none());
    assert!(s.run("plugin.panel", &json!({"id": "eng-panel"})).unwrap_err().contains("disabled"));
    rustgis_plugins::unload("eng-panel");
    rustgis_plugins::unload("eng-nopanel");
}

/// Loads the panel test plugin with `edit`, its panel's state command being `state`.
fn panel_plugin(id: &str, state: &str) {
    let mut m: Value = serde_json::from_str(&rustgis_plugins::testing::panel_manifest(id)).unwrap();
    m["permissions"] = json!(["edit"]);
    m["panel"]["state"] = json!(state);
    let zip =
        rustgis_plugins::testing::zip_of(&[("plugin.json", m.to_string().as_bytes()), ("plugin.wasm", &rustgis_plugins::testing::wasm())]);
    rustgis_plugins::load(rustgis_plugins::Package::from_zip(&zip).unwrap(), "test").unwrap();
}

#[test]
fn panel_state_commands_that_change_nothing_are_no_undo_step() {
    let mut s = world();
    panel_plugin("eng-noop", "h");
    s.run("plugin.panel", &json!({"id": "eng-noop", "refresh": true})).unwrap();
    s.run("plugin:eng-noop/h", &Value::Null).unwrap();
    assert!(!s.can_undo(), "its state command changed nothing");
    // Its other commands keep their undo step, as plugins without a panel do.
    s.run("plugin:eng-noop/q", &Value::Null).unwrap();
    assert_eq!(s.undo_label(), Some("Echo"));
    rustgis_plugins::unload("eng-noop");
    plugin("eng-nopanel-noop", &["edit"]);
    s.undo.clear();
    s.run("plugin:eng-nopanel-noop/h", &Value::Null).unwrap();
    assert_eq!(s.undo_label(), Some("Hello"));
    rustgis_plugins::unload("eng-nopanel-noop");
}

#[test]
fn a_failed_panel_refresh_leaves_the_values() {
    let mut s = world();
    panel_plugin("eng-badstate", "e");
    let e = s.run("plugin.panel", &json!({"id": "eng-badstate", "values": {"local": true}, "refresh": true}));
    assert!(e.is_err());
    assert!(!s.plugin_panels["eng-badstate"].checked("local"), "the values it set are undone");
    rustgis_plugins::unload("eng-badstate");
}

/// A data cube can be a Zarr store's folder or a STAC API's address, so a plugin needs both
/// `files` and `network` to summarise one or work out its trend.
#[test]
fn plugin_data_cubes_need_files_and_network() {
    let mut s = world();
    plugin("eng-cube-files", &["edit", "files"]);
    for id in ["cube.reduce", "cube.trend"] {
        let p = json!({"url": "https://example.com/stac/v1", "collection": "c", "asset": "NDVI", "stat": "mean"});
        let e = forward(&mut s, "eng-cube-files", id, p).unwrap_err();
        assert!(e.contains("'files' and 'network' permissions"), "{id}: {e}");
    }
    rustgis_plugins::unload("eng-cube-files");
}

/// A mosaic of the project's raster layers, written to no file, stays in the project: a plugin
/// with `edit` alone may make one, and none without it. Writing it to a `path`, or an input read
/// from disk (a raster file name that isn't a layer), needs `files`; inputs the command reads no
/// file for fail in the command instead.
#[test]
fn plugin_mosaics_of_project_layers_need_no_files() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let mut s = world();
    // A layer named like a path is still taken for a place; one named like a bare file isn't.
    for (name, x0) in [("west", 0.0), ("east", 1.0), ("../east.tif", 2.0), ("north.tif", 3.0)] {
        let gt = GeoTransform { origin_x: x0, origin_y: 1.0, pixel_width: 0.1, pixel_height: -0.1 };
        let r = Raster::new(name, 10, 10, vec![vec![1.0; 100]], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
        let bytes = geotiff::write(&r, 0).unwrap();
        crate::cmd::raster::add_raster(&mut s, name, rustgis_map::RasterLayer::from_bytes(r, format!("{name}.tif"), bytes)).unwrap();
    }
    plugin("eng-mosaic-view", &[]);
    let e = forward(&mut s, "eng-mosaic-view", "raster.mosaic", json!({"inputs": ["west", "east"]})).unwrap_err();
    assert!(e.contains("'edit' permission"), "{e}");
    rustgis_plugins::unload("eng-mosaic-view");
    plugin("eng-mosaic", &["edit"]);
    forward(&mut s, "eng-mosaic", "raster.mosaic", json!({"inputs": ["west", " east "], "name": "Elevation"})).unwrap();
    assert!(s.map().layer_by_name("Elevation").is_some_and(|l| l.is_raster()));
    // The layer comes before a file of its name.
    forward(&mut s, "eng-mosaic", "raster.mosaic", json!({"inputs": ["east", "north.tif"], "name": "East and north"})).unwrap();
    assert!(s.map().layer_by_name("East and north").is_some());
    // Writing a file, an input read from one (a raster file name that isn't a layer), and a name
    // that looks like a place need `files`.
    for params in [
        json!({"inputs": ["west", "east"], "name": "Elevation", "path": "elevation.tif"}),
        json!({"inputs": ["west", "east.tif"]}),
        json!({"inputs": ["west", "../east.tif"]}),
        json!({"inputs": ["west", "east"], "name": "../elevation"}),
    ] {
        let e = forward(&mut s, "eng-mosaic", "raster.mosaic", params.clone()).unwrap_err();
        assert!(e.contains("'files' permission"), "{params}: {e}");
    }
    // Inputs the command would read no file for fail in the command, as they would with `files`:
    // a typo, a vector layer, a non-text input, a call over the input limit.
    for (params, why) in [
        (json!({"inputs": ["west", "esat"]}), "no raster layer 'esat'"),
        (json!({"inputs": ["west", "Countries"]}), "no raster layer 'Countries'"),
        (json!({"inputs": ["west", 3]}), "each input is a raster layer's name or a file path"),
        (json!({"inputs": vec!["west"; 10_001]}), "at most 10000 inputs"),
    ] {
        let e = forward(&mut s, "eng-mosaic", "raster.mosaic", params.clone()).unwrap_err();
        assert!(e.contains(why) && !e.contains("permission"), "{params}: {e}");
    }
    // So does a raster layer whose cells aren't in memory yet (a tile still downloading).
    let east = s.map().layer_by_name("east").unwrap().id;
    s.map_mut().layer_mut(east).unwrap().raster.as_mut().unwrap().data = None;
    let e = forward(&mut s, "eng-mosaic", "raster.mosaic", json!({"inputs": ["west", "east"]})).unwrap_err();
    assert!(e.contains("no raster layer 'east'") && !e.contains("permission"), "{e}");
    rustgis_plugins::unload("eng-mosaic");
}

#[test]
fn plugin_tile_layers_need_network() {
    let mut s = world();
    let osm = json!({"url": "https://tile.openstreetmap.org/{z}/{x}/{y}.png", "attribution": "© OpenStreetMap contributors"});
    // Without `network`, a plugin can't add a tile layer, directly or by importing a map file.
    plugin("eng-tiles-edit", &["edit", "files"]);
    let e = forward(&mut s, "eng-tiles-edit", "map.addTiles", osm.clone()).unwrap_err();
    assert!(e.contains("'network' permission"), "{e}");
    let mut m = rustgis_map::Map::new("Imported");
    m.tiles.push(rustgis_map::TileLayer::new("Leak", rustgis_map::TileKind::Raster, "https://evil.example.com/{z}/{x}/{y}.png?d=secret"));
    let text = serde_json::to_string(&m).unwrap();
    let e = forward(&mut s, "eng-tiles-edit", "map.import", json!({"text": text})).unwrap_err();
    assert!(e.contains("'network' permission"), "{e}");
    assert!(s.project.maps.iter().all(|m| m.tiles.is_empty()));
    // Nor by changing how a layer it can see fetches (here, an imported map with the same
    // address as an existing layer but another subdomain list).
    s.run("map.addTiles", &json!({"url": "https://{s}.tiles.example.com/{z}/{x}/{y}.png"})).unwrap();
    let mut m = s.map().clone();
    m.name = "Copy".into();
    m.tiles[0].subdomains = vec!["evil".into()];
    let e = forward(&mut s, "eng-tiles-edit", "map.import", json!({"text": serde_json::to_string(&m).unwrap()})).unwrap_err();
    assert!(e.contains("'network' permission"), "{e}");
    assert!(s.project.maps.iter().flat_map(|m| &m.tiles).all(|t| t.subdomains.is_empty()));
    // Changing a layer's opacity is only an edit.
    forward(&mut s, "eng-tiles-edit", "map.setTiles", json!({"index": 0, "opacity": 0.5})).unwrap();
    assert_eq!(s.map().tiles[0].opacity, 0.5);
    s.run("map.removeTiles", &json!({})).unwrap();
    rustgis_plugins::unload("eng-tiles-edit");
    // With it (and `edit`), it can; it needs no `files` for an address.
    plugin("eng-tiles-net", &["edit", "network"]);
    forward(&mut s, "eng-tiles-net", "map.addTiles", osm).unwrap();
    assert_eq!(s.map().tiles.len(), 1);
    let listed = forward(&mut s, "eng-tiles-net", "map.tiles", json!({})).unwrap();
    assert_eq!(listed[0]["attribution"], "© OpenStreetMap contributors");
    forward(&mut s, "eng-tiles-net", "map.removeTiles", json!({})).unwrap();
    assert!(s.map().tiles.is_empty());
    rustgis_plugins::unload("eng-tiles-net");
}

/// Serves documents for `host.fetch` on a local port, counting the requests: `/json`, `/text`,
/// `/latin1` (not UTF-8), `/big` (over the size cap), `/inward` (a redirect to a forbidden
/// address) and `/missing` (404). Returns the base address and the count.
fn serve_documents() -> (String, std::sync::Arc<std::sync::atomic::AtomicUsize>) {
    use std::io::{Read, Write};
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let addr = listener.local_addr().unwrap();
    let count = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let counted = count.clone();
    std::thread::spawn(move || {
        for stream in listener.incoming() {
            let Ok(mut s) = stream else { continue };
            counted.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            let mut buf = [0u8; 4096];
            let read = s.read(&mut buf).unwrap_or(0);
            let req = String::from_utf8_lossy(&buf[..read]).to_string();
            let path = req.split_whitespace().nth(1).unwrap_or("/").to_string();
            let (status, extra, body): (&str, String, Vec<u8>) = match path.as_str() {
                p if p.starts_with("/json") => {
                    ("200 OK", String::new(), br#"{"data":[1],"select":[49059],"size":[17053],"valid":true}"#.to_vec())
                }
                "/text" => ("200 OK", String::new(), b"plain text".to_vec()),
                "/latin1" => ("200 OK", String::new(), b"caf\xe9".to_vec()),
                "/big" => ("200 OK", String::new(), vec![b'x'; crate::cmd::plugins::fetch::MAX_BYTES + 10]),
                "/inward" => ("302 Found", "Location: http://169.254.169.254/latest/meta-data/\r\n".into(), Vec::new()),
                _ => ("404 Not Found", String::new(), b"no".to_vec()),
            };
            let _ = write!(s, "HTTP/1.1 {status}\r\n{extra}Content-Length: {}\r\nConnection: close\r\n\r\n", body.len());
            let _ = s.write_all(&body);
        }
    });
    (format!("http://{addr}"), count)
}

/// Lets this thread's plugin calls fetch from this computer (the test server) and, when `wait`
/// is off, fetch as the browser does.
fn fetch_mode(local: bool, wait: bool) {
    crate::cmd::plugins::fetch::TEST.with(|t| t.set((local, wait)));
}

/// `host.fetch` needs `network`, takes only public http(s) addresses (redirects too), caps the
/// size, wants UTF-8, answers JSON parsed, and keeps answers.
#[test]
fn plugins_fetch_documents_with_network() {
    let mut s = world();
    plugin("eng-fetch-none", &["edit"]);
    let e = forward(&mut s, "eng-fetch-none", "host.fetch", json!({"url": "https://example.com/x.json"})).unwrap_err();
    assert!(e.contains("'network' permission"), "{e}");
    rustgis_plugins::unload("eng-fetch-none");

    plugin("eng-fetch", &["network"]);
    // Never this computer or the local network, by default; never another scheme.
    for bad in [
        json!({}),
        json!({"url": 7}),
        json!({"url": "file:///etc/passwd"}),
        json!({"url": "s3://bucket/key"}),
        json!({"url": "ftp://example.com/"}),
        json!({"url": "http://127.0.0.1:9/x"}),
        json!({"url": "http://localhost/x"}),
        json!({"url": "http://192.168.0.1/"}),
        json!({"url": "http://169.254.169.254/latest/meta-data/"}),
    ] {
        assert!(forward(&mut s, "eng-fetch", "host.fetch", bad.clone()).is_err(), "{bad}");
    }
    // Hostile parameters are errors, never a crash.
    for junk in [Value::Null, json!([1, 2]), json!({"url": null}), json!({"url": {"nested": 1}}), json!({"url": "x".repeat(100_000)})] {
        assert!(forward(&mut s, "eng-fetch", "host.fetch", junk.clone()).is_err(), "{junk}");
    }

    let (base, count) = serve_documents();
    fetch_mode(true, true);
    let a = forward(&mut s, "eng-fetch", "host.fetch", json!({"url": format!("{base}/json?r=1")})).unwrap();
    assert_eq!(a["json"]["select"][0], 49059);
    assert!(a["text"].as_str().unwrap().starts_with('{'));
    let n = count.load(std::sync::atomic::Ordering::SeqCst);
    // Asked again: the cache answers.
    let again = forward(&mut s, "eng-fetch", "host.fetch", json!({"url": format!("{base}/json?r=1#ignored")})).unwrap();
    assert_eq!(again, a);
    assert_eq!(count.load(std::sync::atomic::Ordering::SeqCst), n, "answered from the cache");
    let t = forward(&mut s, "eng-fetch", "host.fetch", json!({"url": format!("{base}/text")})).unwrap();
    assert_eq!(t["text"], "plain text");
    assert!(t.get("json").is_none());
    for (path, why) in [("/latin1", "UTF-8"), ("/big", "larger than"), ("/missing", "404"), ("/inward", "never fetched")] {
        let e = forward(&mut s, "eng-fetch", "host.fetch", json!({"url": format!("{base}{path}")})).unwrap_err();
        assert!(e.contains(why), "{path}: {e}");
    }
    fetch_mode(false, true);
    rustgis_plugins::unload("eng-fetch");
}

/// Where nothing may wait (the browser), `host.fetch` answers pending: the command is undone,
/// quietly, and runs again once the answer is in, when the cache answers.
#[test]
fn plugin_fetches_run_the_command_again_when_they_land() {
    let mut s = world();
    plugin("eng-fetch-web", &["network", "edit"]);
    let (base, _) = serve_documents();
    fetch_mode(true, false);
    let url = format!("{base}/json?web=1");
    s.log.clear();
    let notices = s.notice_mark();
    let undo = s.undo.len();
    let r = forward(&mut s, "eng-fetch-web", "host.fetch", json!({"url": url})).unwrap();
    assert_eq!(r["pending"], true);
    assert_eq!(r["fetching"][0], url.as_str());
    assert_eq!(s.undo.len(), undo, "no undo step for a run that waits");
    assert!(s.notices_since(notices).is_empty(), "{:?}", s.notices_since(notices));
    let t0 = std::time::Instant::now();
    let ran = loop {
        let ran = s.poll_plugin_retries();
        if !ran.is_empty() || t0.elapsed() > std::time::Duration::from_secs(10) {
            break ran;
        }
        std::thread::sleep(std::time::Duration::from_millis(20));
    };
    assert_eq!(ran.len(), 1);
    assert_eq!(ran[0].0, "plugin:eng-fetch-web/f");
    assert_eq!(ran[0].1.as_ref().unwrap()["json"]["valid"], true);
    assert!(s.poll_plugin_retries().is_empty(), "run once");
    assert_eq!(
        s.log.entries().filter(|e| e.command == "plugin:eng-fetch-web/f").count(),
        1,
        "one actual final log entry, no pending entry"
    );
    // A failed fetch is given to the run again as its error.
    let r = forward(&mut s, "eng-fetch-web", "host.fetch", json!({"url": format!("{base}/missing")})).unwrap();
    assert_eq!(r["pending"], true);
    let t0 = std::time::Instant::now();
    let ran = loop {
        let ran = s.poll_plugin_retries();
        if !ran.is_empty() || t0.elapsed() > std::time::Duration::from_secs(10) {
            break ran;
        }
        std::thread::sleep(std::time::Duration::from_millis(20));
    };
    assert!(ran[0].1.as_ref().unwrap_err().contains("404"), "{:?}", ran[0].1);
    // A held pinned retry publishes revocation instead of disappearing from the UI.
    struct Live(std::sync::atomic::AtomicBool);
    impl crate::policy::Revocation for Live {
        fn allows(&self, _: crate::policy::Effects) -> bool {
            self.0.load(std::sync::atomic::Ordering::SeqCst)
        }
    }
    let live = std::sync::Arc::new(Live(true.into()));
    let scope = crate::policy::Scope::assistant(901, live.clone());
    let call = crate::policy::Call::command(
        "plugin:eng-fetch-web/f",
        json!({"op":"host.fetch","params":{"url":format!("{base}/json?revoked=1")}}),
    );
    let crate::policy::Outcome::NeedsApproval(p) = s.review(&scope, &call) else { panic!("plugin must ask") };
    assert_eq!(s.run_permitted(scope, p.allow(), &call).unwrap()["pending"], true);
    live.0.store(false, std::sync::atomic::Ordering::SeqCst);
    let mark = s.notice_mark();
    let started = std::time::Instant::now();
    let revoked = loop {
        let r = s.poll_plugin_retries();
        if !r.is_empty() || started.elapsed() > std::time::Duration::from_secs(10) {
            break r;
        }
        std::thread::yield_now();
    };
    assert_eq!(revoked.len(), 1);
    assert!(revoked[0].1.is_err());
    assert!(s.notices_since(mark).iter().any(|n| n.error), "revoked retry is visible");
    assert!(s.poll_plugin_retries().is_empty());
    // A command forever waiting gives up.
    s.retry_tries = crate::cmd::plugins::fetch::MAX_RETRIES;
    let e = forward(&mut s, "eng-fetch-web", "host.fetch", json!({"url": format!("{base}/json?web=2")})).unwrap_err();
    assert!(e.contains("gave up"), "{e}");
    s.retry_tries = 0;
    fetch_mode(false, true);
    rustgis_plugins::unload("eng-fetch-web");
}

